// ============================================================
// Fonte estática para geração automática de flashcards a partir
// do banco de Classificações da ferramenta clínica (CL_DATA em
// public/index.html). Gerado uma vez a partir dos dados reais —
// não é lido dinamicamente do index.html (são apps/execução
// separados), então precisa ser regenerado manualmente se o
// banco de classificações mudar de forma relevante.
// Cada entrada já vem categorizada por área de estudo (mesma
// taxonomia de QUESTION_AREAS) para respeitar a organização por
// área exigida em todo o site.
// ============================================================
export interface ClassificationFlashcardSource {
  id: string;
  area: string;
  front: string;
  back: string;
}

export const CLASSIFICATION_FLASHCARD_SOURCE: ClassificationFlashcardSource[] = [{"id":"gustilo-anderson","area":"Trauma Geral","front":"GUSTILO\n\nQuais são os critérios dessa classificação?\n(Gustilo-Anderson — Fraturas Expostas)","back":"• Tipo I — Ferida <1cm; limpa; fratura simples. Risco infecção <2%. Desbridamento + fixação.\n• Tipo II — Ferida 1–10cm; pouca contaminação; fratura moderada. Risco <7%.\n• Tipo IIIA — Fratura extensa; cobertura partes moles adequada pós-desbridamento. Risco 7%.\n• Tipo IIIB — Extenso desnudamento periosteal; necessita retalho de cobertura. Risco 10–50%.\n• Tipo IIIC — Lesão arterial necessitando reparo vascular. Risco amputação ~50%."},{"id":"tscherne","area":"Trauma Geral","front":"TSCHERNE\n\nQuais são os critérios dessa classificação?\n(Tscherne — Lesão de Partes Moles em Fraturas)","back":"• C0 — Fechada grau 0 — Sem lesão de partes moles significativa.\n• C1 — Fechada grau 1 — Escoriação superficial ou contusão leve (trauma indireto).\n• C2 — Fechada grau 2 — Contusão profunda; síndrome compartimental iminente (trauma direto).\n• C3 — Fechada grau 3 — Contusão maciça; síndrome compartimental estabelecida; desluvamento.\n• O1 — Aberta grau 1 — Punção pequena; contaminação desprezível; baixa energia.\n• O2 — Aberta grau 2 — Contusão pele/tecidos moles; contaminação moderada.\n• O3 — Aberta grau 3 — Contaminação densa; dano extenso; lesões arteriais/nervosas.\n• O4 — Aberta grau 4 — Amputações incompletas ou completas."},{"id":"ao-osso","area":"Trauma Geral","front":"AO-FRATURAS\n\nQuais são os critérios dessa classificação?\n(AO/OTA — Classificação Universal de Fraturas)","back":"• Tipo A — Extra-articular — Fraturas simples, em cunha ou complexas fora da articulação.\n• Tipo B — Articular parcial — Parte da superfície articular fraturada; restante ligada à diáfise.\n• Tipo C — Articular completa — Epífise completamente separada da metáfise. RAFI obrigatória."},{"id":"pseudartrose-judet","area":"Trauma Geral","front":"JUDET-PSEUDO\n\nQuais são os critérios dessa classificação?\n(Judet-Müller-Weber-Cech — Pseudartrose)","back":"• Hipertrófica — Pata de elefante — Fixação insegura/imobilização inadequada. Calo abundante. Boa vascularização.\n• Hipertrófica — Casco de cavalo — Fixação moderadamente instável. Calo moderado.\n• Oligotrófica — Diástase; ausência de calo. Diástase funcional.\n• Avascular — Cunha de torção — Fragmento intermediário consolidou em um dos fragmentos principais.\n• Avascular — Cominutiva — 1 ou mais fragmentos intermediários necrosados.\n• Avascular — Com defeito — Perda de um fragmento (fratura exposta, sequestrectomia, tumor).\n• Avascular — Atrófica — Resultado final sem fragmentos intermediários. Pior prognóstico."},{"id":"salter-harris","area":"Trauma Geral","front":"SALTER-HARRIS\n\nQuais são os critérios dessa classificação?\n(Salter-Harris — Lesões da Placa de Crescimento)","back":"• Tipo I — Fratura pela placa de crescimento. Bom prognóstico. Imobilização.\n• Tipo II — Placa + fragmento metafisário. Mais comum (75%). Boa evolução.\n• Tipo III — Placa + epífise (intra-articular). RAFI se desvio. Risco de distúrbio de crescimento.\n• Tipo IV — Epífise + placa + metáfise. RAFI obrigatória.\n• Tipo V — Esmagamento da placa. Diagnóstico retrospectivo. Pior prognóstico."},{"id":"cierny-mader","area":"Trauma Geral","front":"CIERNY-MADER\n\nQuais são os critérios dessa classificação?\n(Cierny-Mader — Osteomielite)","back":"• Tipo I — Medular — Canal medular. Hematogênica ou implante.\n• Tipo II — Superficial — Cortical superficial. Pós-traumática ou pós-cirúrgica.\n• Tipo III — Localizada — Cortical + medular; segmento estável. Ressecção + fixação.\n• Tipo IV — Difusa — Todo osso comprometido; instabilidade mecânica. Ressecção ampla ± rotação."},{"id":"neer-clavicula","area":"Ombro e Cotovelo","front":"NEER-CLAV\n\nQuais são os critérios dessa classificação?\n(Neer — Fratura da Clavícula Distal)","back":"• Tipo I — Ambos os ligamentos intactos fixados no fragmento medial. Tratamento conservador.\n• Tipo II — Lig. trapezóide fixado ao fragmento distal; lig. conóide rompido. Instável → cirurgia.\n• Tipo III — Fratura com extensão para articulação acromioclavicular."},{"id":"rockwood-lac","area":"Ombro e Cotovelo","front":"ROCKWOOD-LAC\n\nQuais são os critérios dessa classificação?\n(Rockwood — Luxação Acromioclavicular)","back":"• Tipo I — Entorse da articulação AC; ligamentos intactos.\n• Tipo II — Ruptura dos lig. acromioclaviculares; lig. coracoclaviculares intactos.\n• Tipo III — Rupturas dos lig. AC e CC; espaço coracoclavicular aumentado 25–100%.\n• Tipo IV — Rupturas dos lig. AC e CC; desvio posterior da clavícula (m. trapézio).\n• Tipo V — Desvio superior grosseiro da clavícula 100–300%; mm. trapézio e deltóide arrancados.\n• Tipo VI — Clavícula desviada inferiormente ao acrômio ou processo coracóide."},{"id":"neer-umero","area":"Ombro e Cotovelo","front":"NEER-ÚMERO\n\nQuais são os critérios dessa classificação?\n(Neer — Fratura do Úmero Proximal)","back":"• 1 fragmento — Sem desvio (qualquer nível). Tratamento conservador (tipoia 3–6 semanas).\n• 2 fragmentos — 1 fragmento com desvio >1cm ou >45°. RAFI artroscópica ou aberta.\n• 3 fragmentos — Colo cirúrgico + tuberosidade maior ou menor. RAFI com placa angular.\n• 4 fragmentos — Cabeça + colo + 2 tuberosidades. Artroplastia (reversa em >65 anos)."},{"id":"ideberg","area":"Ombro e Cotovelo","front":"IDEBERG\n\nQuais são os critérios dessa classificação?\n(Ideberg — Fratura da Escápula (Glenóide))","back":"• Tipo I — Fratura da borda anterior (IA) ou posterior (IB) da glenóide.\n• Tipo II — Traço em direção à borda lateral.\n• Tipo III — Traço em direção à borda superior (próx. n. supraescapular).\n• Tipo IV — Traço em direção à borda medial.\n• Tipo V — Combinações: Va (II+IV), Vb (III+IV), Vc (II+III+IV).\n• Tipo VI — Cominutiva."},{"id":"zdravkovic","area":"Ombro e Cotovelo","front":"ZDRAVKOVIC\n\nQuais são os critérios dessa classificação?\n(Zdravkovic — Fratura do Corpo da Escápula)","back":"• Grupo I — Fratura do corpo (trauma direto).\n• Grupo II — Fraturas de apófises: acrômio, espinha (trauma direto); coracóide (arrancamento).\n• Grupo III — Fraturas do colo da escápula.\n• Grupo IV — Fraturas intra-articulares da glenóide.\n• Grupo V — Fraturas combinadas corpo+glenóide+espinha + fratura concomitante da clavícula."},{"id":"cofield-manguito","area":"Ombro e Cotovelo","front":"COFIELD\n\nQuais são os critérios dessa classificação?\n(Cofield — Rotura do Manguito Rotador)","back":"• Pequena (<1cm) — Reparo artroscópico primário. Excelente prognóstico.\n• Média (1–3cm) — Reparo artroscópico; bons resultados.\n• Grande (3–5cm) — Reparo com técnica de dupla fileira. Resultado variável.\n• Maciça (>5cm) — Transferência tendinosa ou prótese reversa de ombro."},{"id":"gartland","area":"Ombro e Cotovelo","front":"GARTLAND\n\nQuais são os critérios dessa classificação?\n(Gartland — Fratura Supracondilar em Crianças)","back":"• Tipo I — Não deslocada. Gesso axilar 3–4 semanas.\n• Tipo II — Deslocada com cortical posterior intacta. Redução fechada + fixação percutânea.\n• Tipo III — Deslocada sem contato cortical. RAFI urgente. Risco lesão n. mediano (póstero-lateral) e n. radial (póstero-medial)."},{"id":"mason-radio","area":"Ombro e Cotovelo","front":"MASON\n\nQuais são os critérios dessa classificação?\n(Mason — Fratura da Cabeça do Rádio)","back":"• Tipo I — Sem desvio (<2mm, <30° angulação, <30% superfície articular). Conservador.\n• Tipo II — Com desvio (impacção ou fragmento isolado >2mm). RAFI se bloquear ADM.\n• Tipo III — Cominutiva. Ressecção ou prótese de cabeça do rádio.\n• Tipo IV — (Johnston/Hotchkiss) Luxação do cotovelo associada. Emergência cirúrgica."},{"id":"ao13","area":"Ombro e Cotovelo","front":"AO-13\n\nQuais são os critérios dessa classificação?\n(AO/OTA 13 — Fratura do Úmero Distal)","back":"• A — Extra-articular — A1: avulsão apofisária; A2: metafisária simples; A3: metafisária multifragmentária.\n• B — Articular parcial — B1: sagital lateral (capítulo); B2: sagital medial; B3: frontal (Hahn-Steinthal).\n• C — Articular completa — C1: articular simples/metafisária simples; C2: articular simples/metafisária complexa; C3: ambas complexas."},{"id":"ao23","area":"Mão","front":"AO-23\n\nQuais são os critérios dessa classificação?\n(AO/OTA 23 — Fratura do Rádio Distal)","back":"• A — Extra-articular — A1: ulnar isolada; A2: rádio simples (Colles/Smith); A3: rádio multifragmentária.\n• B — Articular parcial — B1: lateral (Chauffeur); B2: rebordo dorsal (Barton dorsal); B3: rebordo volar (Barton inversa).\n• C — Articular completa — C1: articular simples/metafisária simples; C2: articular simples/metafisária complexa; C3: ambas complexas."},{"id":"fernandez-radio","area":"Mão","front":"FERNANDEZ\n\nQuais são os critérios dessa classificação?\n(Fernandez — Fratura do Rádio Distal (por Mecanismo))","back":"• Tipo 1 — Flexão/Extensão — Falha metafisária por tração (Colles, Smith). Tratamento: redução fechada + gesso/fixador externo.\n• Tipo 2 — Compressão — Fratura articular com impacção (die-punch, lunate-load). RAFI.\n• Tipo 3 — Cisalhamento — Fratura articular por cisalhamento (Barton, estilóide radial). RAFI com placa de sustentação.\n• Tipo 4 — Avulsão — Avulsão ligamentar (estilóide ulnar). Reparo ligamentar associado.\n• Tipo 5 — Combinada — Lesão de alta energia combinando mecanismos 1–4."},{"id":"palmer-cfct","area":"Mão","front":"PALMER-CFCT\n\nQuais são os critérios dessa classificação?\n(Palmer — Lesão do Complexo Fibrocartilagem Triangular (CFCT))","back":"• Classe 1A — Perfuração/ruptura central traumática. Desbridamento artroscópico.\n• Classe 1B — Avulsão ulnar (mais comum em crianças). Reparo artroscópico fora-dentro.\n• Classe 1C — Ruptura volar distal. Reparo cirúrgico.\n• Classe 1D — Ruptura fora da incisura sigmóide. Reparo artroscópico ou aberto.\n• Classe 2A–E — Degenerativa (SLAC wrist): desgaste progressivo CFCT → condromalacia → artrose."},{"id":"herbert-escafoide","area":"Mão","front":"HERBERT\n\nQuais são os critérios dessa classificação?\n(Herbert-Fisher — Fratura do Escafoide)","back":"• A — Estável — A1: tuberosidade; A2: incompleta do terço médio. Gesso 6–12 semanas.\n• B — Instável — B1: oblíqua distal; B2: completa terço médio; B3: polo proximal; B4: trans-escafossemilunar. Cirurgia.\n• C — Retardo de consolidação — Consolidação retardada. Enxerto + fixação.\n• D — Pseudartrose — D1: fibrose; D2: pseudartrose estabelecida. Enxerto vascularizado."},{"id":"kienboeck","area":"Mão","front":"LICHTMAN\n\nQuais são os critérios dessa classificação?\n(Lichtman-Stahl — Doença de Kienböck (Semilunar))","back":"• Estágio I — Esclerose leve ou fratura linear (RX normal; RM positiva). Descarga + imobilização.\n• Estágio II — Esclerose e fragmentação sem colapso. Procedimentos de equalização ulnar.\n• Estágio IIIA — Fragmentação com colapso; escafóide alinhado. Procedimentos de encurtamento ou vascularização.\n• Estágio IIIB — Colapso + desalinhamento do escafóide (mais vertical). Artrodese limitada.\n• Estágio IV — Fragmentação, colapso e artrite generalizada. Artrodese total ou ressecção."},{"id":"bennett-green","area":"Mão","front":"GREEN-BENNETT\n\nQuais são os critérios dessa classificação?\n(Green — Fratura da Base do 1º Metacarpal)","back":"• Tipo I — Bennett — Fratura-luxação: fragmento volar + luxação do metacarpal. RAFI/redução fechada + fixação.\n• Tipo II — Rolando — Fratura em Y/T articular cominutiva. RAFI ou fixador externo.\n• Tipo IIIA — Fratura epibasal transversa. Gesso + redução fechada.\n• Tipo IIIB — Fratura epibasal oblíqua. RAFI se desvio.\n• Tipo IV — Fratura epifisária (crianças). Salter-Harris."},{"id":"denis-coluna","area":"Coluna","front":"DENIS\n\nQuais são os critérios dessa classificação?\n(Denis — Teoria das 3 Colunas)","back":"• Coluna anterior — ½ ant. corpo + disco + lig. long. anterior. Lesão isolada = estável.\n• Coluna média — ½ post. corpo + disco + lig. long. posterior. Lesão = instabilidade.\n• Coluna posterior — Arco posterior + ligamentos posteriores.\n• 2 colunas (instável) — Envolvimento de coluna média + outra. Cirurgia considerada.\n• 3 colunas (muito instável) — Burst completo. Cirurgia urgente."},{"id":"asia-frankel","area":"Coluna","front":"ASIA\n\nQuais são os critérios dessa classificação?\n(ASIA / Frankel — Lesão Medular)","back":"• A — Completa — Sem função motora ou sensitiva abaixo do nível neurológico (S4–S5).\n• B — Incompleta Sensitiva — Sensitiva preservada; sem motora abaixo do nível.\n• C — Incompleta Motora — Motora presente; >50% músculos chave com força <3.\n• D — Incompleta Motora — Motora presente; ≥50% músculos chave com força ≥3.\n• E — Normal — Funções motoras e sensitivas normais."},{"id":"anderson-odontoid","area":"Coluna","front":"ANDERSON-C2\n\nQuais são os critérios dessa classificação?\n(Anderson-D'Alonzo — Fratura do Processo Odontóide C2)","back":"• Tipo I — Fratura oblíqua proximal do processo odontóide. Estável. Conservador.\n• Tipo II — Fratura na junção odontóide-corpo do áxis. Mais frequente. Alta taxa de não-consolidação. Cirurgia recomendada.\n• Tipo III — Fratura pelo osso esponjoso do corpo do áxis. Boa consolidação com imobilização externa (halo)."},{"id":"magerl-toracolombar","area":"Coluna","front":"MAGERL-AO\n\nQuais são os critérios dessa classificação?\n(Magerl/AO — Fraturas Toracolombares)","back":"• Tipo A — Compressão — A1: impacção; A2: split; A3: burst. Coluna posterior intacta.\n• Tipo B — Distração — B1: lig. posterior (Chance osseo); B2: Chance ligamentar; B3: hiperestensão. Instável.\n• Tipo C — Rotação/Translação — A+Rot, B+Rot ou cisalhamento puro. Lesão das 3 colunas. Muito instável."},{"id":"letournel-acetabulo","area":"Quadril","front":"LETOURNEL\n\nQuais são os critérios dessa classificação?\n(Letournel-Judet — Fratura do Acetábulo)","back":"• Parede posterior — Mais comum. Associada à luxação posterior. Via KL.\n• Coluna posterior — Coluna ilio-isquiática. Via KL.\n• Parede anterior — Incomum. Via ilioinguinal.\n• Coluna anterior — Via ilioinguinal.\n• Transversa — Divide acetábulo em segmento cranial e caudal. Via KL ou ilioinguinal.\n• Parede + coluna post. — Via KL.\n• Transversa + parede post. — Via KL.\n• Fratura em T — Coluna posterior + traço transverso. Via KL."},{"id":"garden","area":"Quadril","front":"GARDEN\n\nQuais são os critérios dessa classificação?\n(Garden — Fratura do Colo do Fêmur)","back":"• Garden I — Incompleta em valgo (impactada). Parafuso canulado ou conservador.\n• Garden II — Completa sem desvio. Parafuso canulado / DHS.\n• Garden III — Completa com desvio parcial em varo. RAFI vs artroplastia (conforme idade/atividade).\n• Garden IV — Completa com desvio total (trabéculas realinhadas). Artroplastia (PTQ em ativos jovens: RAFI)."},{"id":"pauwels","area":"Quadril","front":"PAUWELS\n\nQuais são os critérios dessa classificação?\n(Pauwels — Fratura do Colo do Fêmur (Ângulo))","back":"• Tipo I — 30° — Horizontal. Forças predominantemente compressivas. Estável. Melhor prognóstico.\n• Tipo II — 50° — Intermediária. Forças mistas.\n• Tipo III — 70° — Vertical. Forças de cisalhamento predominam. Instável. Pior prognóstico → cirurgia precoce."},{"id":"pipkin","area":"Quadril","front":"PIPKIN\n\nQuais são os critérios dessa classificação?\n(Pipkin — Fratura da Cabeça Femoral)","back":"• Tipo I — Fratura inferior à fóvea (não sustentação de peso). Via anterior (Smith-Peterson).\n• Tipo II — Fratura superior à fóvea (sustentação de peso). Via anterior.\n• Tipo III — Qualquer fratura da cabeça + fratura do colo femoral. Pior prognóstico.\n• Tipo IV — Qualquer fratura da cabeça + fratura do acetábulo."},{"id":"herring-perthes","area":"Quadril","front":"HERRING\n\nQuais são os critérios dessa classificação?\n(Herring — Doença de Legg-Calvé-Perthes (Pilar Lateral))","back":"• Tipo A — Pilar lateral preservado ou diminuição mínima. Bom prognóstico. Conservador.\n• Tipo B — Comprometimento até 50% da altura do pilar lateral. Tratamento conforme idade.\n• Tipo B/C — (Borderline) Entre B e C.\n• Tipo C — Diminuição >50% da altura do pilar lateral. Pior prognóstico. Osteotomia."},{"id":"ao31a-transtocanterica","area":"Trauma Geral","front":"AO-31A\n\nQuais são os critérios dessa classificação?\n(AO/OTA 31A — Fratura Transtrocantérica)","back":"• 31A1 — Pertrocantérica simples — Ao longo da linha intertrocantérica; 2 fragmentos. DHS. Estável.\n• 31A2 — Pertrocantérica multifrag. — Fragmento posteromedial; mais instável. DHS com placa ou clavo cefálico-medular.\n• 31A3 — Intertrocantérica (inversa) — Linha invertida; muito instável. Clavo cefálico-medular longo."},{"id":"winquist-diafise","area":"Trauma Geral","front":"WINQUIST\n\nQuais são os critérios dessa classificação?\n(Winquist-Hansen — Fratura Diafisária do Fêmur (Cominuição))","back":"• Grau I — Fragmento cominutivo pequeno. Estável. HIM anterógrado.\n• Grau II — Cominuição até 50% da circunferência. Estabilidade relativa. HIM.\n• Grau III — Cominuição >50%. Instável em rotação. HIM bloqueado.\n• Grau IV — Cominuição circunferencial completa (segmentar). HIM bloqueado ou fixador externo."},{"id":"hoffa","area":"Trauma Geral","front":"HOFFA\n\nQuais são os critérios dessa classificação?\n(Fratura de Hoffa — Fratura Condilar Femoral Coronal)","back":"• Tipo I — Linha de fratura próxima ao colo do côndilo. >75% do côndilo. RAFI anteroposterior.\n• Tipo II — Linha oblíqua. Fragmento intermediário.\n• Tipo III — Fratura vertical fina (<25% do côndilo). Difícil fixação."},{"id":"schatzker","area":"Joelho","front":"SCHATZKER\n\nQuais são os critérios dessa classificação?\n(Schatzker — Fratura do Platô Tibial)","back":"• Tipo I — Fissura do platô lateral. Cunha lateral. RAFI com parafusos.\n• Tipo II — Fissura + depressão do platô lateral. RAFI + enxerto/substituto ósseo.\n• Tipo III — Depressão pura do platô lateral (sem cunha). RAFI.\n• Tipo IV — Fratura do platô medial ou ambos os espinhos. RAFI. Alta energia.\n• Tipo V — Fratura bicondilar. RAFI dupla placa. Alta energia.\n• Tipo VI — Fratura bicondilar + dissociação metáfise-diáfise. Alta energia. Fixador externo temporário."},{"id":"ligamento-isakos","area":"Joelho","front":"ISAKOS-LIG\n\nQuais são os critérios dessa classificação?\n(ISAKOS/Clancy — Gradação Ligamentar do Joelho)","back":"• Grau I — Entorse — Microlesões; integridade macroscópica preservada; teste de gaveta/Lachman negativo. Conservador.\n• Grau II — Ruptura parcial — Ruptura parcial; instabilidade discreta; Lachman fraco positivo. Reabilitação.\n• Grau III — Ruptura total — Ruptura completa; Lachman ++ / gaveta anterior +. Reconstrução ligamentar."},{"id":"menisco-isakos","area":"Joelho","front":"ISAKOS-MEN\n\nQuais são os critérios dessa classificação?\n(ISAKOS — Lesões Meniscais)","back":"• Vertical longitudinal — Paralela à periferia. Reparável se <3cm da borda (zona vascularizada).\n• Radial — Perpendicular às fibras. Compromete integridade; ressecção parcial.\n• Alça de balde — Longitudinal deslocável; bloqueio articular. Reparo urgente.\n• Oblíqua (flap) — Ângulo 45°. Ressecção da aba.\n• Degenerativa — Associada à artrose ≥ KL3. Artroscopia com cautela (evidência limitada)."},{"id":"kellgren","area":"Joelho","front":"KELLGREN\n\nQuais são os critérios dessa classificação?\n(Kellgren-Lawrence — Osteoartrose do Joelho)","back":"• Grau 0 — Normal. Sem alterações radiográficas.\n• Grau 1 — Estreitamento duvidoso; possível osteófito incipiente.\n• Grau 2 — Osteófito definido; possível estreitamento. Sintomas leves.\n• Grau 3 — Osteófitos múltiplos; estreitamento definido; esclerose subcondral.\n• Grau 4 — Grande osteófito; estreitamento grave; deformidade óssea."},{"id":"danis-weber","area":"Pé e Tornozelo","front":"WEBER\n\nQuais são os critérios dessa classificação?\n(Danis-Weber — Fratura Maleolar)","back":"• Weber A — Infra-sindesmal — Fratura transversa abaixo da sindesmose. Sindesmose intacta. Conservador ou RAFI simples.\n• Weber B — Trans-sindesmal — Fratura ao nível da sindesmose. Sindesmose pode estar comprometida. RAFI se instável.\n• Weber C — Supra-sindesmal — Fratura acima da sindesmose. Sindesmose rompida. RAFI + fixação da sindesmose."},{"id":"lauge-hansen","area":"Pé e Tornozelo","front":"LAUGE-HANSEN\n\nQuais são os critérios dessa classificação?\n(Lauge-Hansen — Fratura Maleolar por Mecanismo)","back":"• Supinação-Adução (SA) — 1°: lig. colateral lat. ou maléolo lat.; 2°: cisalhamento vertical medial. → Weber A.\n• Supinação-Rotação Ext. (SRE) — 1°: LTFAI; 2°: fíbula oblíqua; 3°: LTFPI; 4°: maléolo medial. → Weber B. Mais comum.\n• Pronação-Abdução (PA) — 1°: maléolo medial; 2°: LTFAI/LTFPI; 3°: fíbula transversa cominutiva. → Weber C.\n• Pronação-Rotação Ext. (PRE) — 1°: maléolo medial; 2°: LTFAI; 3°: fíbula espiral alta; 4°: LTFPI. → Weber C. Maisonneuve possível."},{"id":"sanders-calcaneo","area":"Pé e Tornozelo","front":"SANDERS\n\nQuais são os critérios dessa classificação?\n(Sanders — Fratura do Calcâneo)","back":"• Tipo I — Sem desvio. Conservador.\n• Tipo II — 2 fragmentos: IIA (lateral), IIB (central), IIC (medial). RAFI com bom resultado.\n• Tipo III — 3 fragmentos: IIIAB, IIIAC, IIIBC. RAFI mais complexa.\n• Tipo IV — Cominutiva. Alta energia. Artrodese subtalar primária ou secundária."},{"id":"steinberg-arco","area":"Quadril","front":"ARCO/STEINBERG\n\nQuais são os critérios dessa classificação?\n(ARCO/Steinberg — Osteonecrose da Cabeça Femoral)","back":"• Estágio 0 — Rx, cintilografia e RM normais. Biópsia compatível com necrose.\n• Estágio I — Rx normal; cintilografia e/ou RM alteradas. A (30%) da cabeça.\n• Estágio II — Rx: esclerose/cistos sem colapso. A (30%).\n• Estágio III — Sinal da meia-lua (fratura subcondral). A (30%).\n• Estágio IV — Achatamento da cabeça; estreitamento articular; alterações acetabulares. A/B/C.\n• Estágio V — Estreitamento do espaço articular e/ou alterações acetabulares.\n• Estágio VI — Alterações degenerativas avançadas. Indicação de artroplastia total."},{"id":"brooker-ho","area":"Quadril","front":"BROOKER\n\nQuais são os critérios dessa classificação?\n(Brooker — Ossificação Heterotópica (pós-ATQ))","back":"• Grau I — Ilhas ósseas nos tecidos moles ao redor do quadril. Assintomático.\n• Grau II — Esporões ósseos do fêmur proximal ou da pelve; ≥1 cm entre superfícies opostas.\n• Grau III — Esporões ósseos; <1 cm entre superfícies opostas. Mobilidade reduzida.\n• Grau IV — Anquilose radiográfica do quadril. Indicação de ressecção se compromete função."},{"id":"stulberg","area":"Quadril","front":"STULBERG\n\nQuais são os critérios dessa classificação?\n(Stulberg — Doença de Perthes (Resultado Final))","back":"• Classe I — Cabeça esférica normal, congruente. Sem artrose.\n• Classe II — Cabeça esférica, concêntrica no acetábulo (AP e lateral). Colo encurtado ou acetábulo inclinado. Sem artrose.\n• Classe III — Cabeça ovoide, em cogumelo ou em guarda-chuva (não plana). Artrose leve a moderada na vida adulta.\n• Classe IV — Cabeça plana com acetábulo correspondentemente plano (congruência asférica). Artrose moderada a severa.\n• Classe V — Cabeça plana; acetábulo normal (incongruência asférica). Artrose grave precoce."},{"id":"outerbridge","area":"Joelho","front":"OUTERBRIDGE\n\nQuais são os critérios dessa classificação?\n(Outerbridge — Lesão da Cartilagem Articular)","back":"• Grau I — Amolecimento e edema da cartilagem. Superfície íntegra.\n• Grau II — Fibrilação ou fissura superficial; área ≤1,3 cm.\n• Grau III — Fibrilação profunda até o osso subcondral; área >1,3 cm. \"Aspecto de caranguejo\".\n• Grau IV — Exposição do osso subcondral com erosão. Indicação de procedimento de reparação."},{"id":"jumpers-knee","area":"Joelho","front":"BLAZINA/FERRETTI\n\nQuais são os critérios dessa classificação?\n(Blazina/Ferretti — Tendinose Patelar (Jumper's Knee))","back":"• Estágio 0 — Sem dor.\n• Estágio 1 — Dor só após atividade intensa; sem limitação funcional.\n• Estágio 2 — Dor no início e após atividade; atleta consegue desempenho satisfatório.\n• Estágio 3 — Dor durante a atividade; dificuldade crescente no desempenho.\n• Estágio 4 — Dor durante atividade; impossível competir satisfatoriamente.\n• Estágio 5 — Dor nas atividades diárias; incapaz de praticar esportes em qualquer nível."},{"id":"wiltse-espondilolistese","area":"Coluna","front":"WILTSE\n\nQuais são os critérios dessa classificação?\n(Wiltse — Espondilolistese e Espondilólise)","back":"• Tipo I — Displásica — Anomalias congênitas das facetas de S1 ou L5. Deslizamento de L5 sobre S1 sem defeito de ístimo.\n• Tipo II — Ístmica — Defeito no istmo (pars interarticularis). IIA: fratura de estresse; IIB: pars alongada íntegra; IIC: fratura aguda.\n• Tipo III — Degenerativa — Instabilidade intersegmentar crônica com remodelação das facetas. Comum em L4–L5, adultos >50 anos.\n• Tipo IV — Traumática — Fratura aguda em áreas do arco posterior (exceto istmo): pedículo, lâmina ou faceta.\n• Tipo V — Patológica — Fraqueza óssea generalizada ou localizada (osteogênese imperfeita, tumor, Paget).\n• Tipo VI — Iatrogênica — Pós-cirurgia com desestabilização do segmento (adicionada posteriormente)."},{"id":"winter-cifose","area":"Coluna","front":"WINTER\n\nQuais são os critérios dessa classificação?\n(Winter — Cifose Congênita)","back":"• Tipo I — Falha de formação do corpo vertebral (hémi vertebra, vértebra cunha posterior). Progressão rápida; alto risco neurológico.\n• Tipo II — Falha de segmentação anterior (barra anterior não segmentada). Progressão lenta mas constante.\n• Tipo III — Falha mista: formação + segmentação. Comportamento variável; geralmente grave."},{"id":"tubs-ambrii","area":"Ombro e Cotovelo","front":"TUBS/AMBRII\n\nQuais são os critérios dessa classificação?\n(TUBS / AMBRII — Instabilidade Glenoumeral)","back":"• TUBS — Traumática — Traumática · Unidirecional · Bankart · Cirurgia. Evento único violento → lesão de Bankart → instabilidade anterior. Indicação cirúrgica após 1–2 recidivas.\n• AMBRII — Atraumática — Atraumática · Multidirecional · Bilateral · Reabilitação · Capsuloplastia Inferior (Inferior capsular shift) · Intervalo dos rotadores. Hiperfrouxidão constitucional → reabilitação como 1ª linha (3–6 meses) → cirurgia se falha."},{"id":"hawkins-talus","area":"Pé e Tornozelo","front":"HAWKINS\n\nQuais são os critérios dessa classificação?\n(Hawkins — Fratura do Colo do Tálus)","back":"• Tipo I — Fratura do colo sem desvio; sem incongruência subtalar, tibiotársica ou talonavicular. Conservador ou fixação percutânea. Risco AVN <10%.\n• Tipo II — Fratura do colo + subluxação ou luxação subtalar. Articulação tibiotársica e talonavicular preservadas. Mais frequente. RAFI urgente. Risco AVN 20–50%.\n• Tipo III — Fratura do colo + corpo do tálus extruído de ambas as articulações (tibiotársica e subtalar), geralmente posteromedial. RAFI emergência. Risco AVN 80–100%.\n• Tipo IV — (Canale & Kelly 1978) Tipo III + incongruência talonavicular. Todas as 3 articulações comprometidas. Risco AVN muito elevado. Emergência cirúrgica."},{"id":"ruedi-allgower-pilon","area":"Pé e Tornozelo","front":"RÜEDI-ALLGÖWER\n\nQuais são os critérios dessa classificação?\n(Rüedi-Allgöwer — Fratura do Pilão Tibial)","back":"• Tipo I — Fratura intra-articular sem desvio significativo. Articulação íntegra. Fixação percutânea ou conservador com carga protegida.\n• Tipo II — Desvio articular sem cominuição. Redução anatômica viável. RAFI em 2 etapas (fixador temporário → RAFI definitiva após 7–14 dias).\n• Tipo III — Cominuição articular grave com impacção. Redução complexa. RAFI em 2 etapas obrigatória. Risco de artrite pós-traumática elevado."},{"id":"essex-lopresti-calcaneo","area":"Pé e Tornozelo","front":"ESSEX-LOPRESTI\n\nQuais são os critérios dessa classificação?\n(Essex-Lopresti — Fratura do Calcâneo (Morfológica))","back":"• Tipo Língua (Tongue-type) — Linha secundária horizontal (paralela ao osso), criando fragmento em \"língua\". Fixação percutânea possível. ⚠️ Avaliar ameaça cutânea posterior — urgência relativa.\n• Tipo Depressão Articular — Linha secundária entra na faceta posterior criando fragmento em \"die-punch\" (depressão central). Geralmente requer RAFI via extensile lateral ou sinus tarsi."},{"id":"frykman-radio","area":"Mão","front":"FRYKMAN\n\nQuais são os critérios dessa classificação?\n(Frykman — Fratura do Rádio Distal)","back":"• Tipo I / II — Extra-articular. I: sem fratura da ulna distal. II: com fratura da ulna distal.\n• Tipo III / IV — Intra-articular rádio-cárpica. III: sem fratura ulnar. IV: com fratura ulnar.\n• Tipo V / VI — Intra-articular rádio-ulnar distal (RUD). V: sem fratura ulnar. VI: com fratura ulnar.\n• Tipo VII / VIII — Intra-articular rádio-cárpica + RUD. VII: sem fratura ulnar. VIII: com fratura ulnar. Pior prognóstico."},{"id":"tile-pelve","area":"Quadril","front":"TILE\n\nQuais são os critérios dessa classificação?\n(Tile (Pennal-Tile) — Anel Pélvico)","back":"• Tipo A — Estável — A1: avulsão de apófise / asa do ilíaco. A2: fratura mínima do anel com desvio mínimo. Tratamento conservador ou fixação simples.\n• Tipo B — Instável rotatório (vertical estável) — B1: \"open book\" (compressão AP). B2: compressão lateral ipsilateral. B3: compressão lateral contralateral (\"bucket-handle\"). Fixação anterior ± posterior.\n• Tipo C — Instável rotatório e vertical — Ruptura completa do anel anterior e posterior. C1: unilateral. C2: bilateral. C3: associada a fratura do acetábulo. Alta mortalidade — cirurgia de controle de dano."},{"id":"young-burgess-pelve","area":"Quadril","front":"YOUNG-BURGESS\n\nQuais são os critérios dessa classificação?\n(Young-Burgess — Anel Pélvico (por Mecanismo))","back":"• LC I — Compressão Lateral — Fratura sacral impactada ipsilateral. Estável. Conservador ou fixação anterior simples.\n• LC II — Compressão Lateral — Fratura em crescente do ilíaco ou fratura-luxação SI ipsilateral. Fixação posterior + anterior.\n• LC III — \"Pelve varrida\" — LC I ou II ipsilateral + open book contralateral (mecanismo bilateral). Alta energia. Fixação bilateral.\n• APC I — Compressão AP — Abertura da sínfise <2,5cm; ligamentos CC e SI posteriores intactos. Conservador.\n• APC II — Compressão AP — Abertura sínfise + abertura SI anterior; ligamentos SI posteriores intactos. RAFI anterior ± posterior.\n• APC III — Compressão AP — Ruptura completa da articulação SI anterior e posterior. Alta hemorragia. RAFI urgente anterior + pos..."},{"id":"denis-sacro","area":"Coluna","front":"DENIS-SACRO\n\nQuais são os critérios dessa classificação?\n(Denis — Fratura do Sacro (por Zona))","back":"• Zona I — Alar — Lateral aos forames sacros (asa do sacro). Sem comprometimento do canal. Risco neurológico <6%. Tratamento conservador se estável; RAFI se associada a instabilidade pélvica.\n• Zona II — Foraminal — Através dos forames sacros. Risco de lesão das raízes L4–S3 (30–35%). RAFI se instável; exploração neurológica se déficit.\n• Zona III — Canal central — Através do canal central do sacro. Alto risco de lesão da cauda equina e disfunção vesicorretal (60%). RAFI + descompressão quando indicado."},{"id":"occipital-condilo","area":"Coluna","front":"ANDERSON-MONTISANO\n\nQuais são os critérios dessa classificação?\n(Anderson e Montisano — Fratura do Côndilo Occipital)","back":"• Tipo I — Impactação cominutiva por compressão axial. Geralmente estável. Colar cervical.\n• Tipo II — Extensão de fratura da base do crânio até o côndilo. Geralmente estável. Colar cervical.\n• Tipo III — Fratura por avulsão do côndilo pelo ligamento alar. Potencialmente instável — halo ou fusão occipitocervical se instabilidade confirmada."},{"id":"atlanto-occipital-dissociacao","area":"Coluna","front":"TRAYNELIS\n\nQuais são os critérios dessa classificação?\n(Traynelis — Dissociação Atlanto-Occipital)","back":"• Tipo I — Desvio anterior do occipício em relação a C1.\n• Tipo II — Distração longitudinal pura entre occipício e C1.\n• Tipo III — Desvio posterior do occipício em relação a C1."},{"id":"atlas-levine-edwards","area":"Coluna","front":"LEVINE-EDWARDS-C1\n\nQuais são os critérios dessa classificação?\n(Levine e Edwards — Fratura do Atlas (C1))","back":"• Tipo I — Fratura isolada do arco posterior. Estável. Colar cervical.\n• Tipo II — Fratura cominutiva de ambos os arcos, anterior e posterior (fratura de Jefferson). Estabilidade depende da integridade do ligamento transverso.\n• Tipo III — Fratura da massa lateral. Potencialmente instável, sobretudo se bilateral."},{"id":"rotatoria-c1c2-fielding","area":"Coluna","front":"FIELDING-C1C2\n\nQuais são os critérios dessa classificação?\n(Fielding — Subluxação/Luxação Rotatória Atlantoaxial)","back":"• Tipo I — Rotação simples sem desvio anterior; ligamento transverso íntegro (odontóide como pivô). Tração + colar.\n• Tipo II — Desvio anterior de 3–5mm; uma massa articular atua como pivô. Redução seguida de imobilização.\n• Tipo III — Desvio anterior >5mm; ambas as massas articulares deslocadas anteriormente. Redução + fusão se persistir instabilidade.\n• Tipo IV — Desvio posterior — raro, geralmente associado à erosão do odontóide (artrite reumatoide). Instável, requer fusão."},{"id":"hangman-levine-edwards","area":"Coluna","front":"HANGMAN-LEVINE-EDWARDS\n\nQuais são os critérios dessa classificação?\n(Levine e Edwards — Espondilolistese Traumática do Áxis (Fratura do Enforcado))","back":"• Tipo I — Desvio <3mm, sem angulação significativa. Estável. Colar rígido.\n• Tipo II — Desvio significativo + angulação por falha do disco C2–C3. Tração seguida de halo-colete.\n• Tipo IIA — Angulação grave sem translação (mecanismo de flexão-distração). ⚠️ Tração pode agravar a angulação — halo com cautela, sem tração longitudinal.\n• Tipo III — Fratura + luxação facetária bilateral C2–C3. Muito instável — tratamento cirúrgico."},{"id":"allen-ferguson-subaxial","area":"Coluna","front":"ALLEN-FERGUSON\n\nQuais são os critérios dessa classificação?\n(Allen-Ferguson — Lesões da Coluna Cervical Subaxial (C3–C7) por Mecanismo)","back":"• Compressão-flexão (5 estágios) — Falha progressiva do corpo vertebral anterior, do arredondamento simples até o deslizamento do corpo para o canal.\n• Distração-flexão (4 estágios) — Subluxação facetária progressiva até luxação bilateral completa e deslizamento vertebral.\n• Compressão vertical (3 estágios) — Fratura em explosão (burst) da placa terminal com cominuição progressiva do corpo.\n• Compressão-extensão (5 estágios) — Fratura uni ou bilateral do arco posterior/lâmina, progredindo a luxação anterior.\n• Distração-extensão (2 estágios) — Ruptura do disco e ligamento longitudinal anterior, com ou sem deslocamento posterior do corpo.\n• Flexão lateral (2 estágios) — Fratura compressiva assimétrica de um lado com distração/fratura cont..."},{"id":"ota-cervical-subaxial","area":"Coluna","front":"AO-CERVICAL\n\nQuais são os critérios dessa classificação?\n(AO Spine / OTA — Coluna Cervical Subaxial)","back":"• Tipo A — Compressão — A0 sem lesão óssea/discoligamentar relevante; A1 impacção; A2 split; A3 burst incompleto; A4 burst completo.\n• Tipo B — Tensão-banda — Falha em distração, anterior (através do disco) ou posterior (através dos elementos posteriores).\n• Tipo C — Translação/Rotação — Luxação facetária, deslocamento — instabilidade completa nas 3 colunas."},{"id":"mcafee-toracolombar","area":"Coluna","front":"MCAFEE\n\nQuais são os critérios dessa classificação?\n(McAfee — Fraturas Toracolombares (por Mecanismo))","back":"• Compressão em cunha — Coluna média intacta. Estável.\n• Burst estável — Coluna média em compressão; arco posterior íntegro.\n• Burst instável — Coluna média + posterior comprometidas; risco de cifose progressiva.\n• Chance (flexão-distração) — Falha em tensão através das três colunas, geralmente no mesmo nível ósseo ou ligamentar.\n• Flexão-distração translacional — Cisalhamento com luxação — lesão muito instável.\n• Distração em extensão — Falha em tensão anterior (posterior a posterior) por mecanismo de extensão."},{"id":"clavicula-craig","area":"Ombro e Cotovelo","front":"CRAIG-CLAVICULA\n\nQuais são os critérios dessa classificação?\n(Craig (Allman/Neer combinados) — Fratura da Clavícula (Terços))","back":"• Grupo I — Terço médio — Mais comum (~80%). Geralmente tratamento conservador se desvio mínimo.\n• Grupo II — Terço distal — IIA: ligamentos coracoclaviculares íntegros nos dois fragmentos (estável). IIB: ligamentos rotos ou presos apenas no fragmento medial (instável). Variante com traço intra-articular.\n• Grupo III — Terço proximal — Raro. Avaliar lesão intratorácica/mediastinal associada em traumas de alta energia."},{"id":"coracoide-eyres-brooks","area":"Ombro e Cotovelo","front":"EYRES-BROOKS\n\nQuais são os critérios dessa classificação?\n(Eyres, Brooks e Wells — Fratura do Processo Coracóide)","back":"• Tipo I — Fratura na base do processo, próxima à glenóide.\n• Tipo II — Fratura através da curvatura do coracóide.\n• Tipo III — Fratura acima da inserção do ligamento coracoclavicular.\n• Tipo IV — Fratura da ponta do coracóide (avulsão do bíceps/coracobraquial).\n• Tipo V — Fratura do coracóide associada à fratura da glenóide."},{"id":"luxacao-post-ombro-anatomica","area":"Ombro e Cotovelo","front":"LUX-POST-OMBRO\n\nQuais são os critérios dessa classificação?\n(Classificação Anatômica — Luxação Glenoumeral Posterior)","back":"• Subacromial — Cabeça umeral posicionada posterior ao acrômio. Forma mais comum (>98% dos casos).\n• Subglenóide — Cabeça umeral posterior e inferior à borda da glenóide.\n• Subespinhosa — Cabeça umeral medial à espinha da escápula. Raríssima."},{"id":"umero-diafise-ao","area":"Ombro e Cotovelo","front":"AO-12\n\nQuais são os critérios dessa classificação?\n(AO/OTA 12 — Fratura da Diáfise Umeral)","back":"• Tipo A — Simples — Espiral, oblíqua ou transversa.\n• Tipo B — Cunha — Cunha intacta ou fragmentada.\n• Tipo C — Complexa — Espiral, segmentar ou irregular."},{"id":"intercondilar-riseborough-radin","area":"Ombro e Cotovelo","front":"RISEBOROUGH-RADIN\n\nQuais são os critérios dessa classificação?\n(Riseborough e Radin — Fratura Intercondilar do Úmero Distal)","back":"• Tipo I — Sem desvio entre os côndilos.\n• Tipo II — Desvio sem rotação entre os côndilos (fragmentos em \"T\"/\"Y\" simples).\n• Tipo III — Desvio com rotação dos côndilos no plano frontal.\n• Tipo IV — Cominuição articular grave com ampla separação dos côndilos."},{"id":"condilo-milch","area":"Ombro e Cotovelo","front":"MILCH\n\nQuais são os critérios dessa classificação?\n(Milch — Fratura Condilar do Úmero Distal (Medial/Lateral))","back":"• Tipo I — Traço lateral (ou medial) à crista troclear, que permanece unida à haste umeral. Padrão mais estável.\n• Tipo II — Traço através do sulco/crista troclear, incluindo a crista no fragmento condilar. Instável — risco de luxação em varo/valgo; RAFI."},{"id":"capitulo-hahn-steinthal-kocher-lorenz","area":"Ombro e Cotovelo","front":"HAHN-STEINTHAL/KOCHER-LORENZ\n\nQuais são os critérios dessa classificação?\n(Hahn-Steinthal / Kocher-Lorenz — Fratura do Capítulo)","back":"• Tipo I (Hahn-Steinthal) — Grande fragmento osteocondral com osso subcondral significativo. RAFI com parafusos.\n• Tipo II (Kocher-Lorenz) — Fragmento predominantemente cartilaginoso, com pouco osso subcondral (\"cartilagem descascada\"). Fixação difícil; considerar excisão se pequeno.\n• Tipo III — Cominuição grave do capítulo.\n• Tipo IV (McKee) — Extensão da fratura para a tróclea lateral."},{"id":"coronoide-regan-morrey","area":"Ombro e Cotovelo","front":"REGAN-MORREY\n\nQuais são os critérios dessa classificação?\n(Regan e Morrey — Fratura do Processo Coronóide)","back":"• Tipo I — Avulsão da ponta do coronóide.\n• Tipo II — Fragmento único ou múltiplo envolvendo ≤50% do processo.\n• Tipo III — Fragmento envolvendo >50% do processo. Alto risco de instabilidade do cotovelo — RAFI."},{"id":"olecrano-morrey","area":"Ombro e Cotovelo","front":"MORREY-OLECRANO\n\nQuais são os critérios dessa classificação?\n(Morrey — Fratura do Olécrano)","back":"• Tipo I — Sem desvio, estável. Tratamento conservador (gesso em leve flexão).\n• Tipo II — Com desvio, estável (mecanismo extensor íntegro, sem instabilidade associada). RAFI (banda de tensão ou placa).\n• Tipo III — Com desvio, instável (associada à luxação do cotovelo). RAFI + reparo dos estabilizadores associados."},{"id":"luxacao-cotovelo-descritiva","area":"Ombro e Cotovelo","front":"LUX-COTOVELO\n\nQuais são os critérios dessa classificação?\n(Classificação Descritiva/Cronológica — Luxação do Cotovelo)","back":"• Aguda simples — Sem fratura associada; direção posterior é a mais comum (>80%). Redução fechada + mobilização precoce.\n• Aguda complexa — Associada a fratura (tríade terrível: coronóide + cabeça radial + luxação). RAFI/reconstrução dos estabilizadores.\n• Crônica/recidivante — Instabilidade recorrente por insuficiência ligamentar. Reconstrução do ligamento colateral ulnar.\n• Inveterada (não reduzida) — >3 semanas sem redução. Redução aberta + liberação de partes moles."},{"id":"monteggia-bado","area":"Ombro e Cotovelo","front":"BADO-MONTEGGIA\n\nQuais são os critérios dessa classificação?\n(Bado — Fratura-Luxação de Monteggia)","back":"• Tipo I — Luxação anterior da cabeça do rádio + fratura da diáfise ulnar com angulação anterior. Mais comum (~70%).\n• Tipo II — Luxação posterior/posterolateral da cabeça do rádio + fratura ulnar com angulação posterior.\n• Tipo III — Luxação lateral/anterolateral da cabeça do rádio + fratura da metáfise ulnar. Mais comum em crianças.\n• Tipo IV — Luxação anterior da cabeça do rádio + fraturas do rádio e da ulna no mesmo nível."},{"id":"smith-thomas","area":"Mão","front":"SMITH-THOMAS\n\nQuais são os critérios dessa classificação?\n(Thomas (modificada) — Fratura de Smith do Rádio Distal)","back":"• Tipo I — Extra-articular, transversa. Fratura de Smith clássica (\"Colles reverso\"). Mais comum.\n• Tipo II — Intra-articular, oblíqua dorsal (equivale ao Barton volar invertido).\n• Tipo III — Extra-articular, oblíqua juvenil (através da fise, em crianças)."},{"id":"escafoide-russe","area":"Mão","front":"RUSSE\n\nQuais são os critérios dessa classificação?\n(Russe — Fratura do Escafoide (por Orientação da Linha))","back":"• Horizontal-oblíqua — Linha mais estável; forças de cisalhamento mínimas.\n• Transversa — Orientação intermediária.\n• Vertical-oblíqua — Linha menos estável, maior força de cisalhamento — maior risco de pseudartrose e retardo de consolidação."},{"id":"semilunar-teisen-hjarkbaek","area":"Mão","front":"TEISEN-HJARKBAEK\n\nQuais são os critérios dessa classificação?\n(Teisen e Hjarkbaek — Fratura Isolada do Semilunar)","back":"• Tipo I — Fratura do polo palmar.\n• Tipo II — Fratura do polo dorsal.\n• Tipo III — Fratura transversa do corpo.\n• Tipo IV — Fratura sagital.\n• Tipo V — Cominutiva."},{"id":"falange-distal-kaplan","area":"Mão","front":"KAPLAN\n\nQuais são os critérios dessa classificação?\n(Kaplan — Fratura da Falange Distal)","back":"• Tipo A — Sem desvio.\n• Tipo B — Com desvio/angulação.\n• Tipo C — Intra-articular, com ou sem subluxação.\n• Tipo D — Epifisária (crianças) — associar Salter-Harris."},{"id":"mallet-wehbe-schneider","area":"Mão","front":"WEHBE-SCHNEIDER\n\nQuais são os critérios dessa classificação?\n(Wehbe e Schneider — Fratura em Martelo (Mallet Finger))","back":"• Tipo I — Sem fratura (lesão tendínea pura). Tala em extensão por 6–8 semanas.\n• Tipo II — Fratura com desvio articular <1/3 da superfície, sem subluxação.\n• Tipo III — Fratura com desvio articular ≥1/3, com subluxação volar da falange distal."},{"id":"luxacao-ant-quadril-epstein","area":"Quadril","front":"EPSTEIN\n\nQuais são os critérios dessa classificação?\n(Epstein — Luxação Anterior do Quadril)","back":"• Tipo I — Obturatriz/púbica (superior) — IA sem fratura associada; IB com fratura/impacção da cabeça femoral; IC com fratura do acetábulo.\n• Tipo II — Púbica/obturatriz (inferior) — Subtipos IIA/IIB/IIC análogos ao Tipo I."},{"id":"luxacao-post-quadril-thompson-epstein","area":"Quadril","front":"THOMPSON-EPSTEIN\n\nQuais são os critérios dessa classificação?\n(Thompson e Epstein — Luxação Posterior do Quadril)","back":"• Tipo I — Luxação simples, sem fratura significativa ou com pequeno fragmento da parede posterior.\n• Tipo II — Luxação + fratura de um único e grande fragmento da parede posterior do acetábulo.\n• Tipo III — Luxação + cominuição da parede posterior (com ou sem fragmento maior).\n• Tipo IV — Luxação + fratura do assoalho acetabular.\n• Tipo V — Luxação + fratura da cabeça femoral (associar classificação de Pipkin)."},{"id":"intertrocanterica-boyd-griffin","area":"Quadril","front":"BOYD-GRIFFIN\n\nQuais são os critérios dessa classificação?\n(Boyd e Griffin — Fratura Intertrocantérica)","back":"• Tipo I — Linha simples ao longo da linha intertrocantérica; redução fácil.\n• Tipo II — Linha cominutiva com múltiplos fragmentos corticais; redução mais difícil.\n• Tipo III — Fratura subtrocantérica associada (traço estendendo-se abaixo do pequeno trocanter).\n• Tipo IV — Fratura em qualquer plano com extensão subtrocantérica adicional na diáfise proximal."},{"id":"intertrocanterica-evans","area":"Quadril","front":"EVANS-JENSEN\n\nQuais são os critérios dessa classificação?\n(Evans (Jensen) — Fratura Intertrocantérica por Estabilidade)","back":"• Tipo I — Traço do pequeno trocanter em direção superolateral. Ia sem desvio (estável); Ib com desvio redutível (estável após redução).\n• Tipo I (Ic/Id) — Ic irredutível/cominutiva (instável); Id cominuição em 4 partes (instável).\n• Tipo II (reversa) — Traço em direção oposta (do grande trocanter para inferomedial). Sempre instável."},{"id":"subtrocanterica-fielding","area":"Quadril","front":"FIELDING-SUBTROC\n\nQuais são os critérios dessa classificação?\n(Fielding — Fratura Subtrocantérica)","back":"• Tipo I — Fratura ao nível do pequeno trocanter.\n• Tipo II — Fratura até 2,5cm abaixo do pequeno trocanter.\n• Tipo III — Fratura entre 2,5 e 5cm abaixo do pequeno trocanter."},{"id":"subtrocanterica-seinsheimer","area":"Quadril","front":"SEINSHEIMER\n\nQuais são os critérios dessa classificação?\n(Seinsheimer — Fratura Subtrocantérica)","back":"• Tipo I — Sem desvio (<2mm).\n• Tipo II — 2 fragmentos: IIA transversa; IIB espiral com pequeno trocanter no fragmento proximal; IIC espiral com pequeno trocanter no fragmento distal.\n• Tipo III — 3 fragmentos: IIIA com fragmento em asa de borboleta ligado ao proximal; IIIB ligado ao distal.\n• Tipo IV — Cominutiva, com 4 ou mais fragmentos.\n• Tipo V — Fratura subtrocantérica-intertrocantérica combinada."},{"id":"subtrocanterica-russell-taylor","area":"Quadril","front":"RUSSELL-TAYLOR\n\nQuais são os critérios dessa classificação?\n(Russell-Taylor — Fratura Subtrocantérica (Guia de Fixação))","back":"• Tipo IA — Traço não se estende à fossa piriforme; pequeno trocanter íntegro. Haste intramedular padrão.\n• Tipo IB — Traço não se estende à fossa piriforme; pequeno trocanter comprometido/instável. Haste com parafuso cefálico.\n• Tipo IIA — Traço estende-se à fossa piriforme; parede medial (calcar) íntegra.\n• Tipo IIB — Traço estende-se à fossa piriforme; parede medial comprometida — instabilidade em varo, dificultando haste anterógrada padrão."},{"id":"femur-distal-ao","area":"Trauma Geral","front":"AO-33\n\nQuais são os critérios dessa classificação?\n(AO/OTA 33 — Fratura do Fêmur Distal)","back":"• Tipo A — Extra-articular — A1: simples; A2: cunha metafisária; A3: metafisária complexa.\n• Tipo B — Articular parcial — B1: sagital lateral (côndilo lateral); B2: sagital medial (côndilo medial); B3: coronal (equivale à fratura de Hoffa).\n• Tipo C — Articular completa — C1: articular simples/metafisária simples; C2: articular simples/metafisária complexa; C3: articular complexa."},{"id":"patela-saunders","area":"Joelho","front":"SAUNDERS\n\nQuais são os critérios dessa classificação?\n(Saunders — Fratura da Patela)","back":"• Tipo I — Transversa — Mais comum (~50–80%). RAFI (banda de tensão) se desvio >2–3mm ou degrau articular >2mm.\n• Tipo II — Polo (avulsão) — Fratura do polo superior ou inferior.\n• Tipo III — Vertical (marginal) — Traço vertical, geralmente estável.\n• Tipo IV — Osteocondral — Fragmento osteocondral isolado, frequentemente pós-luxação patelar.\n• Tipo V — Cominutiva (estrelada) — Múltiplos fragmentos, alta energia."},{"id":"luxacao-joelho-descritiva","area":"Joelho","front":"LUX-JOELHO\n\nQuais são os critérios dessa classificação?\n(Classificação Descritiva (Anatômica) — Luxação do Joelho)","back":"• Anterior — Mecanismo de hiperextensão; a mais comum. Alto risco de lesão da artéria poplítea por estiramento.\n• Posterior — Trauma direto na tíbia proximal com o joelho fletido (\"dashboard injury\"). Maior risco de lesão vascular direta (íntima).\n• Lateral — Estresse em valgo; associada a lesão do nervo fibular comum.\n• Medial — Estresse em varo.\n• Rotatória — Posterolateral é a mais grave — pode ser irredutível (botoeira do côndilo femoral medial pela cápsula)."},{"id":"calcaneo-souer-remy","area":"Pé e Tornozelo","front":"SOEUR-REMY\n\nQuais são os critérios dessa classificação?\n(Soeur e Remy — Fratura do Calcâneo (Extra vs. Intra-articular))","back":"• Tipo I — Extra-articular (não envolve a faceta subtalar posterior).\n• Tipo II — Intra-articular, 2 fragmentos.\n• Tipo III — Intra-articular, 3 fragmentos (cominuição moderada).\n• Tipo IV — Intra-articular, 4 ou mais fragmentos (cominuição grave)."},{"id":"calcaneo-extra-articular-anatomica","area":"Pé e Tornozelo","front":"CALCANEO-EXTRA-ART\n\nQuais são os critérios dessa classificação?\n(Classificação Anatômica — Fratura Extra-articular do Calcâneo)","back":"• Processo anterior — Avulsão pelo ligamento bifurcado (entorse em inversão). Frequentemente confundida com entorse de tornozelo.\n• Tuberosidade (avulsão / \"beak fracture\") — Tração pelo tendão do calcâneo; ⚠️ avaliar risco de necrose cutânea posterior — fixação urgente se desvio.\n• Corpo (extra-articular) — Fora da faceta subtalar posterior.\n• Sustentáculo do tálus — Geralmente estável, tratamento conservador.\n• Processo medial — Raro; geralmente conservador."},{"id":"mediotarso-main-jowett","area":"Pé e Tornozelo","front":"MAIN-JOWETT\n\nQuais são os critérios dessa classificação?\n(Main e Jowett — Lesão do Mediopé (Articulação de Chopart))","back":"• Medial/plantar-medial — Força medial; avulsão de pequeno fragmento.\n• Longitudinal — Força axial; fratura-luxação através do complexo naviculocuneiforme.\n• Plantar — Força de flexão plantar; avulsão dorsal.\n• Crush (esmagamento) — Alta energia; cominuição grave, risco de síndrome compartimental do pé.\n• Lateral — Força lateral; impacção do cuboide (\"nutcracker\")."},{"id":"navicular-eichenholtz-levin","area":"Pé e Tornozelo","front":"EICHENHOLTZ-LEVIN\n\nQuais são os critérios dessa classificação?\n(Eichenholtz e Levin — Fratura do Navicular do Tarso)","back":"• Tipo I — Avulsão — Fragmento dorsal, mais comum.\n• Tipo II — Tuberosidade — Fratura da tuberosidade navicular.\n• Tipo III — Corpo — Fratura do corpo do navicular, subtipos por padrão do traço (ver Sangeorzan)."},{"id":"navicular-sangeorzan","area":"Pé e Tornozelo","front":"SANGEORZAN\n\nQuais são os critérios dessa classificação?\n(Sangeorzan — Fratura do Corpo do Navicular)","back":"• Tipo I — Traço no plano coronal, sem angulação do antepé.\n• Tipo II — Traço dorsolateral para plantar-medial, com desvio medial do antepé.\n• Tipo III — Cominuição central/lateral, com abdução do antepé."},{"id":"cuboide-ota","area":"Pé e Tornozelo","front":"OTA-CUBOIDE\n\nQuais são os critérios dessa classificação?\n(OTA — Fratura do Cuboide)","back":"• Extra-articular/avulsão — Geralmente estável, tratamento conservador.\n• Intra-articular simples — Traço único através da articulação.\n• Intra-articular cominutiva (\"nutcracker\") — Compressão entre calcâneo e metatarsais; frequentemente associada à lesão de Chopart/Lisfranc."},{"id":"lisfranc-quenu-kuss-myerson","area":"Pé e Tornozelo","front":"QUENU-KUSS/MYERSON\n\nQuais são os critérios dessa classificação?\n(Quenu-Kuss (modificada por Myerson) — Fratura-Luxação Tarsometatársica (Lisfranc))","back":"• Tipo A — Homolateral/Total — Todos os 5 metatarsais deslocam na mesma direção.\n• Tipo B — Isolada/Parcial — B1: deslocamento medial (1º raio isolado). B2: deslocamento lateral (2º–5º raios).\n• Tipo C — Divergente — Deslocamento em direções opostas (medial e lateral), parcial (C1) ou total (C2)."},{"id":"base-5o-mt-dameron","area":"Pé e Tornozelo","front":"DAMERON\n\nQuais são os critérios dessa classificação?\n(Dameron — Fratura da Base do 5º Metatarsal (Zonas))","back":"• Zona 1 — Avulsão do processo estiloide (tuberosidade). Boa cicatrização; tratamento conservador.\n• Zona 2 (fratura de Jones) — Junção metáfise-diáfise, sem extensão distal à articulação intermetatarsal 4–5. Risco de pseudartrose — considerar fixação em atletas.\n• Zona 3 — Diáfise proximal (fratura de estresse), distal à articulação intermetatarsal. Alto risco de retardo/pseudartrose — fixação frequentemente indicada."},{"id":"halux-mtf-bowers-martin","area":"Pé e Tornozelo","front":"BOWERS-MARTIN\n\nQuais são os critérios dessa classificação?\n(Bowers e Martin — Fratura da Base da Falange Proximal do Hálux)","back":"• Tipo I — Extra-articular.\n• Tipo II — Intra-articular, sem cominuição.\n• Tipo III — Intra-articular, cominutiva."},{"id":"luxacao-1mtf-jahss","area":"Pé e Tornozelo","front":"JAHSS\n\nQuais são os critérios dessa classificação?\n(Jahss — Luxação da 1ª Articulação Metatarsofalângica)","back":"• Tipo I — Placa plantar íntegra, sesamoides não separados; luxação dorsal simples. Redução fechada.\n• Tipo IIA — Ruptura transversa entre os sesamoides, mantendo o ligamento intersesamoideo. Redução fechada difícil.\n• Tipo IIB — Ruptura longitudinal de um sesamoide. Frequentemente irredutível por via fechada — cirurgia aberta."},{"id":"milch-condilo-lateral-pediatrico","area":"Ombro e Cotovelo","front":"MILCH-PED\n\nQuais são os critérios dessa classificação?\n(Milch — Fratura do Côndilo Lateral do Cotovelo (Pediátrica))","back":"• Tipo I — Linha lateral à crista troclear (equivale a Salter-Harris IV); cotovelo permanece estável (articulação úmero-ulnar intacta).\n• Tipo II — Linha através do sulco troclear (equivale a Salter-Harris II); cotovelo pode luxar — mais instável."},{"id":"condilo-medial-kilfoyle-pediatrico","area":"Ombro e Cotovelo","front":"KILFOYLE\n\nQuais são os critérios dessa classificação?\n(Kilfoyle — Fratura do Côndilo Medial do Cotovelo (Pediátrica))","back":"• Tipo I — Fratura incompleta, sem desvio (linha metafisária).\n• Tipo II — Fratura completa, com desvio mínimo em rotação.\n• Tipo III — Fratura completa com desvio e rotação grave do fragmento condilar."},{"id":"transfisaria-delee-pediatrico","area":"Ombro e Cotovelo","front":"DELEE\n\nQuais são os critérios dessa classificação?\n(DeLee — Fratura Transfisária Distal do Úmero (Pediátrica))","back":"• Tipo A — Sem centro de ossificação secundário visível (<2 anos) — diagnóstico difícil, frequentemente confundida com luxação do cotovelo.\n• Tipo B — Com centro de ossificação capitular visível, sem fragmento metafisário.\n• Tipo C — Com pequeno fragmento metafisário medial (sinal de Thurston-Holland).\n• Tipo D — Com fragmento metafisário maior."},{"id":"t-condilar-wilkins-beaty-pediatrico","area":"Ombro e Cotovelo","front":"WILKINS-BEATY\n\nQuais são os critérios dessa classificação?\n(Wilkins e Beaty — Fratura T-condilar do Úmero Distal (Pediátrica))","back":"• Sem desvio — Tratamento com imobilização gessada.\n• Com desvio, sem cominuição — RAFI.\n• Com desvio e cominuição — RAFI complexa; fixador externo se necessário."},{"id":"cabeca-radial-wilkins-pediatrico","area":"Ombro e Cotovelo","front":"WILKINS-RADIO\n\nQuais são os critérios dessa classificação?\n(Wilkins — Fratura da Cabeça/Colo do Rádio (Pediátrica))","back":"• Tipo I — Angulação <30°.\n• Tipo II — Angulação 30–60°.\n• Tipo III — Angulação 60–90°.\n• Tipo IV — Angulação >90° (deslocamento completo)."},{"id":"monteggia-letts-pediatrico","area":"Ombro e Cotovelo","front":"LETTS\n\nQuais são os critérios dessa classificação?\n(Letts — Fratura-Luxação de Monteggia (Pediátrica))","back":"• Tipo A — Fratura em galho verde da ulna + luxação anterior da cabeça radial.\n• Tipo B — Fratura da ulna com angulação anterior + luxação anterior da cabeça radial.\n• Tipo C — Fratura da ulna com angulação posterior + luxação posterior da cabeça radial.\n• Tipo D — Fratura da ulna com angulação lateral + luxação lateral da cabeça radial.\n• Tipo E — Fratura completa de rádio e ulna + luxação da cabeça radial.\n• Tipo F — Fratura do colo radial + fratura da ulna proximal."},{"id":"quadril-pediatrico-delbet","area":"Quadril","front":"DELBET\n\nQuais são os critérios dessa classificação?\n(Delbet — Fratura do Quadril na Criança)","back":"• Tipo I — Transfisária — Com ou sem luxação da epífise. Maior risco de necrose avascular (próximo de 100% se houver luxação associada).\n• Tipo II — Transcervical — Tipo mais comum. Risco de necrose avascular 40–50%.\n• Tipo III — Cervicotrocantérica (basocervical) — Risco de necrose avascular 25–30%.\n• Tipo IV — Intertrocantérica — Menor risco de necrose avascular (<10%)."},{"id":"eminencia-tibial-meyers-mckeever","area":"Joelho","front":"MEYERS-MCKEEVER\n\nQuais são os critérios dessa classificação?\n(Meyers e McKeever — Fratura da Eminência Intercondilar da Tíbia)","back":"• Tipo I — Sem desvio ou desvio anterior mínimo.\n• Tipo II — Desvio anterior parcial, com charneira posterior intacta (\"boca de peixe\"). Redução fechada + imobilização em extensão.\n• Tipo III — Desvio completo, sem contato ósseo. RAFI/fixação artroscópica.\n• Tipo IV — Cominutiva. RAFI."},{"id":"tuberosidade-tibial-watson-jones","area":"Joelho","front":"WATSON-JONES-TT\n\nQuais são os critérios dessa classificação?\n(Watson-Jones — Fratura da Tuberosidade Anterior da Tíbia)","back":"• Tipo I — Pequeno fragmento distal à fise, mínimo desvio.\n• Tipo II — Fratura na junção fise-metáfise, com charneira e desvio proximal.\n• Tipo III — Fratura estende-se através da fise até a articulação (equivale a Salter-Harris III), com desvio."},{"id":"calcaneo-schmidt-weiner-pediatrico","area":"Pé e Tornozelo","front":"SCHMIDT-WEINER\n\nQuais são os critérios dessa classificação?\n(Schmidt e Weiner — Fratura do Calcâneo (Pediátrica))","back":"• Tipo I — Extra-articular — Subtipos A–D por localização (processo anterior, corpo, tuberosidade, sustentáculo). Maioria dos casos (~63%).\n• Tipo II — Intra-articular sem cominuição — Tratamento geralmente conservador.\n• Tipo III — Intra-articular cominutiva — Padrão semelhante ao do adulto; considerar RAFI."},{"id":"periprotetica-quadril-vancouver","area":"Quadril","front":"VANCOUVER\n\nQuais são os critérios dessa classificação?\n(Vancouver — Fratura Periprotética do Quadril (Fêmur))","back":"• Tipo A — Região trocantérica. AG: grande trocanter. AL: pequeno trocanter.\n• Tipo B1 — Ao redor ou logo abaixo da haste; componente estável, osso de boa qualidade. RAFI.\n• Tipo B2 — Ao redor ou logo abaixo da haste; componente solto, estoque ósseo adequado. Revisão da haste + RAFI.\n• Tipo B3 — Ao redor ou logo abaixo da haste; componente solto + perda óssea significativa. Revisão com haste longa/enxerto ou aloenxerto estruturado.\n• Tipo C — Bem distal à ponta da haste, sem afetar a fixação do implante. RAFI convencional."},{"id":"periprotetica-quadril-johansson","area":"Quadril","front":"JOHANSSON\n\nQuais são os critérios dessa classificação?\n(Johansson — Fratura Periprotética do Quadril)","back":"• Tipo I — Proximal à ponta da haste, componente estável.\n• Tipo II — Ao redor da ponta da haste, com desestabilização do implante.\n• Tipo III — Totalmente distal à haste."},{"id":"periprotetica-quadril-cooke-newman","area":"Quadril","front":"COOKE-NEWMAN\n\nQuais são os critérios dessa classificação?\n(Cooke e Newman (modificação de Bethea) — Fratura Periprotética do Quadril)","back":"• Tipo I — Fratura acima do meio da haste.\n• Tipo II — Fratura ao nível ou logo abaixo da ponta da haste.\n• Tipo III — Fratura bem abaixo da ponta da haste, sem envolver o implante."},{"id":"periprotetica-quadril-aaos","area":"Quadril","front":"AAOS-PERIPROT\n\nQuais são os critérios dessa classificação?\n(AAOS — Fratura Periprotética do Quadril)","back":"• Tipo I — Fratura por avulsão (trocantérica).\n• Tipo II — Fratura em espiral ao redor da haste.\n• Tipo III — Fratura transversa/oblíqua ao nível ou distal à ponta da haste.\n• Tipo IV — Fratura cominutiva distal ao componente."},{"id":"periprotetica-joelho-lewis-rorabeck","area":"Joelho","front":"LEWIS-RORABECK\n\nQuais são os critérios dessa classificação?\n(Lewis e Rorabeck — Fratura Periprotética Femoral do Joelho)","back":"• Tipo I — Sem desvio, componente estável. Tratamento conservador (gesso/órtese).\n• Tipo II — Com desvio, componente estável. RAFI.\n• Tipo III — Com desvio, componente solto (com ou sem desgaste). Revisão da artroplastia."},{"id":"periprotetica-joelho-neer-merkel","area":"Joelho","front":"NEER-MERKEL\n\nQuais são os critérios dessa classificação?\n(Neer/Merkel — Fratura Periprotética Femoral Supracondiliana do Joelho)","back":"• Tipo I — Sem desvio significativo.\n• Tipo II — Desvio >1cm ou angulação >5°, sem cominuição grave.\n• Tipo III — Desvio associado a outras lesões (fratura patelar/tibial ipsilateral, luxação de componente protético)."},{"id":"periprotetica-tibial-goldberg","area":"Joelho","front":"GOLDBERG\n\nQuais são os critérios dessa classificação?\n(Goldberg — Fratura Periprotética Tibial do Joelho)","back":"• Tipo I — Platô tibial.\n• Tipo II — Adjacente à haste/quilha do componente.\n• Tipo III — Distal ao implante.\n• Tipo IV — Envolvendo a tuberosidade tibial."},{"id":"periprotetica-ombro-uthscsa","area":"Ombro e Cotovelo","front":"UTHSCSA\n\nQuais são os critérios dessa classificação?\n(University of Texas San Antonio — Fratura Periprotética do Úmero (Ombro))","back":"• Tipo A — Ao redor ou proximal à ponta da haste.\n• Tipo B — Na ponta da haste ou logo abaixo, com pouca extensão distal.\n• Tipo C — Bem distal à ponta da haste."},{"id":"periprotetica-cotovelo","area":"Ombro e Cotovelo","front":"PERIPROT-COTOVELO\n\nQuais são os critérios dessa classificação?\n(Classificação da Fratura Periprotética do Cotovelo)","back":"• Tipo I — Envolvendo apenas o osso, componente estável.\n• Tipo II — Envolvendo o componente, com afrouxamento (haste umeral ou ulnar solta).\n• Tipo III — Perda óssea grave, insuficiente para suportar revisão padrão."},{"id":"melone-radio-distal","area":"Mão","front":"MELONE\n\nQuais são os critérios dessa classificação?\n(Melone — Fratura Intra-articular do Rádio Distal (Complexo Medial))","back":"• Tipo I — Fragmentos minimamente desviados/estáveis; complexo medial íntegro. Tratamento conservador com imobilização gessada.\n• Tipo II — Complexo medial desviado (\"die-punch\"), com impactação articular. IIA redutível (RAFI); IIB irredutível/cominutiva (fixador externo + RAFI limitada).\n• Tipo III — Como o Tipo II + fragmento em \"espícula\" que se estende proximalmente pela diáfise, com risco de lesão neurovascular/tendínea. RAFI com placa volar + fixação da espícula.\n• Tipo IV — Fragmentos do complexo medial totalmente rodados (dorsomedial e palmar-medial separados/rodados) — fratura em 4 partes, a mais instável. RAFI complexa ou fixador externo em ponte."},{"id":"luxacao-esternoclavicular","area":"Ombro e Cotovelo","front":"LUX-ESTERNOCLAV\n\nQuais são os critérios dessa classificação?\n(Classificação Anatômica — Luxação Esternoclavicular)","back":"• Anterior (mais comum) — Extremidade medial da clavícula desvia anterior/anterossuperiormente ao esterno. Tratamento: redução fechada; pequena deformidade residual é geralmente aceitável.\n• Posterior (rara, potencialmente grave) — Extremidade medial desvia posterior/superiormente; risco de compressão mediastinal (dispneia, disfagia, parestesias). ⚠️ TC de tórax é o exame de escolha. Redução fechada sob anestesia geral; cirurgia aberta se falhar (via difícil, risco de lesão de grandes vasos)."},{"id":"galeazzi","area":"Mão","front":"GALEAZZI\n\nQuais são os critérios dessa classificação?\n(Fratura de Galeazzi — Fratura do Rádio com Luxação Radioulnar Distal)","back":"• Fratura + luxação da RUD — Fratura do terço distal (raramente médio) da diáfise do rádio associada a luxação/subluxação da articulação radioulnar distal (RUD). Também chamada \"fratura reversa de Monteggia\" ou \"fratura de necessidade\" (fixação interna é essencial). Tratamento: RAFI obrigatória (placa de compressão dinâmica) — tratamento conservador tem alta taxa de falha; a RUD geralmente se estabiliza após a fixação do rádio."},{"id":"instabilidade-carpal-disi-visi","area":"Mão","front":"DISI/VISI\n\nQuais são os critérios dessa classificação?\n(DISI/VISI — Instabilidade Carpal (Segmento Intercalado))","back":"• DISI (dorsal) — Translação volar do semilunar com perda do ritmo escafo-semilunar (semilunar \"estende\" quando o escafoide \"flete\"). Mecanismo mais comum (força trans-escafoide ou trans-escafolunar). Ângulo escafolunar >70° (normal 30–60°). Tratamento: geralmente cirúrgico — redução + reparo ligamentar escafolunar + fixação com fios-K; artrodese limitada se instabilidade crônica.\n• VISI (volar) — Menos comum; força ulnar dirigida radialmente causa falha do ligamento semilunar-piramidal e colapso do piramidal. Tratamento: reparo ligamentar; princípios semelhantes ao DISI."},{"id":"luxacao-polegar-ucl-gamekeeper","area":"Mão","front":"GAMEKEEPER\n\nQuais são os critérios dessa classificação?\n(Lesão do Ligamento Colateral Ulnar do Polegar (\"Polegar do Guarda-Caça\"/do Esquiador))","back":"• Ruptura parcial — Instabilidade discreta ao estresse em valgo da metacarpofalângica. Tratamento: imobilização tipo \"spica\" em leve flexão por 4–6 semanas.\n• Ruptura completa (± lesão de Stener) — Instabilidade franca; a aponeurose do adutor do polegar pode interpor-se entre as extremidades rotas (lesão de Stener), impedindo a cicatrização espontânea. Tratamento: sutura cirúrgica direta.\n• Fratura por avulsão associada — Se >25% da superfície articular da base da falange proximal: fixação com fio-K além da sutura ligamentar."},{"id":"luxacao-ip-mao-descritiva","area":"Mão","front":"LUX-IP-MAO\n\nQuais são os critérios dessa classificação?\n(Classificação Descritiva — Luxação Interfalângica da Mão (PIP/DIP))","back":"• Dorsal (mais comum) — Mecanismo de hiperextensão + compressão axial (esportes). Tratamento: redução fechada por tração longitudinal (bloqueio digital) + \"neighbour strapping\" por 2–3 semanas; mobilização precoce para evitar rigidez.\n• Volar — Mecanismo de hiperflexão. Mesma abordagem inicial; avaliar integridade do mecanismo extensor central (risco de deformidade em botoeira se negligenciada).\n• Com fratura articular associada — Fragmento grande: tala bloqueadora em extensão para prevenir subluxação dorsal recorrente; RAFI (fios-K/miniparafusos) se instável — resultados cirúrgicos menos previsíveis; fusão pode ser necessária em casos refratários."},{"id":"lesao-mecanismo-extensor-joelho","area":"Joelho","front":"MEC-EXTENSOR-JOELHO\n\nQuais são os critérios dessa classificação?\n(Lesão do Mecanismo Extensor do Joelho (Tendão Quadricipital/Patelar))","back":"• Ruptura parcial/incompleta — Extensão ativa do joelho (elevação da perna estendida) preservada, ainda que dolorosa. Tratamento: imobilização gessada em extensão por 4–6 semanas.\n• Ruptura completa — Perda da extensão ativa do joelho; patela alta (ruptura do tendão patelar) ou baixa/\"baja\" (ruptura do quadricipital). Tratamento: reparo cirúrgico término-terminal precoce com sutura não absorvível ± cerclagem de proteção; imobilização gessada 4–6 semanas + reabilitação intensiva."},{"id":"sindromes-medulares-incompletas","area":"Coluna","front":"SÍNDROMES-MEDULARES\n\nQuais são os critérios dessa classificação?\n(Síndromes Medulares Incompletas (Padrão Anatômico da Lesão Medular))","back":"• Síndrome de Brown-Séquard — Hemissecção medular: paralisia motora ipsilateral + perda contralateral de dor/temperatura. Prognóstico relativamente favorável — maioria recupera alguma função motora e sensitiva.\n• Síndrome medular anterior — Paralisia motora completa + perda de dor/temperatura bilateral abaixo da lesão; propriocepção/vibração (colunas posteriores) preservadas. Pior prognóstico — apenas 10–15% recuperação significativa.\n• Síndrome medular central — Mais comum; maior comprometimento dos membros superiores (fraqueza flácida das mãos) que dos inferiores; comum em espondilose cervical prévia (mecanismo de hiperextensão). Prognóstico: 50–60% recuperação satisfatória, mas função da mão frequentemente permanece prejudicada.\n• Sín..."},{"id":"padroes-heranca-mendeliana","area":"Pediátrica","front":"HERANÇA\n\nQuais são os critérios dessa classificação?\n(Padrões de Herança — Doenças Genéticas Mendelianas e Atípicas)","back":"• Autossômica Dominante — Um alelo mutado já expressa o fenótipo; aparece em toda geração, ambos os sexos afetados igualmente, pai/mãe afetados transmitem a ambos os sexos. Ex.: osteogênese imperfeita, displasia espondiloepifisária, Marfan, Charcot-Marie-Tooth IA/IB, neurofibromatose 1.\n• Autossômica Recessiva — Necessita dos dois alelos mutados; doença surge em filhos de pais fenotipicamente normais (portadores), afeta ambos os sexos, mais frequente em consanguinidade. Típica de genes que codificam enzimas.\n• Ligada ao X Dominante — Homens afetados transmitem a todas as filhas (nunca a filhos); mulheres afetadas transmitem a metade dos filhos de qualquer sexo, com expressão mais branda por inativação aleatória do X. Ex.: síndrome de Ret..."},{"id":"classificacao-funcional-genes-ortopedicos","area":"Pediátrica","front":"GENES I-VI\n\nQuais são os critérios dessa classificação?\n(Classificação Funcional por Tipo de Gene — Distúrbios Genéticos Ortopédicos)","back":"• I. Genes Estruturais — Defeito em proteínas estruturais do tecido conjuntivo; fenótipo evolui com o tempo/uso mecânico (exceto OI grave). Ex.: osteogênese imperfeita (colágeno I), Marfan (fibrilina), displasia espondiloepifisária (colágeno II). Geralmente autossômica dominante.\n• II. Genes de Controle Celular (relacionados a tumor) — Predispõem a crescimento tecidual anormal e neoplasia; deformidade óssea progride rapidamente e o tratamento cirúrgico precoce previne deformidade grave. Ex.: neurofibromatose, exostose múltipla. Autossômica dominante (herança variável possível).\n• III. Genes de Padronização do Desenvolvimento — Erro na formação/padronização óssea; achados presentes ao nascimento (ou intraútero) e pioram conforme o osso an..."},{"id":"segmento-encurtamento-displasia-esqueletica","area":"Pediátrica","front":"RMA\n\nQuais são os critérios dessa classificação?\n(Classificação por Segmento Acometido — Encurtamento de Membro nas Displasias Esqueléticas)","back":"• Rizomélica — Encurtamento do segmento proximal do membro (úmero/fêmur).\n• Mesomélica — Encurtamento do segmento médio do membro (antebraço/perna).\n• Acromélica — Encurtamento do segmento distal do membro (mãos/pés)."},{"id":"img-modalidade-pediatrica","area":"Pediátrica","front":"IMG-PED\n\nQuais são os critérios dessa classificação?\n(Seleção de Modalidade de Imagem em Ortopedia Pediátrica — Guia por Cenário Clínico)","back":"• Suspeita de displasia do desenvolvimento do quadril (DDH) — Ultrassonografia do quadril é o exame de escolha em lactentes <4-6 meses (antes da ossificação da cabeça femoral); avalia morfologia (método estático de Graf) e estabilidade (manobras dinâmicas de Harcke). Radiografia torna-se o método preferido após ossificação do núcleo (~4-6 meses).\n• Suspeita de osteomielite/artrite séptica — RM é o método de escolha (alta sensibilidade para edema medular, abscesso subperiosteal/de partes moles). Cintilografia óssea trifásica é alternativa útil quando há dor mal localizada ou suspeita multifocal (torna-se positiva 24-72h antes da radiografia simples).\n• Dor/claudicação com radiografia normal (fratura oculta, \"toddler's fracture\") — Cintilo..."},{"id":"cintilografia-trifasica-padroes","area":"Pediátrica","front":"CINT-3F\n\nQuais são os critérios dessa classificação?\n(Cintilografia Óssea Trifásica — Padrões de Captação por Diagnóstico)","back":"• Fases do exame — Fase 1 (angiografia radionuclídica, imediata/dinâmica) → Fase 2 (pool sanguíneo, ~5 min) → Fase 3 (óssea tardia, 2-4h). Uma \"quarta fase\" (24h) pode ser acrescentada em insuficiência renal ou depuração de partes moles deficiente.\n• Osteomielite — Captação aumentada nas três fases (hiperemia + remodelação óssea), com atividade persistente na fase óssea tardia — padrão que a diferencia da celulite isolada.\n• Celulite (sem acometimento ósseo) — Captação aumentada apenas nas fases 1 e 2 (angiográfica e de pool sanguíneo), sem atividade focal persistente na fase óssea tardia.\n• Fratura de estresse — Padrão fusiforme de captação focal aumentada na fase óssea tardia; cintilografia já positiva no momento da apresentação clínic..."},{"id":"perfil-rotacional-staheli","area":"Pediátrica","front":"PERFIL ROT.\n\nQuais são os critérios dessa classificação?\n(Perfil Rotacional (Staheli) — Avaliação das Deformidades Torcionais dos MMII)","back":"• Ângulo de progressão do passo — Ângulo entre o eixo do pé e a linha de marcha; normal de 15° de rotação interna a 25° de rotação externa.\n• Rotação interna/externa do quadril (decúbito ventral) — Avalia a torção/anteversão femoral; normal RI 20–80°, RE 25–80°. RI maior que RE sugere aumento da anteversão femoral.\n• Ângulo coxa-pé (thigh-foot angle) — Paciente em decúbito ventral, joelho a 90°; mede a torção tibial; normal de 25° interno a 25° externo.\n• Exame do pé — Documenta deformidades associadas (ex.: metatarso aduzido) que contribuem para o quadro rotacional."},{"id":"ortolani-barlow-galeazzi","area":"Pediátrica","front":"ORTOLANI/BARLOW\n\nQuais são os critérios dessa classificação?\n(Manobras de Ortolani e Barlow (+ Sinal de Galeazzi) — Exame do Quadril no RN/Lactente (DDH))","back":"• Manobra de Ortolani (\"sinal de entrada\") — Quadril e joelho fletidos a 90°; abduz-se o quadril com pressão anterior sobre o trocânter maior. Um \"clunk\" de redução do quadril luxado = teste positivo.\n• Teste provocativo de Barlow (\"sinal de saída\") — Com o quadril aduzido, aplica-se pressão posterolateral sobre a face medial da coxa. \"Clunk\" ou deslizamento posterior do fêmur = quadril instável/subluxável.\n• Sinal de Galeazzi — Quadris e joelhos fletidos a 90°; joelho mais baixo do lado acometido indica discrepância de comprimento femoral por DDH unilateral.\n• Janela de validade — Ortolani/Barlow tornam-se negativos após ~3 meses de vida (contraturas de adutores/flexores já instaladas); a partir daí, achado mais comum passa a ser abduçã..."},{"id":"teste-sinal-trendelenburg","area":"Pediátrica","front":"TRENDELENBURG\n\nQuais são os critérios dessa classificação?\n(Teste (Sinal) de Trendelenburg — Insuficiência dos Abdutores do Quadril)","back":"• Técnica — Paciente em apoio unipodal; o examinador palpa/observa as cristas ilíacas.\n• Teste negativo (normal) — A crista ilíaca contralateral se eleva, indicando contração eficaz dos abdutores do quadril de apoio.\n• Teste positivo — A crista ilíaca contralateral cai (ou o tronco desloca sobre o quadril de apoio) — fraqueza dos abdutores (DDH, Perthes, coxa vara, distrofia muscular) OU quadril irritado/doloroso (paciente evita contrair os abdutores por dor)."},{"id":"metatarso-aduzido-linha-bissetriz","area":"Pediátrica","front":"MTA — LINHA CALCÂNEO\n\nQuais são os critérios dessa classificação?\n(Metatarso Aduzido — Classificação pela Linha Bissetriz do Calcâneo)","back":"• Normal — Linha bissetriz do calcâneo (centrada no calcâneo, paralela ao seu eixo) cruza entre o 2º e o 3º raio.\n• Leve — Linha cruza o 3º raio.\n• Moderado — Linha cruza entre o 3º e o 4º raio.\n• Grave — Linha cruza o 4º ou o 5º raio.\n• Flexibilidade — Flexível se corrige além do eixo neutro à abdução passiva do antepé; rígido se não corrige."},{"id":"criterios-kocher-artrite-septica","area":"Pediátrica","front":"KOCHER\n\nQuais são os critérios dessa classificação?\n(Critérios de Kocher — Artrite Séptica x Sinovite Transitória do Quadril)","back":"• 1 ponto para cada preditor presente — Incapacidade de sustentar peso; febre >38,5°C; VHS >40 mm/h; leucocitose >12.000/mm³.\n• Probabilidade de artrite séptica — 0 preditor ≈ <2%; 1 ≈ 3%; 2 ≈ 40%; 3 ≈ 93%; 4 ≈ ~99%.\n• Uso clínico — Auxilia a decisão de puncionar o quadril sob guia fluoroscópica/USG quando a suspeita clínica de artrite séptica é intermediária ou alta."},{"id":"escala-mrc-forca-muscular","area":"Pediátrica","front":"MRC 0-5\n\nQuais são os critérios dessa classificação?\n(Medical Research Council — Escala de Graduação de Força Muscular)","back":"• Grau 0 — Nenhuma contração muscular visível ou palpável.\n• Grau 1 — Esboço de contração (visível/palpável), sem movimento articular.\n• Grau 2 — Movimento ativo completo com a gravidade eliminada.\n• Grau 3 — Movimento ativo completo contra a gravidade, sem resistência adicional.\n• Grau 4 — Movimento ativo completo contra gravidade e resistência parcial.\n• Grau 5 — Força normal — movimento contra resistência plena."},{"id":"bleck-prognostico-marcha","area":"Pediátrica","front":"BLECK\n\nQuais são os critérios dessa classificação?\n(Escore de Bleck — Prognóstico de Marcha em Criança com Atraso Motor)","back":"• 1 ponto para cada reflexo primitivo ainda presente (além de 10 meses) — Moro, preensão palmar, endireitamento cervical, tônico-cervical simétrico, tônico-cervical assimétrico.\n• 1 ponto para cada reflexo postural ainda ausente — Reação de paraquedas; reação de posicionamento do pé (foot-placement).\n• Escore 0 — Bom prognóstico de marcha.\n• Escore 1 — Prognóstico reservado (pode vir a caminhar).\n• Escore ≥2 — Mau prognóstico para marcha independente."},{"id":"teste-bloco-coleman","area":"Pediátrica","front":"COLEMAN\n\nQuais são os critérios dessa classificação?\n(Teste do Bloco de Coleman — Flexibilidade do Retropé Varo no Pé Cavo)","back":"• Técnica — Paciente em pé, de costas para o examinador; observa-se o grau de varo do retropé. Coloca-se um bloco de 2–3 cm sob a face lateral do antepé e o calcanhar, deixando o 1º metatarso \"pendurado\" fora do bloco medialmente (anula o efeito tripé).\n• Retropé flexível — O varo do retropé se corrige ao ficar sobre o bloco — varo secundário ao antepé pronado/1º raio plantarfletido.\n• Retropé rígido — O varo do retropé persiste apesar do bloco — deformidade estrutural fixa da articulação subtalar."},{"id":"adams-escoliometro-atr","area":"Pediátrica","front":"ADAMS/ATR\n\nQuais são os critérios dessa classificação?\n(Manobra de Adams + Escoliômetro — Ângulo de Rotação do Tronco (ATR))","back":"• Técnica — Paciente flete o tronco para frente, mãos unidas, \"como se fosse tocar os pés\"; observa-se a simetria da flexão da coluna.\n• Achado positivo — Assimetria do tronco/giba costal ou lombar visível — um dos testes clínicos mais sensíveis para escoliose.\n• Escoliômetro (ATR) — Mede o ângulo de rotação do tronco (giba) no ápice da curva com o paciente na posição de Adams.\n• Limiar para radiografia — ATR > 7° — a maioria dos autores recomenda radiografias de coluna em PA e perfil."},{"id":"teste-silfverskiold","area":"Pediátrica","front":"SILFVERSKIÖLD\n\nQuais são os critérios dessa classificação?\n(Teste de Silfverskiöld — Contratura de Gastrocnêmio Isolado x Gastrocsóleo)","back":"• Técnica — Mede-se a dorsiflexão máxima do tornozelo (retropé supinado, subtalar travada) primeiro com o joelho em extensão, depois com o joelho fletido a 90°.\n• Resultado positivo (gastrocnêmio isolado) — A dorsiflexão aumenta significativamente com o joelho fletido — contratura isolada do gastrocnêmio, que relaxa quando o joelho fleciona (músculo biarticular).\n• Resultado negativo (gastrocsóleo) — A dorsiflexão permanece limitada mesmo com o joelho fletido — contratura envolve também o sóleo (tríceps sural como um todo)."},{"id":"teste-wilson-ocd-joelho","area":"Pediátrica","front":"WILSON\n\nQuais são os critérios dessa classificação?\n(Teste de Wilson — Osteocondrite Dissecante do Côndilo Femoral Medial)","back":"• Técnica — Joelho fletido a 90° com a tíbia internamente rodada; estende-se gradualmente o joelho.\n• Teste positivo — Dor por volta de 30° de flexão (lesão na face lateral do côndilo femoral medial entra em conflito com a eminência tibial); a dor é aliviada ao rodar a tíbia externamente."},{"id":"graduacao-entorse-colateral-joelho","area":"Pediátrica","front":"GRAU I-III (LCM/LCL)\n\nQuais são os critérios dessa classificação?\n(Graduação da Entorse dos Ligamentos Colaterais do Joelho (LCM/LCL))","back":"• Grau I — Dor à palpação do ligamento; abertura da interlinha ao estresse em valgo/varo de 0-5 mm, com ponto final firme.\n• Grau II — Abertura de 6-10 mm ao estresse em valgo/varo.\n• Grau III — Abertura >10 mm — lesão completa/instabilidade grosseira, sem ponto final firme."},{"id":"nrs-dor-pediatrica","area":"Pediátrica","front":"NRS/ENV\n\nQuais são os critérios dessa classificação?\n(NRS — Escala Numérica de Dor (>12 anos))","back":"• Aplicação — Pergunta-se: \"Numa escala de zero a dez, sendo zero nenhuma dor e dez a pior dor possível, qual seu nível de dor agora?\" Pode ser verbal ou escrita.\n• Faixa etária — Recomendada para crianças e adolescentes acima de 12 anos.\n• Sem dor — Escore 0.\n• Dor leve a moderada — 1-3 = leve; 4-6 = moderada.\n• Dor intensa — 7-10 = grave/intensa."},{"id":"vas-dor-pediatrica","area":"Pediátrica","front":"EVA/VAS\n\nQuais são os critérios dessa classificação?\n(VAS — Escala Visual Analógica de Dor (>8 anos))","back":"• Formato — Linha horizontal de 100 mm; extremo esquerdo = \"sem dor\", extremo direito = \"pior dor possível\", sem marcadores numéricos.\n• Aplicação — Paciente marca um ponto na linha correspondente à intensidade de sua dor.\n• Pontuação — Mede-se a distância em mm do extremo esquerdo até a marcação; escore de 0-100.\n• Faixa etária — Mais apropriada para crianças acima de 8 anos.\n• Variante — Escala análoga de cores (cores mais intensas, ex. vermelho, representam mais dor) pode substituir a linha."},{"id":"wong-baker-faces","area":"Pediátrica","front":"Wong-Baker\n\nQuais são os critérios dessa classificação?\n(Escala de Faces de Wong-Baker (dor autorreferida, 3-12 anos))","back":"• Face 0 — Sorridente — \"sem dor\".\n• Face 2 — Neutra leve — \"dói um pouquinho\".\n• Faces 4-6 — Careta progressiva — \"dói um pouco mais\" / \"dói ainda mais\".\n• Face 8 — Choro — \"dói muito\".\n• Face 10 — Choro intenso — \"dói o máximo que se pode imaginar\"."},{"id":"faces-pain-scale-revised","area":"Pediátrica","front":"FPS-R\n\nQuais são os critérios dessa classificação?\n(FPS-R — Faces Pain Scale-Revised (dor autorreferida, ≥4 anos))","back":"• Estrutura — Seis faces em fileira, sem sorrisos nem lágrimas, variando de expressão neutra a dor intensa (sem choro).\n• Numeração — Faces correspondem a 0, 2, 4, 6, 8, 10 (aproximação da métrica 0-10).\n• Aplicação — Clínico aponta cada face descrevendo a intensidade; a criança escolhe a que melhor representa sua dor.\n• Faixa etária — Validada a partir dos 4 anos de idade.\n• Disponibilidade — Traduzida e validada em mais de 30 idiomas."},{"id":"oucher-scale","area":"Pediátrica","front":"Oucher\n\nQuais são os critérios dessa classificação?\n(Escala de Oucher (dor autorreferida, 3-12 anos))","back":"• Composição — Duas escalas paralelas: uma numérica vertical (0-10) e uma fotográfica com 6 fotos de crianças em diferentes níveis de dor.\n• Escolha da escala — Numérica se a criança sabe contar até 100 de 10 em 10 e identificar o maior entre dois números; caso contrário, usa-se a fotográfica.\n• Versões étnicas — 5 versões: caucasiana, afro-americana, hispânica, indígena norte-americana (menino/menina) e asiática (menino/menina).\n• Conversão — Se usada a escala fotográfica, a foto escolhida é convertida em escore ordinal de 0-5.\n• Faixa etária — Autorrelato validado para crianças de 3 a 12 anos."},{"id":"poker-chip-tool","area":"Pediátrica","front":"Poker Chip\n\nQuais são os critérios dessa classificação?\n(Poker Chip Tool (Pieces of Hurt) — dor autorreferida em pré-escolares)","back":"• Material — 4 fichas vermelhas (\"pedaços de dor\"); algumas versões incluem ficha branca para \"sem dor\".\n• 1 ficha — \"Um pouquinho de dor\".\n• 2 fichas — \"Um pouco mais de dor\".\n• 3 fichas — \"Mais dor ainda\".\n• 4 fichas — \"A pior dor que a criança já sentiu\"."},{"id":"cries-neonatal","area":"Pediátrica","front":"CRIES\n\nQuais são os critérios dessa classificação?\n(CRIES — Escala de Dor Pós-Operatória Neonatal (<1 mês))","back":"• Choro (Crying) — 0=ausente; 1=agudo mas consolável; 2=agudo e inconsolável.\n• Requer O2 p/ SatO2 ≥95% — 0=não; 1=FiO2 30%.\n• Sinais vitais aumentados — 0=FC/PA no basal ou abaixo; 1=aumento 20% do basal.\n• Expressão facial — 0=nenhuma; 1=careta; 2=careta com grunhido.\n• Insônia (Sleepless) — 0=não; 1=acorda com frequência; 2=constantemente acordado."},{"id":"flacc-dor-pediatrica","area":"Pediátrica","front":"FLACC\n\nQuais são os critérios dessa classificação?\n(FLACC — Escala Comportamental de Dor (0-7 anos / não-verbal))","back":"• Face — 0=neutra/sorridente; 1=careta ocasional; 2=tremor de queixo frequente, mandíbula cerrada.\n• Pernas — 0=posição normal/relaxada; 1=inquietas/tensas; 2=chutando ou pernas fletidas.\n• Atividade — 0=deitada quieta/posição normal; 1=contorcendo-se; 2=arqueada, rígida ou com movimentos bruscos.\n• Choro — 0=sem choro; 1=gemidos/choro ocasional; 2=choro constante, grito.\n• Consolabilidade — 0=satisfeita/relaxada; 1=tranquilizada por toque/conversa ocasional; 2=difícil de consolar."},{"id":"cheops-dor-pos-operatoria","area":"Pediátrica","front":"CHEOPS\n\nQuais são os critérios dessa classificação?\n(CHEOPS — Children's Hospital of Eastern Ontario Pain Scale (1-12 anos))","back":"• Choro — Pontuado de 0-3 conforme intensidade (ausente a choro/grito).\n• Facial — Pontuado de 0-3 (sorridente a careta franca).\n• Verbal — Pontuado de 0-3 (fala positiva a queixas de dor).\n• Tronco / Toque / Pernas — Cada domínio pontuado de 0-3 conforme postura, tentativa de tocar o local operado e movimento das pernas.\n• Escore total — Soma dos 6 comportamentos (choro, facial, verbal, tronco, toque, pernas): varia de 4 a 13."},{"id":"comfort-scale-pediatrica","area":"Pediátrica","front":"COMFORT\n\nQuais são os critérios dessa classificação?\n(COMFORT Scale — Dor/Sedação em UTI Pediátrica (RN a 18 anos))","back":"• Domínios comportamentais — Alerta, calma/agitação, movimento físico e tensão facial — cada um pontuado de 1-5.\n• Domínios fisiológicos — Resposta respiratória, pressão arterial média, frequência cardíaca e tônus muscular — cada um pontuado de 1-5.\n• Subescalas — Gera dois subescores: distress comportamental e distress fisiológico.\n• Uso — Criada originalmente para guiar necessidade de sedação em UTI; também usada para avaliar dor pós-operatória em neonatos e lactentes.\n• Faixa etária — Aplicável de recém-nascidos até adolescentes de 18 anos."},{"id":"budapest-criteria-crps","area":"Pediátrica","front":"Budapest\n\nQuais são os critérios dessa classificação?\n(Critérios de Budapest — Diagnóstico Clínico de SDCR/CRPS (tipo I))","back":"• Critério 1 — Dor contínua, desproporcional a qualquer evento desencadeante.\n• Critério 2 (sintomas) — Relato de ≥1 sintoma em 3 das 4 categorias: sensorial (hiperestesia/alodinia); vasomotora (assimetria de temperatura/cor de pele); sudomotora/edema (edema, sudorese assimétrica); motora/trófica (redução de ADM, disfunção motora, alterações de pele/unha/pelo).\n• Critério 3 (sinais) — Presença de ≥1 sinal, no exame atual, em 2 ou mais das 4 categorias acima.\n• Critério 4 — Nenhum outro diagnóstico explica melhor os sinais e sintomas.\n• Aplicação pediátrica — Critérios não validados especificamente em crianças, mas são os mais usados na prática; CRPS tipo I (sem lesão nervosa maior) é a forma mais comum na infância, com predomínio em memb..."},{"id":"yunus-masi-fibromialgia-juvenil","area":"Pediátrica","front":"Yunus-Masi\n\nQuais são os critérios dessa classificação?\n(Critérios de Yunus e Masi para Fibromialgia Juvenil)","back":"• Critérios maiores (todos obrigatórios) — Dor musculoesquelética generalizada em ≥3 sítios por ≥3 meses; ausência de condição subjacente que explique a dor; exames laboratoriais normais; ≥5 dos 18 pontos dolorosos (tender points) ao exame.\n• Critérios menores (parte 1) — Fadiga crônica; sono não reparador/insônia; cefaleia crônica; síndrome do intestino irritável; edema subjetivo de partes moles.\n• Critérios menores (parte 2) — Parestesias/dormência; dor modulada pela atividade física; dor modulada pelo clima; dor modulada por ansiedade/estresse; rigidez articular subjetiva.\n• Pontos dolorosos (18, bilaterais) — Occipital, cervical baixo, trapézio, 2ª costela, escápula, epicôndilo lateral, glúteo, trocânter maior, joelhos mediais.\n• Dia..."},{"id":"acr-fibromialgia-criterios","area":"Pediátrica","front":"ACR\n\nQuais são os critérios dessa classificação?\n(Critérios ACR para Fibromialgia (1990 e 2010) — aplicados à pediatria)","back":"• ACR 1990 — dor difusa — Dor no esqueleto axial (pescoço, dorso ou tórax) associada a dor em pelo menos metade do corpo (lado esquerdo e direito, acima e abaixo da cintura), por ≥3 meses.\n• ACR 1990 — pontos dolorosos — Dor à palpação digital (~4 kg) em ≥11 dos 18 pontos: occipital, cervical lateral, trapézio, supraespinhal, 2ª junção costocondral, epicôndilo lateral, prega glútea, trocânter maior posterior, coxim gorduroso medial do joelho (bilaterais).\n• ACR 2010 — Índice de Dor Generalizada (WPI) — Conta o nº de regiões corporais dolorosas na última semana (mandíbula, ombro, braço, antebraço, quadril/nádega, coxa, perna — 2 pontos se bilateral — mais pescoço, tórax, abdome, dorso superior e inferior); escore 0-19.\n• ACR 2010 — Escala..."},{"id":"beighton-score-hipermobilidade","area":"Pediátrica","front":"Beighton\n\nQuais são os critérios dessa classificação?\n(Escore de Beighton para Hipermobilidade Articular Generalizada)","back":"• 5º dedo (mindinho) — Dorsiflexão passiva >90° — 1 ponto de cada lado (máx. 2).\n• Polegar — Aposição passiva do polegar contra a face flexora do antebraço — 1 ponto de cada lado (máx. 2).\n• Cotovelo — Hiperextensão >10° — 1 ponto de cada lado (máx. 2).\n• Joelho — Hiperextensão >10° — 1 ponto de cada lado (máx. 2).\n• Tronco — Flexão anterior com joelhos estendidos, palmas tocando o chão — 1 ponto."},{"id":"classificacao-hsd","area":"Pediátrica","front":"HSD\n\nQuais são os critérios dessa classificação?\n(Classificação dos Distúrbios do Espectro da Hipermobilidade (HSD))","back":"• HSD generalizado — Hipermobilidade articular generalizada (Beighton positivo) + ≥1 manifestação musculoesquelética secundária.\n• HSD periférico — Hipermobilidade limitada a mãos e pés + ≥1 manifestação musculoesquelética secundária.\n• HSD localizado — Hipermobilidade em articulação(ões) isolada(s)/grupo articular + ≥1 manifestação secundária regional relacionada.\n• HSD histórico — Hipermobilidade generalizada autorreferida no passado (5PQ positivo) + Beighton atual negativo + ≥1 manifestação secundária.\n• Uso clínico — Rótulo para hipermobilidade sintomática que não preenche critérios para nenhum subtipo específico de EDS (incluindo hEDS)."},{"id":"questionario-5-pontos-hipermobilidade","area":"Pediátrica","front":"5PQ\n\nQuais são os critérios dessa classificação?\n(Questionário de 5 Pontos para Hipermobilidade Articular Histórica)","back":"• Pergunta 1 — \"Você consegue (ou já conseguiu) colocar as mãos no chão sem dobrar os joelhos?\"\n• Pergunta 2 — \"Você consegue (ou já conseguiu) dobrar o polegar para tocar o antebraço?\"\n• Pergunta 3 — \"Quando criança, você divertia os amigos contorcendo o corpo em posições estranhas, ou conseguia fazer espacate ('splits')?\"\n• Pergunta 4 — \"Quando criança ou adolescente, seu ombro ou patela luxou mais de uma vez?\"\n• Pergunta 5 — \"Você se considera com os ossos soltos ('double-jointed')?\""},{"id":"raquitismo-mecanismo","area":"Pediátrica","front":"Raquitismo\n\nQuais são os critérios dessa classificação?\n(Raquitismo — Classificação Segundo o Mecanismo Fisiopatológico (Deficiência no Cálcio, Fosfato ou Fosfatase Alcalina))","back":"• Raquitismo nutricional / gastrointestinal (grupo cálcio) — Deficiência de vitamina D e/ou cálcio dietético, ou má-absorção (doença celíaca, Crohn, colestase). Lab: FA alta, Ca baixo-normal, 25-OH-vit D baixa, PTH alto. Tratamento: reposição de vitamina D + cálcio.\n• Raquitismo vitamina D-dependente tipo I e II (grupo cálcio) — Tipo I: deficiência de 1-alfa-hidroxilase (AR), responde a calcitriol em baixa dose. Tipo II: insensibilidade do receptor de vitamina D — 1,25(OH)2D muito elevada e alopecia característica; resposta terapêutica incompleta.\n• Raquitismo hipofosfatêmico ligado ao X (XLH) (grupo fosfato) — Forma hereditária mais comum de raquitismo. Mutação PHEX → excesso de FGF23 → perda renal de fosfato e supressão de 1,25(OH)2D. ..."},{"id":"hipofosfatasia-formas","area":"Pediátrica","front":"Hipofosfatasia\n\nQuais são os critérios dessa classificação?\n(Hipofosfatasia — Classificação por Forma Clínica)","back":"• Forma perinatal — Forma letal, manifestação mais grave, diagnosticada ao nascimento.\n• Forma da infância (childhood) — Apresenta-se com raquitismo aos 2-3 anos de idade; pode haver remissão da doença na adolescência.\n• Forma do adulto — Osteomalácia leve com fraturas patológicas e pseudofraturas.\n• Achado laboratorial-chave — Fosfatase alcalina sérica BAIXA — ao contrário de todas as outras causas de raquitismo, que cursam com FA elevada. Perda precoce de dentes decíduos com mínima reabsorção radicular.\n• Tratamento — Terapia de reposição enzimática com fosfatase alcalina tecido-não-específica recombinante (asfotase alfa/TNSALP) mudou a sobrevida nas formas graves."},{"id":"osteoporose-pediatrica-primaria-secundaria","area":"Pediátrica","front":"Osteoporose 1ª/2ª\n\nQuais são os critérios dessa classificação?\n(Osteoporose na Infância — Classificação em Primária vs. Secundária)","back":"• Primária — Osteogênese Imperfeita — Causa mais comum de osteoporose primária na infância (ver classificação de Sillence).\n• Primária — Síndrome Pseudoglioma-Osteoporose / Osteoporose Idiopática Juvenil (IJO) — Pseudoglioma-osteoporose: AR, mutação LRP5, cegueira congênita + fragilidade óssea tipo OI. IJO: forma esporádica rara, 2-3 anos pré-puberdade, dor lombar/fraturas de ossos longos, remissão espontânea possível após a puberdade.\n• Secundária — nutricional/inflamatória — Anorexia nervosa, doença inflamatória intestinal, artrite idiopática juvenil, escoliose idiopática do adolescente com osteopenia associada.\n• Secundária — neuromuscular — Paralisia cerebral (principalmente não-deambuladores), distrofia muscular de Duchenne — risco ..."},{"id":"osteopetrose-formas","area":"Pediátrica","front":"Osteopetrose\n\nQuais são os critérios dessa classificação?\n(Osteopetrose — Classificação por Forma Clínica)","back":"• Forma infantil (autossômica recessiva, \"maligna\") — Forma mais grave, pode ser fatal na 1ª década. Fraturas patológicas, compressão de nervos cranianos (cegueira, disfunção facial, surdez neurossensorial), pancitopenia e hepatoesplenomegalia por hematopoiese extramedular, nistagmo pesquisante.\n• Forma intermediária — Fenótipo mais grave que a forma adulta, porém sobrevive até a vida adulta. Classificações genéticas emergentes (≥6 tipos) ainda não substituem a classificação clínica.\n• Forma adulta (autossômica dominante, \"benigna\") — Fraturas patológicas e dor surda, baixa estatura leve, testa proeminente. Pode ser achado radiográfico incidental em paciente pouco sintomático.\n• Achados radiográficos comuns a todas as formas — Ossos dens..."},{"id":"skel-dysplasia-padrao-radiografico","area":"Pediátrica","front":"Nosologia\n\nQuais são os critérios dessa classificação?\n(Displasias Esqueléticas — Classificação por Padrão Radiográfico de Acometimento)","back":"• Predomínio epifisário — Displasia epifisária múltipla (MED) — epífises pequenas/fragmentadas; metáfises e coluna poupadas.\n• Predomínio espondiloepifisário — SED congênita, SED tarda, Kniest, pseudoacondroplasia, displasia metatrópica — acometimento vertebral associado ao epifisário.\n• Predomínio metafisário — Condrodisplasias metafisárias (McKusick, Schmid, Jansen, Kozlowski) — irregularidade metafisária com epífises normais.\n• Predomínio diafisário — Displasia diafisária múltipla / exostose múltipla hereditária (EXT1/EXT2) — osteocondromas metafisários múltiplos.\n• Grupo FGFR3 (rizomélico) — Acondroplasia, hipocondroplasia, displasia tanatofórica — mutações no FGFR3; encurtamento rizomélico proximal (úmero/fêmur)."},{"id":"hipocondroplasia-criterios-hall-spranger","area":"Pediátrica","front":"Hall-Spranger\n\nQuais são os critérios dessa classificação?\n(Critérios de Hall e Spranger para Hipocondroplasia)","back":"• Critérios primários (maiores) — Estreitamento dos pedículos lombares, quadratura das asas ilíacas, colos femorais alargados, discreto alargamento metafisário e braquidactilia.\n• Critérios secundários (menores) — Encurtamento dos pedículos lombares, discreto escalope posterior dos corpos vertebrais, alongamento da fíbula distal e estiloide ulnar proeminente.\n• Diferencial-chave vs. acondroplasia — Incisuras isquiáticas normais na hipocondroplasia (são estreitas na acondroplasia).\n• Estenoses associadas — Estenose do forame magno e estenose lombossacra são raras na hipocondroplasia (contrastando com a acondroplasia)."},{"id":"displasia-diastrofica-escoliose-classificacao","area":"Pediátrica","front":"DD\n\nQuais são os critérios dessa classificação?\n(Displasia Diastrófica — Classificação da Escoliose (Remes et al.))","back":"• Precoce progressiva — Início precoce e curva progressiva; maior necessidade de tratamento cirúrgico (fusão posterior, considerar anterior se cifose >50°).\n• Tipo idiopático-símile — Comportamento e progressão semelhantes à escoliose idiopática do adolescente.\n• Leve não progressiva — Curva discreta e estável; geralmente sem necessidade de intervenção cirúrgica."},{"id":"sed-congenita-vs-tarda","area":"Pediátrica","front":"SED\n\nQuais são os critérios dessa classificação?\n(Displasia Espondiloepifisária — Congênita vs. Tarda)","back":"• Herança / gene — Congênita: autossômica dominante (frequente mutação nova), COL2A1. Tarda: mais comum ligada ao X (SEDL/TRAPPC2); também formas AD/AR por COL2A1.\n• Idade de apresentação — Congênita: ao nascimento, nanismo grave (altura adulta 90-125 cm). Tarda: infância tardia/adolescência, estatura pouco reduzida (pode ser ≥152 cm).\n• Achado radiográfico-chave — Congênita: vértebras em \"pera\", coxa vara quase universal (melhor marcador de gravidade). Tarda: platispondilia leve em \"machado\"; coxa vara em minoria.\n• Risco de instabilidade C1-C2 — Ambas apresentam risco por hipoplasia/aplasia do odontoide — rastreamento com radiografia em flexo-extensão obrigatório nas duas formas.\n• Conduta ortopédica — Congênita: cifoescoliose em >50%,..."},{"id":"displasias-instabilidade-cervical-limiares","area":"Pediátrica","front":"C1-C2\n\nQuais são os critérios dessa classificação?\n(Instabilidade Atlantoaxial nas Displasias Esqueléticas — Limiares para Fusão Profilática)","back":"• SED congênita / Kniest — Fundir se espaço disponível para a medula (SAC) 8 mm, ou se sintomático.\n• Pseudoacondroplasia — Fundir se ADI > 8 mm ou SAC < 14 mm; mielopatia é indicação adicional independente dos valores.\n• Displasias metafisárias (McKusick e outras) — Fundir se movimento em flexo-extensão > 8 mm ao raio-x dinâmico.\n• SED tarda / condrodisplasia punctata — Rastrear todos; fundir se instabilidade documentada em flexão ou extensão, mesmo critério da forma congênita/sintomática.\n• Rastreamento geral — Radiografias em flexão-extensão a cada 2-3 anos (displasias de risco) e sempre antes de anestesia geral; RM se odontoide difícil de visualizar ou houver sinais neurológicos."},{"id":"med-subtipos-historicos","area":"Pediátrica","front":"MED\n\nQuais são os critérios dessa classificação?\n(Displasia Epifisária Múltipla — Subtipos Históricos (Ribbing / Fairbank))","back":"• Tipo Ribbing — Forma mais leve, acometimento epifisário discreto, apresentação mais tardia.\n• Tipo Fairbank — Forma mais grave, epífises mais fragmentadas e achatadas, maior impacto funcional e articular."},{"id":"condrodisplasia-punctata-tipos","area":"Pediátrica","front":"CDP\n\nQuais são os critérios dessa classificação?\n(Condrodisplasia Punctata — Classificação por Tipo)","back":"• Tipo dominante ligado ao X (Conradi-Hünermann/Happle) — Forma mais comum; letal em homens. Hipertelorismo, ponte nasal deprimida, ponta nasal bífida, alopecia, malformações cardíacas/renais.\n• Tipo rizomélico (autossômico recessivo) — Deficiência peroxissomal de di-hidroxiacetona-fosfato aciltransferase; microcefalia, catarata congênita, frequentemente fatal no 1º ano de vida.\n• Tipo recessivo ligado ao X — Forma rara, menos caracterizada clinicamente.\n• Outros tipos raros — Ao menos quatro subtipos adicionais descritos na literatura, ainda mais raros que os anteriores."},{"id":"condrodisplasias-metafisarias-tipos","area":"Pediátrica","front":"CDM\n\nQuais são os critérios dessa classificação?\n(Condrodisplasias Metafisárias — Classificação por Tipo)","back":"• Tipo McKusick (displasia cartilagem-cabelo) — Autossômica recessiva (gene RMRP); comum em comunidade Amish. Cabelo fino/escasso, imunodeficiência de células T (risco de varicela grave), anemia, risco aumentado de neoplasias, frouxidão ligamentar de cotovelo, genu varum.\n• Tipo Schmid — Autossômica dominante (COL10A1). Forma mais comum e mais leve; estatura pouco reduzida, face normal, varo leve dos joelhos; diagnóstico diferencial com raquitismo/hipofosfatasia.\n• Displasia metafisária de Jansen — Autossômica dominante (receptor do PTH/PTHrP); hipercalcemia; alterações metafisárias mais pronunciadas que Schmid/McKusick.\n• Tipo Kozlowski (espondilometafisária) — Autossômica dominante; platispondilia leve, cifose progressiva, marcha de Tr..."},{"id":"exostose-multipla-hereditaria-categorias-complicacoes","area":"Pediátrica","front":"HME\n\nQuais são os critérios dessa classificação?\n(Exostose Múltipla Hereditária (Displasia Diafisária Múltipla) — Categorias de Complicações)","back":"• 1. Compressão localizada — Compressão de nervos/vasos/tendões (ex.: paralisia do fibular por exostose lateral, compressão do plexo braquial, pseudoaneurismas); lesões intraespinais em minoria significativa.\n• 2. Crescimento angular — Tethering do osso mais fino de segmento duplo (antebraço/perna), gerando valgo de punho, joelho ou tornozelo; subluxação/luxação da cabeça radial.\n• 3. Discrepância de comprimento dos membros — Membro mais acometido por exostoses pode ficar até 4 cm mais curto que o contralateral.\n• 4. Degeneração maligna — Transformação em condrossarcoma em ~5% dos pacientes após a maturidade esquelética; mais comum em mutações EXT1. Sinal de alerta: crescimento ou dor em exostose já madura — indicar RM."},{"id":"ghent-marfan","area":"Pediátrica","front":"Ghent\n\nQuais são os critérios dessa classificação?\n(Critérios de Ghent (Revisados) — Diagnóstico de Síndrome de Marfan)","back":"• Sem história familiar — critério maior — Dilatação/dissecção de aorta (Z-score ≥2) + ectopia lentis = diagnóstico independente de mutação FBN1.\n• Sem história familiar — alternativa — Dilatação de aorta + mutação FBN1 conhecida; OU dilatação de aorta + escore sistêmico ≥7 pontos (achados esqueléticos/oculares/outros).\n• Com história familiar positiva — Ectopia lentis + história familiar de Marfan; OU escore sistêmico ≥7 + história familiar; OU dilatação de aorta (Z≥2 acima de 20 anos, Z≥3 abaixo) + história familiar.\n• Achados musculoesqueléticos do escore sistêmico — Sinal do polegar, sinal do punho, pectus carinatum, pé plano valgo, protrusão acetabular, escoliose/cifose, perda de extensão do cotovelo.\n• Relevância cirúrgica — Ectasi..."},{"id":"eds-nosology-2017","area":"Pediátrica","front":"EDS 2017\n\nQuais são os critérios dessa classificação?\n(Classificação Internacional 2017 — Síndromes de Ehlers-Danlos (EDS))","back":"• 13 subtipos reconhecidos — Variam conforme o tecido acometido (pele, ligamentos, articulações, olhos, intestino, sistema cardiovascular). 90% dos casos correspondem à EDS clássica (cEDS) ou EDS hipermóvel (hEDS).\n• cEDS — base genética/clínica — Autossômica dominante; >90% associada a mutações COL5A1/COL5A2 (também COL1A1/COL1A2 quando critérios clínicos são preenchidos); hiperextensibilidade cutânea com cicatrizes atróficas + hipermobilidade articular generalizada.\n• hEDS — base genética/clínica — Autossômica dominante, sem marcador molecular confirmado; diagnóstico depende de hipermobilidade articular generalizada pelo escore de Beighton.\n• Escore de Beighton — pontos de corte para hEDS — ≥6 em crianças pré-púberes e adolescentes; ≥5..."},{"id":"sillence-oi","area":"Pediátrica","front":"Sillence\n\nQuais são os critérios dessa classificação?\n(Classificação de Sillence (Modificada) — Osteogênese Imperfeita)","back":"• Tipo I — Deficiência quantitativa de colágeno tipo I; estatura normal/baixa-normal, escleras azuis, fraturas frequentes na infância (reduzem após puberdade), surdez comum. Herança AD.\n• Tipo II — Forma letal perinatal; fêmures curtos e \"amassados\" (accordion-like) ao raio-x; óbito geralmente por insuficiência respiratória associada a fraturas de costela. Herança AD.\n• Tipo III — Forma sobrevivível mais grave; fraturas múltiplas e deformidades progressivas, ossos wormianos no crânio, vértebras em \"boca de peixe\", cifoescoliose grave; maioria evolui para cadeira de rodas. Herança AD.\n• Tipo IV — Gravidade variável, geralmente ambulatorial; estatura baixa, ossos arqueados, fraturas vertebrais, escleras brancas ou levemente azuladas, sem d..."},{"id":"nf1-diagnostic-criteria","area":"Pediátrica","front":"NF1\n\nQuais são os critérios dessa classificação?\n(Critérios Diagnósticos (NIH) — Neurofibromatose Tipo 1)","back":"• Manchas café-com-leite — Seis ou mais, com diâmetro >5 mm em criança ou >15 mm em adulto.\n• Neurofibromas — Dois ou mais neurofibromas de qualquer tipo, ou um neurofibroma plexiforme.\n• Efélides (sardas) — Presentes na região axilar ou inguinal.\n• Achados oculares — Glioma óptico; ou dois ou mais nódulos de Lisch (hamartomas de íris).\n• Lesão óssea distintiva — Escalopamento vertebral, afilamento cortical de osso longo ou outra lesão óssea característica.\n• História familiar — Parente de primeiro grau com NF1 confirmada.\n• Interpretação — Diagnóstico requer ≥2 dos 7 critérios acima."},{"id":"silver-russell-criteria","area":"Pediátrica","front":"SRS\n\nQuais são os critérios dessa classificação?\n(Critérios Diagnósticos (Maiores/Menores) — Síndrome de Silver-Russell)","back":"• Fenótipo clássico — Criança de baixa estatura com face pequena e triangular, proeminência frontal e perímetro cefálico occipitofrontal preservado (macrocefalia relativa).\n• Assimetria de membros — critério menor — Discrepância de comprimento de membros inferiores é achado bem estabelecido e consiste em um dos critérios diagnósticos menores.\n• Clinodactilia — critério menor — Clinodactilia bilateral por hipoplasia da falange média com encurtamento do lado radial; tende a melhorar com o crescimento, sem necessidade de cirurgia.\n• Outras manifestações ortopédicas — Deformidade espinhal (escoliose/cifose em 17%-36%, geralmente padrão idiopático), displasia de quadril, sindactilia de pé/tornozelo, hálux varo.\n• Base genética — Distúrbio de ..."},{"id":"proteus-syndrome-criteria","area":"Pediátrica","front":"Proteus\n\nQuais são os critérios dessa classificação?\n(Critérios Diagnósticos — Síndrome de Proteus)","back":"• Critérios gerais (obrigatórios) — Distribuição em mosaico das lesões, ocorrência esporádica e curso progressivo.\n• Lesão patognomônica — Lesões cerebriformes de tecido conjuntivo.\n• Critérios específicos — esquelético — Supercrescimento assimétrico de membros e crânio; macrodactilia de mãos/pés, frequentemente em dígitos não adjacentes, rapidamente progressiva nos primeiros anos de vida.\n• Critérios específicos — outros sistemas — Disregulação do tecido adiposo, malformações vasculares, cistos pulmonares, anomalias faciais fenotípicas.\n• Neoplasias associadas — Cistadenoma ovariano e adenoma monomórfico de parótida, tipicamente antes dos 20 anos."},{"id":"issva-vascular-anomalies","area":"Pediátrica","front":"ISSVA\n\nQuais são os critérios dessa classificação?\n(Classificação ISSVA — Anomalias Vasculares)","back":"• Distinção fundamental — Tumor vascular (hiperplasia endotelial, cresce na infância e regride) versus malformação vascular (turnover celular normal, cresce proporcionalmente à criança e piora com o tempo).\n• Malformações de baixo fluxo — Capilares, venosas ou linfáticas.\n• Malformações de alto fluxo — Qualquer lesão com envolvimento arterial (fístula arteriovenosa, malformação arteriovenosa).\n• Malformações mistas — Combinação de componentes de baixo e alto fluxo.\n• Relevância ortopédica — Discrepância de comprimento de membros clinicamente significativa (>2 cm) em 7%-15% dos casos, macrodactilia, contraturas articulares e risco aumentado de escoliose — associação particular com CLOVES (supercrescimento lipomatoso congênito, malformaçõe..."},{"id":"gorham-stout-criteria","area":"Pediátrica","front":"Gorham-Stout\n\nQuais são os critérios dessa classificação?\n(Critérios Diagnósticos — Doença de Gorham-Stout)","back":"• Biópsia — Tecido angiomatoso à biópsia, sem atipia celular.\n• Atividade osteoclástica — Ausência de resposta osteoclástica, apesar de reabsorção óssea progressiva.\n• Padrão da lesão — Ausência de lesão expansiva e ausência de envolvimento visceral.\n• Radiografia — Osteólise evidente ao raio-x, sem esclerose ou reação óssea perilesional.\n• Exclusão — Ausência de outra etiologia — metabólica, neoplásica, imunológica ou infecciosa."},{"id":"larsen-atelosteogenesis-subtypes","area":"Pediátrica","front":"Larsen/AO\n\nQuais são os critérios dessa classificação?\n(Subtipos — Síndrome de Larsen e Atelosteogênese)","back":"• Síndrome de Larsen — forma AD — Mutação no gene FLNB (filamina B); luxações de grandes articulações, pé torto, face característica (hipertelorismo, ponte nasal deprimida, face achatada), dedos espatulados (marcante no polegar).\n• Síndrome de Larsen — forma AR — Deficiência de carboidrato sulfotransferase 3 (CHST3); calcâneo duplicado ao raio-x lateral do pé e patela \"de duas camadas\" ao raio-x de joelho são sugestivos.\n• Atelosteogênese tipo I (AO I) — Condrodisplasia letal no período perinatal.\n• Atelosteogênese tipo II (AO II) — Não derivada de mutação FLNB.\n• Atelosteogênese tipo III (AO III) — Forma grave da síndrome de Larsen, também por mutação FLNB; nanismo de membros curtos grave e escoliose."},{"id":"down-c1c4-sac-ratio","area":"Pediátrica","front":"C1/C4 SAC\n\nQuais são os critérios dessa classificação?\n(Razão C1/C4 SAC (Nakamura) — Instabilidade Cervical na Síndrome de Down)","back":"• Método — Radiografia cervical lateral em posição neutra; mede-se o espaço disponível para a medula (SAC) nos níveis de C1 e C4; calcula-se a razão C1/C4.\n• Controles normais — Média de 1,29 (±0,14).\n• Down sem indicação cirúrgica — Média de 1,15 (±0,13).\n• Down submetidos a fusão posterior — Média de 0,63 (±0,1).\n• Limiar de risco — Razão C1/C4 SAC <0,8 associada a maior probabilidade de mielopatia, indicando necessidade de estabilização cirúrgica."},{"id":"distal-arthrogryposis-classification","area":"Pediátrica","front":"DA\n\nQuais são os critérios dessa classificação?\n(Classificação da Artrogripose Distal (DA))","back":"• DA1 — Contraturas articulares predominantemente distais (mãos e pés), sem envolvimento facial ou de outros sistemas orgânicos.\n• DA2A — Síndrome de Freeman-Sheldon — Contraturas faciais, boca pequena em \"assobio\", baixa estatura, escoliose; envolvimento articular distal predominante, com envolvimento proximal variável.\n• DA2B — Síndrome de Sheldon-Hall — Forma intermediária entre DA1 e DA2A, com envolvimento facial mais leve e contraturas predominantemente distais.\n• Base genética — Ao contrário da AMC, as DAs são predominantemente hereditárias; genes envolvidos codificam proteínas do sarcômero (TPM2, TNNI2, TNNT3, MYH3, MYH8, entre outros).\n• Abrangência — Bamshad et al. identificaram 9 formas distintas de DA, com uma 10ª descrita em ..."},{"id":"klippel-trenaunay-parkes-weber","area":"Pediátrica","front":"KTS/PWS\n\nQuais são os critérios dessa classificação?\n(Klippel-Trenaunay × Parkes-Weber — Diferenciação das Malformações Vasculares Combinadas)","back":"• Síndrome de Klippel-Trenaunay (KTS) — Tríade clássica: malformação capilar-venosa cutânea, varizes e hipertrofia óssea/tecidos moles do membro; fluxo lento; AVM ausente ou trivial; sem risco aumentado de tumor de Wilms.\n• Síndrome de Parkes-Weber (PWS) — Mesmo quadro associado a malformação arteriovenosa (shunt de alto fluxo) dominando o quadro; maior risco de insuficiência cardíaca de alto débito e de piora vascular após epifisiodese."},{"id":"proteus-lesoes-cutaneas","area":"Pediátrica","front":"Proteus\n\nQuais são os critérios dessa classificação?\n(Classificação das Lesões Cutâneas na Síndrome de Proteus)","back":"• Tipo 1 — Congênitas — Nevo epidérmico e malformações vasculares presentes ao nascimento; em geral não progridem.\n• Tipo 2 — De início neonatal/tardio — Lipomas e nevo do tecido conjuntivo cerebriforme (patognomônico); surgem após o nascimento com progressão imprevisível; frequentemente atrasam o diagnóstico (confundido com KTS)."},{"id":"hemi-hipertrofia-hipotrofia","area":"Pediátrica","front":"HH\n\nQuais são os critérios dessa classificação?\n(Classificação da Hemi-hipertrofia e Hemi-hipotrofia Congênitas)","back":"• Total — Envolvimento de todos os sistemas orgânicos do lado afetado, não apenas o aparelho locomotor.\n• Limitada — Clássica — Membros superior e inferior ipsilaterais aumentados (ou diminuídos, na hipotrofia).\n• Limitada — Segmentar — Restrita a um único membro.\n• Limitada — Facial — Envolve cabeça e face.\n• Limitada — Cruzada — Membros contralaterais envolvidos (ex.: braço direito e perna esquerda)."},{"id":"upton-macrodactilia","area":"Pediátrica","front":"Upton\n\nQuais são os critérios dessa classificação?\n(Upton — Classificação da Macrodactilia)","back":"• Tipo 1 — Lipofibromatose de nervo periférico — Forma mais comum; subtipo estático (dígito ~1,5× o normal, proporção estável) ou progressivo (crescimento desproporcional contínuo, pode acometer tecido proximal ao dígito).\n• Tipo 2 — Associada à neurofibromatose — Macrodactilia no contexto de neurofibromatose tipo 1.\n• Tipo 3 — Associada à hiperostose — Macrodactilia com hiperostose óssea associada.\n• Tipo 4 — Associada à hemi-hipertrofia — Macrodactilia como manifestação de síndromes de supercrescimento (Proteus, KTS)."},{"id":"patterson-banda-constricao","area":"Pediátrica","front":"Patterson\n\nQuais são os critérios dessa classificação?\n(Patterson — Classificação da Síndrome da Banda de Constrição Congênita (Bandas Amnióticas))","back":"• Tipo 1 — Anel de constrição simples — Sulco anelar sem deformidade distal significativa.\n• Tipo 2 — Anel com deformidade distal — Constrição com deformidade da parte distal ao anel (edema/linfedema, angulação).\n• Tipo 3 — Anel com sindactilia — Sindactilia \"em fenestra\" (fenda entre dígitos proximal e distal ao anel).\n• Tipo 4 — Amputação intrauterina — Amputação congênita completa distal à banda."},{"id":"azouz-arealis-deh","area":"Pediátrica","front":"DEH\n\nQuais são os critérios dessa classificação?\n(Azouz/Arealis — Classificação da Displasia Epifisária Hemimélica (Doença de Trevor))","back":"• Localizada — Envolvimento de uma única epífise.\n• Clássica — Múltiplas epífises de um único membro.\n• Generalizada — Todo o membro inferior envolvido, da pelve ao pé."},{"id":"kaplan-fop-estagios","area":"Pediátrica","front":"FOP\n\nQuais são os critérios dessa classificação?\n(Kaplan — Estágios da Ossificação Heterotópica na Fibrodisplasia Ossificante Progressiva)","back":"• Lesão precoce — Nódulo subfascial eritematoso, doloroso, quente e edemaciado (simula processo infeccioso); pode causar edema exuberante quando em membro.\n• Lesão intermediária — Dor e edema regridem após algumas semanas, mas há aumento da induração dos tecidos moles.\n• Lesão tardia — Massa dura e indolor, já visível radiograficamente por volta de 12 semanas (ossificação endocondral madura)."},{"id":"ackerman-miosite-ossificante","area":"Pediátrica","front":"MO\n\nQuais são os critérios dessa classificação?\n(Ackerman — Zoneamento Histológico da Miosite Ossificante)","back":"• Zona central (interna) — Células indiferenciadas com figuras mitóticas atípicas — pode ser confundida com sarcoma se a biópsia amostrar só esta região.\n• Zona intermediária — Formação de osteoide bem orientado em estroma não neoplásico, com neoformação óssea progressiva.\n• Zona periférica (externa) — Osso lamelar maduro, bem organizado, nitidamente demarcado do tecido adjacente — matura primeiro (padrão centrípeto)."},{"id":"gravidade-hemofilia-wfh","area":"Pediátrica","front":"OMS/WFH\n\nQuais são os critérios dessa classificação?\n(Classificação de Gravidade da Hemofilia (por Atividade do Fator))","back":"• Grave — Atividade do fator < 1%. Sangramentos articulares e de partes moles espontâneos. Corresponde a 43% dos pacientes.\n• Moderada — Atividade do fator 1% a 5%. Sangramento espontâneo incomum, mas hemorragia excessiva e hemartroses ocorrem após trauma menor. Corresponde a 26% dos pacientes.\n• Leve — Atividade do fator 5% a 40%. Sangramento anormal tipicamente só após trauma maior ou cirurgia. Corresponde a 31% dos pacientes."},{"id":"tipos-doenca-von-willebrand","area":"Pediátrica","front":"vWD Tipo 1-3\n\nQuais são os critérios dessa classificação?\n(Classificação da Doença de von Willebrand)","back":"• Tipo 1 — Deficiência quantitativa parcial do fator de von Willebrand (FvW). Forma mais comum (60-80% dos casos), herança autossômica dominante. Sangramento leve: equimoses fáceis, epistaxe prolongada, menorragia.\n• Tipo 2 — Deficiência qualitativa (funcional) do FvW, com múltiplos subtipos (15-30% dos casos). Apresentação semelhante ao tipo 1; alguns subtipos mimetizam hemofilia A por deficiência de fator VIII associada.\n• Tipo 3 — Ausência quase completa do FvW (~5% dos casos). Fator VIII tipicamente 1-5% do normal por proteólise aumentada — quadro clinicamente indistinguível da hemofilia A moderada."},{"id":"tipos-doenca-gaucher","area":"Pediátrica","front":"Gaucher Tipo 1-3\n\nQuais são os critérios dessa classificação?\n(Classificação da Doença de Gaucher)","back":"• Tipo 1 — Forma não neuronopática, de longe a mais comum. Hepatoesplenomegalia, pancitopenia e manifestações esqueléticas predominantes (dor óssea, osteonecrose, fraturas patológicas).\n• Tipo 2 — Forma neuronopática aguda, rara. Envolvimento de SNC e nervos cranianos; geralmente causa óbito por apneia ou aspiração antes dos 2 anos de idade.\n• Tipo 3 — Forma neuronopática subaguda. Sintomas neurológicos, incluindo convulsões, iniciando-se na adolescência."},{"id":"genotipos-doenca-falciforme","area":"Pediátrica","front":"SS/SC/Sβ+/Sβ0\n\nQuais são os critérios dessa classificação?\n(Classificação Genotípica da Doença Falciforme)","back":"• SS (homozigoto) — Herança homozigótica da mutação da hemoglobina S. Toda a hemoglobina é HbS; falcização grave. Maior incidência de osteonecrose.\n• SC — Um alelo de hemoglobina S e um de hemoglobina C. Tendência à falcização atenuada pela HbC.\n• Sβ+ — Um alelo de HbS e um alelo de talassemia-β com síntese de β-globina levemente reduzida. Falcização menos grave.\n• Sβ0 — Um alelo de HbS e um alelo de talassemia-β com síntese de β-globina muito reduzida. Predomínio de HbS; falcização grave, similar ao genótipo SS. Maior incidência de osteonecrose."},{"id":"infarto-vs-osteomielite-falciforme","area":"Pediátrica","front":"Infarto vs OM (SCD)\n\nQuais são os critérios dessa classificação?\n(Diferenciação entre Crise Vaso-Oclusiva/Infarto Ósseo e Osteomielite na Doença Falciforme)","back":"• Epidemiologia — Osteomielite é bem menos comum que crise dolorosa (apenas 1,6% dos internados por dor musculoesquelética grave tinham osteomielite). Salmonella é mais frequente na doença falciforme, mas S. aureus continua sendo o patógeno bacteriano mais comum.\n• História e exame físico — Achados semelhantes nas duas condições; não são discriminatórios. Crise dolorosa raramente cursa com edema ou limitação de movimento marcantes.\n• Laboratório — Leucograma, VHS e PCR são semelhantes nas duas condições e não diferenciam com confiabilidade.\n• Imagem — Radiografia simples raramente é diagnóstica. Ultrassom pode detectar coleção subperiosteal. Cintilografia sequencial (sulfur colloid + MDP) foi descrita para diferenciação, mas sem consistê..."},{"id":"crise-ossea-vs-osteomielite-gaucher","area":"Pediátrica","front":"Crise Óssea vs OM (Gaucher)\n\nQuais são os critérios dessa classificação?\n(Diferenciação entre Crise Óssea (Pseudo-Osteomielite) e Osteomielite na Doença de Gaucher)","back":"• Quadro clínico — Crise óssea: dor óssea aguda com febre, leucocitose e VHS elevada — clinicamente indistinguível de osteomielite (\"pseudo-osteomielite\").\n• Hemocultura — Pode ajudar a diferenciar crise óssea de osteomielite verdadeira.\n• Radiografia — Normal no início da crise; pode evoluir com reação periosteal e radiolucências.\n• Cintilografia/RM — Cintilografia pode mostrar área de hipocaptação no início e hipercaptação periférica tardiamente. RM mostra edema medular em T2, com ou sem sinais de hemorragia. Líquido periosteal na RM sugere infecção e deve ser aspirado sob guia radiográfica estéril.\n• Conduta — Crise óssea é tratada de forma sintomática (opioides ± prednisolona) com melhora em 2-4 semanas. Falha de melhora clínica obri..."},{"id":"ilar-jia-subtipos","area":"Pediátrica","front":"ILAR\n\nQuais são os critérios dessa classificação?\n(Classificação ILAR — Subtipos de Artrite Idiopática Juvenil)","back":"• Oligoartrite — ≤4 articulações nos primeiros 6 meses de doença. Subdividida em persistente (nunca >4 durante todo o curso) ou estendida (>4 após 6 meses). Subtipo mais frequente; joelho é a articulação mais acometida; maior risco de uveíte crônica, sobretudo se FAN+.\n• Poliartrite FR-negativa — ≥5 articulações durante os primeiros 6 meses, fator reumatoide negativo. Acomete grandes e pequenas articulações, incluindo coluna cervical e ATM. FAN+ associa-se a maior risco de uveíte (15-20%).\n• Poliartrite FR-positiva — ≥5 articulações nos primeiros 6 meses + FR IgM positivo em ≥2 ocasiões com intervalo ≥3 meses. Padrão simétrico de pequenas articulações, semelhante à AR do adulto; maior risco de sinovite erosiva precoce e curso destrutivo...."},{"id":"mas-jia-sistemica","area":"Pediátrica","front":"SAM\n\nQuais são os critérios dessa classificação?\n(Critérios para Síndrome de Ativação Macrofágica (SAM) secundária à AIJ Sistêmica)","back":"• Critério de entrada — Criança com AIJ sistêmica confirmada ou suspeita, com febre e ferritina <684 ng/mL.\n• Plaquetas — ≤181 × 10⁹/L (≤181.000/mm³).\n• AST — Aspartato aminotransferase >48 U/L.\n• Triglicerídeos — ≥156 mg/dL.\n• Fibrinogênio — ≤360 mg/dL."},{"id":"nova-york-espondilite-anquilosante","area":"Pediátrica","front":"Nova York\n\nQuais são os critérios dessa classificação?\n(Critérios de Nova York — Espondilite Anquilosante (aplicados à Espondilite Anquilosante Juvenil))","back":"• Critérios clínicos — Limitação da mobilidade lombar nos 3 planos; história ou presença de dor lombar; expansão torácica ≤2,5 cm no 4º espaço intercostal.\n• EA definida — Sacroileíte radiográfica bilateral grau 3-4 + ≥1 critério clínico; OU sacroileíte grau 3-4 unilateral (ou grau 2 bilateral) + critério clínico 1, ou critérios 2 e 3.\n• EA provável — Sacroileíte radiográfica bilateral grau 3-4 presente, sem nenhum critério clínico associado."},{"id":"jones-modificados-febre-reumatica","area":"Pediátrica","front":"Jones\n\nQuais são os critérios dessa classificação?\n(Critérios de Jones Modificados — Febre Reumática Aguda)","back":"• Manifestações maiores — Cardite; poliartrite; nódulos subcutâneos; eritema marginado; coreia.\n• Manifestações menores — Febre; artralgia; intervalo PR prolongado; VHS ou PCR elevados.\n• Regra diagnóstica — 2 critérios maiores, OU 1 maior + 2 menores, com evidência de infecção estreptocócica prévia (título de ASLO em ascensão, cultura de orofaringe positiva ou teste rápido de antígeno positivo).\n• Relevância ortopédica — Artrite migratória de grandes articulações, muito dolorosa, com resposta dramática a AAS/AINEs em horas; principal diagnóstico diferencial de AIJ sistêmica ou poliarticular no pronto-atendimento."},{"id":"triagem-uveite-aij","area":"Pediátrica","front":"Triagem Uveíte\n\nQuais são os critérios dessa classificação?\n(Estratificação de Risco para Frequência de Exames Oftalmológicos na AIJ)","back":"• Alto risco — a cada 3 meses — FAN positivo; oligoartrite, poliartrite FR-negativa ou psoriásica; início ≤6 anos; doença nos primeiros anos de evolução.\n• Risco moderado-alto — a cada 6 meses — FAN positivo com início ≤6 anos e alguns anos de doença; ou início >6 anos nos primeiros anos de doença; ou FAN negativo com início ≤6 anos e doença recente.\n• Risco moderado — a cada 12 meses — FAN positivo com doença de longa data (>7 anos), ou início >6 anos com doença estabelecida (>2 anos).\n• Risco baixo-moderado — a cada 12 meses — FAN negativo com início ≤6 anos e doença de longa duração, ou início >6 anos independentemente da duração.\n• Demais subtipos — a cada 12 meses — Artrite relacionada a entesite (ERA) e AIJ poliarticular FR-positiv..."},{"id":"kocher-quadril-septico","area":"Pediátrica","front":"Kocher\n\nQuais são os critérios dessa classificação?\n(Critérios de Kocher — Artrite Séptica x Sinovite Transitória do Quadril)","back":"• 4 preditores clínicos independentes — História de febre; recusa de sustentar peso (não deambula); VHS ≥40mm/h; leucócitos séricos >12.000/mm³.\n• Probabilidade de artrite séptica (estudo original de Boston) — 1 preditor ≈3,0%; 2 preditores ≈40,0%; 3 preditores ≈93,1%; 4 preditores ≈99,6%.\n• Validação prospectiva (mesma instituição) — 1 preditor ≈9,5%; 2 ≈35,0%; 3 ≈72,8%; 4 ≈93,0% — desempenho diagnóstico bom, porém inferior ao estudo original.\n• Validação externa (Luhmann et al.) — Com os 4 preditores presentes, probabilidade de artrite séptica de apenas ≈59% (versus 99,6% no estudo original) — reforça a necessidade de julgamento clínico local.\n• Critérios adicionais (CHOP) — Cinco fatores — temperatura oral >38,5°C, PCR elevada, VHS el..."},{"id":"criterios-diagnosticos-osteomielite-ped","area":"Pediátrica","front":"Morrey/Peltola\n\nQuais são os critérios dessa classificação?\n(Critérios Diagnósticos de Osteomielite (Morrey-Peterson e Peltola-Vahvanen))","back":"• Osteomielite \"definitiva\" (Morrey-Peterson) — Organismo recuperado do osso ou tecido adjacente, ou evidência histológica de infecção.\n• Osteomielite \"provável\" (probable) — Hemocultura positiva associada a achados clínicos e radiográficos típicos de osteomielite.\n• Osteomielite \"presumida\" (likely) — Achados clínicos e radiográficos típicos com resposta favorável ao antibiótico, na ausência de cultura positiva.\n• Critério de Peltola-Vahvanen (2 de 4) — Diagnóstico firmado quando 2 dos 4 critérios estão presentes: pus aspirado do osso; cultura óssea/sanguínea positiva; dor localizada com edema, calor e limitação de movimento da articulação adjacente; alterações radiográficas típicas."},{"id":"criterios-morrey-artrite-septica","area":"Pediátrica","front":"Morrey\n\nQuais são os critérios dessa classificação?\n(Critérios de Morrey para Artrite Séptica com Cultura Negativa)","back":"• Regra diagnóstica — Presença de 5 dos 6 critérios a seguir permite firmar o diagnóstico mesmo com cultura negativa.\n• Os 6 critérios — Temperatura >38,3°C; dor na articulação afetada, piorando com a movimentação; edema da articulação; sintomas sistêmicos; ausência de outro processo patológico identificável; resposta satisfatória à antibioticoterapia."},{"id":"gledhill-roberts-osteomielite-subaguda","area":"Pediátrica","front":"Gledhill/Roberts\n\nQuais são os critérios dessa classificação?\n(Classificação Radiográfica de Gledhill/Roberts — Osteomielite Subaguda)","back":"• Tipo IA e IB (metafisário) — IA: lesão metafisária \"em saca-bocado\" (punched-out), lembrando granuloma eosinofílico — verdadeiro abscesso de Brodie. IB: semelhante, porém com córtex esclerótico ao redor.\n• Tipo II — Erosão metafisária mais agressiva, podendo envolver o córtex; aspecto agressivo que simula osteossarcoma ou neuroblastoma metastático.\n• Tipo III — Reação cortical e periosteal localizada, simulando osteoma osteoide.\n• Tipo IV — Reação periosteal \"em casca de cebola\" (onionskin) na diáfise, mimetizando sarcoma de Ewing.\n• Tipos V e VI — V: erosão epifisária, podendo cruzar a fise até a metáfise (2º tipo mais comum na infância). VI: acometimento de corpo vertebral."},{"id":"enneking-tumores-musculoesqueleticos","area":"Tumor","front":"Enneking\n\nQuais são os critérios dessa classificação?\n(Enneking — Estadiamento de Tumores Musculoesqueléticos (Benignos e Malignos))","back":"• Benigno — Estágio 1 (latente) — Lesão inativa, margem esclerótica bem definida; frequentemente achado incidental (ex.: fibroma não ossificante, cisto ósseo simples latente distante da fise); geralmente não requer tratamento.\n• Benigno — Estágio 2 (ativo) — Crescimento progressivo lento, dor surda que piora à noite e com atividade; margem ainda definida mas pode expandir o osso (ex.: osteoblastoma, condroblastoma); curetagem/enxerto costuma ser curativa.\n• Benigno — Estágio 3 (agressivo) — Lesão localmente agressiva, pode invadir tecidos vizinhos e cortical (ex.: cisto ósseo aneurismático, tumor de células gigantes); maior taxa de recidiva, exige margem cirúrgica mais ampla.\n• Maligno — Estágio IA / IB (baixo grau) — Grau histológico ba..."},{"id":"ajcc-tumores-osseos-partes-moles","area":"Tumor","front":"AJCC/UICC\n\nQuais são os critérios dessa classificação?\n(AJCC/UICC — Estadiamento TNM de Sarcomas Ósseos e de Partes Moles (8ª edição))","back":"• Grau histológico (G) — G1 = baixo grau; G2 = grau intermediário; G3 = alto grau. É o principal fator prognóstico na ausência de metástase.\n• Extensão/tamanho local (T) — T1 = tumor <8 cm (ósseo) ou <5 cm (partes moles); T2 = tumor ≥8 cm (ósseo) ou ≥5 cm (partes moles). Na 8ª edição, foi dado maior peso à profundidade do tumor.\n• Linfonodos (N) — N0 = sem acometimento linfonodal; N1 = linfonodo regional comprometido (achado incomum, mas descrito em epitelioide, sinovial, rabdomiossarcoma e angiossarcoma).\n• Metástase (M) — M0 = sem metástase; M1 = metástase a distância presente. Metástase ao diagnóstico coloca o paciente automaticamente no estágio de maior risco, independente de G/T/N.\n• Estágios finais — Combinação de G+T+N+M gera 4 es..."},{"id":"gmfcs-pc","area":"Pediátrica","front":"GMFCS\n\nQuais são os critérios dessa classificação?\n(GMFCS — Sistema de Classificação da Função Motora Grossa (Paralisia Cerebral))","back":"• Nível I — Anda em casa, escola, ambientes externos e na comunidade; sobe escadas sem corrimão; corre e pula com limitação de velocidade e equilíbrio. Risco de deslocamento do quadril igual ao da população geral.\n• Nível II — Anda na maioria dos ambientes segurando corrimão em escadas; dificuldade em longas distâncias e terrenos irregulares; pode usar dispositivo de apoio ou mobilidade sobre rodas em trajetos longos. Risco de deslocamento do quadril (MP>30%): 15%.\n• Nível III — Anda com dispositivo de apoio manual (andador/muletas) na maioria dos ambientes externos; usa cadeira de rodas para longas distâncias. Risco de deslocamento do quadril: 41%.\n• Nível IV — Locomoção própria requer assistência física ou mobilidade motorizada na maio..."},{"id":"topografica-pc","area":"Pediátrica","front":"Topográfica\n\nQuais são os critérios dessa classificação?\n(Classificação Topográfica da Paralisia Cerebral (Unilateral x Bilateral))","back":"• Monoplegia — Envolvimento de um único membro, geralmente inferior; ao correr, frequentemente revela postura anormal do membro superior ipsilateral — forma unilateral mais leve.\n• Hemiplegia — Envolvimento de um hemicorpo (membro superior e inferior do mesmo lado); quase todas as crianças deambulam de forma independente na comunidade.\n• Diplegia — Envolvimento bilateral dos membros inferiores, simétrico ou assimétrico, com função dos membros superiores preservada (exceto motricidade fina); associada a prematuridade e leucomalácia periventricular; cerca de 80% deambulam.\n• Quadriplegia — Envolvimento dos quatro membros, geralmente em crianças nascidas a termo com lesão cerebral extensa e distúrbio de movimento misto (espástico + distônic..."},{"id":"disturbio-movimento-pc","area":"Pediátrica","front":"PC-Movimento\n\nQuais são os critérios dessa classificação?\n(Classificação da Paralisia Cerebral por Distúrbio do Movimento)","back":"• Espástica — Subtipo mais comum (~90%); lesão do sistema piramidal com aumento do tônus dependente de velocidade e hiper-reflexia tônica ao estiramento; associada a prematuridade e leucomalácia periventricular; padrão previsível e responsivo à cirurgia ortopédica corretiva.\n• Distônica — Distúrbio extrapiramidal com posturas de torção e movimentos vermiformes variáveis, desencadeados por atenção, susto, esforço, toque ou dor; lesão típica nos núcleos da base; pouco previsível e pouco responsiva à cirurgia ortopédica — pode se beneficiar de bomba de baclofeno intratecal.\n• Mista (espástico-distônica) — Coexistência de componentes piramidais e extrapiramidais no mesmo segmento; comum em crianças a termo com lesões cerebrais extensas; dife..."},{"id":"winters-gage-hemiplegia-pc","area":"Pediátrica","front":"Winters-Gage\n\nQuais são os critérios dessa classificação?\n(Winters-Gage-Hicks — Classificação da Marcha na Hemiplegia Espástica)","back":"• Tipo I — Pé caído na fase de balanço por perda de controle seletivo do tibial anterior, sem contratura do tríceps sural (2º rocker normal). Tratamento: apenas órtese tornozelo-pé (AFO); sem indicação cirúrgica.\n• Tipo II — Espasticidade do tríceps sural evoluindo para contratura fixa e marcha em equino, com 1º e 2º rockers comprometidos. Tratamento: alongamento do tríceps sural + AFO.\n• Tipo III — Contratura do tríceps sural associada a envolvimento do joelho, com co-contração de isquiotibiais e reto femoral. Tratamento: alongamento do tríceps sural + isquiotibiais mediais + transferência do reto femoral.\n• Tipo IV — Comprometimento nos três níveis: equino de tornozelo, rigidez de joelho e extensão incompleta do quadril com adução e ro..."},{"id":"marcha-diplegia-espastica-pc","area":"Pediátrica","front":"Diplegia-Marcha\n\nQuais são os critérios dessa classificação?\n(Sutherland/Rodda-Graham — Classificação da Marcha Sagital na Diplegia Espástica)","back":"• Equino verdadeiro — Marcha na ponta dos pés com quadris e joelhos estendidos; acoplamento flexão plantar-extensão de joelho hiperativo; típico de crianças pequenas iniciando a marcha. Tratamento: toxina botulínica no tríceps sural + AFO articulada.\n• Marcha em salto (jump gait) — Equino de tornozelo associado a extensão incompleta de joelho e quadril; padrão mais comum no pré-adolescente com diplegia; frequentemente beneficiado por cirurgia multinível em evento único (SEMLS).\n• Equino aparente — Marcha na ponta dos pés sem contato de calcanhar, porém com amplitude de tornozelo normal; as contraturas verdadeiras são proximais (joelho/quadril). Risco de alongamento indevido do tríceps sural se não identificado — idealmente confirmado por..."},{"id":"migracao-percentual-reimers-pc","area":"Pediátrica","front":"MP (Reimers)\n\nQuais são os critérios dessa classificação?\n(Índice de Migração de Reimers — Vigilância e Limiares Cirúrgicos do Quadril na PC)","back":"• MP < 30% — Quadril estável; manter vigilância radiográfica de rotina conforme o nível GMFCS, sem indicação cirúrgica.\n• MP 30-40% (progressiva) — Displasia em progressão, confirmada em 2 ou mais radiografias seriadas; considerar cirurgia preventiva de partes moles (liberação de adutores ± iliopsoas), sobretudo em crianças ambulantes GMFCS II-III.\n• MP > 40% — Indicação de cirurgia reconstrutiva (liberação de adutores + osteotomia femoral de varização/derrotação ± osteotomia pélvica), principalmente se persistente por mais de 12 meses após liberação de partes moles, ou como cirurgia índice em criança maior de 8 anos.\n• MP > 50% / luxação estabelecida — Risco de deformidade progressiva da cabeça femoral e do acetábulo, perda de cartilage..."},{"id":"macs-pc","area":"Pediátrica","front":"MACS\n\nQuais são os critérios dessa classificação?\n(MACS — Sistema de Classificação da Habilidade Manual (Paralisia Cerebral))","back":"• Nível I — Manuseia objetos com facilidade e sucesso; limitações apenas em tarefas manuais que exigem velocidade e precisão finas.\n• Nível II — Manuseia a maioria dos objetos, mas com redução de qualidade e/ou velocidade; pode evitar certas atividades ou usar métodos alternativos.\n• Nível III — Manuseia objetos com dificuldade; necessita ajuda para preparar e/ou modificar as atividades.\n• Nível IV — Manuseia apenas objetos previamente selecionados e adaptados, com esforço limitado; requer apoio contínuo.\n• Nível V — Não manuseia objetos; capacidade gravemente limitada mesmo para ações simples; requer assistência total."},{"id":"estadiamento-rang-pc","area":"Pediátrica","front":"Estágios (Rang)\n\nQuais são os critérios dessa classificação?\n(Estadiamento da Patologia Musculoesquelética Progressiva na Paralisia Cerebral (Mercer Rang))","back":"• Estágio 1 — Espasticidade presente, sem contraturas fixas; manejo não operatório (fisioterapia, órteses, toxina botulínica) — primeira «janela terapêutica» para tratar a espasticidade antes da fixação da deformidade.\n• Estágio 2 — Contraturas fixas estabelecidas, ainda sem deformidades ósseas relevantes — segunda «janela terapêutica» para correção de partes moles antes da descompensação.\n• Estágio 3 — Contraturas associadas a deformidades ósseas (torção, instabilidade articular); geralmente requer cirurgia ortopédica corretiva multinível."},{"id":"rm-scpe-pc","area":"Pediátrica","front":"RM-SCPE\n\nQuais são os critérios dessa classificação?\n(Sistema de Classificação por Ressonância Magnética na Paralisia Cerebral (SCPE))","back":"• Malformações — Alterações do desenvolvimento estrutural do encéfalo fetal (~10-15% dos casos); associadas a causas genéticas, teratogênicas ou infecciosas (ex.: citomegalovírus congênito); costumam cursar com comprometimento funcional mais grave e comorbidades.\n• Lesão predominante da substância branca — Padrão mais comum, sobretudo em prematuros (<32 semanas): leucomalácia periventricular/hemorragia intraventricular; associada a PC bilateral ou unilateral de predomínio em membros inferiores, com boas taxas de deambulação.\n• Lesão predominante da substância cinzenta — Inclui lesão hipóxico-isquêmica perinatal a termo e acidente vascular isquêmico arterial perinatal; associada a menores taxas de deambulação e maior comprometimento cogni..."},{"id":"mmc-classificacao-funcional","area":"Pediátrica","front":"MMC\n\nQuais são os critérios dessa classificação?\n(Classificação Funcional da Mielomeningocele (por Nível Neurológico))","back":"• Torácico/lombar alto (L3 ou acima) — ~30% — Ausência de quadríceps funcional (grau ≤2). Para deambular na infância necessita órtese até o quadril (RGO ou HKAFO). 70-99% usam cadeira de rodas na vida adulta pelo alto custo energético. FMS típico 1,1,1.\n• Lombar baixo (L3-L5) — ~30% — Quadríceps e isquiotibiais mediais grau ≥3, porém glúteo médio, glúteo máximo e gastrocsóleo grau ≤2. Necessita AFO e muletas/andador. 80-95% mantêm deambulação comunitária no adulto. FMS típico 3,3,1. L4 tem o maior potencial de ganho com tratamento ortopédico agressivo de quadril, rotação tibial, joelho, tornozelo e pé.\n• Sacral alto (S1-S3) — ~30% — Quadríceps e glúteo médio grau ≥3, mas gastrocsóleo grau ≤2. Deambula sem dispositivos auxiliares, porém n..."},{"id":"fms-mobilidade-funcional","area":"Pediátrica","front":"FMS\n\nQuais são os critérios dessa classificação?\n(Escala de Mobilidade Funcional (Functional Mobility Scale))","back":"• 1 — Usa cadeira de rodas.\n• 2 — Usa andador de forma independente.\n• 3 — Usa muletas de forma independente.\n• 4 — Usa uma ou duas bengalas de forma independente.\n• 5 — Independente em superfícies planas.\n• 6 — Independente em qualquer tipo de superfície.\n• C — Engatinha (crawls) para percorrer a distância avaliada.\n• N — Não completa a distância avaliada."},{"id":"miopatias-congenitas-achados","area":"Pediátrica","front":"MC\n\nQuais são os critérios dessa classificação?\n(Achados Clínicos nas Miopatias Congênitas Clássicas)","back":"• Doença do Core Central (Central Core Disease) — Autossômica dominante, início na infância, curso não progressivo. Envolve tronco e musculatura proximal. Hipotonia e atraso motor; sensibilidade normal. Risco de hipertermia maligna. Achados ortopédicos: escoliose, cifose, contraturas articulares, instabilidade de quadril, pé torto congênito. Prognóstico variável.\n• Miopatia Nemalínica (Rod-Body Myopathy) — Herança autossômica dominante, recessiva ou esporádica. Três formas: neonatal (grave), congênita (moderada) e de início no adulto. Acomete toda musculatura esquelética; hipotonia e atraso de marcos. Risco de hipertermia maligna. Escoliose e lordose lombar. Forma neonatal com mortalidade de 90% até os 3 anos.\n• Miopatia Centronuclear (M..."},{"id":"ame-classificacao-tipos","area":"Pediátrica","front":"AME\n\nQuais são os critérios dessa classificação?\n(Classificação da Atrofia Muscular Espinhal (AME/SMA) por Tipo)","back":"• Tipo 0 — Forma mais grave; manifesta-se intraútero com diminuição dos movimentos fetais. Cardiopatia congênita comum. Fraqueza extrema ao nascer; a maioria morre antes dos 6 meses de vida.\n• Tipo 1 (Doença de Werdnig-Hoffmann) — Forma grave mais encontrada na prática ortopédica; evidente antes dos 6 meses. Responde por mais da metade dos casos novos. Fraqueza intensa, hipotonia, flacidez, sem controle cefálico, dificuldade alimentar, incapaz de sentar sem apoio. Sem tratamento, óbito antes dos 2 anos.\n• Tipo 2 (Doença de Dubowitz) — Apresentação entre 6 e 18 meses. Fraqueza difusa, hipotonia, fraqueza respiratória e atraso de marcos. Senta de forma independente, mas a maioria não fica em pé nem anda sozinha. Sem tratamento, desenvolve ..."},{"id":"conduta-ame-coluna-quadril","area":"Pediátrica","front":"CONDUTA\n\nQuais são os critérios dessa classificação?\n(Conduta Ortopédica na Escoliose e no Quadril da Atrofia Muscular Espinhal)","back":"• Curvas pequenas/flexíveis — Tratamento inicial com órtese TLSO — auxilia suporte de tronco e posicionamento, mas não retarda comprovadamente a progressão da deformidade; pode ser mal tolerada e interferir no esforço respiratório.\n• Indicação de artrodese — Fusão espinhal indicada para curvas progressivas maiores que 50 graus; idealmente adiada até os 10 anos para permitir fusão definitiva. Fusões longas, geralmente até a pelve, para corrigir obliquidade pélvica e reduzir necessidade de nova cirurgia.\n• Crianças pequenas com curvas grandes — Quando cirurgia é necessária antes dos 10 anos, utilizam-se construtos \"growth-friendly\" (crescimento guiado). Cirurgia anterior deve ser evitada pela já diminuída reserva pulmonar.\n• Janela para nu..."},{"id":"dmd-bmd-manejo","area":"Pediátrica","front":"CONDUTA\n\nQuais são os critérios dessa classificação?\n(Conduta Clínica e Ortopédica na Distrofia Muscular de Duchenne/Becker)","back":"• Corticosteroides — Uso crônico reduz inflamação muscular e retarda a progressão da fraqueza, prolonga a deambulação e diminui o risco/progressão da escoliose. Efeitos colaterais: ganho de peso, baixa estatura, osteoporose, alterações comportamentais, catarata.\n• Vigilância cardíaca — Cardiomiopatia dilatada é universal (dystrophin cardíaca ausente); fração de ejeção tipicamente anormal a partir dos 14 anos na DMD. Uso precoce de inibidores da ECA (IECA) é rotina e eficaz. Na BMD, envolvimento sintomático é raro antes dos 16 anos, mas até 70% têm insuficiência cardíaca sintomática aos 40 anos.\n• Vigilância pulmonar — Função pulmonar declina após a perda da deambulação e correlaciona-se com a perda de função do braço; espirometria seriad..."},{"id":"cmt-classificacao","area":"Pediátrica","front":"CMT\n\nQuais são os critérios dessa classificação?\n(Classificação da Doença de Charcot-Marie-Tooth (CMT))","back":"• CMT-1 (5 subtipos, 1A a 1E) — Herança autossômica dominante. Estudo eletrodiagnóstico mostra diminuição da velocidade de condução nervosa motora e sensitiva. Patologia: desmielinização dos axônios nervosos. Representa 70% de todos os casos de CMT; o subtipo 1A (duplicação de PMP22 em 17p11.2-p12) corresponde a 70% do CMT-1 (40% de todo o CMT) e é o subtipo mais comumente encontrado pelo ortopedista pediátrico.\n• CMT-2 (18 subtipos) — Herança autossômica dominante. Velocidade de condução motora normal ou levemente diminuída, com redução da amplitude do CMAP. Patologia: anormalidades neuronais/axonais (perda axonal, e não desmielinização).\n• CMT-X (5 subtipos) — Herança ligada ao X. Discreta lentificação da condução nervosa motora. Patol..."},{"id":"hmsn-classificacao-tipos","area":"Pediátrica","front":"HMSN\n\nQuais são os critérios dessa classificação?\n(Classificação das Neuropatias Motoras e Sensitivas Hereditárias (HMSN))","back":"• HMSN tipo I — Forma hipertrófica da CMT (desmielinizante), início na infância; corresponde ao CMT-1.\n• HMSN tipo II — Forma neuronal da CMT (perda axonal), início na infância, geralmente com fraqueza menos grave e início mais tardio que o tipo I; corresponde ao CMT-2.\n• HMSN tipo III (Doença de Dejerine-Sottas) — Autossômica recessiva, início na infância/lactância; alterações mais graves de condução nervosa e distúrbios sensitivos mais extensos que os tipos I e II; causada por desmielinização.\n• HMSN tipo IV (Doença de Refsum) — Início tardio (idade adulta); caracterizada por acúmulo excessivo de ácido fitânico.\n• HMSN tipo V — Paraplegia espástica hereditária de início tardio, com fraqueza distal de membros a partir da 2ª década, marc..."},{"id":"lgmd-classificacao","area":"Pediátrica","front":"LGMD\n\nQuais são os critérios dessa classificação?\n(Classificação das Distrofias Musculares de Cinturas (LGMD))","back":"• LGMD1 — Formas autossômicas dominantes; podem apresentar envolvimento distal significativo, além do padrão de cinturas. Inclui a forma autossômica dominante da distrofia muscular de Emery-Dreifuss (LGMD1B), com envolvimento cardíaco relevante.\n• LGMD2 — Formas autossômicas recessivas; correspondem a mais de três quartos das LGMDs. CK tipicamente mais elevada que nas formas dominantes."},{"id":"dm1-classificacao-formas","area":"Pediátrica","front":"DM1\n\nQuais são os critérios dessa classificação?\n(Classificação Clínica da Distrofia Miotônica Tipo 1 (Doença de Steinert))","back":"• DM1 Congênita — Forma mais grave; diminuição de movimentos fetais, hipotonia ao nascer, dificuldades respiratórias/alimentares/de deglutição (até necessidade de ventilação mecânica). Envolvimento ortopédico mais severo (equino, pé torto congênito, contraturas, escoliose). Mortalidade de até 20% no primeiro mês; sobrevida rara além dos 40 anos.\n• DM1 de Início na Infância (Childhood-Onset) — Marcos motores geralmente atingidos no tempo esperado; apresentação predominantemente cognitivo-comportamental (transtorno do espectro autista, TDAH, distúrbios de aprendizagem), sintomas gastrointestinais e distúrbios do sono.\n• DM1 de Início no Adulto (Adult-Onset) — Início entre 18-25 anos, curso lentamente progressivo. Envolvimento de masseter, ..."},{"id":"hsp-classificacao-harding","area":"Pediátrica","front":"HSP\n\nQuais são os critérios dessa classificação?\n(Classificação de Harding da Paraplegia Espástica Hereditária (Pura vs. Complicada))","back":"• Forma Pura — Espasticidade e fraqueza típicas, podendo associar-se a déficit de sensibilidade vibratória e proprioceptiva, atrofia muscular distal leve e disfunção esfincteriana (urgência urinária em até 53% dos casos).\n• Forma Complicada — Além da espasticidade/fraqueza, apresenta ataxia, déficits cognitivos, distúrbios do movimento, distúrbios psiquiátricos, neuropatia periférica, alterações oftalmológicas e cutâneas."},{"id":"friedreich-ataxia-classificacao-inicio","area":"Pediátrica","front":"FRDA\n\nQuais são os critérios dessa classificação?\n(Classificação da Ataxia de Friedreich por Idade de Início e Repetições GAA (gene FXN))","back":"• Início típico — Apresentação antes dos 25 anos (idade típica 10-15 anos); corresponde a cerca de 85% dos pacientes.\n• Início tardio (late-onset) — Apresentação entre 26 e 39 anos.\n• Início muito tardio (very late-onset) — Apresentação a partir dos 40 anos.\n• Alelos normais — 5 a 33 repetições GAA no gene FXN (cromossomo 9q13).\n• Pré-mutação — 34 a 65 repetições GAA.\n• Zona limítrofe (borderline) — 44 a 66 repetições GAA.\n• Alelos causadores de doença — 66 a 1300 repetições GAA (tipicamente 600-1200); mais de 95% dos pacientes têm expansão em ambos os alelos do gene FXN."},{"id":"escoliose-nomenclatura-curva","area":"Pediátrica","front":"SRS-LOC\n\nQuais são os critérios dessa classificação?\n(Nomenclatura de Localização da Curva Escoliótica (Sociedade de Pesquisa em Escoliose — SRS))","back":"• Cervical — Ápice da curva entre C2 e C6\n• Cervicotorácica — Ápice entre C7 e T1\n• Torácica — Ápice entre T2 e T11\n• Toracolombar — Ápice entre T12 e L1\n• Lombar — Ápice entre L2 e L4\n• Lombossacra — Ápice em L5 ou abaixo"},{"id":"escoliose-idade-inicio","area":"Pediátrica","front":"IDADE\n\nQuais são os critérios dessa classificação?\n(Classificação da Escoliose Idiopática por Idade de Início)","back":"• Infantil — 0 a 3 anos\n• Juvenil — 4 a 10 anos\n• Adolescente — 11 a 17 anos\n• Adulto — ≥18 anos\n• Simplificação atual — Escoliose de início precoce (early-onset, <10 anos) vs. de início tardio (late-onset, tipo adolescente) — apenas a de início precoce tem potencial de evoluir para deformidade torácica grave com comprometimento cardiopulmonar"},{"id":"escoliose-curva-estrutural","area":"Pediátrica","front":"ESTRUT\n\nQuais são os critérios dessa classificação?\n(Curva Estrutural vs. Não Estrutural / Maior vs. Menor)","back":"• Curva estrutural — Não corrige para menos de 25° em radiografia de inclinação lateral (side-bending) — critério adotado pela classificação de Lenke\n• Curva não estrutural (compensatória) — Corrige para <25° no bending; desenvolve-se com ou após a curva primária para rebalancear cabeça e tronco sobre a pelve\n• Curva maior — Geralmente a primeira a se desenvolver e a de maior magnitude\n• Curva menor — Curva de compensação; pode ser estrutural ou não estrutural"},{"id":"escoliose-cobb","area":"Pediátrica","front":"COBB\n\nQuais são os critérios dessa classificação?\n(Método de Cobb — Medida do Ângulo de Curvatura Escoliótica)","back":"• Definição de escoliose — Curvatura no plano coronal >10°; abaixo disso é considerada assimetria espinhal normal\n• Vértebra terminal cranial — Vértebra mais inclinada da extremidade superior da curva — traça-se linha ao longo do platô superior\n• Vértebra terminal caudal — Vértebra mais inclinada da extremidade inferior — traça-se linha ao longo do platô inferior\n• Ângulo de Cobb — Ângulo formado pelas perpendiculares às duas linhas acima (ou ângulo direto entre elas)\n• Erro de medida / progressão — Erro inter/intraobservador de ~5° por curva; a maioria dos cirurgiões considera progressão uma diferença ≥6° entre exames seriados"},{"id":"escoliose-rotacao-vertebral","area":"Pediátrica","front":"ROT-VERT\n\nQuais são os critérios dessa classificação?\n(Quantificação da Rotação Vertebral — Métodos de Nash-Moe e Perdriolle)","back":"• Achado radiográfico de rotação — Assimetria dos pedículos e desvio do processo espinhoso em direção à concavidade; máxima no ápice da curva\n• Método de Nash-Moe — Classifica a rotação pela posição do pedículo côncavo em relação ao contorno do corpo vertebral na radiografia PA\n• Método de Perdriolle — Utiliza um torsímetro (régua gradada) posicionado sobre a imagem do pedículo para estimar o grau de rotação axial\n• Limitação — Ambos os métodos têm imprecisão substancial; a rotação vertebral não é medida rotineiramente na prática clínica"},{"id":"escoliose-risser","area":"Pediátrica","front":"RISSER\n\nQuais são os critérios dessa classificação?\n(Sinal de Risser — Estadiamento da Maturidade Esquelética pela Apófise Ilíaca)","back":"• Risser 0 — Ausência de ossificação da apófise ilíaca\n• Risser I a III — Ossificação progressiva da apófise em sentido látero-medial, cobrindo aproximadamente 25%, 50% e 75% da crista ilíaca, respectivamente\n• Risser IV — Apófise totalmente ossificada (100%) porém ainda não fundida ao ílio\n• Risser V — Apófise fundida ao ílio — crescimento espinhal completo\n• Tempo de evolução — Ossificação látero-medial ocorre ao longo de 18-24 meses"},{"id":"escoliose-sanders","area":"Pediátrica","front":"SANDERS\n\nQuais são os critérios dessa classificação?\n(Sanders — Sistema de Estadiamento da Maturidade Esquelética Digital (Idade Óssea Digital))","back":"• Base do método — Avalia o desenvolvimento progressivo da epífise dos metacarpos e falanges em radiografia de mão\n• Estágio 3 de Sanders — Capeamento (capping) da epífise digital — sinal que se aproxima do momento do pico de velocidade de crescimento\n• Utilidade — Mais acurado que o Risser na predição do risco de progressão da curva relacionado ao crescimento esquelético remanescente\n• Aplicação preferencial — Particularmente útil na fase Risser 0, quando o sinal de Risser ainda não é informativo\n• Confiabilidade — Reprodutibilidade interobservador boa a moderada (depende do treinamento), superior à do estadiamento de Risser"},{"id":"escoliose-fatores-risco-progressao","area":"Pediátrica","front":"RISCO-PROG\n\nQuais são os critérios dessa classificação?\n(Fatores de Risco para Progressão da Curva na Escoliose Idiopática do Adolescente)","back":"• Sexo — Meninas predominam progressivamente conforme a curva aumenta de magnitude, chegando a razão de 1:8 entre os que necessitam tratamento\n• Maturidade esquelética (Risser) — Risser ≤1: risco de progressão de 60-70%; Risser 3: risco <10%\n• Localização da curva — Curvas com ápice acima de T12 (torácicas) progridem mais que curvas lombares isoladas\n• Magnitude ao diagnóstico — Curvas maiores no momento do diagnóstico têm maior probabilidade de progressão adicional\n• Fase de crescimento — Progressão mais rápida durante o pico de velocidade de crescimento, que ocorre antes da menarca e antes do aparecimento do sinal de Risser"},{"id":"escoliose-king-moe","area":"Pediátrica","front":"KING-MOE\n\nQuais são os critérios dessa classificação?\n(Classificação de King-Moe dos Padrões de Curva Torácica na Escoliose Idiopática)","back":"• Tipo I — Curvas torácica e lombar duplas, ambas cruzam a linha média; proeminências torácica e lombar clinicamente visíveis; lombar pode ser maior que a torácica; ambas estruturais, com flexibilidade semelhante no bending — verdadeiro duplo-major, ambas requerem fusão\n• Tipo II — Curvas torácica e lombar, com mínima proeminência lombar clínica; ambas cruzam a linha média, mas a lombar é mais flexível no bending — duplo-major falso, permite fusão seletiva da curva torácica\n• Tipo III — Curva torácica isolada com descompensação mínima ou ausente; a curva lombar não cruza a linha média\n• Tipo IV — Curva torácica longa com descompensação acentuada; a curva alcança a linha média em L4, que se inclina para dentro da curva\n• Tipo V — Curva to..."},{"id":"escoliose-lenke","area":"Pediátrica","front":"LENKE\n\nQuais são os critérios dessa classificação?\n(Classificação de Lenke da Escoliose Idiopática do Adolescente)","back":"• Tipo 1 — Torácica principal — Curva estrutural única na região torácica (King II/III); ~metade dos casos operados; subtipos 1A/1B/1C conforme translação apical lombar\n• Tipo 2 — Torácica dupla — Torácica superior esquerda estrutural (>20° no bending) + torácica principal direita (King V); geralmente requer fusão iniciando em T2\n• Tipo 3 — Duplo-major (torácica + lombar) — Curva torácica maior, com curva lombar também estrutural (bending >25°); geralmente ambas fundidas (King I/II)\n• Tipo 4 — Curva tripla — Curvas estruturais nas três regiões (torácica superior esquerda, torácica principal direita, lombar/toracolombar esquerda); padrão menos comum\n• Tipo 5 — Toracolombar/lombar — Curva lombar ou toracolombar isolada, sem componente torá..."},{"id":"escoliose-conduta-conservadora","area":"Pediátrica","front":"CONDUTA\n\nQuais são os critérios dessa classificação?\n(Conduta Conservadora na Escoliose Idiopática do Adolescente (Observação e Órtese))","back":"• Curva <15° — Alta para acompanhamento pelo pediatra, reavaliação anual\n• Curva 15-25° — Observação clínica e radiográfica a cada 6-12 meses (a cada 4-6 meses se em fase de crescimento rápido)\n• Indicação de órtese — Curva progressiva ≥25° em paciente imaturo (Risser ≤2); alguns iniciam em 20° se forte história familiar de progressão\n• Limite de tratamento com órtese — Curva até aproximadamente 40-45°; objetivo é impedir progressão até a maturidade, não corrigir definitivamente a curva\n• Esquema de uso e meta — Recomenda-se 18-20h/dia (efeito dose-dependente comprovado pelo estudo BRAIST); meta radiográfica in-brace de ≥50% de correção em colete tipo TLSO e >75% em órtese noturna de flexão"},{"id":"escoliose-conduta-cirurgica","area":"Pediátrica","front":"CONDUTA\n\nQuais são os critérios dessa classificação?\n(Indicações e Seleção de Níveis para Tratamento Cirúrgico da Escoliose Idiopática)","back":"• Paciente esqueleticamente imaturo — Considerar cirurgia se curva torácica com Cobb >40-50°\n• Paciente esqueleticamente maduro — Fusão reservada para curvas ≥50° (menor risco de progressão espontânea)\n• Fatores além do Cobb — Deformidade de tronco (translação/rotação apical), desequilíbrio do tronco e padrão de curva (curva longa única causa mais deformidade clínica que curvas duplas balanceadas) devem pesar na decisão\n• Fusão seletiva torácica — Possível em curvas Lenke 1C/3C quando a curva lombar é flexível (<25° no bending) e a deformidade torácica é dominante; risco de descompensação do tronco se indicação inadequada\n• Tethering vertebral anterior (fusionless) — Técnica emergente para curva torácica de 45-65° com 2-3 anos de crescim..."},{"id":"escoliose-complicacoes-radiograficas","area":"Pediátrica","front":"PJK-CST\n\nQuais são os critérios dessa classificação?\n(Complicações Radiográficas Pós-operatórias na Cirurgia da Escoliose (Crankshaft, PJK, Adding-on))","back":"• Fenômeno do crankshaft — Progressão rotacional da deformidade por crescimento anterior contínuo após fusão posterior bem-sucedida em paciente esqueleticamente imaturo (cartilagem trirradiada aberta); definido por aumento do Cobb >10° ou aumento da rotação apical\n• Cifose juncional proximal (PJK) — Alteração ≥10° entre a vértebra terminal superior instrumentada e as 1-2 vértebras adjacentes não instrumentadas; incidência de 9-27%\n• \"Adding-on\" — Progressão/extensão da curva primária — cunha discal progressiva abaixo da vértebra instrumentada distal ou aumento do número de vértebras incluídas na medida de Cobb\n• Fatores de risco para PJK — Grande cifose torácica pré-operatória, perda de cifose torácica nos segmentos instrumentados, uso d..."},{"id":"c-eos","area":"Pediátrica","front":"C-EOS\n\nQuais são os critérios dessa classificação?\n(Classificação para Escoliose de Início Precoce (Classification for Early-Onset Scoliosis))","back":"• Idade — Idade do paciente em anos no momento da classificação, usada como prefixo contínuo (ex.: \"3\" para 3 anos).\n• Etiologia — C = Congênita/estrutural (inclui escoliose por anomalia da parede torácica ou iatrogênica); N = Neuromuscular (deformidade atribuível a alteração do tônus); S = Sindrômica (síndrome associada a escoliose, não primariamente congênita/estrutural nem neuromuscular); I = Idiopática (sem causa identificada). Em caso de múltiplas etiologias possíveis, prevalece a ordem C > N > S > I (ex.: hemivértebras múltiplas + Klippel-Feil = \"C\", não \"S\").\n• Curva maior (Cobb) — Medida no plano coronal, na posição de maior gravidade: 1 = curva 90°.\n• Cifose — Magnitude máxima de cifose mensurável entre quaisquer dois níveis no ..."},{"id":"rvad-mehta","area":"Pediátrica","front":"RVAD\n\nQuais são os critérios dessa classificação?\n(Diferença do Ângulo Costovertebral (RVAD) e Fase Costal de Mehta — prognóstico da escoliose idiopática infantil)","back":"• Definição do RVAD — Ângulo subtendido por uma linha do ponto médio do colo ao ponto médio da cabeça da costela correspondente à vértebra apical, em relação ao seu eixo vertical, medido nos lados côncavo e convexo; RVAD = diferença entre os dois ângulos.\n• RVAD >20° (progressiva) — RVAD progressivo (aumentando em radiografias seriadas) e/ou RVAD inicial >20° predizem baixa chance de resolução espontânea e alto risco de progressão da curva.\n• RVAD <20° / resolução — Valores baixos e não progressivos associam-se a maior probabilidade de resolução espontânea da escoliose idiopática infantil.\n• Fase costal 1 — Sem sobreposição da cabeça costal apical convexa sobre a borda lateral do corpo vertebral apical — menor rotação axial, melhor progn..."},{"id":"complicacoes-coluna-crescimento","area":"Pediátrica","front":"GSS-COMP\n\nQuais são os critérios dessa classificação?\n(Classificação de complicações em cirurgia de coluna em crescimento (growth-friendly))","back":"• Grau I — Complicação que não requer cirurgia não planejada (ex.: migração de âncora sem repercussão clínica que exija intervenção).\n• Grau IIA — Complicação que requer uma única intervenção cirúrgica não planejada.\n• Grau IIB — Complicação que requer múltiplas intervenções cirúrgicas não planejadas e hospitalização (ex.: infecção de sítio cirúrgico).\n• Grau III — Complicação que altera substancialmente o plano de tratamento (ex.: abandono da técnica growth-friendly).\n• Grau IV — Óbito."},{"id":"skaggs-implantes-growth-friendly","area":"Pediátrica","front":"SKAGGS\n\nQuais são os critérios dessa classificação?\n(Classificação de Skaggs dos implantes de coluna \"growth-friendly\" (poupadores de crescimento))","back":"• Critério de classificação — Estratégia de correção ou tipo de força exercida pelo implante sobre a coluna: (a) baseados em distração, (b) baseados em compressão, ou (c) sistemas de crescimento guiado.\n• Baseados em distração — Hastes de crescimento tradicionais (TGR), hastes de crescimento controladas magneticamente (MCGR) e VEPTR; fixação em ambas as extremidades com parafusos pediculares ou ganchos, com alongamentos programados.\n• Baseados em compressão — Sistemas que atuam por força compressiva sobre o lado convexo da curva (ex.: hemiepifisiodese/tethering), modulando o crescimento assimétrico da coluna sem fusão extensa.\n• Crescimento guiado — Sistemas que direcionam o crescimento ao longo de uma trajetória fixa sem alongamentos ci..."},{"id":"conduta-eos-manejo","area":"Pediátrica","front":"CONDUTA\n\nQuais são os critérios dessa classificação?\n(Conduta no tratamento da escoliose de início precoce (EOS) — gesso, hastes de crescimento e fusão definitiva)","back":"• Gesso seriado (método de Mehta) — Princípio: elongação-derrotação-flexão. Indicado em escoliose idiopática infantil progressiva, RVAD >20° e fase costal 2, idealmente <2 anos com curva <60°. Regra prática: idade em anos = intervalo de troca em meses (ex.: <2 anos, trocar a cada 2 meses). Série de 3-4 gessos; manter órtese por ≥1 ano após retirada. Contraindicações: deformidade torácica grave, anomalias costais/síndrome de insuficiência torácica, tronco curto, algumas displasias esqueléticas.\n• Indicação de cirurgia de crescimento (hastes) — Considerar cirurgia quando a curva progride além de ~60-70° Cobb (ou 50° em neuromuscular) ou há declínio de crescimento/função respiratória, tipicamente entre 5-10 anos na EOS idiopática, mais cedo..."},{"id":"scheuermann-classificacao-sorensen","area":"Pediátrica","front":"SORENSEN\n\nQuais são os critérios dessa classificação?\n(Critérios de Sorensen e Classificação da Doença de Scheuermann (Típica x Atípica))","back":"• Critério diagnóstico (Sorensen) — Cifose estrutural definida por 3 ou mais vértebras consecutivas, cada uma com cunha (wedging) anterior ≥5 graus, medida pelo ângulo entre as linhas paralelas aos platôs superior e inferior do corpo vertebral.\n• Forma típica (torácica) — Mais comum; acomete a coluna torácica com ápice entre T7-T9; preenche os critérios de Sorensen (≥3 vértebras cunhadas ≥5°); história natural bem estabelecida na adolescência e após a maturidade esquelética.\n• Forma atípica (toracolombar/lombar) — Localizada na junção toracolombar ou coluna lombar; caracterizada por irregularidade dos platôs, redução do espaço discal e nódulos de Schmorl anteriores; não preenche necessariamente os critérios de Sorensen de 3 vértebras cun..."},{"id":"pavf-estagios","area":"Pediátrica","front":"PAVF\n\nQuais são os critérios dessa classificação?\n(Estágios da Fusão Vertebral Anterior Progressiva (Síndrome de Copenhague))","back":"• Estágio 1 — Estreitamento do espaço discal, mais acentuado anteriormente do que posteriormente.\n• Estágio 2 — Aumento da esclerose dos platôs vertebrais das colunas anterior e média.\n• Estágio 3 — Fragmentação dos platôs vertebrais anteriores.\n• Estágio 4 — Fusão da coluna anterior e, por vezes, também da coluna média.\n• Estágio 5 — Desenvolvimento de deformidade cifótica, por crescimento contínuo do espaço discal posterior enquanto o anterior já está fundido."},{"id":"deacon-escoliose-scheuermann","area":"Pediátrica","front":"DEACON\n\nQuais são os critérios dessa classificação?\n(Classificação de Deacon da Escoliose Associada à Doença de Scheuermann)","back":"• Tipo 1 — O ápice da escoliose coincide com o ápice da cifose; a curva rotaciona em direção à convexidade — sentido oposto ao observado na escoliose idiopática, atribuído ao fato de a escoliose ocorrer em uma coluna cifótica (e não hipocifótica/lordótica).\n• Tipo 2 — O ápice da escoliose está acima ou abaixo do ápice da cifose; a curva rotaciona em direção à concavidade, padrão semelhante ao da escoliose idiopática; é o tipo mais comum.\n• Relevância clínica — A escoliose associada à doença de Scheuermann raramente é progressiva e geralmente não requer tratamento específico, independentemente do tipo."},{"id":"cifose-pos-laminectomia-tipos","area":"Pediátrica","front":"PÓS-LAMINECT\n\nQuais são os critérios dessa classificação?\n(Tipos de Cifose Pós-Laminectomia em Crianças)","back":"• Tipo 1 — Instabilidade pós-facetectomia — Cifose aguda e angular, geralmente no pós-operatório imediato ou precoce, associada a perda de função neurológica; ocorre principalmente quando mais de 50% da faceta articular é ressecada.\n• Tipo 2 — Hipermobilidade intervertebral — Arredondamento gradual da cifose ao longo do tempo devido ao estresse sobre as estruturas posteriores remanescentes; mais comum quando as facetas são preservadas.\n• Tipo 3 — Cunhificação por distúrbio de crescimento — Em coluna imatura, a cifose resultante inibe o crescimento das fises anteriores das vértebras envolvidas, causando cunhificação vertebral progressiva, acelerada no estirão de crescimento adolescente."},{"id":"rajasekaran-coluna-risco-tb","area":"Pediátrica","front":"RAJASEKARAN\n\nQuais são os critérios dessa classificação?\n(Sinais Radiológicos de \"Coluna em Risco\" de Rajasekaran (Cifose Pós-Tuberculose))","back":"• Luxação facetária — Separação/luxação da articulação facetária no nível do ápice da curva, causando instabilidade e perda de alinhamento; em casos graves pode ocorrer em dois níveis.\n• Retropulsão posterior — Identificada traçando duas linhas ao longo da superfície posterior das primeiras vértebras normais acima e abaixo da curva; os segmentos doentes ficam posteriores à intersecção dessas linhas.\n• Translação lateral — Confirmada quando uma linha vertical traçada pelo meio do pedículo da primeira vértebra normal inferior não toca o pedículo da primeira vértebra normal superior, na incidência anteroposterior.\n• Sinal do \"toppling\" (tombamento) — Uma linha traçada ao longo da superfície anterior da primeira vértebra normal inferior inte..."},{"id":"brenton-dent-osteoporose-juvenil","area":"Pediátrica","front":"BRENTON-DENT\n\nQuais são os critérios dessa classificação?\n(Classificação de Brenton e Dent da Osteoporose Juvenil Idiopática)","back":"• Leve — Dor nas costas e fraturas vertebrais apenas, sem outras manifestações.\n• Moderada — Dor nas costas e em membros inferiores associada a fraturas, com alguma limitação das atividades, porém com retorno eventual à função normal.\n• Grave — Dor nas costas e em membros inferiores com fraturas (metafisárias e diafisárias); há melhora clínica, mas sem retorno completo à atividade normal mesmo após a puberdade."},{"id":"scheuermann-conduta-tratamento","area":"Pediátrica","front":"CONDUTA\n\nQuais são os critérios dessa classificação?\n(Indicações de Tratamento na Cifose de Scheuermann (Colete, Gesso e Cirurgia))","back":"• Observação — Cifose leve e não progressiva: seguimento clínico e radiográfico (incidência lateral) a cada 4-6 meses até a maturidade esquelética.\n• Indicação de colete (Milwaukee) — Coluna imatura (≥1 ano de crescimento remanescente), curva com alguma flexibilidade (correção de pelo menos 40-50% ao teste de flexibilidade) e cifose >50°. Uso inicial em tempo integral por 12-18 meses; uso parcial (16h/dia) tem eficácia semelhante ao uso integral. Colete de perfil baixo, sem apoio cervical, pode ser usado se o ápice estiver em T9 ou abaixo.\n• Fatores de mau prognóstico com colete — Cifose >75°, cunhificação vertebral >10° ou paciente próximo/após a maturidade esquelética — associados a pior resposta ao tratamento com órtese.\n• Indicação c..."},{"id":"acondroplasia-cifose-toracolombar-conduta","area":"Pediátrica","front":"CONDUTA\n\nQuais são os critérios dessa classificação?\n(Algoritmo de Tratamento da Cifose Toracolombar na Acondroplasia)","back":"• Prevenção — Orientar os pais a evitar a posição sentada sem apoio no lactente hipotônico; acompanhamento clínico próximo.\n• Indicação de órtese (TLSO) — Cifose >30° antes da marcha independente: iniciar TLSO e manter até a criança andar de forma independente e/ou até haver melhora da cunhificação vertebral e da cifose.\n• Gesso seriado — Se não houver resposta ao colete, indicar gesso seriado em hiperextensão; se houver correção ≥50% em 3-4 meses, retomar o tratamento com órtese.\n• Indicação cirúrgica — Progressão documentada da cifose; cifose >40° em criança com mais de 5-6 anos de idade; ou déficit neurológico relacionado à deformidade.\n• Observações técnicas — Evitar instrumentação com ganchos/fios que entrem no canal, pela estenose ..."},{"id":"wiltse-newman-espondilolistese","area":"Pediátrica","front":"Wiltse-Newman\n\nQuais são os critérios dessa classificação?\n(Classificação de Wiltse-Newman-Macnab da Espondilolistese)","back":"• Tipo I — Displásica (congênita) — displasia congênita das facetas articulares L5-S1 ou do sacro superior, permitindo o escorregamento; arco neural de L5 permanece intacto, com maior risco de estenose de canal e compressão da cauda equina a partir de cerca de 50% de escorregamento.\n• Tipo II — Ístmica — defeito na pars interarticularis (istmo); é o tipo mais comum, subdividido em IIA, IIB e IIC.\n• Tipo IIA — Espondilolítica — fratura de estresse (fadiga) na região da pars interarticularis, por microtrauma repetitivo em hiperextensão (mecanismo mais comum em crianças/adolescentes atletas).\n• Tipo IIB — Pars interarticularis alongada — elongação do istmo sem solução de continuidade franca, por microfraturas repetidas seguidas de consolida..."},{"id":"meyerding-boxall-espondilolistese","area":"Pediátrica","front":"Meyerding/Boxall\n\nQuais são os critérios dessa classificação?\n(Classificação de Meyerding e Percentual de Escorregamento de Boxall)","back":"• Grau 0 — Espondilólise isolada — defeito da pars interarticularis sem escorregamento vertebral associado.\n• Grau I — Escorregamento de 1% a 25% da largura do platô sacral (linha do rebordo posterior do corpo vertebral cranial em relação ao platô de S1).\n• Grau II — Escorregamento de 26% a 50%.\n• Grau III — Escorregamento de 51% a 75% — considerado alto grau; associado a maior risco de progressão.\n• Grau IV — Escorregamento de 76% a 100% — alto grau.\n• Grau V — Espondiloptose — corpo vertebral cranial (geralmente L5) totalmente deslocado e caído abaixo do platô anterior do corpo caudal (S1), além de 100% de translação."},{"id":"parametros-angulares-espondilolistese","area":"Pediátrica","front":"SA/IS/IP\n\nQuais são os critérios dessa classificação?\n(Parâmetros Radiográficos Angulares (Ângulo de Escorregamento, Inclinação Sacral e Incidência Pélvica))","back":"• Ângulo de escorregamento (slip angle) — Ângulo entre a linha perpendicular à cortical posterior do sacro (linha de referência sacral) e a linha do platô inferior de L5; normalmente em lordose (valor negativo). Ângulos >+45° (cifose) associam-se a maior risco de progressão do escorregamento.\n• Rotação sagital — Ângulo entre a cortical posterior do sacro e a cortical posterior do corpo de L5; deve ser aproximadamente igual ao ângulo de escorregamento. Em escorregamentos >50%, medir também o ângulo L4-sacro, que passa a ser a nova referência caso a fusão seja estendida a L4.\n• Inclinação sacral (sacral inclination) — Ângulo entre a cortical posterior do sacro e uma linha vertical; normal <30°. Tende a diminuir (sacro mais vertical) quanto..."},{"id":"morita-espondilolise-estagios","area":"Pediátrica","front":"Morita\n\nQuais são os critérios dessa classificação?\n(Estadiamento de Morita da Espondilólise (Potencial de Consolidação Óssea))","back":"• Estágio inicial (early) — Defeito em linha capilar (hairline) na TC. Maior potencial de consolidação com tratamento conservador (cerca de 73-94% de cicatrização nas séries citadas).\n• Estágio progressivo — Defeito mais largo, com fragmentos ósseos visíveis. Cicatrização em cerca de 38,5-80% dos casos conforme a série.\n• Estágio terminal — Esclerose evidente nas margens do defeito (pseudartrose estabelecida). Cicatrização em 0% dos casos com tratamento conservador — indica defeito crônico irreversível.\n• Cintilografia SPECT \"quente\" — Captação aumentada de radiotraçador no istmo, sugerindo defeito metabolicamente ativo (lesão aguda/fratura de estresse), com potencial de resposta à imobilização.\n• Cintilografia SPECT \"fria\" — Captação no..."},{"id":"conduta-tratamento-espondilolistese","area":"Pediátrica","front":"CONDUTA\n\nQuais são os critérios dessa classificação?\n(Conduta e Indicações de Tratamento da Espondilólise e Espondilolistese Pediátrica)","back":"• Tratamento conservador inicial — Observação, modificação de atividades, órtese (TLSO/LSO ou cinta sacroilíaca) por 6 a 12 semanas e fisioterapia para fortalecimento do core; indicado em espondilólise ou espondilolistese grau I-II sintomática, sem déficit neurológico.\n• Indicações de cirurgia — Escorregamento >50% (Meyerding grau III ou mais), mesmo assintomático, pelo risco de progressão; dor persistente/incapacitante refratária a 4-6 meses de tratamento conservador bem conduzido; ou presença de déficit neurológico.\n• Reparo direto da pars interarticularis — Opção em espondilólise ou escorregamento mínimo que reduz ao posicionamento, sem doença discal degenerativa adjacente e com atividade metabólica confirmada em RM/cintilografia; con..."},{"id":"adi-sac-craniocervical-ped","area":"Pediátrica","front":"ADI/SAC\n\nQuais são os critérios dessa classificação?\n(Parâmetros radiográficos de instabilidade craniocervical pediátrica (ADI, SAC e regra dos terços de Steel))","back":"• ADI (Intervalo Atlanto-Odontóideo) — Distância entre a borda anterior do odontoide e a borda posterior do arco anterior do atlas, medida em flexão/extensão. Normal em crianças até 5 mm (valor adulto: 3 mm), pela maior cartilagem e frouxidão ligamentar próprias da infância.\n• SAC (Espaço Disponível para a Medula) — Distância entre a borda posterior do odontoide e a borda anterior do arco posterior do atlas (ou forame magno). SAC < 13 mm associa-se a risco neurológico; em crianças pequenas, compressão medular é iminente quando o SAC é igual ou menor que o diâmetro transverso do odontoide.\n• Regra dos terços de Steel — No canal ao nível de C1: um terço medula, um terço odontoide, um terço espaço livre (zona de segurança, mantida pelo liga..."},{"id":"torticollis-congenito-subgrupos","area":"Pediátrica","front":"TMC\n\nQuais são os critérios dessa classificação?\n(Torcicolo Muscular Congênito — subgrupos clínicos e preditores de conduta)","back":"• Tumoração do esternocleidomastóideo (43%) — Subgrupo mais grave, apresentação mais precoce; maior associação com apresentação pélvica (19%), parto difícil (56%) e displasia do quadril (6,8%); maior taxa de necessidade cirúrgica (~8%).\n• Torcicolo muscular — contratura sem massa (31%) — Resposta ao alongamento em 54-70% dos casos.\n• Torcicolo postural (22%) — Sem contratura fixa; resolução quase universal com tratamento conservador; cirurgia praticamente não é necessária.\n• Extensão da fibrose ao ultrassom — Fibrose restrita ao terço inferior do músculo: 100% respondem à fisioterapia. Fibrose de todo o comprimento do músculo: até 35% necessitam cirurgia.\n• Indicação cirúrgica — Falha do alongamento após 1 ano de idade, deformidade facia..."},{"id":"fielding-hawkins-aarf","area":"Pediátrica","front":"Fielding-Hawkins\n\nQuais são os critérios dessa classificação?\n(Classificação de Fielding-Hawkins da Fixação/Subluxação Rotatória Atlantoaxial (AARF))","back":"• Tipo I — Deslocamento rotatório simples, sem deslocamento anterior de C1. Tipo mais comum na infância; geralmente benigno e frequentemente resolve espontaneamente.\n• Tipo II — Deslocamento rotatório com deslocamento anterior de C1 de até 5 mm. Potencialmente mais perigoso, com comprometimento de uma massa lateral/ligamento transverso.\n• Tipo III — Deslocamento rotatório com deslocamento anterior maior que 5 mm. Raro, risco neurológico significativo.\n• Tipo IV — Deslocamento rotatório com deslocamento posterior de C1. Raríssimo, risco de morte súbita.\n• Limiar de deslocamento anterior patológico — Maior que 3 mm em crianças maiores/adultos; maior que 4 mm em crianças pequenas."},{"id":"aarf-grisel-conduta","area":"Pediátrica","front":"CONDUTA\n\nQuais são os critérios dessa classificação?\n(Conduta na Fixação Rotatória Atlantoaxial (AARF) e Síndrome de Grisel)","back":"• 1-4 semanas de sintomas — Colar cervical macio + analgésicos/relaxante muscular (ex.: diazepam); manter até resolução dos sintomas (tipicamente 1-2 semanas).\n• Falha de redução espontânea — Hospitalização para tração halter, relaxantes musculares e analgésicos.\n• Mais de 1 mês de sintomas — Tração cervical (geralmente halo esquelético) por até 2 semanas; prognóstico reservado.\n• Pós-redução — Sem deslocamento anterior: manter suporte cervical apenas enquanto persistirem sintomas. Com deslocamento anterior: imobilizar por 6 semanas para cicatrização ligamentar.\n• Indicações de fusão C1-C2 posterior — Comprometimento neurológico, deslocamento anterior, falha em obter/manter a redução, deformidade presente há mais de 3 meses, ou recidiva ..."},{"id":"hemiatlas-classificacao","area":"Pediátrica","front":"Hemiatlas\n\nQuais são os critérios dessa classificação?\n(Classificação da Ausência Unilateral de C1 (Hemiatlas Congênito))","back":"• Tipo I — Hemiatlas isolado.\n• Tipo II — Aplasia parcial ou completa de uma hemiatlas, com outras anomalias associadas da coluna cervical (ex.: fusão de C3-C4, barras congênitas na coluna cervical baixa).\n• Tipo III — Fusão atlantooccipital parcial ou completa, com aplasia simétrica ou assimétrica da hemiatlas, com ou sem anomalias do odontoide e da coluna cervical baixa."},{"id":"escoliose-cervical-congenita-classif","area":"Pediátrica","front":"ECC\n\nQuais são os critérios dessa classificação?\n(Classificação das Anomalias Vertebrais Congênitas da Coluna Cervical)","back":"• Falha de formação — Vértebra em cunha ou hemivértebra (falha completa de formação de metade do corpo vertebral).\n• Hemivértebra totalmente segmentada (65%) — Disco de crescimento normal acima e abaixo da anomalia; maior potencial de progressão da deformidade.\n• Hemivértebra parcialmente segmentada (22%) — Fundida a uma vértebra vizinha de um lado, com espaço discal aberto do lado oposto.\n• Hemivértebra incarcerada/não segmentada (12%) — Sem espaço discal entre as vértebras adjacentes; menor potencial de progressão.\n• Falha de segmentação — Barra óssea entre segmentos adjacentes; a combinação de barra unilateral com hemivértebra contralateral é o padrão de maior risco de progressão.\n• Classificação 3D de Kawakami (TC tridimensional) — T..."},{"id":"klippel-feil-hensinger","area":"Pediátrica","front":"Hensinger\n\nQuais são os critérios dessa classificação?\n(Classificação de Hensinger da Síndrome de Klippel-Feil)","back":"• Tríade clássica — Fusão congênita de duas ou mais vértebras cervicais, pescoço curto e implantação baixa do cabelo (a tríade completa está presente em apenas parte dos casos).\n• Tipo I — Fusão de C2-C3 com occipitalização do atlas.\n• Tipo II — Fusão longa com junção occipitocervical anormal.\n• Tipo III — Dois segmentos de fusão em bloco com um único espaço interdiscal aberto — teoricamente pior prognóstico pela sobrecarga de um único disco móvel entre duas alavancas longas, embora dados de longo prazo não confirmem aumento de complicações neurológicas.\n• Padrão de risco de instabilidade — Fusão de C1-C2 e C3-C4 com nível C2-C3 não fundido predispõe a hipermobilidade e sintomas neurológicos nesse nível intermediário."},{"id":"os-odontoideum-matsui","area":"Pediátrica","front":"Matsui\n\nQuais são os critérios dessa classificação?\n(Classificação Radiográfica do Os Odontoideum e Indicações Cirúrgicas)","back":"• Tipo redondo (round) — Ossículo oval a redondo, com borda esclerótica lisa, na posição da ponta normal do odontoide.\n• Tipo cônico (cone) — Variante cônica do ossículo.\n• Tipo dente rombo (blunt tooth) — Variante com aspecto de dente rombo.\n• Achado associado — Base do dente costuma ser hipoplásica; o intervalo entre o os e o dente hipoplásico é mais largo que em fratura e situa-se bem acima do nível das facetas.\n• Indicação cirúrgica — ADI igual ou maior que 10 mm, SAC igual ou menor que 13 mm, comprometimento neurológico, instabilidade progressiva ou dor cervical persistente."},{"id":"basilar-invagination-lines","area":"Pediátrica","front":"Chamberlain/McRae/McGregor\n\nQuais são os critérios dessa classificação?\n(Linhas Radiográficas para Impressão/Invaginação Basilar)","back":"• Linha de McRae — Define a abertura do forame magno; em pacientes sintomáticos, o odontoide projeta-se acima dessa linha.\n• Linha de Chamberlain — Traçada do lábio posterior do forame magno até a margem dorsal do palato duro.\n• Linha de McGregor — Traçada da borda posterossuperior do palato duro até o ponto mais caudal da curva occipital; considerada a melhor linha para triagem por ter referências ósseas claras em radiografia simples de perfil, em qualquer idade.\n• Principais etiologias — Doenças ósseas metabólicas (Paget, osteodistrofia renal, raquitismo/osteomalácia), displasias ósseas, síndromes mesenquimais (osteogênese imperfeita, acondroplasia, hipocondroplasia, neurofibromatose) e doenças reumatológicas.\n• Quadro clínico — Pescoç..."},{"id":"down-syndrome-instabilidade-craniocervical","area":"Pediátrica","front":"AAI Down\n\nQuais são os critérios dessa classificação?\n(Instabilidade Craniocervical na Síndrome de Down — critérios e conduta)","back":"• Instabilidade occipito-C1 — Incidência de até 60% em crianças; razão de Powers menor que 0,55 associa-se a maior risco de sintomas neurológicos; subluxação de 7-10 mm na junção occipitoatlantal é considerada patológica e geralmente requer fusão occipitocervical.\n• Instabilidade atlantoaxial — Incidência de 9-22%; instabilidade sintomática é muito mais rara (~2,6%). Anomalias ósseas associadas (sincondrose persistente, espinha bífida oculta de C1, os odontoideum) aumentam o risco de progressão.\n• Rastreio radiográfico — Radiografias de rotina em pacientes assintomáticos NÃO são recomendadas pela American Academy of Pediatrics (1995/2011) pela baixa reprodutibilidade do exame; história e exame neurológico são mais importantes que a radio..."},{"id":"aod-criterios-traumaticos","area":"Pediátrica","front":"AOD\n\nQuais são os critérios dessa classificação?\n(Critérios Diagnósticos para Luxação Atlanto-Occipital Traumática (AOD))","back":"• Razão de Powers (BC/OA) — Historicamente, valor maior que 1,0 indicava luxação atlanto-occipital, mas pode não detectar lesões de distração isolada ou luxações já reduzidas espontaneamente.\n• Distância dente-basion (DB) — Distância entre a ponta do odontoide e o basion maior que 12,5 mm sugere potencial de luxação atlanto-occipital.\n• Razão interespinhosa posterior C1-C2/C2-C3 — Se maior que 2,5, alta probabilidade de ruptura da membrana tectorial; RM está indicada.\n• Apresentação clínica — Vítimas de politrauma com lesão craniana grave; espectro desde exame neurológico normal até parada cardíaca; sobreviventes frequentemente apresentam disfunção de nervos cranianos e graus variáveis de quadriplegia.\n• Conduta — Imobilização definitiva..."},{"id":"sciwora-ped-conduta","area":"Pediátrica","front":"SCIWORA\n\nQuais são os critérios dessa classificação?\n(Lesão Medular Sem Anormalidade Radiográfica (SCIWORA) — conduta)","back":"• Definição — Déficit neurológico medular sem fratura, luxação ou instabilidade visível em radiografias simples; ocorre em 5-55% das lesões medulares pediátricas na literatura neurocirúrgica (dados multicêntricos mais recentes sugerem incidência menor).\n• Mecanismos — Hiperextensão, flexão, distração e isquemia medular (contusão ou lesão vascular direta); a estenose do canal não é fator de risco significativo (razão de Torg média maior que 1,0 nas séries).\n• Distribuição — 78% dos déficits são cervicais; SCIWORA da coluna cervical alta associa-se a lesões neurológicas mais graves que a da coluna cervical baixa.\n• Imagem — RM é o exame de escolha para avaliar medula, discos e complexo ligamentar; achados positivos na RM correlacionam-se c..."},{"id":"ortolani-barlow-sinais-ddh","area":"Pediátrica","front":"Ortolani/Barlow\n\nQuais são os critérios dessa classificação?\n(Sinais clínicos de instabilidade do quadril no recém-nascido (Ortolani e Barlow))","back":"• Sinal de Ortolani — Sensação palpável de redução ao abduzir suavemente o quadril fletido (o \"clique de entrada\"); a cabeça femoral desliza de volta ao acetábulo sobre a crista de cartilagem acetabular hipertrofiada (neolimbo).\n• Manobra de Barlow — Manobra provocativa: com o quadril fletido e aduzido, a cabeça femoral é levada a sair parcial ou totalmente do acetábulo (o \"clique de saída\"). O quadril Barlow-positivo é considerado mais instável, porém tende a se estabilizar espontaneamente com maior frequência.\n• Conduta prática — O autor não distingue tratamento entre quadril Ortolani-positivo e Barlow-positivo; ambos representam o mesmo espectro de instabilidade e devem ser tratados.\n• Cliques inócuos — Cliques de partes moles de alta..."},{"id":"ddh-fatores-risco","area":"Pediátrica","front":"Fatores DDH\n\nQuais são os critérios dessa classificação?\n(Fatores de risco para displasia/luxação do desenvolvimento do quadril (DDH))","back":"• Sexo e lateralidade — 80% dos casos ocorrem em meninas; o quadril esquerdo é o mais comumente acometido, pois é forçado em adução contra o sacro materno na posição fetal mais comum.\n• Apresentação pélvica — Fator de risco importante (relatado em 17% a 23% dos casos de DDH); meninas nascidas em apresentação pélvica têm risco de instabilidade de quadril de aproximadamente 1 em 15.\n• História familiar e primogenitura — História familiar positiva em 12% a 33% dos pacientes; primogênitos (útero e parede abdominal pouco distendidos) têm maior incidência.\n• Fatores intrauterinos restritivos — Oligoidrâmnio e outras condições que limitam a mobilidade fetal aumentam o risco; associação frequente com torcicolo congênito e metatarso aduto (\"fenôm..."},{"id":"achados-diagnostico-tardio-ddh","area":"Pediátrica","front":"Dx tardio DDH\n\nQuais são os critérios dessa classificação?\n(Achados clínicos do diagnóstico tardio de DDH)","back":"• Limitação da abdução — É o achado físico mais confiável no diagnóstico tardio; decorre do encurtamento secundário do adutor longo associado à subluxação/luxação.\n• Sinal de Galeazzi — Encurtamento femoral aparente, avaliado com quadris e joelhos fletidos a 90° comparando a altura dos joelhos.\n• Assimetria de pregas — Assimetria das pregas glúteas, da coxa ou labiais; sinal menos específico, mas sugestivo quando associado a outros achados.\n• Discrepância de comprimento de membro — Pode ser evidente clinicamente em luxações unilaterais não tratadas.\n• Achados em casos bilaterais — Marcha anserina (waddling) e hiperlordose lombar são típicas de luxações bilaterais não tratadas."},{"id":"graf-harcke-us-quadril","area":"Pediátrica","front":"US quadril (Graf/Harcke)\n\nQuais são os critérios dessa classificação?\n(Avaliação ultrassonográfica do quadril na DDH (Graf/Harcke))","back":"• Avaliação morfológica (Graf) — Mede o ângulo alfa (inclinação do teto ósseo acetabular) e o ângulo beta (componente cartilaginoso do acetábulo); classifica o quadril em quatro tipos e vários subtipos.\n• Avaliação dinâmica (Harcke) — Observa em tempo real, em múltiplos planos, o comportamento do quadril durante as manobras de Ortolani/Barlow; mais dependente do operador.\n• Limitações — Ambos os métodos apresentam variação interobservador e intraobservador significativa, sobretudo na medida do ângulo beta.\n• Uso ideal — Monitorar a \"redução guiada\" de um quadril luxado/subluxado em tratamento com arnês de Pavlik, a intervalos de 7 a 10 dias, evitando radiação.\n• Rastreio universal — Seu uso rotineiro em berçário resulta em sobrediagnósti..."},{"id":"parametros-radiograficos-ddh","area":"Pediátrica","front":"Radiografia DDH\n\nQuais são os critérios dessa classificação?\n(Parâmetros radiográficos clássicos de avaliação da DDH)","back":"• Índice acetabular — Medida mais útil em crianças menores de 8 anos para avaliar o desenvolvimento acetabular; costuma estar aumentado na displasia.\n• Ângulo centro-borda (CE) de Wiberg — Útil somente em pacientes com mais de 5 anos de idade, sendo mais aplicável no paciente adulto.\n• Linha de Shenton — Deve estar íntegra em todas as incidências após os 3-4 anos de idade; sua ruptura indica anormalidade na relação fêmur-acetábulo (subluxação).\n• Linhas de Hilgenreiner e Perkins — Definem o quadrante ínfero-medial onde o núcleo ossificado/beak metafisário femoral deve estar localizado; sua ausência sugere luxação/subluxação.\n• Figura em lágrima (teardrop) e ângulo de Sharp — A ausência da figura em lágrima é achado clássico de displasia;..."},{"id":"obstaculos-reducao-ddh","area":"Pediátrica","front":"Obstáculos redução\n\nQuais são os critérios dessa classificação?\n(Obstáculos à redução concêntrica no diagnóstico tardio de DDH)","back":"• Extra-articulares — Contratura secundária do adutor longo e do iliopsoas, encurtados pela posição luxada/subluxada crônica do quadril.\n• Ligamento redondo (teres) — Pode estar espessado e alongado, sendo, em crianças que já engatinham ou andam, volumoso o suficiente para impedir a redução concêntrica sem excisão.\n• Ligamento transverso do acetábulo — Pode hipertrofiar secundariamente à tração constante do ligamento redondo, reduzindo o diâmetro efetivo do acetábulo.\n• Cápsula constrita — A constrição da cápsula anteromedial é, segundo o autor, o obstáculo intra-articular mais significativo à redução.\n• Neolimbo (não é o lábio invertido) — Frequentemente confundido em artrografias com lábio invertido; é cartilagem epifisária e quase nun..."},{"id":"arnes-pavlik-conduta-ddh","area":"Pediátrica","front":"Arnês de Pavlik\n\nQuais são os critérios dessa classificação?\n(Conduta com o arnês de Pavlik no tratamento da DDH)","back":"• Indicação e faixa etária — Dispositivo de escolha para DDH no recém-nascido/lactente até 6 meses de idade; a taxa de sucesso cai para menos de 50% após os 6 meses.\n• Técnica de aplicação — Flexão do quadril de 100-110°; tirantes anteriores na linha axilar anterior; tirante posterior de abdução ajustado à \"zona segura\" (arco entre a luxação e a abdução confortável não forçada).\n• Duração — Uso em tempo integral por 6 semanas além do ponto de estabilidade clínica; ajustes a cada 7-10 dias; taxa de sucesso de 95% no quadril Ortolani-positivo estável.\n• Contraindicações — Desequilíbrio muscular importante (mielodisplasia, paralisia cerebral), rigidez articular (artrogripose) e frouxidão ligamentar excessiva (Ehlers-Danlos).\n• Complicações ..."},{"id":"tracao-pre-reducao-ddh","area":"Pediátrica","front":"Tração pré-redução\n\nQuais são os critérios dessa classificação?\n(Tração pré-redução na DDH: papel e controvérsias)","back":"• Racional teórico — Relaxar gradualmente a musculatura contraturada (iliopsoas, adutor longo), permitindo a redução sem forças excessivas e reduzindo teoricamente o risco de necrose avascular.\n• Evidência conflitante — Vários estudos (Cooperman, Kutlu) não encontraram relação entre o grau de deslocamento inicial vencido pela tração e a incidência de distúrbio de crescimento proximal do fêmur.\n• Duração variável — Séries relatam de 1-2 semanas a 8 semanas de tração; a maioria dos cirurgiões que a utilizam considera 1-2 semanas suficientes.\n• Tendência atual — Um número cada vez menor de cirurgiões pediátricos utiliza tração pré-redução rotineiramente.\n• Complicações — Perda de pele e isquemia de membros inferiores por má aplicação; exige..."},{"id":"reducao-fechada-tecnica-ddh","area":"Pediátrica","front":"Redução fechada\n\nQuais são os critérios dessa classificação?\n(Técnica e critérios de redução fechada na DDH)","back":"• Técnica — Redução suave sob anestesia geral por flexão, tração e abdução; tenotomia adutora (aberta ou percutânea) geralmente necessária para ampliar a \"zona segura\".\n• Critério de adequação — Na opinião do autor, apenas a redução anatômica é aceitável; a artrografia dinâmica sob fluoroscopia auxilia a avaliar obstáculos e a qualidade da redução.\n• \"Posição humana\" — Posição preferida de imobilização em gesso: hiperflexão do quadril com abdução limitada, evitando abdução ampla forçada ou rotação interna forçada.\n• Imobilização — Gesso pelvipodálico bem moldado dorsalmente aos trocânteres maiores (para prevenir reluxação), mantido cerca de 6 semanas abaixo do joelho no lado afetado, seguido de mais 6 semanas com o joelho livre.\n• Pós-ge..."},{"id":"reducao-aberta-abordagens-ddh","area":"Pediátrica","front":"Redução aberta\n\nQuais são os critérios dessa classificação?\n(Indicações e vias de abordagem para redução aberta na DDH)","back":"• Indicação (6-18 meses) — Falha do tratamento fechado, subluxação persistente, interposição de partes moles ou redução instável fora de posições extremas de abdução.\n• Abordagem anterior (Smith-Petersen/Salter) — Abordagem clássica; expõe cápsula e ambos os aspectos superior/inferior do acetábulo, permite capsulorrafia e osteotomia pélvica associada no mesmo acesso.\n• Abordagem anteromedial (Weinstein-Ponseti) — Ideal para crianças menores de 18-24 meses quando a redução concêntrica não é obtida por métodos fechados; acesso direto aos obstáculos, mínima perda sanguínea, mas sem possibilidade de capsulorrafia nem de osteotomia associada.\n• Abordagem medial (Ferguson) — Entre adutor longo/breve e grácil/adutor magno; mínima dissecção, mas..."},{"id":"conduta-por-idade-ddh","area":"Pediátrica","front":"Conduta DDH x idade\n\nQuais são os critérios dessa classificação?\n(Conduta terapêutica na DDH conforme a idade ao diagnóstico)","back":"• Recém-nascido a 6 meses — Arnês de Pavlik em tempo integral; sucesso de 95% no quadril Ortolani-positivo e cerca de 85% quando usado para guiar a redução de quadril luxado/subluxado.\n• 6 a 18 meses — Sucesso do arnês cai para menos de 50%; tratamento por redução fechada (± tração prévia) com gesso pelvipodálico, ou redução aberta se houver falha/interposição de partes moles.\n• 18 meses a 3 anos (\"zona cinzenta\") — Potencial de desenvolvimento acetabular já reduzido; redução aberta geralmente necessária, com osteotomia pélvica associada (Salter/Pemberton) simultânea ou estadiada em 6-8 semanas, conforme estabilidade e evolução radiográfica.\n• Maiores de 3 anos — Redução aberta deve ser acompanhada de encurtamento femoral (reduz drastica..."},{"id":"kalamchi-macewen-classificacao-avn","area":"Pediátrica","front":"Kalamchi-MacEwen\n\nQuais são os critérios dessa classificação?\n(Classificação de Kalamchi-MacEwen para necrose avascular pós-tratamento de DDH)","back":"• Conceito geral — Classifica os distúrbios de crescimento decorrentes de necrose avascular por grupos (I a IV), enfatizando o grau de acometimento fisário.\n• Grupo II (tipo mais comum) — Envolve um tether (ponte óssea) físeal lateral, produzindo inclinação em valgo do fêmur proximal e subluxação secundária do quadril.\n• Grupo III — Distúrbio de crescimento com sobrecrescimento trocantérico e deformidade acetabular correspondente; pode gerar marcha claudicante por insuficiência abdutora (Trendelenburg).\n• Grupo IV (forma mais grave) — Padrão de acometimento mais extenso; Kalamchi e MacEwen descreveram maior incidência dessa forma grave em pacientes mais jovens no momento do tratamento.\n• Latência diagnóstica — O padrão de acometimento fí..."},{"id":"salter-classificacao-disturbio-crescimento-femoral","area":"Pediátrica","front":"Salter (dist. crescimento)\n\nQuais são os critérios dessa classificação?\n(Classificação de Salter do distúrbio de crescimento da cabeça femoral pós-tratamento de DDH)","back":"• Uso — É a classificação mais amplamente utilizada para o distúrbio de crescimento proximal do fêmur secundário ao tratamento da DDH.\n• Crítica do autor (Weinstein) — O autor discorda da inclusão da coxa magna como forma de distúrbio, pois esta é frequentemente vista após redução aberta como resultado do estímulo de fluxo sanguíneo ao fêmur proximal, e não necessariamente uma lesão.\n• Achado comum associado — Achatamento do aspecto medial do fêmur proximal, decorrente da pressão da cabeça femoral contra o ílio antes da redução.\n• Ossificação irregular temporária — Áreas de ossificação irregular da epífise femoral podem representar dano cartilaginoso ou apenas múltiplos centros de ossificação que se fundem — distinção só possível com seg..."},{"id":"fatores-risco-necrose-avascular-ddh","area":"Pediátrica","front":"Risco NAV-DDH\n\nQuais são os critérios dessa classificação?\n(Fatores associados à necrose avascular no tratamento da DDH)","back":"• Luxações altas — Luxações altas e com inversão do lábio, e estreitamento do introito entre o lábio superior e o ligamento transverso na posição de redução, aumentam o risco.\n• Profundidade de redução inadequada — Cabeça femoral a mais de 3 mm do assoalho acetabular após a redução é fator de risco documentado pelo German Orthopaedic Study Group.\n• Idade e imobilização — Idade maior que 12 meses e imobilização em 60 graus ou mais de abdução para instabilidade articular aumentam o risco.\n• Posições extremas (posição de Lorenz) — Abdução extrema combinada a rotação medial forçada comprime a artéria circunflexa femoral medial e pode interromper quase totalmente o fluxo sanguíneo à epífise femoral proximal.\n• Tenotomia do adutor — Também ass..."},{"id":"classificacao-procedimentos-acetabulares-ddh","area":"Pediátrica","front":"4 grupos acetábulo\n\nQuais são os critérios dessa classificação?\n(Classificação dos procedimentos cirúrgicos acetabulares para displasia residual)","back":"• Grupo 1 — Osteotomias redirecionadoras — Cortes completos que reorientam todo o acetábulo, cobrindo a cabeça femoral com cartilagem articular: Salter, dupla inominada de Sutherland, tríplices (Tönnis, Steel, Ganz) e esféricas (Wagner, Eppright).\n• Grupo 2 — Acetabuloplastias incompletas — Cortes incompletos que se apoiam (dobradiça) em porções da cartilagem trirradiada, alterando a forma do acetábulo: Pemberton e Dega. Exigem cartilagem trirradiada aberta.\n• Grupo 3 — Procedimentos de salvamento — Colocam osso sobre a cápsula articular na porção descoberta da cabeça femoral, cobrindo-a por metaplasia fibrosa (não cartilagem articular): shelf (Staheli, Albee) e osteotomia de deslocamento medial de Chiari.\n• Grupo 4 — Procedimentos híbri..."},{"id":"osteotomia-salter-indicacoes","area":"Pediátrica","front":"Osteotomia de Salter\n\nQuais são os critérios dessa classificação?\n(Indicações e pré-requisitos da osteotomia inominada de Salter)","back":"• Mecanismo — Osteotomia que gira sobre a sínfise púbica, fornecendo cobertura anterior do acetábulo, porém à custa de alguma cobertura posterior.\n• Faixa etária ideal — Melhor realizada em lactentes, crianças ou adolescentes, pela maior flexibilidade da sínfise púbica nessa faixa etária, embora também possa ser realizada em adultos.\n• Prognóstico — Tem maior probabilidade de sucesso quando o ângulo CE é maior que 10 graus.\n• Fixação e enxerto — Usa enxerto ósseo tricortical da crista ilíaca, testado quanto à estabilidade por tração com pinça de Kocher após inserção.\n• Combinação frequente — Frequentemente associada, na faixa dos 18 meses a 3 anos, à redução aberta e/ou encurtamento femoral no mesmo tempo cirúrgico, através da via antero..."},{"id":"osteotomia-pemberton-vs-dega","area":"Pediátrica","front":"Pemberton vs Dega\n\nQuais são os critérios dessa classificação?\n(Comparação técnica entre as osteotomias pericapsulares de Pemberton e Dega)","back":"• Racional da Pemberton — Desenvolvida para corrigir acetábulo raso e voltado anterior/lateralmente na criança maior com subluxação/luxação; a dobradiça ocorre através da cartilagem trirradiada flexível.\n• Extensão do corte (Pemberton) — Termina no ramo ilioisquiático da cartilagem trirradiada, dividindo completamente o osso ilíaco de anterior até esse ponto.\n• Extensão do corte (Dega) — Termina logo acima da porção horizontal da cartilagem trirradiada (ramos ilioisquiático e iliopúbico), deixando um segmento posterior do córtex ilíaco íntegro junto à incisura isquiática, que forma a dobradiça.\n• Direção da cobertura — Ambas fornecem cobertura anterolateral variável conforme a angulação do corte, mas nenhuma das duas aumenta suficienteme..."},{"id":"pao-ganz-indicacoes","area":"Pediátrica","front":"PAO de Ganz\n\nQuais são os critérios dessa classificação?\n(Indicações e pré-requisitos da osteotomia periacetabular de Ganz (PAO))","back":"• Indicação principal — Osteotomia rotacional mais popular para displasia com cartilagem trirradiada já fechada (paciente maduro/adolescente); reorienta de forma potente e versátil o acetábulo displásico maduro.\n• Pré-requisito absoluto — Radiografia em abdução máxima deve demonstrar cabeça femoral reduzida, coberta e congruente, com bom espaço articular preservado.\n• Vantagem técnica — Cortes próximos ao acetábulo permitem maior grau de correção rotacional do que osteotomias mais distantes (como Salter isolada).\n• Alternativas equivalentes — Osteotomia tríplice de Tönnis e osteotomias esféricas rotacionais (Wagner na Europa; Ninomiya e Tagawa no Japão) oferecem princípio semelhante.\n• Abordagem do lábio — Há debate se a patologia labial..."},{"id":"sindrome-rebordo-acetabular-ddh","area":"Pediátrica","front":"Síndrome rebordo acetabular\n\nQuais são os critérios dessa classificação?\n(Síndrome do rebordo acetabular (impacto/sobrecarga do rebordo) na displasia residual)","back":"• Quadro clínico — Dor inguinal aguda de início súbito, com sensação de \"travamento\" ou estalido, e episódios de falseio (\"giving way\"), tipicamente em adultos jovens com displasia residual.\n• Teste do impacto — Dor reproduzida ao levar o quadril à flexão de 90° com adução e rotação interna, colocando o colo femoral anterior em contato com o rebordo acetabular anterior.\n• Imagem — Radiografias em carga e perfil falso (false profile) mostram evidência de displasia; pode haver fratura do rebordo acetabular sugestiva de sobrecarga.\n• Estudo complementar — RM com artrografia por gadolínio é o melhor exame para lesão labial; TC tridimensional é o melhor exame para as deficiências acetabulares.\n• Conduta — Na ausência de artrose (ou com artros..."},{"id":"displasia-residual-adulto-conduta","area":"Pediátrica","front":"Displasia incidental adulto\n\nQuais são os critérios dessa classificação?\n(Conduta na displasia residual/incidental do quadril no paciente maduro assintomático)","back":"• Sem história prévia de DDH — A história natural da displasia radiográfica isolada, sem diagnóstico prévio de DDH, é desconhecida na população geral.\n• Com história prévia de DDH — Nesse contexto, a história natural é clara e inequívoca: desenvolvimento de osteoartrose ao longo do tempo.\n• Displasia mínima assintomática — Conduta recomendada: observação clínica, orientação da família sobre o potencial de evolução adversa, e tratamento cirúrgico apenas no início dos sintomas.\n• Subluxação radiográfica (mesmo assintomática) — Nesse cenário o autor recomenda correção cirúrgica independentemente dos sintomas, pois sem tratamento a história natural adversa é praticamente certa.\n• Doença degenerativa avançada — Em casos extremos de artrose em..."},{"id":"historia-natural-luxacao-completa-adulto","area":"Pediátrica","front":"História natural luxação\n\nQuais são os critérios dessa classificação?\n(História natural da luxação completa de quadril não tratada no adulto)","back":"• Fator prognóstico principal — O desenvolvimento de um falso acetábulo bem formado é o principal determinante do prognóstico clínico, junto da bilateralidade.\n• Falso acetábulo bem desenvolvido — Associado a apenas 24% de chance de bom resultado clínico e maior probabilidade de doença degenerativa radiográfica.\n• Falso acetábulo ausente/pouco desenvolvido — Associado a cerca de 52% de chance de bom resultado clínico; muitos pacientes mantêm boa amplitude de movimento com pouca incapacidade funcional.\n• Casos bilaterais — Marcha anserina e hiperlordose lombar são comuns; a dor, quando presente, costuma ser lombar (secundária à hiperlordose) mais do que no próprio quadril.\n• Casos unilaterais — Discrepância de comprimento de membro (até 1..."},{"id":"displasia-vs-subluxacao-radiografica","area":"Pediátrica","front":"Displasia x subluxação Rx\n\nQuais são os critérios dessa classificação?\n(Distinção radiográfica entre displasia e subluxação do quadril)","back":"• Displasia radiográfica — Linha de Shenton íntegra; a relação entre cabeça femoral e acetábulo está mantida, mas o desenvolvimento acetabular é inadequado.\n• Subluxação radiográfica — Linha de Shenton rompida, com a cabeça femoral deslocada superior, lateral ou súpero-lateralmente em relação à parede medial do acetábulo.\n• Todo quadril subluxado é displásico — Por definição, qualquer quadril com algum contato entre cabeça femoral e acetábulo (subluxação) é anatomicamente displásico.\n• Conversão ao longo do tempo — Alterações degenerativas secundárias podem converter, com os anos, um quadril radiograficamente displásico em um quadril radiograficamente subluxado.\n• Relevância prática — Essa distinção frequentemente não é separada na liter..."},{"id":"waldenstrom-estagios-perthes","area":"Pediátrica","front":"WALDENSTRÖM\n\nQuais são os critérios dessa classificação?\n(Classificação radiográfica de Waldenström dos estágios evolutivos da doença de Legg-Calvé-Perthes (modificada por Joseph et al. com subestágios A/B))","back":"• Estágio I (inicial/necrose) — Falha do núcleo ossificado epifisário em crescer comparado ao lado normal, esclerose e alargamento aparente do espaço articular medial; subdividido em Ia e Ib.\n• Estágio II (fragmentação) — Fissuras no segmento esclerótico com áreas de radiolucência (reabsorção óssea ativa) e radiodensidade (osso necrótico); subdividido em IIa (precoce) e IIb (tardio). A fase IIb é crítica: a extrusão epifisária costuma ultrapassar 20% e o osso está mais fraco, predispondo à deformidade.\n• Estágio III (reossificação/reconstituição) — Retorno gradual da densidade óssea normal, com osso novo surgindo em áreas antes radiolúcidas; alterações no formato da cabeça e colo femoral já se tornam aparentes; subdividido em IIIa e IIIb..."},{"id":"catterall-classificacao-perthes","area":"Pediátrica","front":"CATTERALL\n\nQuais são os critérios dessa classificação?\n(Classificação de Catterall da extensão do acometimento epifisário na doença de Legg-Calvé-Perthes)","back":"• Grupo 1 — Acometimento apenas da porção anterolateral da epífise; sem colapso, sem sinais de risco; melhor prognóstico.\n• Grupo 2 — Acometimento de até cerca de 50% da epífise, com coluna (pilar) lateral íntegra e preservada, que protege contra o colapso.\n• Grupo 3 — Acometimento de aproximadamente 75% da epífise, restando apenas pequena porção lateral e medial preservada.\n• Grupo 4 — Acometimento total da cabeça femoral; pior prognóstico, maior risco de deformidade e de sinais de risco radiográficos.\n• Correlação prognóstica e limitações — 90% dos pacientes com bom resultado eram grupo 1 ou 2; 90% dos com resultado ruim eram grupo 3 ou 4. Apresenta, porém, importante variabilidade interobservador e só pode ser aplicada de forma confiá..."},{"id":"catterall-sinais-risco-perthes","area":"Pediátrica","front":"HEAD-AT-RISK\n\nQuais são os critérios dessa classificação?\n(Sinais radiográficos de risco (head-at-risk signs) de Catterall na doença de Legg-Calvé-Perthes)","back":"• Sinal de Gage — Radiolucência em V na porção lateral da epífise e metáfise, indicando ossificação precoce de uma epífise alargada; presente apenas quando a cabeça já está deformada.\n• Calcificação lateral à epífise — Achado indicativo de ossificação precoce de epífise alargada, associado a pior prognóstico.\n• Lesões metafisárias — Cistos metafisários e osteoporose metafisária difusa, sinalizando potencial distúrbio de crescimento da placa fisária.\n• Subluxação lateral — Indica cabeça femoral alargada e extrusão, fator de risco para deformidade progressiva.\n• Placa de crescimento horizontal — Fise horizontalizada (quadril aduzido) implica rigidez que, se não tratada, evolui para deformidade fixa, abdução em dobradiça (hinge abduction) e..."},{"id":"salter-thompson-classificacao-perthes","area":"Pediátrica","front":"SALTER-THOMPSON\n\nQuais são os critérios dessa classificação?\n(Classificação simplificada de Salter-Thompson (dois grupos) baseada na extensão da linha de fratura subcondral)","back":"• Grupo A — Menos da metade da cabeça femoral envolvida (corresponde aos grupos 1 e 2 de Catterall); coluna lateral da epífise viável, o que protege contra o colapso.\n• Grupo B — Mais da metade da cabeça envolvida (corresponde aos grupos 3 e 4 de Catterall); ausência de coluna lateral viável.\n• Base do diagnóstico — Extensão da linha de fratura subcondral (sinal do crescente), visível precocemente no curso da doença, antes do colapso franco.\n• Limitação prática — A linha de fratura subcondral só é visível em cerca de um terço dos pacientes com Perthes, tornando a classificação inaplicável em muitos casos.\n• Relevância prognóstica — A integridade da coluna lateral (grupo A) é o fator distintivo mais importante entre os dois grupos e predi..."},{"id":"herring-lateral-pillar-perthes","area":"Pediátrica","front":"HERRING\n\nQuais são os critérios dessa classificação?\n(Classificação do pilar lateral (lateral pillar) de Herring na doença de Legg-Calvé-Perthes)","back":"• Definição do pilar lateral — Ocupa os 15% a 30% laterais da largura da cabeça femoral na radiografia AP durante a fase de fragmentação; o pilar central ocupa cerca de 50% e o medial 20% a 35%.\n• Grupo A — Altura do pilar lateral mantida em 100%, sem perda de altura nem densidade; melhor prognóstico.\n• Grupo B — Manutenção de mais de 50% da altura do pilar lateral.\n• Grupo C — Menos de 50% da altura do pilar lateral é mantida; pior prognóstico.\n• Confiabilidade e correlação — Confiabilidade intraobservador relatada de 0,78; o grau do pilar lateral correlacionou-se bem com o desfecho medido pela classificação de Stulberg em coorte de 93 quadris em 86 pacientes."},{"id":"herring-bc-border-perthes","area":"Pediátrica","front":"B/C BORDER\n\nQuais são os critérios dessa classificação?\n(Grupo de borda B/C — refinamento da classificação do pilar lateral de Herring)","back":"• Critério de definição — Adicionado para quadris com altura do pilar lateral de exatamente 50%, ou pilar lateral estreito (menos de 2 a 3 mm de largura) mesmo com pouca perda de altura.\n• Racional — Criado porque casos limítrofes entre B e C tinham prognósticos heterogêneos quando forçados em uma única categoria.\n• Prognóstico — Prognóstico intermediário entre os grupos B e C clássicos.\n• Reprodutibilidade — Parte da reavaliação da confiabilidade da classificação do pilar lateral combinada à classificação de Stulberg, publicada por Herring et al.\n• Aplicação clínica — Crianças de 4 a 6 anos com doença em borda B/C ou grupo C têm apenas cerca de 43% de bons resultados em duas séries, reforçando a necessidade de estratificação mais fina."},{"id":"stulberg-classificacao-perthes","area":"Pediátrica","front":"STULBERG\n\nQuais são os critérios dessa classificação?\n(Classificação de Stulberg do resultado radiográfico final (congruência e esfericidade) na doença de Legg-Calvé-Perthes)","back":"• Classe I — Quadril radiograficamente normal, cabeça femoral esférica (congruência esférica).\n• Classe II — Cabeça femoral esférica, porém com coxa magna, colo femoral curto ou acetábulo levemente displásico (congruência esférica).\n• Classe III — Cabeça femoral não esférica (ovoide), mas não achatada (congruência asférica).\n• Classe IV — Cabeça femoral achatada, congruente com acetábulo igualmente achatado (congruência asférica).\n• Classe V — Cabeça femoral achatada, incongruente com acetábulo normal (não achatado); pior prognóstico (incongruência asférica)."},{"id":"fatores-prognosticos-perthes","area":"Pediátrica","front":"PROGNÓSTICO PERTHES\n\nQuais são os critérios dessa classificação?\n(Fatores prognósticos na doença de Legg-Calvé-Perthes)","back":"• Idade de início — 8 anos é o divisor de águas mais citado; prognóstico pior quando o início ocorre após os 6 anos, e muito reservado após os 11-12 anos mesmo com Catterall 2 ou Salter-Thompson A.\n• Extensão do acometimento epifisário — Quanto maior a extensão (Catterall 3-4, Salter-Thompson B, Herring C), pior o prognóstico.\n• Extrusão epifisária — Extrusão superior a 20% da largura da cabeça femoral é o limiar crítico após o qual o risco de deformação aumenta dramaticamente.\n• Sinais de risco (head-at-risk) — Presença de dois ou mais sinais associa-se a maus resultados.\n• Comprometimento fisário — Interferência do crescimento fisário ocorre em até 90% dos pacientes, com 25% desenvolvendo fechamento fisário prematuro; correlaciona-se d..."},{"id":"mose-classificacao-esfericidade","area":"Pediátrica","front":"MOSE\n\nQuais são os critérios dessa classificação?\n(Método do template de Mose para avaliação semiquantitativa da esfericidade da cabeça femoral)","back":"• Técnica — Template transparente de círculos concêntricos espaçados 2 mm, sobreposto às radiografias AP e perfil (Lauenstein) da cabeça femoral.\n• Cabeça esférica — A margem articular da cabeça femoral coincide perfeitamente com o arco de um círculo do mesmo raio em ambas as incidências.\n• Cabeça ovoide — Margem articular ajusta-se ao arco de um círculo em ambas as incidências, mas o raio difere em até 2 mm entre AP e perfil.\n• Cabeça achatada/irregular — Margem articular não se ajusta ao arco de nenhum círculo em uma das incidências, ou o raio difere em mais de 2 mm entre as duas incidências.\n• Achado de longo prazo — Nenhum paciente com cabeça 'normal, esférica' (classificação de Mose) desenvolveu artrose até a metade da 4ª década, ma..."},{"id":"conduta-por-estagio-perthes","area":"Pediátrica","front":"CONDUTA-PERTHES\n\nQuais são os critérios dessa classificação?\n(Objetivos e escopo do tratamento da doença de Legg-Calvé-Perthes conforme o estágio de apresentação (Tabela 23-4))","back":"• Estágios Ia a IIa (fase precoce) — Objetivo é prevenir a deformidade da cabeça femoral; janela de oportunidade limitada, pois a deformação inicia no final da fragmentação (IIb) ou logo após; tratamento deve ser instituído em até 7 a 11 meses do início dos sintomas.\n• Estágio IIb ou IIIa (fase tardia) — Cabeça já extrusada e sujeita a forças deformantes, possivelmente já com alguma distorção; objetivo passa a ser minimizar o dano causado pelo atraso no tratamento e abordar a abdução em dobradiça (hinge abduction), se presente.\n• Estágio IIIb ou IV (deformidade já estabelecida) — Tratamento das sequelas (coxa breve, sobrecrescimento trocantérico, coxa magna); considerar avanço do trocanter, osteotomias de resgate ou correção da forma da ..."},{"id":"indicacoes-contencao-perthes","area":"Pediátrica","front":"CONTENÇÃO\n\nQuais são os critérios dessa classificação?\n(Indicações de contenção (containment) em crianças com Legg-Calvé-Perthes em fase inicial — estágios Ia, Ib, IIa (Tabela 23-5))","back":"• Crianças menores de 8 anos — Contenção indicada assim que qualquer extrusão for detectada na radiografia AP de acompanhamento.\n• Crianças de 8 anos ou mais — Contenção 'preventiva' (preemptive) recomendada assim que o diagnóstico é estabelecido, mesmo sem extrusão demonstrável, pois a extrusão ocorrerá mais cedo ou mais tarde nesses casos.\n• Contenção não indicada (grupo 1) — Crianças jovens com doença leve (menos de 50% da epífise infartada) e sem extrusão, que têm bom prognóstico natural.\n• Contenção não indicada (grupo 2) — Casos em que já é tarde demais (doença além do estágio IIa) ou início na adolescência, quando a contenção não funciona.\n• Benefício da contenção precoce — Estudo mostrou odds ratio de resultado ruim de 16,5 quand..."},{"id":"classificacao-coxa-vara","area":"Pediátrica","front":"COXA VARA\n\nQuais são os critérios dessa classificação?\n(Classificação de coxa vara (Elmslie, modificada por Fairbank) — Tabela 23-6)","back":"• Coxa vara congênita — Defeito cartilaginoso primário no colo femoral; espectro de deficiência femoral (fêmur curto congênito, fêmur arqueado congênito, deficiência focal femoral proximal); discrepância de comprimento de membro frequentemente presente.\n• Coxa vara adquirida — Secundária a trauma, infecção, distúrbios ósseos patológicos (ex. displasia fibrosa), epifisiólise femoral proximal (EFP) ou doença de Legg-Calvé-Perthes; decréscimo do ângulo cervicodiafisário por necrose da cabeça femoral ou alteração do crescimento fisário.\n• Coxa vara desenvolvimental (idiopática) — Diminuição do ângulo cervicodiafisário que se desenvolve na infância precoce sem outras manifestações esqueléticas ou causa evidente; incidência de 1 em 25.000 nasc..."},{"id":"angulo-he-coxa-vara-desenvolvimento","area":"Pediátrica","front":"ÂNGULO H-E\n\nQuais são os critérios dessa classificação?\n(Ângulo de Hilgenreiner-epifisário (H-E) como fator prognóstico na coxa vara desenvolvimental)","back":"• Definição — Ângulo entre a linha de Hilgenreiner e uma linha traçada paralela à fise femoral capital; valor médio normal é de 16 graus.\n• Ângulo menor que 45 graus — Deformidade considerada estável; progressão improvável; seguimento radiográfico bienal recomendado até a maturidade esquelética.\n• Ângulo entre 45 e 59 graus — Risco de progressão incerto; radiografias anuais recomendadas para reavaliação.\n• Ângulo de 60 graus ou mais — Deformidade quase invariavelmente progride; intervenção cirúrgica recomendada.\n• Meta cirúrgica — Correção do ângulo H-E para menos de 38-40 graus está associada a taxa de recidiva muito baixa (cerca de 5%); manutenção acima de 40 graus associa-se a até 93% de necessidade de revisão por recidiva do varo."},{"id":"kocher-criterios-artrite-septica","area":"Pediátrica","front":"KOCHER\n\nQuais são os critérios dessa classificação?\n(Critérios preditivos de Kocher para diferenciar artrite séptica de sinovite transitória do quadril)","back":"• Critério 1 — História de febre.\n• Critério 2 — Recusa de carga de peso (não deambulação / não weight-bearing).\n• Critério 3 — VHS (velocidade de hemossedimentação) maior que 40 mm/hora.\n• Critério 4 — Leucócitos séricos maiores que 12.000 células/mL.\n• Aplicação — Quatro preditores clínicos multivariados independentes; outros autores (Taylor e Clarke) descreveram preditores adicionais, incluindo temperatura acima de 37°C, PCR maior que 1 mg/dL e espaço articular do quadril aumentado em mais de 2 mm."},{"id":"diferencial-sinovite-transitoria-perthes","area":"Pediátrica","front":"DIFERENCIAL SINOVITE\n\nQuais são os critérios dessa classificação?\n(Diagnóstico diferencial da sinovite transitória do quadril na criança)","back":"• Artrite séptica — Diagnóstico mais crítico a excluir; dor mais intensa e limitação de movimento mais acentuada; hemocultura e análise do líquido sinovial (Gram positivo em 30% a 50% dos casos) confirmam.\n• Doença de Legg-Calvé-Perthes — Apresentação semelhante e faixa etária similar, porém dor de início mais insidioso e mais prolongada; radiografia pode mostrar alargamento do espaço articular medial e núcleo ossificado femoral menor no lado afetado.\n• Osteomielite/tuberculose de fêmur ou pelve — Pode mimetizar dor de quadril, limitação de movimento e efusão articular; RM e cintilografia óssea auxiliam a diferenciar por alterações características na medula óssea.\n• Febre reumática/artrite pós-estreptocócica — Sinovite ocorre 2 a 4 seman..."},{"id":"idiopathic-chondrolysis-diagnostico","area":"Pediátrica","front":"CONDRÓLISE IDIOPÁTICA\n\nQuais são os critérios dessa classificação?\n(Critérios diagnósticos e evolução da condrólise idiopática do quadril)","back":"• Critério radiográfico diagnóstico — Diminuição concêntrica do espaço articular para menos de 3 mm é considerada critério diagnóstico (espaço normal mede 3,5 a 7 mm).\n• Perfil clínico típico — Adolescente do sexo feminino (proporção aproximada de 6:1), idade média de 11-12 anos, com história de 2 a 3 meses de dor, rigidez e claudicação do quadril, sem sintomas sistêmicos.\n• Estágio agudo — Dura de 6 a 16 meses, com resposta inflamatória, dor e diminuição da amplitude de movimento.\n• Estágio crônico — Dura de 3 a 5 anos, com aumento de tecido fibroso e curso menos previsível; desfecho final variável (resolução parcial/completa, anquilose rígida pouco dolorosa, ou anquilose dolorosa progressiva).\n• Achados radiográficos avançados — Oblite..."},{"id":"classificacao-coxa-saltans","area":"Pediátrica","front":"COXA SALTANS\n\nQuais são os critérios dessa classificação?\n(Classificação do quadril em estalido (coxa saltans / snapping hip))","back":"• Tipo externo — Mais comum; estalido da borda posterior do trato iliotibial ou da borda anterior do glúteo máximo sobre o trocanter maior durante a flexão do quadril a partir da extensão.\n• Tipo interno — Estalido do tendão iliopsoas sobre a eminência iliopectínea ou sobre a cabeça femoral; mais comum em adolescentes atletas (14 a 17 anos) envolvidos em corrida.\n• Tipo intra-articular — Causado por corpo livre intra-articular (fragmento de fratura ou ruptura labral); apresentação distinta e quase sempre requer cirurgia para alívio sintomático.\n• Diagnóstico do tipo interno — Reproduzido levando o quadril de flexão/abdução para extensão/adução; bloqueio do estalido com pressão digital sobre o tendão iliopsoas confirma o diagnóstico.\n• Tr..."},{"id":"bladder-exstrophy-espectro","area":"Pediátrica","front":"EXSTROFIA VESICAL\n\nQuais são os critérios dessa classificação?\n(Espectro de anomalias da exstrofia vesical (classic exstrophy, epispádia isolada, exstrofia cloacal))","back":"• Exstrofia clássica — Forma mais comum (70% dos casos); pelve alargada com diástase anterior, bexiga aberta e epispádia completa.\n• Epispádia isolada — Forma mais leve do espectro; pode ter bexiga fechada, mas com sínfise púbica alargada.\n• Exstrofia cloacal — Forma mais grave; inclui todos os achados anteriores mais onfalocele e frequentemente defeito do tubo neural; anatomia extremamente variável entre pacientes.\n• Achados pélvicos característicos — Diástase púbica de 3 a 5 cm ao nascimento (aumenta com a idade); asas ilíacas rodadas externamente cerca de 15 graus; acetábulos retrovertidos; displasia de quadril em cerca de 16% dos neonatos.\n• Indicação de osteotomia — Reservada para bexiga que não pode ser fechada sem mobilização adic..."},{"id":"loder-estabilidade-scfe","area":"Pediátrica","front":"LODER\n\nQuais são os critérios dessa classificação?\n(Classificação de Loder da Epifisiólise Femoral Proximal (EFCF) por estabilidade)","back":"• Estável — Criança consegue deambular, com ou sem muletas, apesar da dor.\n• Instável — Dor tão intensa que a deambulação é impossível mesmo com muletas.\n• Frequência — EFCF instável corresponde a 50-60% dos casos agudos e a 5-10% de todos os EFCF.\n• Prognóstico — Osteonecrose (ON) em 47% dos instáveis vs. 0% dos estáveis na série original de Loder et al.\n• Relevância — Substituiu a classificação temporal (agudo/crônico) por predizer melhor ON e desfechos ruins."},{"id":"classificacao-temporal-scfe","area":"Pediátrica","front":"TEMP-SCFE\n\nQuais são os critérios dessa classificação?\n(Classificação temporal da EFCF (agudo, crônico, agudo sobre crônico, pré-escorregamento))","back":"• Crônico — Sintomas por mais de 3 semanas; corresponde a 80-90% de todos os EFCF.\n• Agudo — Sintomas por menos de 3 semanas.\n• Agudo sobre crônico — Exacerbação aguda da dor após pródromo de sintomas de ao menos 3 semanas.\n• Pré-escorregamento (preslip) — Quadril sintomático com fisólise sem deslocamento verdadeiro do colo em relação à cabeça; confirmação geralmente exige RM.\n• Limitação — Classificação de pouco valor prognóstico/pato-mecânico; amplamente substituída pela classificação de estabilidade de Loder."},{"id":"wilson-grau-escorregamento","area":"Pediátrica","front":"WILSON\n\nQuais são os critérios dessa classificação?\n(Classificação de Wilson do grau de escorregamento (deslocamento percentual))","back":"• Leve — Deslocamento da epífise menor que 33% do diâmetro do colo femoral.\n• Moderado — Deslocamento entre 33% e 50% do diâmetro do colo femoral.\n• Grave — Deslocamento maior que 50% do diâmetro do colo femoral.\n• Método — Descrita por Wilson em 1938; quantifica o deslocamento da cabeça femoral como percentual do diâmetro do colo.\n• Limitação — Medida inconsistente por variações de posicionamento e por remodelação proximal progressiva ao longo do tempo; útil apenas antes da remodelação."},{"id":"southwick-grau-escorregamento","area":"Pediátrica","front":"SOUTHWICK\n\nQuais são os critérios dessa classificação?\n(Ângulo de Southwick (grau de escorregamento epífise-diáfise))","back":"• Leve — Diferença do ângulo cabeça-diáfise (lado afetado vs. contralateral) menor que 30 graus.\n• Moderado — Diferença entre 30 e 50 graus.\n• Grave — Diferença maior que 50 graus.\n• Técnica — Ângulos entre a fise femoral proximal e a diáfise medidos nas incidências anteroposterior e em perfil; a diferença entre o lado afetado e o não afetado determina o grau.\n• Uso clínico — Orienta a escolha e a magnitude de correção em osteotomias corretivas (Southwick, Imhauser) para deformidade residual."},{"id":"klein-linha-trethowan","area":"Pediátrica","front":"KLEIN\n\nQuais são os critérios dessa classificação?\n(Linha de Klein e sinal de Trethowan na EFCF)","back":"• Técnica — Linha traçada ao longo da borda lateral do colo femoral na radiografia anteroposterior do quadril.\n• Normal — Uma porção da epífise femoral situa-se lateral à linha de Klein.\n• Positivo (EFCF) — A linha de Klein fica cefálica à epífise, ou a porção de epífise acima da linha é menor que 2 mm em comparação ao quadril contralateral.\n• Sinônimo — Um resultado positivo também é conhecido como sinal de Trethowan.\n• Sensibilidade — A incidência em perfil (frog-leg) é mais sensível que a AP para detectar graus leves de escorregamento."},{"id":"sinal-mancha-metafisaria-steel","area":"Pediátrica","front":"STEEL\n\nQuais são os critérios dessa classificação?\n(Sinal da mancha metafisária de Steel (metaphyseal blanch sign))","back":"• Achado — Radiodensidade aumentada na metáfise femoral proximal, visível na incidência anteroposterior.\n• Mecanismo — Sobreposição da metáfise sobre o colo/epífise à medida que o escorregamento progride lateralmente em relação ao teardrop acetabular.\n• Achados associados — Diminuição da altura da epífise, alargamento/irregularidade fisária e osteopenia do quadril afetado.\n• Utilidade — Achado radiográfico precoce e sutil que auxilia o diagnóstico de EFCF leve, quando o deslocamento franco ainda não é evidente."},{"id":"psa-risco-contralateral","area":"Pediátrica","front":"PSA\n\nQuais são os critérios dessa classificação?\n(Ângulo de inclinação posterior (Posterior Sloping Angle) — risco de EFCF contralateral)","back":"• Técnica — Medido na incidência em perfil (frog-leg), entre a linha que une as margens anterior e posterior da epífise e uma linha perpendicular à diáfise femoral.\n• Limiar de risco — Valores de PSA entre 12 e 15 graus têm sido propostos como limiar para prever EFCF contralateral futuro.\n• Aplicação clínica — Auxilia a decisão entre observação vigilante e fixação profilática do quadril contralateral ainda não escorregado."},{"id":"loder-criterios-atipico","area":"Pediátrica","front":"LODER-ATÍPICO\n\nQuais são os critérios dessa classificação?\n(Critérios de Loder para EFCF atípico (teste idade-peso-altura))","back":"• Conceito — Teste prognóstico idade-peso e idade-altura para distinguir EFCF típico (idiopático) de atípico (geralmente relacionado a endocrinopatia).\n• Achado — Extremos de idade e peso, de altura e peso, ou de idade+altura+peso associam-se a odds ratio aumentado de EFCF atípico.\n• Faixa etária suspeita — Início antes dos 10 anos, ou após 14 anos em meninas/16 anos em meninos, deve levantar suspeita de causa metabólica/sistêmica.\n• Skeletal age — Idade óssea (método de Oxford) tende a estar avançada em crianças mais novas e atrasada em crianças mais velhas com EFCF.\n• Conduta — Triagem endócrina de rotina não é recomendada em todos os pacientes; reservada a casos com idade atípica, baixa estatura ou outros sinais de alerta."},{"id":"criterios-triagem-endocrina-scfe","area":"Pediátrica","front":"TRIAGEM-ENDÓCRINA\n\nQuais são os critérios dessa classificação?\n(Critérios de triagem endócrina em crianças com EFCF (Burrow et al.))","back":"• Critério principal — Estatura abaixo do percentil 10 é a característica isolada mais útil para rastreio de anormalidades endócrinas.\n• Desempenho — Sensibilidade e valor preditivo negativo de ao menos 90% usando esse ponto de corte de estatura.\n• Exames indicados — Em crianças com suspeita de doença endócrina (idade 15 anos, baixa estatura), solicitar provas de função tireoidiana; dosar GH em crianças de baixa estatura.\n• Achado prático — A maioria das crianças com EFCF e disfunção tireoidiana não tem história prévia conhecida de tireoidopatia no momento do diagnóstico do EFCF.\n• Conduta geral — Triagem endócrina de rotina em todos os pacientes com EFCF não é recomendada na ausência de sinais clínicos sugestivos."},{"id":"risco-scfe-contralateral","area":"Pediátrica","front":"RISCO-CONTRA\n\nQuais são os critérios dessa classificação?\n(Risco de EFCF contralateral metácrono)","back":"• Apresentação inicial — EFCF bilateral já presente em cerca de 20% dos casos no momento do diagnóstico.\n• Metácrono — 10-20% adicional desenvolve EFCF contralateral na adolescência; 80-90% desses casos ocorre dentro de 18 meses do primeiro escorregamento.\n• Longo prazo — Frequência total de bilateralidade em seguimento a longo prazo de aproximadamente 60% (podendo chegar a 80% em algumas séries).\n• Endocrinopatias — 61-100% de bilateralidade a curto prazo em crianças com EFCF e doença endócrina subjacente conhecida.\n• EFCF instável contralateral — Risco estimado de apenas 1-2% durante a adolescência (combinando 20-25% de risco de escorregamento contralateral com 5-10% de taxa de instabilidade)."},{"id":"indicacao-fixacao-profilatica-contralateral","area":"Pediátrica","front":"PROFILÁTICA\n\nQuais são os critérios dessa classificação?\n(Indicações de fixação profilática do quadril contralateral não escorregado)","back":"• Doença endócrina subjacente — Alto risco de escorregamento contralateral (fixação profilática recomendada).\n• Radioterapia pélvica prévia — Quando o quadril contralateral foi incluído no campo de radiação.\n• Idade menor que 10 anos — Risco elevado de bilateralidade e de discrepância de comprimento de membros após fixação unilateral.\n• Acesso limitado a seguimento — Pacientes em áreas remotas, com dificuldade de acompanhamento clínico e radiográfico regular.\n• Doença renal — Contraindicação relativa; manejo clínico da osteodistrofia renal é preferido em vez da fixação profilática rotineira."},{"id":"escala-osteonecrose-scfe","area":"Pediátrica","front":"ON-SCFE\n\nQuais são os critérios dessa classificação?\n(Risco de osteonecrose (ON) conforme estabilidade e método de tratamento do EFCF)","back":"• EFCF estável — Osteonecrose próxima de 0% (série original de Loder et al.).\n• EFCF instável — Osteonecrose em cerca de 47% na série de Loder et al.; faixa geral relatada de 12,5% a 58%.\n• Fixação in situ — Osteonecrose em 0-5% dos casos, mais comumente 2-3%.\n• Osteotomia subcapital — Maior risco de todas as técnicas: osteonecrose em 5-35% (até 42% em algumas séries).\n• Osteotomia na base do colo / intertrocantérica — Base do colo: ON em 0-5%; intertrocantérica: raramente associada a ON (até 6% relatado)."},{"id":"condrolise-criterios-scfe","area":"Pediátrica","front":"CONDRÓLISE\n\nQuais são os critérios dessa classificação?\n(Critérios diagnósticos de condrólise pós-EFCF)","back":"• Tríade diagnóstica — Dor, diminuição da amplitude de movimento do quadril e estreitamento radiográfico do espaço articular.\n• Suspeita clínica — Sinovite e amplitude de movimento que não melhoram nas primeiras 2-3 semanas de pós-operatório.\n• Sinal característico — Contratura fixa em abdução do quadril, diferente de outras afecções do quadril.\n• Incidência por tratamento — Espica gessada 14-53%; osteotomia intertrocantérica 2-25%; fixação in situ e epifisiodese com enxerto ósseo, geralmente <5%.\n• Conduta — Tratamento inicialmente conservador (descarga protegida, fisioterapia, anti-inflamatórios); casos refratários podem necessitar cirurgia de salvamento."},{"id":"conduta-fixacao-scfe-estabilidade","area":"Pediátrica","front":"CONDUTA-FIX\n\nQuais são os critérios dessa classificação?\n(Conduta de fixação cirúrgica in situ conforme estabilidade do EFCF)","back":"• EFCF estável — Um parafuso canulado grande (6,5-7,3 mm), de rosca reversa; carga total permitida como tolerado no pós-operatório.\n• EFCF instável — Dois parafusos canulados grandes; considerar aspiração/artrotomia articular; descarga de peso por 3-4 semanas no pós-operatório.\n• Posicionamento do implante — Parafuso perpendicular à fise, posição centro-centro na cabeça femoral, a 5-6 mm da subcondral, ponto de entrada lateral à linha intertrocantérica.\n• Manipulação/redução forçada — Contraindicada; associada a maior risco de osteonecrose.\n• Seguimento radiográfico — Radiografias com 1 semana, 1 mês e 2 meses; depois a cada 3-6 meses até o fechamento fisário bilateral."},{"id":"conduta-osteotomia-corretiva-scfe","area":"Pediátrica","front":"OSTEOTOMIA-COND\n\nQuais são os critérios dessa classificação?\n(Conduta de osteotomia corretiva para deformidade residual do EFCF)","back":"• Indicação geral — Persistência de dor e/ou limitação funcional significativa por pelo menos 1 ano após a fixação in situ.\n• Osteotomia intertrocantérica (Southwick/Imhauser) — Técnica mais utilizada; menor risco de osteonecrose, porém correção mais distante do foco real da deformidade.\n• Osteotomia subcapital — Maior poder de correção anatômica, porém maior risco de osteonecrose (5-35%); reservada a casos selecionados por cirurgiões experientes.\n• Osteotomia na base do colo — Correção intermediária entre subcapital e intertrocantérica, com risco de osteonecrose intermediário (0-5%).\n• Osteotomia rotacional transtrocantérica (Sugioka) — Reservada a deslocamento maior que 45 graus (ângulo cabeça-diáfise); tecnicamente exigente, uso restr..."},{"id":"sugioka-criterio-osteotomia-rotacional","area":"Pediátrica","front":"SUGIOKA\n\nQuais são os critérios dessa classificação?\n(Critério de Sugioka para osteotomia rotacional transtrocantérica)","back":"• Indicação — EFCF com deslocamento maior que 45 graus, medido pelo ângulo cabeça-diáfise (head-shaft angle).\n• Técnica — Osteotomia intertrocantérica rotacional para correção de deformidade residual grave da proximal do fêmur.\n• Resultados — 90% de resultados excelentes e melhora da amplitude de movimento na série original de Sugioka; risco de osteonecrose relatado em casuísticas pequenas.\n• Limitação — Tecnicamente muito exigente; uso restrito a poucos centros com experiência específica na técnica."},{"id":"medidas-radiograficas-displasia-acetabular-adolescente","area":"Pediátrica","front":"RX-DISPLASIA\n\nQuais são os critérios dessa classificação?\n(Medidas Radiográficas de Displasia Acetabular no Quadril do Adolescente (incidência AP de pelve))","back":"• Ângulo centro-borda lateral (Wiberg) — Maior que 25 graus é considerado normal; menor que 25 graus é considerado displasia do quadril.\n• Ângulo de Tönnis (ângulo do teto acetabular) — De 0 a 10 graus é normal; maior que 10 graus é consistente com displasia do quadril.\n• Índice de cobertura da cabeça femoral (A/B) — Razão maior que 0,80 é considerada normal; razão menor que 0,80 é preocupante para displasia do quadril.\n• Profundidade acetabular (A/B) — Razão deve ser maior que 0,30; razão menor que 0,30 é comum na subcobertura anterior e na displasia do quadril.\n• Relação parede anterior/posterior (sinal do cross-over) — A parede anterior (linha azul) deve ser mais medial e mais horizontal que a parede posterior (linha vermelha) na AP d..."},{"id":"padroes-deficiencia-acetabular-tc-jovem-adulto","area":"Pediátrica","front":"DEF-ACET\n\nQuais são os critérios dessa classificação?\n(Padrões de Deficiência Acetabular na Displasia do Adolescente/Adulto Jovem (avaliação por TC 3D))","back":"• Deficiência anterior — Subcobertura predominantemente da parede/teto anterior do acetábulo.\n• Deficiência superior — Subcobertura predominantemente do teto superior (sourcil) do acetábulo.\n• Deficiência posterior — Subcobertura predominantemente da parede posterior do acetábulo.\n• Deficiência global — Subcobertura envolvendo de forma difusa todas as paredes do acetábulo, sem predomínio regional isolado."},{"id":"indicacao-cirurgica-fai-aberta-artroscopica-adolescente","area":"Pediátrica","front":"FAI-COND\n\nQuais são os critérios dessa classificação?\n(Indicação de Conduta no Impacto Femoroacetabular (FAI) do Quadril do Adolescente)","back":"• Tratamento não cirúrgico inicial — Modificação/repouso de atividade, anti-inflamatório oral, fisioterapia e/ou terapia intra-articular; indicado quando o exame físico, sintomas e estudos radiográficos são consistentes com FAI, antes de indicar cirurgia.\n• Cirurgia aberta (luxação cirúrgica) — Mais indicada em deformidades cam de maior magnitude, impacto associado a retrotorsão femoral significativa, ou malrotação acetabular maior/impacto extra-articular envolvendo estruturas como o trocânter maior.\n• Artroscopia de quadril — Indicação ideal para lesão acessível por via artroscópica no fêmur anterior ou rebordo acetabular, na ausência de defeitos ou deformidade cartilaginosa articular maiores (femoral ou acetabular).\n• Procedimentos e c..."},{"id":"mecanismo-impacto-pos-scfe","area":"Pediátrica","front":"IMP-SCFE\n\nQuais são os critérios dessa classificação?\n(Mecanismos de Impacto Femoroacetabular Residual Após Epifisiólise Proximal do Fêmur Tratada (pós-SCFE))","back":"• Mecanismo tipo cam — Anatomia semelhante a uma deformidade cam clássica, resultante do próprio deslizamento epifisário e do remodelamento metafisário; o dano cartilaginoso pode ser independente da gravidade original do escorregamento e mais associado à deformidade cam/metafisária residual na vida adulta.\n• Mecanismo tipo pincer — Causado por proeminência metafisária associada a grande retroversão do colo femoral; a retroversão femoral é altamente prevalente em pacientes com SCFE, favorecendo esse padrão mesmo quando há deformidade cam-like importante associada.\n• Mecanismo misto (cam + pincer) — Combinação dos dois padrões acima, comum no SCFE tratado, já que a retroversão femoral coexiste frequentemente com deformidade cam residual; o..."},{"id":"congruencia-articular-lcp-residual-planejamento","area":"Pediátrica","front":"CONGR-LCP\n\nQuais são os critérios dessa classificação?\n(Congruência Articular no Planejamento Cirúrgico da Doença de Legg-Calvé-Perthes Residual Sintomática)","back":"• Congruência esférica — Cabeça femoral aspérica/deformada, porém mantendo relação congruente com o acetábulo através da amplitude de movimento avaliada.\n• Congruência asférica — Cabeça femoral não esférica com adaptação acetabular relativa que ainda mantém contato articular satisfatório em determinadas posições.\n• Incongruência — Perda de contato articular adequado entre cabeça femoral e acetábulo, indicando maior complexidade e risco cirúrgico."},{"id":"categorias-etiologicas-dor-quadril-adolescente","area":"Pediátrica","front":"ETIO-DOR\n\nQuais são os critérios dessa classificação?\n(Categorias Etiológicas da Dor no Quadril do Adolescente (diagnóstico diferencial))","back":"• Causas intra-articulares — Lesões pós-traumáticas, sinovite crônica e neoplasias não malignas como osteoma osteoide e condromatose sinovial.\n• Causas extra-articulares — Tendinopatia, fraqueza muscular, bursite e condições raras como compressão nervosa periarticular (nervo ciático ou cutâneo femoral lateral).\n• Causas não ortopédicas — Anormalidades neurológicas, do retroperitônio, da parede abdominal e intraperitoneais que podem causar dor referida na região do quadril."},{"id":"estruturas-periarticulares-bursite-tendinopatia-quadril","area":"Pediátrica","front":"BURSA-QUADRIL\n\nQuais são os critérios dessa classificação?\n(Estruturas Periarticulares Mais Acometidas por Bursite/Tendinopatia no Quadril do Adolescente)","back":"• Bursa iliopectínea e tendão do psoas — Bursite/tendinopatia do psoas, ocasionalmente associada a instabilidade anterior do quadril; manejo inclui repouso, anti-inflamatórios, fisioterapia e, se refratário, alongamento do tendão do psoas (intramuscular na borda pélvica ou no trocânter menor).\n• Bursa trocantérica e trato iliotibial — Bursite trocantérica crônica; quando refratária, manejo cirúrgico com bursectomia e janelamento ou alongamento da banda iliotibial, por via aberta ou artroscópica.\n• Tendão adutor longo — Overuse por movimentos repetitivos e forçados do quadril (ex.: dança de alto chute, artes marciais); dor à palpação ao longo do trajeto do músculo/tendão, podendo simular estalido intra-articular condrolabral.\n• Bursa isqu..."},{"id":"conduta-terapeutica-displasia-acetabular-sintomatica-adolescente","area":"Pediátrica","front":"COND-DISPLASIA\n\nQuais são os critérios dessa classificação?\n(Conduta Terapêutica na Displasia Acetabular Sintomática do Adolescente)","back":"• Tratamento não cirúrgico — Considerado em formas mais leves de displasia e na ausência de subluxação, cujo curso natural é menos previsível; inclui modificação de atividade, fortalecimento de core e abdutores, anti-inflamatórios e infiltração intra-articular de corticoide.\n• Plicatura capsular artroscópica — Técnica descrita para formas mais leves de displasia definidas apenas pelo ângulo centro-borda lateral; durabilidade e eficácia em longo prazo ainda não bem documentadas, com resultados inferiores relatados após reconstrução por falha de artroscopia prévia.\n• Osteotomia periacetabular de Bernese (PAO) — Procedimento contemporâneo de escolha para displasia acetabular sintomática; objetivo é estabilizar o quadril e preservar/melhorar..."},{"id":"perfil-rotacional-tfa","area":"Pediátrica","front":"TFA\n\nQuais são os critérios dessa classificação?\n(Perfil Rotacional e Ângulo Coxo-Podálico (Thigh-Foot Angle))","back":"• Técnica — Paciente em decúbito ventral, joelhos fletidos; observa-se o eixo do retropé em relação à coxa (mantida em rotação neutra) para determinar o TFA.\n• TFA no lactente — Média de 5 graus interno (variação de -30 a +20 graus).\n• TFA aos 8 anos — Aumenta para média de 10 graus externo (variação de -5 a +30 graus); muda pouco após os 12 anos.\n• Ângulo intermaleolar-coxa — Usado quando há deformidade significativa do pé; ângulo entre o eixo longitudinal da coxa e uma linha perpendicular ao eixo intermaleolar.\n• Bisector do antepé — Linha ao longo do retropé que, projetada ao antepé, deve bissectar o segundo espaço interdigital em pé normal (desvia lateralmente no metatarso aduto)."},{"id":"teste-craig-ryder-anteversao","area":"Pediátrica","front":"Craig/Ryder\n\nQuais são os critérios dessa classificação?\n(Teste de Proeminência Trocantérica (Craig ou Ryder) para Anteversão Femoral)","back":"• Posição — Paciente em decúbito ventral; o quadril é rotado até que a proeminência do trocânter maior seja palpada na posição mais lateral possível.\n• Medida — O grau de rotação interna (medial) do quadril nessa posição corresponde à anteversão femoral verdadeira.\n• Anteversão ao nascimento — Média de 30 graus (variação de 15 a 50 graus).\n• Anteversão aos 10 anos — Diminui para média de 20 graus (variação de 10 a 35 graus).\n• Alerta clínico — Rotação externa do quadril assimétrica em adolescente deve levantar suspeita de epifisiólise proximal do fêmur, não anteversão diminuída isolada."},{"id":"eixos-mecanico-anatomico-joa","area":"Pediátrica","front":"JOA\n\nQuais são os critérios dessa classificação?\n(Eixos Mecânico/Anatômico e Ângulos de Orientação Articular (Nomenclatura Padronizada))","back":"• Eixo mecânico — Linha reta que conecta os centros articulares proximal e distal; do centro da cabeça femoral ao centro do tornozelo, passa 5-10 mm medial ao centro do joelho no membro normal.\n• Eixo anatômico — Linha diafisária média de um segmento ósseo; no fêmur, angula-se 6 graus em valgo em relação ao eixo mecânico; na tíbia, é paralelo ao eixo mecânico.\n• Nomenclatura JOA — Letra minúscula indica eixo anatômico (a) ou mecânico (m); letra maiúscula indica lado medial (M), lateral (L), anterior (A) ou posterior (P); ex.: aLDFA = ângulo anatômico lateral distal do fêmur.\n• Linha articular do joelho (frontal) — Distal do fêmur: tangente aos pontos mais distais dos côndilos femorais medial e lateral; proximal da tíbia: através das porç..."},{"id":"jlca-angulo-convergencia","area":"Pediátrica","front":"JLCA\n\nQuais são os critérios dessa classificação?\n(Ângulo de Convergência da Linha Articular (Joint Line Convergence Angle))","back":"• Definição — Ângulo formado entre as linhas de orientação articular do fêmur distal e da tíbia proximal, que deveriam ser paralelas em situação normal.\n• Valor anormal — JLCA maior que 3 graus indica frouxidão ligamentar ou perda de espaço cartilaginoso na articulação do joelho.\n• Relevância clínica — A frouxidão de tecidos moles pode criar deformidade angular aparente do membro que pode ser confundida com deformidade óssea verdadeira.\n• Aplicação no Blount — Alargamento lateral do espaço articular mais de 3 graus em radiografia em pé indica instabilidade do ligamento colateral lateral por varo de longa data."},{"id":"llrs-aim-index","area":"Pediátrica","front":"LLRS-AIM\n\nQuais são os critérios dessa classificação?\n(LLRS-AIM Index para Deformidade de Membro Inferior)","back":"• Estrutura — Sistema de escore que avalia 7 domínios (mnemônico LLRS-AIM), cada um pontuado de 1 a 4, somando de 0 a 28 pontos totais.\n• Interpretação — Quanto maior a pontuação total, maior a complexidade estimada do procedimento de correção da deformidade.\n• Validação — Demonstrou alta confiabilidade intra e interobservador, com correlação positiva significativa com a classificação de gravidade/complexidade feita por especialistas.\n• Exemplo prático — Caso com deformidade angular única de 30 graus e discrepância de comprimento de 6 cm em osso displásico (doença de Ollier) somou 7 pontos, classificado como nível \"difícil\".\n• Utilidade — Auxilia na discussão de risco e complicações com o paciente/família antes de planejar a correção."},{"id":"sindrome-mau-alinhamento-rotacional","area":"Pediátrica","front":"MMS\n\nQuais são os critérios dessa classificação?\n(Síndrome do Mau Alinhamento Rotacional (Miserable Malalignment Syndrome))","back":"• Definição — Deformidade rotacional combinada dos membros inferiores, com anteversão femoral significativa associada à torção tibial externa, causando dor anterior no joelho.\n• Exame físico — Rotação interna excessiva do quadril com rotação externa limitada; TFA excessivamente rodado externamente (para fora).\n• Achado dinâmico — Ao caminhar, o ângulo de progressão do pé pode ser relativamente normal, mas observacionalmente os joelhos giram para dentro.\n• Tratamento conservador — Fortalecimento e fisioterapia devem ser tentados e a patologia subjacente excluída antes de considerar cirurgia.\n• Tratamento cirúrgico — Rotação bilateral de tíbia e fêmur: rotação externa do fêmur combinada com rotação interna compensatória da tíbia para resta..."},{"id":"langenskiold-tibia-vara","area":"Pediátrica","front":"Langenskiöld\n\nQuais são os critérios dessa classificação?\n(Classificação de Langenskiöld para Tibia Vara (Doença de Blount))","back":"• Estágios I-II — Alterações epifisárias iniciais e reversíveis (grupo de \"baixo grau\").\n• Estágios III-IV — Progressão das alterações epifisárias, ainda reversíveis (grupo de \"baixo grau\").\n• Estágios V-VI — Alterações epifisárias irreversíveis, incluindo formação de barra óssea medial (grupo de \"alto grau\").\n• Espectro — Publicada em 1952; apresenta um espectro progressivo de gravidade da doença em 6 estágios; é a classificação mais usada, apesar de baixa concordância interobservador nos estágios intermediários.\n• Divisão prática — Divisão em baixo grau (I-IV, alterações reversíveis) versus alto grau (V-VI, alterações irreversíveis) mostrou-se mais reprodutível e um guia melhor para prognóstico e tratamento."},{"id":"smith-tibia-vara","area":"Pediátrica","front":"Smith\n\nQuais são os critérios dessa classificação?\n(Classificação de Smith para Tibia Vara)","back":"• Grau A — Tibia vara potencial.\n• Grau B — Tibia vara leve.\n• Grau C — Tibia vara avançada.\n• Grau D — Fechamento fisário."},{"id":"laville-blount","area":"Pediátrica","front":"Laville\n\nQuais são os critérios dessa classificação?\n(Classificação de Laville para Doença de Blount (Idade e Progressão))","back":"• Estágio 0 — Pacientes com menos de 2,5 anos, com torção tibial interna e genu varum ao exame e \"bico\" metafisário tibial superomedial na radiografia; Blount possível, não certo — indicado seguimento semestral.\n• Estágio 1 — Blount certo; pacientes acima de 2,5 anos com doença progressiva; fise ativa sem evidência de ponte óssea; 1 em 3 chance de cura espontânea.\n• Estágio 2 (platô normal) — Blount certo; fise inativa por presença de ponte óssea medial; platô medial normal — indicada osteotomia valgizante com desrotação.\n• Estágio 2 (platô inclinado) — Blount certo; fise inativa; platô medial inclinado — indicada osteotomia valgizante com desrotação."},{"id":"lamont-blount","area":"Pediátrica","front":"LaMont\n\nQuais são os critérios dessa classificação?\n(Classificação de LaMont (Prognóstico Cirúrgico no Blount, Estágios II-III de Langenskiöld))","back":"• Tipo A — Defeito metafisário medial com lucência parcial.\n• Tipo B — Defeito completamente lúcido; rebordo inferior do defeito com inclinação ascendente (\"pires\" que retém água\") — prognóstico de correção definitiva por osteotomia melhora dramaticamente.\n• Tipo C — Defeito completamente lúcido; rebordo inferior sem inclinação ascendente (como um \"pires de lado\", derramando água).\n• Objetivo — Sistema desenvolvido para melhorar a precisão prognóstica de sucesso cirúrgico, questionando a precisão da classificação de Langenskiöld nos estágios II e III."},{"id":"blount-inicio-precoce-tardio","area":"Pediátrica","front":"Blount E/T\n\nQuais são os critérios dessa classificação?\n(Doença de Blount de Início Precoce versus Tardio (Entidades Distintas))","back":"• Início precoce (infantil) — 2 a 7 anos de idade; mais comum em meninas; doença bilateral mais frequente; deformidade multiplanar mais grave; pode haver formação de barra óssea medial e depressão epifisária medial.\n• Início tardio — ≥10 anos de idade; mais comum em meninos obesos; doença unilateral mais frequente; sem barra óssea ou depressão do platô medial descritas.\n• Localização do varo — No início precoce, o varo origina-se na tíbia proximal (fêmur pode desenvolver valgo compensatório); no início tardio, há combinação de varo na tíbia proximal e no fêmur distal.\n• Tratamento (órtese) — Órtese é opção de primeira linha no início precoce; não tem papel no início tardio.\n• Meta cirúrgica — No início tardio, objetivo é restaurar o eixo..."},{"id":"mda-angulo-metafiso-diafisario","area":"Pediátrica","front":"MDA\n\nQuais são os critérios dessa classificação?\n(Ângulo Metafisário-Diafisário Proximal da Tíbia (Levine e Drennan))","back":"• Método — Linha perpendicular ao eixo longitudinal da tíbia e linha através dos dois \"bicos\" da metáfise definem o eixo transverso; o MDA é o ângulo formado entre elas.\n• Corte original (1982) — MDA maior que 11 graus identificado como fator de risco para arqueamento patológico.\n• Refinamento (Feldman e Schoenecker) — MDA ≤9 graus ou ≥16 graus reduz erro falso-negativo/falso-positivo para menos de 5%; zona cinzenta entre 9 e 16 graus contém 30-40% dos pacientes.\n• Limitações — Rotação do membro no posicionamento radiográfico afeta a acurácia; sobreposição da metáfise fibular proximal deve ser menor que 60% para alinhamento neutro adequado.\n• Combinação com IMC — Scott et al.: todos os membros com MDA >10 graus e IMC acima de 22 desenvol..."},{"id":"ema-angulo-epifiso-metafisario","area":"Pediátrica","front":"EMA\n\nQuais são os critérios dessa classificação?\n(Ângulo Epifisário-Metafisário (Davids et al.))","back":"• Método — Ângulo formado por uma linha através da fise tibial proximal (paralela à base do centro de ossificação epifisário) e uma linha ligando o ponto médio dessa base ao ponto mais distal do bico medial da metáfise tibial.\n• Ponto de corte — MDA ≥10 graus associado a EMA acima de 20 graus indica maior risco de desenvolver doença de Blount, exigindo seguimento próximo.\n• Origem — Proposto por Davids, Blackhurst e Allen como método complementar ao MDA para avaliação radiográfica do arqueamento de membros inferiores em crianças."},{"id":"ftr-relacao-femoro-tibial","area":"Pediátrica","front":"FTR\n\nQuais são os critérios dessa classificação?\n(Relação Fêmoro-Tibial (McCarthy et al.))","back":"• Cálculo — FTR = MDA do fêmur distal dividido pelo MDA da tíbia proximal.\n• Corte diagnóstico — FTR menor que 1 é prognóstico para Blount de início precoce, com taxa de erro falso-negativo de 10% e falso-positivo de 7%.\n• Vantagem — Ao contrário do MDA isolado, a medida do FTR não é afetada pela rotação do membro durante a radiografia."},{"id":"pdt-percentual-deformidade-tibia","area":"Pediátrica","front":"%DT\n\nQuais são os critérios dessa classificação?\n(Percentual de Deformidade na Tíbia (Bowen et al.))","back":"• Cálculo — Varo do membro (LV) = ângulo entre eixo mecânico do fêmur e da tíbia; varo femoral (FV) = ângulo entre eixo mecânico do fêmur e a linha articular do joelho; varo tibial (TV) = ângulo entre eixo mecânico da tíbia e a linha articular; %DT = TV/LV.\n• Progressão — Todos os pacientes que progrediram tiveram %DT >50%; 96% dos que resolveram espontaneamente tiveram %DT <50%.\n• Combinação com MDA — Especificidade de 100% para progressão da deformidade quando %DT >50% E MDA ≥16 graus estavam presentes simultaneamente."},{"id":"blount-fatores-risco-falha-orte","area":"Pediátrica","front":"Blount-Órtese\n\nQuais são os critérios dessa classificação?\n(Fatores de Risco para Falha da Órtese no Blount de Início Precoce)","back":"• Peso — Peso acima do percentil 90 associa-se a falha do tratamento com órtese.\n• Marcha — Presença de thrust em varo durante a marcha é fator de mau prognóstico para bracing.\n• Idade — Idade maior que 3 anos no início do tratamento com órtese reduz a chance de sucesso.\n• Lateralidade — Envolvimento bilateral é fator de risco para falha.\n• Estágio radiográfico — Langenskiöld estágio III ou superior não responde bem à órtese; candidato ideal é criança magra, com doença unilateral leve, com menos de 3 anos."},{"id":"heath-staheli-angulo-joelho","area":"Pediátrica","front":"Heath-Staheli\n\nQuais são os critérios dessa classificação?\n(Valores Normais do Ângulo do Joelho e Distância Intermaleolar/Intercondilar (Heath e Staheli))","back":"• Gráfico de referência — Fornece a faixa normal por idade para o ângulo do joelho e as distâncias intermaleolar (genu valgum) e intercondilar (genu varum).\n• Distância intermaleolar normal — Deve medir menos de 8 a 10 cm; entre 2 e 8 anos, corresponde a não mais que 2 a 4 dedos do examinador entre os maléolos mediais.\n• Fibular head — Normalmente a cabeça da fíbula situa-se abaixo da linha articular; sobrecrescimento relativo em direção à linha articular sugere displasia esquelética, hemimelia tibial ou doença de Blount."},{"id":"displasia-fibrocartilaginosa-focal","area":"Pediátrica","front":"DFF\n\nQuais são os critérios dessa classificação?\n(Displasia Fibrocartilaginosa Focal (Diagnóstico Diferencial com Blount Infantil))","back":"• Localização do ápex — Varo distinto no nível da inserção do pes anserinus, mais distal que o Blount infantil (que ocorre no nível da fise).\n• Achados radiográficos — Varo abrupto na junção metafisário-diafisária sem envolver a fise; esclerose cortical medial no nível do varo, com radiolucência proximal à esclerose.\n• Fise — Fise tibial proximal normal (ao contrário do Blount infantil).\n• História natural — Correção espontânea, especialmente se o varo for menor que 30 graus.\n• Tratamento cirúrgico — Se progressiva ou limitante, osteotomia tibial proximal aguda ou gradual (gradual preferida se houver discrepância de comprimento associada)."},{"id":"genu-valgum-teste-malalinhamento","area":"Pediátrica","front":"Malalignment Test\n\nQuais são os critérios dessa classificação?\n(Teste de Malalinhamento — Gradação do Genu Valgum pelo Eixo Mecânico)","back":"• Leve — Eixo mecânico passa pelo terço medial do platô tibial lateral.\n• Moderado — Eixo mecânico passa pelo terço médio do platô tibial lateral.\n• Grave — Eixo mecânico passa pelo terço lateral do platô tibial ou não cruza o joelho.\n• Indicação de radiografia — Recomendada se genu valgum acima de 10-15 graus ao exame ou se houver assimetria entre os membros."},{"id":"eberbach-localizacao-valgo","area":"Pediátrica","front":"Eberbach\n\nQuais são os critérios dessa classificação?\n(Localização Anatômica do Genu Valgum (Eberbach et al.))","back":"• Origem tibial — 41,0% dos casos, revisão de 420 radiografias em pé de membro inteiro com desalinhamento em valgo.\n• Origem femoral — 23,6% dos casos.\n• Origem femoral e tibial combinada — 26,9% dos casos.\n• Origem intra-articular/ligamentar — 8,6% dos casos."},{"id":"fenomeno-cozen","area":"Pediátrica","front":"Cozen\n\nQuais são os critérios dessa classificação?\n(Fenômeno de Cozen (Genu Valgum Pós-Fratura Metafisária Proximal da Tíbia))","back":"• Descrição — Descrito por Cozen em 1953; fraturas metafisárias proximais extrafisárias da tíbia com fíbula íntegra podem desenvolver genu valgum, especialmente em crianças pequenas.\n• Mecanismo — Provável estímulo de crescimento da porção medial da tíbia proximal por hiperemia pós-fratura; a fise não é diretamente lesada.\n• Curso temporal — O valgo começa a se desenvolver nos primeiros meses após a lesão e atinge o máximo cerca de 1 ano depois; tende a se resolver espontaneamente com o tempo.\n• Conduta — Observação e orientação da família desde a lesão inicial; retorno programado em 4-6 meses para acompanhar o crescimento.\n• Tratamento cirúrgico se necessário — Placa de tensão em crescimento guiado medial proximal da tíbia, idealmente d..."},{"id":"boyd-pseudartrose-congenita-tibia","area":"Pediátrica","front":"Boyd\n\nQuais são os critérios dessa classificação?\n(Classificação de Boyd para Pseudartrose Congênita da Tíbia)","back":"• Tipo II — Forma mais comum; associada à maior dificuldade de obter consolidação da pseudartrose (equivalente ao Crawford tipo dysplastic IIC).\n• Tipo IV — Arqueamento anterolateral que por vezes não progride para pseudartrose franca; pode ser manejado com enxerto fibular profilático e órtese de longo prazo.\n• Aplicação — Classificação radiográfica da displasia tibial congênita (CTD), descrevendo variável história natural e prognóstico conforme o tipo."},{"id":"crawford-displasia-tibial-congenita","area":"Pediátrica","front":"Crawford\n\nQuais são os critérios dessa classificação?\n(Classificação de Crawford para Displasia Tibial Congênita (Pseudartrose Congênita da Tíbia))","back":"• Tipo IIC (dysplastic) — Consolidação da pseudartrose mais difícil de obter, equivalente ao Boyd tipo II.\n• Associação com NF1 — Mais da metade dos casos de displasia tibial congênita associam-se à neurofibromatose tipo 1 (NF1); alguns autores relatam associação em praticamente todos os casos.\n• Incidência — Pseudartrose congênita da tíbia associada ao arqueamento anterolateral é rara (1:140.000 nascidos vivos).\n• Idade de fratura — Fratura ocorre geralmente nos primeiros 5 a 6 anos de vida; pseudartrose antes dos 4 anos tem pior prognóstico, principalmente por risco de refratura."},{"id":"pseudartrose-congenita-fibula","area":"Pediátrica","front":"PCF\n\nQuais são os critérios dessa classificação?\n(Pseudartrose Congênita Isolada da Fíbula)","back":"• Associação — Geralmente ocorre associada à pseudartrose congênita da tíbia (CTD); isoladamente é muito rara; frequentemente ligada à neurofibromatose.\n• Evolução da deformidade do tornozelo — Inicialmente varo do tornozelo na infância; uma vez estabelecida a pseudartrose fibular, a deformidade converte-se de varo para valgo.\n• Tratamento — Reparo precoce (excisão da pseudartrose, enxerto ósseo autólogo, haste intramedular ou placa) antes do desenvolvimento da deformidade; crescimento guiado medial da tíbia distal se houver valgo do tornozelo.\n• Casos graves — Sinostose distal tíbio-fibular pode ser necessária para prevenir progressão do valgo do tornozelo."},{"id":"arqueamento-posteromedial-tibia","area":"Pediátrica","front":"APM\n\nQuais são os critérios dessa classificação?\n(Arqueamento Posteromedial Congênito da Tíbia)","back":"• Apresentação — Arqueamento distal posteromedial da tíbia associado a deformidade em calcâneo-valgo do pé; pode ser dramático ao nascimento e melhorar com a idade.\n• História natural — Resolução espontânea do arqueamento é a norma; discrepância de comprimento residual variável (em média 3 cm na maturidade, podendo chegar a 8 cm).\n• Diagnóstico diferencial — Osteogênese imperfeita deve ser descartada em criança com deformidade em arqueamento.\n• Tratamento inicial — Alongamento passivo do pé para correção do calcâneo-valgo; gessos seriados em casos graves; nenhum tratamento é necessário para o arqueamento em si, que se resolve espontaneamente.\n• Manejo da discrepância — Epifisiodese tibial proximal contralateral se discrepância prevista >..."},{"id":"luxacao-congenita-joelho-classificacao","area":"Pediátrica","front":"LCJ\n\nQuais são os critérios dessa classificação?\n(Espectro de Gravidade da Hiperextensão/Luxação Congênita do Joelho (CDK))","back":"• Hiperextensão (recurvato) — Joelho pode ser fletido com alongamento suave; forma mais leve do espectro.\n• Subluxação congênita — Joelho não fleti além do neutro, mas não há subluxação à tentativa de flexão.\n• Luxação verdadeira — Incapacidade de fletir o joelho ativa ou passivamente; tendão quadricipital frequentemente muito contraído; patela de difícil palpação, geralmente deslocada lateralmente.\n• Incidência — Luxação congênita verdadeira do joelho (CDK) é muito rara, estimada em 1 por 100.000 nascidos vivos; pode ser uni ou bilateral.\n• Associações — CDK unilateral e hiperextensão associam-se a luxação de quadril e pé torto em 50-70% dos casos; CDK bilateral quase sempre é sindrômica (Larsen, Beals, Ehlers-Danlos)."},{"id":"sindrome-pterigio-poplíteo","area":"Pediátrica","front":"SPP\n\nQuais são os critérios dessa classificação?\n(Síndrome do Pterígio Poplíteo (Contratura de Flexão do Joelho))","back":"• Achado característico — Membrana poplítea (webbing) que é a marca registrada da síndrome; associada a fenda labial/palatina e sindactilias.\n• Síndrome de Escobar — Síndrome do pterígio múltiplo, com membranas também em membros superiores (fossa antecubital) e cifoescoliose.\n• Estrutura anatômica — Banda fibrosa subcutânea que se estende do ísquio ao calcâneo (banda isquiocalcânea), intimamente envolvida com o ramo tibial do nervo isquiático.\n• Tratamento — Resistente à manipulação; requer liberação cirúrgica de tecidos moles com múltiplas Z-plastias na pele posterior; osteotomias de encurtamento associadas para evitar tensão neurológica."},{"id":"marcha-ponta-pes-idiopatica","area":"Pediátrica","front":"MPPI\n\nQuais são os critérios dessa classificação?\n(Marcha em Ponta dos Pés Idiopática (Diagnóstico Diferencial com Paralisia Cerebral Leve))","back":"• Definição — Persistência da marcha em ponta dos pés além dos 2-3 anos de idade em criança com desenvolvimento normal.\n• Critérios de exclusão — Não deve haver história familiar de doença neurológica de base (pode haver história familiar de marcha em ponta dos pés); não deve ser progressivamente pior; exame físico benigno.\n• Diferenciação clínica da PC leve — Criança com marcha em ponta dos pés idiopática corre melhor do que anda; a criança com PC leve tem mais dificuldade para correr e pode fletir um ou ambos os braços ao correr.\n• Exame físico — Tipicamente bilateral; flexão plantar passiva normal, mas dorsiflexão frequentemente limitada; sem aumento de tônus ou clônus.\n• EMG dinâmica — Pode auxiliar no diagnóstico diferencial; PC pod..."},{"id":"blount-obesidade-complicacoes","area":"Pediátrica","front":"Blount-Obesidade\n\nQuais são os critérios dessa classificação?\n(Considerações Especiais no Manejo do Blount em Paciente Obeso)","back":"• Risco de hipertensão — Halverson et al. encontraram risco 150% maior de hipertensão em pacientes com Blount comparados a controles.\n• Deficiência de vitamina D — Montgomery et al. relataram deficiência de vitamina D sete vezes mais provável em pacientes com Blount.\n• Ganho de peso pós-correção — Ao contrário do esperado, pacientes com Blount tendem a ganhar ainda mais peso após correção da deformidade do membro, inclusive durante o tratamento com fixador externo.\n• Gravidade relacionada ao IMC — Pacientes com IMC ≥40 apresentam varo e procurvato significativamente maiores do que aqueles com IMC <40.\n• Falha de implante — IMC >35 e desvio do eixo mecânico >80 mm associam-se a taxa de falha de 88% dos implantes de crescimento guiado, com..."},{"id":"blount-instabilidade-ligamentar-colateral","area":"Pediátrica","front":"Blount-LCL\n\nQuais são os critérios dessa classificação?\n(Instabilidade do Ligamento Colateral Lateral no Blount (Avaliação e Conduta))","back":"• Achado clínico — Thrust visível em varo durante a marcha e frouxidão ao estresse em varo/valgo do joelho ao exame.\n• Achado radiográfico — Alargamento assimétrico do espaço articular lateral (JLCA >3 graus) na radiografia em pé.\n• Estratégia 1 — Restaurar o eixo mecânico para o centro da articulação do joelho geralmente alivia o estresse sobre o ligamento colateral lateral, permitindo que este se retesa com o tempo.\n• Estratégia 2 — Sobrealongamento da tíbia em relação à fíbula durante correção gradual, trazendo a cabeça da fíbula à posição adequada, o que tensiona indiretamente o ligamento colateral lateral.\n• Casos refratários — Reforço (reefing) do ligamento colateral lateral ou reconstrução ligamentar completa se instabilidade sint..."},{"id":"hemiplateau-elevacao-indicacao","area":"Pediátrica","front":"Blount-Platô\n\nQuais são os critérios dessa classificação?\n(Indicação de Elevação do Hemiplatô Medial na Doença de Blount)","back":"• Achado radiográfico — Depressão do platô tibial medial maior que 30 graus de angulação.\n• Achados clínicos associados — Frouxidão do ligamento colateral, thrust à marcha e subluxação lateral da tíbia.\n• Avaliação por imagem avançada — RM ou artrografia recomendadas antes de decisão cirúrgica, pois nem toda depressão radiográfica corresponde a um espaço vazio verdadeiro (pode ser cartilagem não ossificada).\n• Achados de RM associados — Espessamento da cartilagem medial não ossificada, hipertrofia do menisco medial, sinal alterado em até 39% dos meniscos mediais e rotura do corno posterior em 16%; laxidão do LCA em cerca de 25% dos pacientes.\n• Conduta se depressão real — Elevação do hemiplatô medial associada a fechamento da fise tibial..."},{"id":"genu-valgum-conduta-cirurgica-idade","area":"Pediátrica","front":"GV-Conduta\n\nQuais são os critérios dessa classificação?\n(Conduta Cirúrgica no Genu Valgum Patológico (Guided Growth vs. Osteotomia))","back":"• Observação — Deformidade leve com mais de 3 anos de crescimento restante — observação com radiografias seriadas a cada 6-12 meses.\n• Crescimento guiado — Tratamento de escolha se houver crescimento suficiente restante e fise normal, pois o genu valgum idiopático geralmente tem fises funcionantes que respondem de forma confiável (diferente do Blount).\n• Tempo de correção — A maioria dos pacientes com genu valgum idiopático corrige em cerca de 12 meses com placas de crescimento guiado.\n• Risco de rebote — Correção rápida associa-se a rebote mais frequente e grave; correção lenta com baixo IMC tem menor rebote, e ausência de rebote com IMC ≥21 kg/m².\n• Osteotomia — Reservada para pacientes próximos da maturidade esquelética ou já maduros;..."},{"id":"genu-valgum-tecnica-sleeper-plate","area":"Pediátrica","front":"Sleeper Plate\n\nQuais são os critérios dessa classificação?\n(Técnica da Placa \"Sleeper\" para Recidiva de Deformidade Angular em Crescimento Guiado)","back":"• Indicação — Pacientes jovens com alto risco de recidiva da deformidade após correção completa por crescimento guiado.\n• Técnica — Ao atingir o alinhamento desejado, remove-se apenas o parafuso metafisário; a placa e o parafuso epifisário permanecem em posição em modo \"adormecido\".\n• Reativação — Se a deformidade recorrer no futuro, o parafuso metafisário pode ser reinserido sem necessidade de reoperar todo o implante.\n• Vantagem — Técnica menos invasiva e mais custo-efetiva do que remover o implante inteiro e substituí-lo posteriormente por um novo."},{"id":"guided-growth-taxa-correcao","area":"Pediátrica","front":"GG-Taxa\n\nQuais são os critérios dessa classificação?\n(Taxa Esperada de Correção Angular com Crescimento Guiado (Hemiepifisiodese))","back":"• Tíbia proximal — Aproximadamente 5 graus de correção angular por período de 12 meses.\n• Fêmur distal — Aproximadamente 7 graus de correção angular por período de 12 meses.\n• Variabilidade — A taxa de correção pode ser altamente variável entre pacientes; seguimento clínico próximo é essencial.\n• Indicação — Crianças com crescimento remanescente adequado e fises funcionantes viáveis; fise \"doente\" ou com parada de crescimento não responde bem ao crescimento guiado.\n• Risco de supercorreção — Falta de seguimento adequado pode causar supercorreção — incidência de 12% de seguimento incompleto relatada em série multicêntrica."},{"id":"blount-osteotomia-tecnicas","area":"Pediátrica","front":"Blount-Osteotomia\n\nQuais são os critérios dessa classificação?\n(Técnicas de Osteotomia Tibial Proximal na Doença de Blount)","back":"• Osteotomia transversa clássica — Corte abaixo do nível da tuberosidade tibial; mais fácil de realizar, mas não fica no nível do ápice da deformidade (fise), exigindo translação lateral/anterior do fragmento distal.\n• Osteotomias oblíquas — Angulam-se cefalicamente em direção à fise para evitar necessidade de translação (ex.: técnica de Khanfour com cunha de abertura medial incompleta; técnica de Burton e Hennrikus com cunha de fechamento lateral completa).\n• Osteotomia de Rab — Osteotomia oblíqua a 45 graus, desenhada para corrigir varo e rotação interna simultaneamente.\n• Correção aguda vs. gradual — Correção gradual (fixador externo) apresenta menor risco de paralisia do nervo fibular e maior acurácia (100% vs 57% na restauração de p..."},{"id":"cpt-complicacoes-tratamento","area":"Pediátrica","front":"CPT-Complicações\n\nQuais são os critérios dessa classificação?\n(Complicações do Tratamento da Pseudartrose Congênita da Tíbia)","back":"• Rigidez do tornozelo/subtalar — Transfixação das articulações do tornozelo e subtalar para estabilidade predispõe à rigidez; espera-se migração proximal da haste com o crescimento (idealmente após 2 anos).\n• Refratura — Mais comum em pacientes jovens; recomendado uso de órtese até a maturidade esquelética para prevenir; bisfosfonatos têm sido propostos para reduzir esse risco.\n• Deformidade em valgo — Secundária à perda de suporte lateral quando a fíbula é deficiente; tratada com hemiepifisiodese (parafuso ou placa de tensão) proximal e/ou distal.\n• Discrepância de comprimento — Parte da história natural da CTD e também decorrente do encurtamento necessário para excisar a pseudartrose; média de 5 cm, podendo chegar a 10 cm.\n• Pseudartr..."},{"id":"cpt-amputacao-indicacoes","area":"Pediátrica","front":"CPT-Amputação\n\nQuais são os critérios dessa classificação?\n(Indicações de Amputação na Pseudartrose Congênita da Tíbia)","back":"• Falha de consolidação — Falha em obter união óssea apesar de múltiplas cirurgias.\n• Discrepância de comprimento grave — Discrepância severa de comprimento dos membros como indicação adicional.\n• Perda funcional — Perda de função do membro secundária a deformidade ou contraturas.\n• Técnica preferida — Recomenda-se preservar o retropé com procedimento de Boyd ou Syme, preservando o comprimento do coto residual e permitindo uso de prótese que estabiliza e protege a pseudartrose."},{"id":"cover-up-test-genu-varum","area":"Pediátrica","front":"Cover-Up Test\n\nQuais são os critérios dessa classificação?\n(Teste do Cover-Up para Diferenciar Genu Varum Verdadeiro de Aparente (por Torção Tibial))","back":"• Técnica — Paciente em decúbito dorsal, pernas totalmente estendidas, patelas apontando anteriormente; o examinador cobre os pés e a porção inferior da tíbia.\n• Objetivo — Remover a contribuição visual da torção tibial, permitindo avaliação mais precisa do grau real de varo no joelho.\n• Achado associado — Torção tibial interna pode coexistir com o arqueamento dos membros, acentuando a aparência de genu varum ao fazer os joelhos apontarem para fora para manter os pés retos (\"genu varum aparente\").\n• Diferenciação de padrão — Arqueamento fisiológico tende a ter curva longa e suave simétrica; arqueamento patológico tende a ser mais agudo e focal, geralmente na tíbia proximal."},{"id":"apparent-genu-valgum-causas","area":"Pediátrica","front":"AGV\n\nQuais são os critérios dessa classificação?\n(Genu Valgum Aparente (Sem Deformidade Óssea Verdadeira) — Diagnóstico Diferencial)","back":"• Obesidade (\"knock-thighs\") — A espessura das coxas empurra as pernas para longe uma da outra; radiografias panorâmicas em pé são geralmente normais; perda de peso resolve o problema.\n• Pé plano-valgo — Pronação grave do pé força o joelho para posição em valgo para manter o pé apoiado no chão; suportes de arco plantar podem ajudar.\n• Anteversão femoral excessiva — Rotação interna do joelho durante a fase de apoio pode dar aparência de valgo (flexão do joelho anatômica visualizada fora do plano)."},{"id":"definicoes-discrepancia-mmii","area":"Pediátrica","front":"DEF-LLD\n\nQuais são os critérios dessa classificação?\n(Definições de Discrepância de Comprimento dos Membros Inferiores (Verdadeira, Aparente, Funcional))","back":"• Discrepância estrutural/verdadeira — Diferença real no comprimento de um segmento anatômico específico (fêmur, tíbia ou pé).\n• Discrepância aparente/postural — Não representa diferença real de comprimento; resulta de deformidade angular, contratura ou luxação do quadril, joelho, tornozelo ou pé que faz um membro parecer mais curto ou mais longo.\n• Discrepância funcional — Soma da discrepância verdadeira com a aparente; é a mais importante para a decisão terapêutica.\n• Idade cronológica vs. idade óssea (esquelética) — Idade cronológica é o número de anos de vida; idade óssea é medida de maturidade baseada em padrões normativos, usada para prever o crescimento futuro."},{"id":"etiologia-encurtamento-mmii","area":"Pediátrica","front":"ETIO-CURT\n\nQuais são os critérios dessa classificação?\n(Etiologia da Discrepância por Encurtamento do Membro)","back":"• Congênita — Fêmur curto congênito (associado a coxa vara, arqueamento, hipoplasia do côndilo femoral lateral, torção externa), hemimelia fibular ou tibial, arqueamento posteromedial da tíbia, pseudartrose congênita da tíbia, pé torto.\n• Traumática (malunião) — Fratura consolidada em posição encurtada; algum regrowth ocorre em crianças pequenas (especialmente no fêmur), mas malunião semelhante em crianças maiores/adolescentes tende a ser permanente por diminuição do potencial de crescimento.\n• Lesão fisária/parada de crescimento — Fraturas da fise, osteomielite neonatal multifocal com artrite séptica intra-articular, radiação, neoplasias benignas ou malignas (encondroma, osteocondroma, cisto ósseo simples).\n• Mecânica — Doença de Blount..."},{"id":"etiologia-hipercrescimento-mmii","area":"Pediátrica","front":"ETIO-HIPER\n\nQuais são os critérios dessa classificação?\n(Etiologia da Discrepância por Hipercrescimento (Alongamento) do Membro)","back":"• Hipercrescimento pós-traumático — Mais comum após fratura de fêmur (terço proximal ou médio), com pico entre 4-7 anos; overgrowth médio de 7 a 10 mm, ocorrendo majoritariamente nos primeiros 2 anos.\n• Hipercrescimento pós-inflamatório — Osteomielite ou artrite inflamatória crônica (reumatoide, psoriática, lúpica) estimulam crescimento por aumento do fluxo sanguíneo próximo à fise.\n• Malformação vascular/hemi-hipertrofia sindrômica — Síndrome de Klippel-Trenaunay(-Weber), síndrome de Parkes Weber, síndrome de Proteus, macrodactilia, neurofibromatose tipo 1 (NF-1).\n• Hemi-hipertrofia idiopática/Beckwith-Wiedemann — Critérios maiores (macroglossia, hipercrescimento, defeitos de parede torácica anterior) e menores (pregas auriculares, nevo..."},{"id":"shapiro-padroes-inibicao-crescimento","area":"Pediátrica","front":"SHAPIRO\n\nQuais são os critérios dessa classificação?\n(Padrões de Inibição do Crescimento Descritos por Shapiro)","back":"• Conceito geral — Cinco padrões distintos de inibição de crescimento ao longo do desenvolvimento foram descritos por Shapiro (1982), ilustrados graficamente na Fig. 27-16 original.\n• Inibição constante — É o único padrão nomeado explicitamente no texto: a proporção entre o segmento curto e o longo permanece constante ao longo do crescimento, embora a diferença absoluta de comprimento aumente.\n• Padrões mistos por diagnóstico — Um mesmo diagnóstico (poliomielite, doença de Ollier, parada de crescimento pós-lesão fisária) pode exibir mais de um padrão de inibição simultaneamente.\n• Aplicabilidade clínica limitada — Apesar de reconhecidos, os cinco padrões são de difícil uso prático nas previsões de rotina, mas devem ser lembrados ao plane..."},{"id":"green-anderson-crescimento-remanescente","area":"Pediátrica","front":"G-A GROWTH\n\nQuais são os critérios dessa classificação?\n(Método do Gráfico de Crescimento Remanescente de Green e Anderson)","back":"• Base de dados — Coorte inicialmente semilongitudinal de mais de 800 indivíduos (1947); posteriormente coorte pura longitudinal de 50 meninos e 50 meninas seguidos anualmente (1963), com idade óssea determinada por Greulich-Pyle.\n• Gráfico de crescimento remanescente — A partir da idade esquelética, permite ler diretamente a quantidade de crescimento restante na fise distal do fêmur e proximal da tíbia, útil para prever o resultado da epifisiodese.\n• Nomograma de comprimento absoluto — Plota comprimento de fêmur e tíbia por idade cronológica (67 meninos e 67 meninas, 1 a 18 anos), permitindo comparar o percentil do membro \"normal\" com o grau de inibição do membro curto.\n• Limitações — Não leva em conta diferenças de estatura/percentil d..."},{"id":"moseley-linha-reta","area":"Pediátrica","front":"MOSELEY\n\nQuais são os critérios dessa classificação?\n(Método do Gráfico de Linha Reta de Moseley)","back":"• Princípio — Nomograma derivado dos dados de Green-Anderson, corrigido para variações de percentil de maturidade/tamanho relativo; o crescimento de cada membro é representado como uma linha reta.\n• Técnica de plotagem — Plota-se o comprimento do membro NORMAL na linha normativa; traça-se linha vertical na idade esquelética de referência (Greulich-Pyle); plota-se o comprimento do membro ANORMAL no mesmo ponto vertical; repete-se com pelo menos 3 medidas.\n• Predição final — Linhas de melhor ajuste são traçadas para o membro anormal; a distância entre as linhas projetadas até a maturidade representa a discrepância prevista.\n• Uso terapêutico — Linhas de referência de inclinação para epifisiodese (fêmur distal, tíbia proximal, ou ambas) per..."},{"id":"menelaus-white-aritmetico","area":"Pediátrica","front":"ARITM-MW\n\nQuais são os critérios dessa classificação?\n(Método Aritmético de White/Menelaus (Regra dos Polegares))","back":"• Premissas de White — Fêmur distal cresce 10 mm/ano e tíbia proximal 6 mm/ano; a discrepância aumenta 3 mm/ano; equivale a 37% do crescimento total do membro no fêmur distal e 28% na tíbia proximal. White assumiu cessação do crescimento aos 17 anos (meninos) e 16 anos (meninas).\n• Ajuste de Menelaus — Idade de cessação do crescimento ajustada para 16 anos (meninos) e 14 anos (meninas); recomenda-se uso apenas quando a idade óssea e a cronológica estão a menos de 1 ano de diferença.\n• Indicação principal — Útil quando existe apenas um ponto de dados disponível (não descreve o crescimento, apenas prevê o momento ideal da epifisiodese); mais adequado nos últimos anos de crescimento.\n• Medida clínica — Utiliza a discrepância clínica determi..."},{"id":"dimeglio-metodo-previsao","area":"Pediátrica","front":"DIMEGLIO\n\nQuais são os critérios dessa classificação?\n(Método de Dimeglio de Previsão e Momento da Epifisiodese)","back":"• Premissas de crescimento — Crescimento no joelho de 2 cm/ano (1,1 cm fêmur + 0,9 cm tíbia) no início da puberdade (idade óssea 11 anos nas meninas, 13 anos nos meninos); cessação aos 13,5 anos (meninas) e 15,5 anos (meninos).\n• Discrepância de 5 cm — Epifisiodese de fêmur distal e tíbia proximal no início da puberdade.\n• Discrepância de 4 cm — Epifisiodese de fêmur e tíbia 6 meses após o início da puberdade.\n• Discrepância de 3 cm — Epifisiodese isolada do fêmur no início da puberdade.\n• Discrepância de 2 cm — Epifisiodese isolada do fêmur 1 ano após o início da puberdade."},{"id":"paley-metodo-multiplicador","area":"Pediátrica","front":"MULT-PALEY\n\nQuais são os critérios dessa classificação?\n(Método do Multiplicador de Paley para Previsão de Discrepância na Maturidade)","back":"• Princípio — Tabelas de multiplicadores (por idade e sexo), que decrescem com a idade, multiplicadas pela deformidade atual, preveem a discrepância final na maturidade esquelética.\n• Fórmula congênita — Discrepância na maturidade = (L − S) × M, em que L e S são os comprimentos do membro longo e curto e M é o multiplicador apropriado para a idade.\n• Fórmula desenvolvimental (adquirida) — Discrepância na maturidade = (L − S) + [1 − (S − S′)/(L − L′)] × L × (M − 1), usando comprimentos atuais (S, L) e de 6 a 12 meses antes (S′, L′) para calcular a taxa de inibição.\n• Vantagem prática — Os autores originais afirmam que a idade cronológica é tão acurada quanto a idade óssea neste método."},{"id":"metodos-avaliacao-maturidade-esqueletica","area":"Pediátrica","front":"MATUR-OSSEA\n\nQuais são os critérios dessa classificação?\n(Métodos de Avaliação da Maturidade Esquelética (Idade Óssea))","back":"• Greulich e Pyle — Método mais usado; compara radiografia de mão/punho esquerdos com atlas de crianças saudáveis. Limitações incluem lacunas de até 14 meses entre padrões e viés étnico, pois foi baseado em crianças brancas afluentes de décadas atrás.\n• Tanner-Whitehouse (TW2, RUS) — Avalia 20 marcos ósseos do rádio, ulna e ossos curtos da mão por meio de escore numérico com procedimento matemático computadorizado, resultando em menor erro padrão.\n• Sauvegrain/Dimeglio — Avalia 4 centros de ossificação do cotovelo, com escore máximo de 27 pontos; útil dos 9 aos 15 anos, período em que o atlas de Greulich-Pyle carece de normas em intervalos regulares. Não pode ser usado antes dos 9 anos (meninas) ou 11 anos (meninos).\n• Discordância idade..."},{"id":"metodos-radiograficos-mensuracao-discrepancia","area":"Pediátrica","front":"RX-MENSURA\n\nQuais são os critérios dessa classificação?\n(Métodos Radiográficos de Mensuração da Discrepância de Comprimento dos MMII)","back":"• Radiografia de MMII em pé (< 2 anos) — Exposição única, menor acurácia de medida, mas avalia bem o alinhamento global; preferida em crianças pequenas por exigir apenas um disparo.\n• TC scanograma — Rápido, associado a menor radiação, acomoda bem contraturas e fixadores externos; em alguns estudos mostrou-se mais acurado que medidas radiográficas convencionais.\n• Teleorradiografia (teleoroentgenograma) — Filme único (35 x 90 cm) a 2 m de distância centrado no joelho; sujeito a erro de magnificação (paralaxe), mas mostra deformidades angulares e é ideal para crianças que não conseguem ficar paradas.\n• Ortorradiografia — Três exposições (quadril, joelho, tornozelo) na mesma película com régua centrada em cada articulação, eliminando o err..."},{"id":"diretrizes-tratamento-magnitude-discrepancia","area":"Pediátrica","front":"COND-MAGNITUDE\n\nQuais são os critérios dessa classificação?\n(Diretrizes de Conduta Conforme a Magnitude da Discrepância Prevista na Maturidade)","back":"• 0 a 2 cm — Nenhum tratamento.\n• 2 a 6 cm — Uso de órtese/palmilha, epifisiodese, encurtamento esquelético, ou alongamento intramedular.\n• 6 a 20 cm — Reconstrução do membro (alongamento ósseo, com ou sem procedimentos adjuvantes).\n• Maior que 20 cm — Adaptação protética (com ou sem otimização cirúrgica prévia)."},{"id":"epifisiodese-indicacoes-tecnicas","area":"Pediátrica","front":"EPIFISIODESE\n\nQuais são os critérios dessa classificação?\n(Indicações e Técnicas de Epifisiodese (Interrupção Fisária Controlada))","back":"• Indicação — Discrepância prevista de 2 a 6 cm na maturidade, com crescimento remanescente suficiente para efetivar a correção; ideal quando o membro longo é claramente o anormal (ex.: hipercrescimento ou fise já em processo de parada contralateral).\n• Perda de crescimento por segmento — Epifisiodese isolada da tíbia proximal perde 27% do crescimento; do fêmur distal, 38%; epifisiodese combinada (pan-genu) de ambas as fises, 65%.\n• Grampeamento (técnica de Blount) — Três grampos extraperiosteais mediais e laterais; historicamente usado como parada \"temporária\" removível, mas com resultados imprevisíveis (deformidade angular, crescimento de rebote); reservado hoje a hipercrescimento importante e precoce (>6 cm previstos), podendo ser rem..."},{"id":"encurtamento-esqueletico-agudo-indicacoes","area":"Pediátrica","front":"ENCURT-OSSEO\n\nQuais são os critérios dessa classificação?\n(Indicações e Limites do Encurtamento Ósseo Agudo (Skeletal Shortening))","back":"• Indicação — Mesmas indicações gerais da epifisiodese (discrepância prevista de 2 a 6 cm), reservado a pacientes muito próximos ou além da maturidade esquelética, ou quando a extensão futura não pode ser prevista com confiança.\n• Limite de segurança — Regra prática de aproximadamente 10% do comprimento do osso; encurtamentos maiores sem perda funcional relatada chegaram a 7,5 cm no fêmur e 5 cm na tíbia.\n• Preferência anatômica — Realizado preferencialmente no fêmur; a tíbia raramente é encurtada pelo maior risco de complicação neurovascular, retardo de consolidação, pseudartrose e síndrome compartimental.\n• Técnica fechada (serra intramedular) — Encurtamento diafisário fechado com fixação por haste bloqueada; menor dissecção de partes ..."},{"id":"criterios-ressecao-barra-fisaria","area":"Pediátrica","front":"BARRA-FISARIA\n\nQuais são os critérios dessa classificação?\n(Critérios para Ressecção de Barra/Ponte Óssea Fisária (Physeal Bar Excision))","back":"• Indicação principal — Barra envolvendo menos de 50% da área de superfície da fise, com discrepância prevista de pelo menos 2 cm na maturidade.\n• Discrepância prevista menor que 2 cm — Completar a parada de crescimento (epifisiodese) é preferível à ressecção, cujos resultados são imprevisíveis nesse cenário.\n• Barras maiores que 50% — Ressecção pode ser considerada em casos selecionados quando a perda de crescimento prevista é maior que 5 cm, preferível ao difícil tratamento de alongamento em pacientes jovens.\n• Deformidade angular associada — Não é contraindicação à ressecção da barra, mas osteotomia concomitante deve ser considerada se a deformidade angular for maior que 15-20 graus.\n• Barra central vs. periférica — Barra central é ma..."},{"id":"reconstrucao-alongamento-indicacoes","area":"Pediátrica","front":"RECONSTR-ALONG\n\nQuais são os critérios dessa classificação?\n(Indicações e Princípios de Reconstrução/Alongamento do Membro)","back":"• Faixa de indicação — Discrepâncias previstas de 6 a 20 cm; tradicionalmente não indicado para correções menores que 6 cm pela menor morbidade do encurtamento, exceto quando dispositivos intramedulares modernos toleram bem 3-6 cm em pacientes de baixa estatura.\n• Otimização prévia do membro (limb optimization) — Correção de instabilidade articular (ex.: displasia de quadril no fêmur curto congênito), contraturas e deformidades angulares antes do alongamento definitivo, para evitar luxação ou subluxação durante a distração.\n• Magnitude por tentativa — Ganho esperado de 10% a 20% do comprimento ósseo original por tentativa de alongamento; não é uniforme esperar mais que 8-10 cm por tentativa sem complicações ou dor limitante.\n• Tempo de f..."},{"id":"amputacao-protese-indicacoes","area":"Pediátrica","front":"AMPUT-PROTESE\n\nQuais são os critérios dessa classificação?\n(Indicações de Amputação e Adaptação Protética)","back":"• Indicação principal — Discrepância prevista maior que 15-20 cm, especialmente na presença de pé funcionalmente inútil.\n• Procedimentos — Amputação de Syme ou de Boyd; procedimentos adjuvantes incluem artrodese iliofemoral, artrodese de joelho e rotacionplastia de Van Ness (tornozelo invertido passa a funcionar como joelho).\n• Momento ideal — Amputação de Syme ao final do primeiro ano de vida; rotacionplastia por volta dos 3 anos de idade.\n• Deficiência focal femoral proximal — Crianças tratadas requerem prótese acima do joelho; funcionam bem, embora não tão bem quanto amputações abaixo do joelho. Após rotacionplastia de Van Ness, algumas próteses acima do joelho podem funcionar como abaixo do joelho.\n• Hemimelia fibular com tornozelo i..."},{"id":"fases-osteogenese-distracao","area":"Pediátrica","front":"FASES-OSTEOG\n\nQuais são os critérios dessa classificação?\n(Fases da Osteogênese por Distração (Alongamento Ósseo Gradual))","back":"• Latência — Período de 3 a 14 dias após a osteotomia em que as extremidades ósseas permanecem justapostas, atravessando a fase inflamatória da consolidação da fratura; mais longa em pacientes mais velhos, em osso diafisário, ou com cirurgia/trauma prévio.\n• Distração — Ritmo padrão de 1 mm/dia, idealmente em incrementos de 0,25 mm quatro vezes ao dia; radiografias 1 semana após o início da distração e a cada 2-4 semanas para monitorar o regenerado.\n• Consolidação — Dispositivo mantido até a formação de três das quatro corticais em radiografias ortogonais; pacientes com fixador externo podem ter carga total; a dinamização do dispositivo estimula formação óssea por carga cíclica.\n• Interrupção da distração — Deve ser considerada se surgir..."},{"id":"fixador-externo-vs-prego-intramedular-alongamento","area":"Pediátrica","front":"FIX-VS-PRECICE\n\nQuais são os critérios dessa classificação?\n(Fixador Externo versus Prego Intramedular Motorizado (PRECICE) no Alongamento Ósseo)","back":"• Fixador externo (Ilizarov/monolateral) — Permite correção simultânea de deformidade angular/rotacional complexa e translação de segmentos; desvantagens incluem infecção de trajeto de pino, cicatrizes, dor por tethering de partes moles e longo período de uso do dispositivo.\n• Prego intramedular motorizado (PRECICE) — Alongamento por campo magnético externo controlado por dispositivo remoto (ERC); diâmetros de 8,5/10,7/12,5 mm, comprimentos de 155 a 365 mm, ganho máximo de 3 a 8 cm conforme o tamanho do prego.\n• Requisitos técnicos — Diâmetro diafisário mínimo de 10,5 mm (reamer 1,5-2 mm maior que o prego); obesidade pode enfraquecer o campo magnético e prejudicar o funcionamento do dispositivo.\n• Contraindicação relativa — Fises proxima..."},{"id":"complicacoes-alongamento-osseo","area":"Pediátrica","front":"COMPL-ALONG\n\nQuais são os critérios dessa classificação?\n(Complicações do Alongamento Ósseo)","back":"• Complicações técnicas — Erros na colocação do fixador ou na execução da osteotomia, lesão neurovascular, fratura, infecção, síndrome compartimental.\n• Complicações do processo de alongamento — Hipertensão súbita durante o alongamento, mau funcionamento do dispositivo, falha de pino, infecção de trajeto de pino, osteomielite, consolidação prematura, formação óssea deficiente.\n• Complicações tardias — Fratura após remoção do dispositivo, diminuição do crescimento do membro, desalinhamento durante o alongamento, dor, cicatriz de partes moles, rigidez articular por encurtamento muscular e até luxação articular.\n• Expectativa a ser comunicada à família — Deve-se informar que ao menos uma complicação e um tratamento/cirurgia adicional são es..."},{"id":"historia-natural-discrepancia-adulto","area":"Pediátrica","front":"HIST-NAT-ADULTO\n\nQuais são os critérios dessa classificação?\n(História Natural da Discrepância de MMII no Adulto e Limiares Clínicos)","back":"• Discrepância menor que 2 cm — Sem consequência funcional ou clínica demonstrada no adulto; não requer tratamento.\n• Discrepância entre 1 e 2,5 cm — Apesar de considerada não significativa clinicamente por alguns critérios, aumento da oscilação postural (postural sway) já foi demonstrado com discrepâncias simuladas de apenas 1 cm.\n• Índice de simetria (Liu et al.) — Medida proposta da qualidade da marcha (symmetry index); a correção da discrepância com um salto/calço (heel lift) melhora consideravelmente o índice de simetria.\n• Discrepância maior que 5,5% do comprimento do membro — Aumenta o trabalho mecânico realizado pelo membro longo e o deslocamento vertical do centro de massa corporal, com penalidade energética; discrepâncias menor..."},{"id":"avaliacao-clinica-discrepancia-mmii","area":"Pediátrica","front":"AVAL-CLIN-LLD\n\nQuais são os critérios dessa classificação?\n(Avaliação Clínica da Discrepância de Comprimento dos MMII (Sinais e Técnicas))","back":"• Medida por blocos graduados — Nivelamento das espinhas ilíacas póstero-superiores com blocos sob o calcanhar do lado curto; acurácia de aproximadamente 1,5 cm, com maior imprecisão em pacientes obesos e nos até 5% da população com assimetria pélvica normal.\n• Fita métrica — Comprimento aparente medido do umbigo ao maléolo medial; comprimento verdadeiro medido da espinha ilíaca ântero-superior ao maléolo medial ou lateral.\n• Sinal de Galeazzi — Diferença na altura dos joelhos com quadris e joelhos fletidos a 90 graus, sugerindo patologia no segmento femoral (entre a articulação do quadril e a do joelho).\n• Avaliação em decúbito ventral — Diferença na altura do coxim do calcanhar sugere patologia localizada entre o fêmur distal e o pé.\n•..."},{"id":"accessory-navicular-tipos","area":"Pediátrica","front":"NAVICULAR ACESSÓRIO\n\nQuais são os critérios dessa classificação?\n(Classificação do Navicular Acessório (Tipos I, II e III))","back":"• Tipo I — Pequeno osso sesamoide, do tamanho de uma ervilha, no interior da porção mais distal do tendão do tibial posterior (os naviculare); raramente sintomático.\n• Tipo II — Ossículo em formato de bala unido à tuberosidade do navicular por sindesmose/sincondrose fibrocartilaginosa; é o tipo mais frequentemente sintomático.\n• Tipo III — Navicular córneo grande, resultante provável da fusão de um tipo II com o corpo do navicular ao longo do tempo; estudo longitudinal documentou fusão em 42% dos casos.\n• Diagnóstico diferencial — Diferenciar de proeminência da cabeça do tálus em pé plano flexível: invertendo/evertendo a subtalar com o polegar sobre a proeminência — se ela se move, é navicular acessório; se permanece estacionária, é a ca..."},{"id":"cavus-etiologia-tabela","area":"Pediátrica","front":"CAVO-ETIOLOGIA\n\nQuais são os critérios dessa classificação?\n(Classificação Etiológica do Pé Cavo (Tabela 28-1) — Causas Uni- e Bilaterais)","back":"• Regra geral — O pé cavo deve ser considerado manifestação de doença neuromuscular com desequilíbrio muscular até prova em contrário; pelo menos 2/3 dos pacientes com pé cavo doloroso têm doença neurológica subjacente, e mais da metade destes tem Charcot-Marie-Tooth (CMT).\n• Causas tipicamente bilaterais — Neuropatias hereditárias/sistêmicas (CMT e outras), disrafismo espinhal, paralisia cerebral, distrofias musculares, ataxia de Friedreich.\n• Causas tipicamente unilaterais — Sequelas de trauma, tumor medular ou de nervo periférico, lesão neurológica focal, poliomielite unilateral.\n• Calcaneocavo (posterior/transtarso) — Visto quase exclusivamente em mielomeningocele e poliomielite, por padrão específico de desequilíbrio muscular.\n• Apl..."},{"id":"cavus-padroes-cavovaro-calcaneocavo","area":"Pediátrica","front":"CAVOVARO/CALCANEOCAVO\n\nQuais são os critérios dessa classificação?\n(Padrões de Deformidade em Pé Cavo — Cavovaro (Anterior) vs. Calcaneocavo (Posterior/Transtarso))","back":"• Cavovaro (cavo anterior) — Padrão mais comum; pronação do antepé sobre o retropé associada a inversão/varo do retropé — deformidades rotacionalmente opostas (\"pé torcido como uma toalha\").\n• Mecanismo do tripé — O primeiro metatarsal fixo em flexão plantar obriga o retropé a assumir varo durante a carga, forçando a cabeça do quinto metatarsal ao solo (efeito tripé descrito por Paulos e Coleman).\n• Calcaneocavo (cavo posterior/transtarso) — Menos frequente; arco elevado transversalmente por todo o mediopé, calcâneo dorsifletido e verticalizado (\"deformidade em coronha de pistola\"), visto quase exclusivamente em mielomeningocele/pólio.\n• Progressão — A deformidade cavovara é inicialmente flexível e torna-se rígida com o tempo pela contra..."},{"id":"coleman-block-test-cavovaro","area":"Pediátrica","front":"COLEMAN BLOCK TEST\n\nQuais são os critérios dessa classificação?\n(Teste do Bloco de Coleman (e Variante Radiográfica de Mosca) para Flexibilidade do Retropé no Pé Cavovaro)","back":"• Técnica original (Coleman e Chesnut) — Paciente em pé sobre um bloco de madeira sob o calcanhar e a borda lateral do antepé, permitindo que o primeiro metatarsal \"caia\" em flexão plantar enquanto recria o tripé.\n• Interpretação — flexível — O varo do retropé corrige para valgo quando o primeiro metatarsal cai livremente fora da borda do bloco.\n• Interpretação — rígido — O varo do retropé não corrige, indicando contratura fixa dos tecidos moles plantar-mediais da subtalar.\n• Variante radiográfica de Mosca — Bloco de Plexiglas sob as cabeças do 2º-3º metatarsais (mantendo o calcanhar no chão/filme) documenta radiograficamente a flexibilidade pelo ângulo tálus-1º metatarsal (foot-CORA) na incidência AP em carga.\n• Implicação cirúrgica — R..."},{"id":"foot-cora-meary-cavus","area":"Pediátrica","front":"FOOT-CORA/MEARY\n\nQuais são os critérios dessa classificação?\n(Ângulo de Meary (Tálus–1º Metatarsal) e Conceito de Foot-CORA na Avaliação do Pé Cavo e do Pé Plano)","back":"• Definição de Meary — Relação linear reta normal entre o eixo do tálus e o eixo do primeiro metatarsal na incidência lateral em carga (ângulo próximo de 0 grau, com faixa normal de variação).\n• No pé cavo — As linhas se cruzam dentro do corpo do cuneiforme medial, definindo esse ponto como o foot-CORA do pé cavo, com ápice da angulação voltado dorsalmente.\n• Pitch calcaneano (CP) — Valor de CP maior que 30 graus associado a flexão plantar do antepé é indicativo de deformidade em cavo; hiperdorsiflexão do calcâneo confirma que o equino clínico aparente pode ser, na verdade, equino do antepé.\n• No pé plano (contraponto) — O foot-CORA do mesmo ângulo costuma localizar-se na cabeça do tálus/articulação talonavicular, mas com ápice voltado p..."},{"id":"cleft-foot-blauth-borisch","area":"Pediátrica","front":"BLAUTH-BORISCH\n\nQuais são os critérios dessa classificação?\n(Classificação de Blauth e Borisch para Pé Fendido (Ectrodactilia))","back":"• Base da classificação — Seis grupos definidos pelo número de ossos metatarsais presentes, avaliados radiograficamente.\n• Formas adicionais — Tipo polidactílico (metatarsais duplicados associados à fenda) e tipo diastático (monodactilia com diástase da perna ou aplasia tibial).\n• Achados associados — Sinostoses e pontes ósseas (\"cross-bones\") nas margens da fenda e nos tarsais também são descritas.\n• Avaliação recomendada — Ultrassonografia renal indicada pela associação frequente com anomalias renais; radiografias do pé para tipificação.\n• Epidemiologia — Ocorrência de 1:90.000 nascidos vivos na forma bilateral (geralmente associada a fenda de mão, herança autossômica dominante com penetrância incompleta) versus 1:150.000 na forma unil..."},{"id":"clubfoot-sindromes-associadas","area":"Pediátrica","front":"TABELA 28-2\n\nQuais são os critérios dessa classificação?\n(Síndromes Comumente Associadas ao Pé Torto Congênito (Tabela 28-2))","back":"• Achado de alerta — artrogripose — Polegares aduzidos e contraídos sobre a palma identificam uma criança com pé torto como portadora de artrogripose.\n• Avaliação sistemática — Testes musculares e exame sensorial devem fazer parte do exame inicial de todo paciente com pé torto, pela associação descrita com ausência de músculos do compartimento anterior e lesões de inervação.\n• Rastreio de quadril — Exame dos quadris no recém-nascido é obrigatório na triagem musculoesquelética, embora não haja risco comprovadamente aumentado de displasia do quadril em pé torto isolado.\n• Relevância prognóstica — Pés tortos sindrômicos/neurogênicos tendem a ser mais rígidos, respondem pior ao método de Ponseti isolado e requerem cirurgia com maior frequênc..."},{"id":"clubfoot-pirani-score","area":"Pediátrica","front":"PIRANI\n\nQuais são os critérios dessa classificação?\n(Escore de Pirani para Classificação de Gravidade do Pé Torto Congênito)","back":"• Estrutura — Seis achados físicos isolados (três do mediopé, três do retropé), cada um pontuado como 0, 0,5 ou 1 ponto conforme a gravidade.\n• Escore total — Máximo possível de 6 pontos, subdividido em escore do mediopé (midfoot contracture score) e escore do retropé (hindfoot contracture score), 3 pontos cada.\n• Achados avaliados — Gravidade da deformidade, profundidade das pregas cutâneas e grau de certas variações patoanatômicas do mediopé e retropé.\n• Aplicabilidade — Pode ser aplicado em menos de 2 minutos; correlação entre observadores (coeficiente 0,9) melhora após a pontuação inicial dos primeiros 15 pés.\n• Uso clínico — Auxilia a determinar necessidade de tenotomia percutânea do tendão de Aquiles após gessos de Ponseti e a acom..."},{"id":"clubfoot-dimeglio-score","area":"Pediátrica","front":"DIMEGLIO\n\nQuais são os critérios dessa classificação?\n(Classificação de Dimeglio para Gravidade do Pé Torto Congênito)","back":"• Componentes principais — Equino, varo, adução e rotação do pé são graduados de 0 a 4 conforme a gravidade (quatro parâmetros x 4 pontos = até 16 pontos).\n• Itens adicionais — Profundidade da prega posterior, prega medial, presença de cavo e condição muscular recebem cada um 0 ou 1 ponto adicional (até 4 pontos extras).\n• Escore total — Varia de 0 a 20 pontos, correlacionando-se com a gravidade da deformidade do pé torto.\n• Uso terapêutico — Escore de Dimeglio abaixo de 10 associado a sucesso consistente do método funcional/francês sem cirurgia; escores mais altos frequentemente exigem tratamento cirúrgico.\n• Reprodutibilidade — Wainwright et al. compararam quatro sistemas (Dimeglio, Catterall, Harrold e Walker, Ponseti e Smoley) e conc..."},{"id":"clubfoot-angulos-radiograficos","area":"Pediátrica","front":"ÂNGULOS PÉ TORTO\n\nQuais são os critérios dessa classificação?\n(Ângulos Radiográficos Utilizados na Avaliação do Pé Torto Congênito)","back":"• Ângulo talocalcaneano — Os eixos do tálus e calcâneo normalmente divergem nas incidências AP e lateral; no pé torto tornam-se paralelos, indicando varo/inversão da subtalar.\n• Ângulo tálus-1º metatarsal — Normalmente forma linha quase reta; usado tanto na incidência AP quanto lateral para avaliar alinhamento residual.\n• Ângulos tibiotalar e tibiocalcaneano — Avaliam o componente de equino residual na incidência lateral em dorsiflexão máxima; alguns centros usam a incidência lateral para indicar necessidade de tenotomia percutânea do Aquiles.\n• Técnica de aquisição — Incidência AP com dorsiflexão e eversão forçada contra o filme; lateral com rotação interna da perna para verdadeira lateral do tornozelo (fíbula projetada na metade poster..."},{"id":"clubfoot-ponseti-protocolo","area":"Pediátrica","front":"PONSETI\n\nQuais são os critérios dessa classificação?\n(Protocolo de Ponseti para Pé Torto Congênito (Manipulação, Gessos, Tenotomia e Órtese))","back":"• Sequência de correção — Cavo → adução → varo → equino, nessa ordem, com manipulação suave e gessos inguinopodálicos trocados a cada 5-7 dias; em geral 4 a 8 sessões de manipulação/gesso.\n• Contrapressão-chave — Aplicada na face dorsolateral da cabeça do tálus (não no calcâneo/cuboide); o terceiro ponto de estabilização é o maléolo medial.\n• Tenotomia percutânea do Aquiles — Indicada se não se atinge pelo menos 10 graus de dorsiflexão do tornozelo após os gessos (necessária em mais de 90% dos casos); gesso final mantido por 3 semanas após a tenotomia, com pé em 15-20 graus de dorsiflexão e 70-75 graus de rotação externa.\n• Fase de manutenção — órtese de abdução do pé (FAB) — Uso em tempo integral por 3 meses (23h/dia) e depois noturno a..."},{"id":"clubfoot-metodo-frances-funcional","area":"Pediátrica","front":"MÉTODO FRANCÊS\n\nQuais são os critérios dessa classificação?\n(Método Funcional (Francês) de Tratamento do Pé Torto Congênito)","back":"• Base do método — Fisioterapia diária com manipulação e alongamento das estruturas plantar-mediais contraídas, estimulação dos músculos fibulares, associada a enfaixamento adesivo (taping) para manter a correção.\n• Cronograma — Sessões diárias por 2 meses, reduzindo para 3x/semana até os 6 meses de idade; uso de splintagem noturna por 2 a 3 anos após.\n• Adição de CPM — Uso de máquina de movimento passivo contínuo (CPM) noturno, introduzido no início dos anos 1990, reduziu a necessidade de cirurgia em alguns estudos.\n• Resultados — Bensahel et al. relataram 48% de bons resultados sem cirurgia e taxa geral de sucesso de 86% (bom/excelente) somando-se liberações cirúrgicas em cerca de metade dos pacientes; Van Campenhout et al. relataram 7..."},{"id":"clubfoot-abordagens-cirurgicas","area":"Pediátrica","front":"CIRURGIA PÉ TORTO\n\nQuais são os critérios dessa classificação?\n(Principais Abordagens Cirúrgicas Históricas para Liberação do Pé Torto Refratário)","back":"• Turco (posteromedial) — Abre a subtalar como um \"livro\" com dobradiça posterolateral (ligamento calcaneofibular preservado); associado a rotação interna/valgo excessivo do retropé por translação lateral do calcâneo.\n• Goldner — Premissa de rotação interna do tálus no tornozelo; alongamento do ligamento deltóideo com reconstrução extensa da talonavicular; a subtalar não é liberada.\n• Carroll / McKay — Liberação circunferencial e rotação da subtalar preservando o ligamento interósseo talocalcâneo; discordam entre si sobre o alinhamento do tálus no tornozelo (externamente rodado vs neutro).\n• Simons — Liberação mais extensa, circunferencial da subtalar e frequentemente da calcaneocuboide, com risco de desestabilização translacional grave ..."},{"id":"vertical-talus-etiologia-tabela","area":"Pediátrica","front":"TABELA 28-3\n\nQuais são os critérios dessa classificação?\n(Etiologia do Tálus Vertical Congênito (Tabela 28-3))","back":"• Idiopático — 12% a 20% dos casos são isolados; parte transmitida como traço autossômico dominante de penetrância incompleta, com genes causais identificados (HOXD10, CDMP-1).\n• Defeitos do tubo neural — Mielomeningocele, agenesia sacral e diastematomielia — desequilíbrio muscular neurologicamente mediado; tálus vertical presente em cerca de 10% dos pacientes com mielomeningocele.\n• Artrogripose — Desequilíbrio muscular mioplástico cria a deformidade.\n• Síndromes genéticas — Diversas síndromes associadas, incluindo aquelas ligadas à displasia acromélica, síndrome de DuPan e braquidactilia tipo C.\n• Avaliação recomendada — Avaliação neuromuscular completa obrigatória em todo tálus vertical congênito, incluindo possível RM do neuroeixo."},{"id":"vertical-talus-espectro-classificacao","area":"Pediátrica","front":"ESPECTRO TÁLUS VERTICAL\n\nQuais são os critérios dessa classificação?\n(Espectro de Gravidade das Deformidades em Valgo/Eversão do Retropé — Tálus Vertical, Tálus Oblíquo e Pé Plano Flexível com Aquiles Curto)","back":"• Classificação de Coleman (histórica) — Dois tipos com base na luxação de ambas talonavicular e calcaneocuboide vs luxação isolada dorsal da talonavicular.\n• Tálus vertical congênito (extremo grave) — Subtalar não pode ser invertida próximo do alinhamento anatômico; tálus permanece maximamente fletido plantarmente apesar de tentativas de dorsiflexão do tornozelo — nenhuma deformidade é corrigível por manipulação.\n• Tálus oblíquo congênito (grau intermediário) — Subtalar pode ser invertida a alinhamento quase, mas não completamente, anatômico; tálus pode ser parcialmente dorsifletido — sem definição consensual na literatura.\n• Pé plano flexível com Aquiles curto (extremo leve, Harris e Beath) — Subtalar pode ser invertida além do neutro,..."},{"id":"vertical-talus-protocolo-dobbs","area":"Pediátrica","front":"DOBBS/REVERSE PONSETI\n\nQuais são os critérios dessa classificação?\n(Técnica Minimamente Invasiva de Dobbs (Gesso Reverso tipo Ponseti) para Tálus Vertical Congênito)","back":"• Gessos seriados — Aplicação semanal, fletindo plantarmente e invertendo o pé com contrapressão na cabeça medial do tálus; tipicamente 4 a 6 gessos até alinhar o mediopé sobre o retropé, confirmado por radiografia lateral.\n• Manejo do equino residual — Tenotomia percutânea do tendão de Aquiles associada a capsulotomia talonavicular limitada aberta com fixação retrógrada por fio (pinagem da TN) — não é uma plicatura, apenas visualização para pinagem.\n• Transferência tendínea — Em crianças acima de 2 anos, transferência do tibial anterior para o colo dorsal do tálus é recomendada.\n• Critério para liberação dorsal aberta — Se a flexão plantar for menor que 25 graus após pinagem TN e tenotomia do Aquiles, indicar alongamento fracionado do e..."},{"id":"flatfoot-harris-beath-classificacao","area":"Pediátrica","front":"HARRIS-BEATH\n\nQuais são os critérios dessa classificação?\n(Classificação de Harris e Beath do Pé Plano (Base Conceitual para o Pé Plano Pediátrico))","back":"• Tipo flexível/hipermóvel — Boa mobilidade articular e tendínea; corresponde a 2/3 dos pés planos; de pouca ou nenhuma relevância clínica como causa de incapacidade.\n• Tipo flexível com Aquiles curto — Contratura do tendão de Aquiles presente em 25% da coorte com pé plano flexível; associado a dor e incapacidade em alguns indivíduos.\n• Tipo rígido — Menos comum; mobilidade restrita da subtalar, geralmente causado por coalizão tarsal; incapacidade dolorosa por vezes observada.\n• Prevalência — Identificado em aproximadamente 23% de 3.619 adultos examinados (recrutas canadenses).\n• Critério central — A frouxidão/mobilidade do pé (não o achatamento do arco em si) é o que determina a relevância clínica potencial."},{"id":"flatfoot-medidas-radiograficas","area":"Pediátrica","front":"MEDIDAS RADIOGRÁFICAS PP\n\nQuais são os critérios dessa classificação?\n(Medidas Radiográficas do Pé Plano — Pitch Calcaneano, Ângulo Tálus-Horizontal e Ângulo de Meary)","back":"• Pitch calcaneano (CP) — Mede a flexão plantar do calcâneo na incidência lateral em carga; diminuído (mais horizontal) no pé plano.\n• Ângulo tálus-horizontal (T-H) — Mede grau ainda maior de flexão plantar do tálus; junto ao CP, é a melhor medida para avaliar deformidade em valgo do retropé.\n• Ângulo de Meary (tálus-1º metatarsal) — Normal próximo de 0 grau (linha reta), com variação normal (média de 10 graus no plano AP e 13 graus no lateral); no pé plano o ápice fica voltado plantarmente, no sítio do sag do mediopé na talonavicular.\n• Foot-CORA no pé plano — Localiza-se mais frequentemente na cabeça do tálus/articulação talonavicular, indicando o sítio do sag do mediopé.\n• Limitação no plano AP — A ossificação excêntrica do navicular ..."},{"id":"flatfoot-testes-clinicos-flexibilidade","area":"Pediátrica","front":"TESTES CLÍNICOS PP\n\nQuais são os critérios dessa classificação?\n(Testes Clínicos de Flexibilidade e Contratura do Aquiles/Gastrocnêmio no Pé Plano)","back":"• Teste de ficar na ponta dos pés (toe standing) — No pé plano flexível, o arco se eleva e o calcanhar corrige de valgo para varo pelo efeito windlass da fáscia plantar.\n• Teste de Jack (Jack toe-raise test) — Dorsiflexão passiva do hálux eleva o arco pelo mesmo efeito windlass — confirma flexibilidade da subtalar.\n• Teste diferencial gastrocnêmio vs sóleo — Com a subtalar mantida invertida ao neutro, mede-se a dorsiflexão do tornozelo com o joelho fletido e depois estendido.\n• Interpretação — contratura de todo o Aquiles (sóleo) — Menos de 10 graus de dorsiflexão com o joelho fletido indica contratura do sóleo, equivalente a contratura de todo o tendão de Aquiles.\n• Interpretação — gastrocnêmio isolado — Mais de 10 graus com o joelho fl..."},{"id":"flatfoot-conduta-escalonada","area":"Pediátrica","front":"CONDUTA PÉ PLANO\n\nQuais são os critérios dessa classificação?\n(Conduta Escalonada no Pé Plano Flexível Sintomático (incluindo Osteotomia de Alongamento do Calcâneo))","back":"• Pé plano flexível assintomático — Nenhum tratamento indicado; órteses e modificações de calçado não alteram o desenvolvimento espontâneo do arco em estudos controlados randomizados.\n• Pé plano flexível com dor inespecífica — Palmilhas/órteses de prateleira ou moldadas podem aliviar sintomas e prolongar a vida útil do calçado, sem necessariamente elevar o arco de forma permanente.\n• Dor sob a cabeça do tálus com Aquiles/gastrocnêmio curto — Programa agressivo de alongamento do Aquiles com a subtalar invertida; refratariedade ao tratamento conservador prolongado é indicação de reconstrução cirúrgica.\n• Opções cirúrgicas preservadoras de movimento — Osteotomia de alongamento do calcâneo (Evans/Mosca) e osteotomia de deslocamento medial do..."},{"id":"metatarsus-adductus-bleck-severidade","area":"Pediátrica","front":"BLECK-SEVERIDADE\n\nQuais são os critérios dessa classificação?\n(Classificação de Bleck da Gravidade do Metatarso Aduzido (Método do Bissetor do Calcanhar))","back":"• Técnica — Aplicada sobre fotocópia do pé em carga, traça-se uma linha que bissecta o calcanhar e observa-se sua relação com os dedos.\n• Graduação — Classifica a gravidade da deformidade conforme qual dedo a linha do bissetor atinge, de leve a grave.\n• Limitação importante — A gravidade determinada pelo método do bissetor do calcanhar não se correlaciona com o prognóstico.\n• Uso combinado — Deve ser usada junto (não em vez) da classificação de flexibilidade de Bleck, que é a que realmente orienta a conduta.\n• Indicação de radiografia — Reservada para crianças maiores/adolescentes com deformidade residual grave, dor ou outra incapacidade, quando se considera cirurgia."},{"id":"metatarsus-adductus-bleck-flexibilidade","area":"Pediátrica","front":"BLECK-FLEXIBILIDADE\n\nQuais são os critérios dessa classificação?\n(Classificação de Bleck da Flexibilidade do Metatarso Aduzido)","back":"• Flexível — O antepé pode ser passivamente abduzido além da linha média do bissetor do calcanhar, mantendo-se o calcanhar firme.\n• Parcialmente flexível — O antepé pode ser abduzido apenas até a linha média.\n• Inflexível/rígido — O antepé não pode ser abduzido até a linha média.\n• Correlação prognóstica — Ponseti e Becker documentaram melhora por volta dos 3-4 anos em 88% das crianças com pés flexíveis; os 12% com deformidade parcialmente flexível/rígida necessitaram de gesso corretivo.\n• Conduta por categoria — Flexível → observação; parcialmente flexível/rígido → manipulação e gesso seriado (idealmente iniciado antes de 1 ano de idade); cirurgia é raramente, se alguma vez, indicada."},{"id":"metatarsus-adductus-berg-radiografico","area":"Pediátrica","front":"BERG\n\nQuais são os critérios dessa classificação?\n(Classificação Radiográfica de Berg para Metatarso Aduzido e Pé Serpentino (Skewfoot))","back":"• Base do sistema — Baseado em radiografias de pés de crianças entre 2 e 17 meses, avaliando a relação entre tálus e navicular.\n• Falha estrutural — O navicular tipicamente não ossifica até os 3-4 anos de idade, muito além da idade das crianças estudadas, tornando o sistema inerentemente falho.\n• Validação — Estudos posteriores documentaram baixa concordância inter- e intraobservador usando este sistema.\n• Correlação com tratamento — Não houve correlação demonstrada entre a classificação de Berg e a resposta ao tratamento.\n• Recomendação prática — Radiografias não são necessárias nem indicadas para diagnosticar metatarso aduzido em lactentes; reservadas para casos residuais graves em crianças maiores."},{"id":"skewfoot-criterios-clinicos","area":"Pediátrica","front":"SKEWFOOT\n\nQuais são os critérios dessa classificação?\n(Critérios Clínicos para Diferenciar Pé Serpentino (Skewfoot) de Metatarso Aduzido)","back":"• Definição consensual — Combinação de deformidade em adução do antepé com deformidade em valgo do retropé — metatarso aduzido associado a pé plano.\n• Forma plantar — Formato em \"S\" no skewfoot versus formato em \"C\" no metatarso aduzido simples.\n• Achados diferenciais no lactente — Convexidade dorsolateral proeminente sobre o cuboide, prega cutânea vertical no mediopé medial, e cabeça do tálus visível/palpável imediatamente proximal a essa prega — ausentes no metatarso aduzido puro.\n• Retropé — Alinhamento em valgo significativo com deslocamento lateral do navicular sobre a cabeça do tálus, porém arco longitudinal aparentemente mais alto que o normal (discordância frontal/sagital).\n• Achado em crianças mais velhas/adultos — O retropé con..."},{"id":"tarsal-coalition-tipos-localizacao","area":"Pediátrica","front":"LOCALIZAÇÃO COALIZÃO\n\nQuais são os critérios dessa classificação?\n(Tipos e Localização das Coalizões Tarsais)","back":"• Sítios mais comuns — Faceta média da articulação talocalcaneana (subtalar) e entre o processo anterior do calcâneo e o navicular (calcaneonavicular) — ocorrem com frequência aproximadamente igual e juntas respondem por cerca de 90% de todas as coalizões.\n• Bilateralidade — Coalizões tarsais são bilaterais em 50% a 60% dos casos.\n• Tipos raros — Talonavicular, calcaneocuboide, naviculocuneiforme e cuneiforme-metatarsal, todas incomuns.\n• Múltiplas coalizões — Documentadas em até 6 de 30 pacientes revisados por TC, embora a incidência real seja considerada bem menor.\n• Associação sindrômica — Coalizões associadas a hemimelia fibular, pé torto, síndrome de Apert e síndrome de Nievergelt-Pearlman tendem a ser mais extensas (mais ossos/maio..."},{"id":"tarsal-coalition-sinais-radiograficos","area":"Pediátrica","front":"SINAIS RADIOGRÁFICOS COALIZÃO\n\nQuais são os critérios dessa classificação?\n(Sinais Radiográficos Clássicos de Coalizão Tarsal)","back":"• Sinal do \"nariz de tamanduá\" (anteater nose sign) — Alongamento do processo anterior do calcâneo na incidência lateral, sugestivo de coalizão calcaneonavicular.\n• Sinal do \"duplo maléolo medial\" — Proeminência óssea palpável/visível distal ao maléolo medial em pé doloroso com subtalar restrita, fortemente sugestiva de coalizão talocalcaneana da faceta média.\n• Bico talar e C-sign de Lateur — Bico dorsal na cabeça do tálus (esporão de tração, não artrose) e linha subcondral em C ao redor do sustentáculo do tálus; o C-sign tem baixa sensibilidade e não é patognomônico.\n• Faceta média estreita/ausente — Achado mais acurado para diagnóstico de coalizão subtalar do que o bico talar ou o C-sign.\n• Tornozelo em \"bola e soquete\" (ball-and-sock..."},{"id":"tarsal-coalition-criterios-tc-cirurgia","area":"Pediátrica","front":"CRITÉRIOS TC COALIZÃO\n\nQuais são os critérios dessa classificação?\n(Critérios Tomográficos para Planejamento Cirúrgico da Coalizão Talocalcaneana)","back":"• Histologia da coalizão — Fibrosa, cartilaginosa ou óssea — determinada na TC de cortes finos.\n• Tamanho relativo — Tamanho da coalizão em relação ao tamanho da faceta posterior.\n• Saúde da cartilagem — Espessura e integridade da cartilagem da faceta posterior remanescente.\n• Grau de deformidade do retropé — Alinhamento em valgo do calcâneo avaliado na imagem coronal central de TC.\n• Subtipo posteromedial — Coalizões subtalares em posição posteromedial (entre a faceta média clássica e a posterior) correspondem a 28% do total, com resultados mais favoráveis após ressecção do que as coalizões da faceta média."},{"id":"tarsal-coalition-conduta-escalonada","area":"Pediátrica","front":"CONDUTA COALIZÃO\n\nQuais são os critérios dessa classificação?\n(Conduta Escalonada na Coalizão Tarsal Sintomática)","back":"• Indicação de tratamento — Apenas coalizões dolorosas devem ser tratadas — não há evidência de incapacidade a longo prazo em coalizões assintomáticas (cerca de 75% de todas as coalizões).\n• Primeira linha (não operatória) — Modificação de atividade, anti-inflamatórios, palmilhas de amortecimento, imobilização em bota gessada ou gesso abaixo do joelho.\n• Resposta ao gesso/bota — Alívio completo da dor geralmente em 24-48h após imobilização; cerca de 30% permanecem sem dor após a retirada do gesso/bota 6 semanas depois.\n• Cirurgia — coalizão calcaneonavicular — Ressecção da barra com interposição de tecido mole (gordura autógena ou extensor curto dos dedos - EDB); interposição de gordura autógena mostrou menor reossificação e reoperação q..."},{"id":"polydactyly-temtamy-mckusick","area":"Pediátrica","front":"TEMTAMY-MCKUSICK\n\nQuais são os critérios dessa classificação?\n(Classificação de Temtamy e McKusick para Polidactilia do Pé)","back":"• Pré-axial — Duplicação do hálux.\n• Pós-axial — Duplicação do quinto dedo — tipo mais frequente (79% em série de Phelps e Grogan).\n• Central — Duplicação do segundo, terceiro ou quarto dedo — tipo menos comum (6%).\n• Subtipo estrutural — Tipo A (bem-formado e articulado) versus tipo B (rudimentar e vestigial).\n• Associação relevante — Suspeitar de bracket epifisário longitudinal (LEB) do primeiro metatarsal sempre que houver polidactilia/polissindactilia pré-axial (incidência de LEB de 14% a 34% nessas séries)."},{"id":"polydactyly-venn-watson","area":"Pediátrica","front":"VENN-WATSON\n\nQuais são os critérios dessa classificação?\n(Classificação Morfológica de Venn-Watson para Polidactilia do Pé)","back":"• Base do sistema — Classificação morfológica das anormalidades de metatarsais e falanges na polidactilia do pé, com base em avaliação radiográfica.\n• Tipo pós-axial — Padrões descritos de duplicação do quinto raio.\n• Tipo pré-axial — Padrões descritos de duplicação do hálux, com maior tendência a desvio medial do dedo duplicado.\n• Classificação complementar (Burger et al.) — Sistema mais recente com 17 padrões específicos de polidactilia pré-axial, baseado em revisão de 73 pés em 43 pacientes.\n• Aplicação prática — Auxilia no planejamento cirúrgico ao caracterizar exatamente qual estrutura óssea está duplicada/rudimentar."},{"id":"congenital-hallux-varus-leb","area":"Pediátrica","front":"LEB/HÁLUX VARO CONGÊNITO\n\nQuais são os critérios dessa classificação?\n(Hálux Varo Congênito e Bracket Epifisário Longitudinal (LEB) do Primeiro Metatarsal — Critérios Diagnósticos)","back":"• Definição — Desvio medial do hálux sobre o primeiro metatarsal presente ao nascimento, frequentemente associado a primeiro metatarsal curto e arredondado, LEB, metatarsais/falanges acessórios e banda fibrosa medial.\n• Achado radiográfico de LEB — Formato em \"D\" do metatarsal — córtex lateral côncavo e córtex medial convexo, sem diferenciação cortical normal na borda medial da diáfise.\n• Diferencial clínico — Diferenciar do desvio medial flexível do hálux comumente associado a metatarso aduzido (passivamente corrigível; o hálux varo congênito verdadeiro não é).\n• Achados-chave ao exame — Banda fibrosa subcutânea na borda medial do antepé, espaço interdigital 1-2 alargado, e aparente encurtamento do primeiro metatarsal.\n• Conduta cirúrgi..."},{"id":"juvenile-hallux-valgus-angulos","area":"Pediátrica","front":"ÂNGULOS HALLUX VALGUS JUVENIL\n\nQuais são os critérios dessa classificação?\n(Ângulos Radiográficos-Chave no Hálux Valgo Juvenil (HVA, IMA/Metatarso Primo Varo e DMAA))","back":"• Ângulo de hálux valgo (HVA) — Definido pela interseção dos eixos longitudinais da falange proximal e do primeiro metatarsal; normal menor que 15 graus.\n• Metatarso primo varo / ângulo intermetatarsal (IMA) — Ângulo intermetatarsal entre 1º e 2º raios maior que 8 graus; relacionado à orientação/flexibilidade da articulação metatarsocuneiforme (MTC).\n• DMAA (ângulo articular metatarsal distal) — Quantifica a orientação lateralizada da cartilagem articular distal do primeiro metatarsal; DMAA aumentado presente em 48% dos casos de hálux valgo juvenil com articulação MTF congruente, percentual maior que em adultos.\n• Correlação clínica do DMAA — Significativamente maior em pacientes com história familiar positiva, início precoce (antes dos ..."},{"id":"juvenile-hallux-valgus-piggott-congruencia","area":"Pediátrica","front":"PIGGOTT\n\nQuais são os critérios dessa classificação?\n(Classificação de Piggott — Congruência da Articulação Metatarsofalângica no Hálux Valgo Juvenil)","back":"• Articulação congruente — Grau de hálux valgo igual ao DMAA; considerada mais estável e menos propensa a progredir.\n• Articulação subluxada (incongruente) — Leva a deformidade progressiva e artrose degenerativa em taxa imprevisível.\n• Prevalência comparativa — Articulação MTF congruente encontrada em 9% dos adultos versus 47% dos pacientes juvenis com hálux valgo.\n• Implicação terapêutica — Mesmo com articulação congruente, cirurgia pode ser necessária se a gravidade da deformidade causar incapacidade funcional.\n• Cautela cirúrgica — Realinhamento de partes moles isolado (liberação lateral + avanço capsular medial) não deve ser feito isoladamente, pelo alto risco de recidiva e de hálux varo iatrogênico."},{"id":"macrodactyly-estatico-progressivo","area":"Pediátrica","front":"MACRODACTILIA\n\nQuais são os critérios dessa classificação?\n(Classificação Evolutiva da Macrodactilia do Pé — Estática vs Progressiva)","back":"• Tipo estático — Dedo aumentado já ao nascimento, com crescimento proporcional aos dedos normais ao longo do tempo.\n• Tipo progressivo — Dedo envolvido cresce desproporcionalmente mais rápido que os dedos normais; é o tipo mais comum no pé.\n• Composição tecidual — Excesso de tecido fibrogorduroso compõe a maior parte do aumento de partes moles, mas todos os tecidos (nervos, artérias, veias, músculos, ligamentos) estão aumentados em circunferência.\n• Objetivo terapêutico — Não é a cosmese em si, mas permitir uso confortável de calçados de tamanho semelhante em ambos os pés e retardar/reduzir recidiva do aumento de tecidos moles não ressecáveis.\n• Opção mais eficaz — Ressecção de raio (ray resection) tem os melhores resultados relatados p..."},{"id":"sever-apofisite-diferencial-dor-calcanhar","area":"Pediátrica","front":"DOR NO CALCANHAR (SEVER)\n\nQuais são os critérios dessa classificação?\n(Diagnóstico Diferencial da Dor no Calcanhar na Criança/Adolescente (incluindo Apofisite de Sever))","back":"• Apofisite calcaneana (doença de Sever) — Causa mais comum de dor no calcanhar no atleta imaturo; idade típica de apresentação 10-12 anos, predomínio masculino (2-3x), bilateral em cerca de 60%; dor à compressão médio-lateral da apófise, sem calor/edema/dor noturna.\n• Tendinite do Aquiles — Dor localizada mais proximalmente, sobre o próprio tendão.\n• Bursite retrocalcânea — Dor localizada posteriormente, próxima à inserção do Aquiles.\n• Fratura de estresse calcaneana — Considerar no diagnóstico diferencial, especialmente se dor atípica; cintilografia óssea útil quando radiografia é inconclusiva.\n• Fasciíte plantar/bursite calcânea plantar — Localização plantar; extremamente rara em crianças e adolescentes."},{"id":"calcaneovalgus-vs-vertical-talus-diferencial","area":"Pediátrica","front":"CALCANEOVALGO vs TÁLUS VERTICAL\n\nQuais são os critérios dessa classificação?\n(Diagnóstico Diferencial entre Pé Calcaneovalgo Posicional e Tálus Vertical Congênito)","back":"• Pé calcaneovalgo posicional — Dorsiflexão acentuada e flexível de todo o pé no tornozelo, com eversão leve e flexível da subtalar; dorso do pé pode encostar na face anterior da perna.\n• Tálus vertical congênito — Equino fixo e valgo do retropé, dorsiflexão rígida do mediopé sobre o retropé, e impossibilidade de criar arco longitudinal por manipulação, acompanhado de contratura do Aquiles.\n• Teste diferencial radiográfico — Radiografias laterais em flexão plantar e dorsiflexão máximas diferenciam as duas entidades quando há dúvida clínica.\n• Outros diferenciais — Arqueamento póstero-medial congênito da tíbia (tíbia arqueada com tornozelo flexível vs tíbia reta com limitação real de flexão plantar) e calcaneovalgo paralítico (fraqueza do..."},{"id":"curly-toe-flexivel-rigido","area":"Pediátrica","front":"CURLY TOE\n\nQuais são os critérios dessa classificação?\n(Dedo em Garra Congênito (Curly Toe) — Distinção entre Deformidade Flexível e Rígida)","back":"• Definição — Flexão, varo e rotação lateral das falanges e interfalângicas de um ou mais dedos menores (3º e 4º mais frequentes), fazendo o dedo curvar-se sob o dedo mais medial adjacente; articulação metatarsofalângica com alinhamento normal.\n• Forma flexível (típica) — Devida à contratura do flexor longo/curto dos dedos; as interfalângicas podem ser estendidas totalmente quando MTF e tornozelo são fletidos plantarmente, comprovando contratura tendínea, não capsular.\n• Forma rígida — Deformidade em formato de trapézio de uma ou mais falanges, exigindo osteotomia ou artrodese para correção quando sintomática.\n• História natural — Geralmente assintomático na infância; muitos melhoram espontaneamente; pode tornar-se sintomático em criança..."},{"id":"flatfoot-staheli-vanderwilde-normativos","area":"Pediátrica","front":"STAHELI/VANDERWILDE\n\nQuais são os critérios dessa classificação?\n(Dados Normativos de Arco Longitudinal na Criança — Técnica da Impressão Plantar (Staheli) e Radiografia Normativa (Vanderwilde))","back":"• Técnica da impressão plantar (Staheli et al.) — Avaliação de 882 pés assintomáticos entre 1 e 80 anos demonstrou que a maioria dos lactentes é plana, o arco se desenvolve espontaneamente na primeira década, e pés planos estão dentro dos limites normais de confiança para altura do arco tanto em adultos quanto em crianças.\n• Estudo radiográfico normativo (Vanderwilde et al.) — Primeiro estudo abrangente de medidas radiográficas normativas do pé em crianças de 6 meses a 10 anos (médias e faixas de 2 desvios-padrão para diversos ângulos AP e laterais).\n• Achado-chave — Grande espectro de valores normais para crianças de diferentes idades; valores normais diferem dos valores normais do adulto e mudam espontaneamente com a idade rumo aos val..."},{"id":"frantz-orahilly-classificacao","area":"Pediátrica","front":"FRANTZ-ORAHILLY\n\nQuais são os critérios dessa classificação?\n(Classificação de Frantz e O'Rahilly das Deficiências Congênitas de Membros)","back":"• Amelia — Ausência completa do membro.\n• Deficiência transversa — Perda da parte distal da extremidade, com a parte proximal relativamente normal (extensão nomeada pelo nível, ex. hemimelia).\n• Deficiência longitudinal — Afeta um lado do membro (pré-axial, pós-axial ou porção central), podendo ser completa ou parcial.\n• Deficiência intercalar — Segmentos proximal e distal do membro relativamente não afetados, com segmento intermediário comprometido.\n• Nomenclatura complementar — Termos como hemimelia (aprox. metade do membro), podos (pé), cheir (mão), dactylos (dedos) e phalanx (falanges) descrevem extensão/localização do acometimento."},{"id":"iso-ispo-classificacao","area":"Pediátrica","front":"ISO/ISPO\n\nQuais são os critérios dessa classificação?\n(Classificação ISO/ISPO das Deficiências Congênitas de Membros)","back":"• Deficiência transversa — Nomeia-se o segmento no qual o membro está ausente, podendo indicar a extensão dentro do segmento (ex.: \"transversa perna terço médio\").\n• Deficiência longitudinal (hemimélica) — O(s) osso(s) ausente(s) é(são) nomeado(s) de proximal para distal e descrito(s) como \"parcial\" ou \"total\" (ex.: \"tíbia longitudinal completa, raio 1 parcial\").\n• Base conceitual — Incorpora muitos conceitos da classificação de Frantz e O'Rahilly; aceita como linguagem universal entre organizações nacionais que tratam essas crianças."},{"id":"crianca-vs-adulto-deficiencia-membro","area":"Pediátrica","front":"PED-vs-ADULTO\n\nQuais são os critérios dessa classificação?\n(Diferenças entre a Criança e o Adulto com Deficiência de Membro)","back":"• Etiologia predominante — Crianças mais frequentemente apresentam deficiências congênitas, deficiências múltiplas de membros e deficiências de membro superior.\n• Comorbidades — Diabetes e doença vascular periférica, comuns no amputado adulto disvascular, geralmente estão ausentes na criança.\n• Crescimento — Com o crescimento, a criança sofre alterações de comprimento e volume no coto residual, exigindo modificações protéticas e cirúrgicas mais frequentes.\n• Dor fantasma — Menos comum na criança do que no adulto.\n• Adaptação — Crianças se adaptam mais facilmente física e psicossocialmente à sua condição e costumam ter demandas funcionais mais altas que seus pares adultos."},{"id":"hipercrescimento-osseo-terminal-coto","area":"Pediátrica","front":"OVERGROWTH\n\nQuais são os critérios dessa classificação?\n(Hipercrescimento Ósseo Terminal do Coto de Amputação na Criança)","back":"• Incidência — Entre 20% e 50%, variando conforme causa da amputação, idade no momento da amputação, osso e localização envolvidos.\n• Padrão de ocorrência — Mais comum após amputação traumática ou eletiva através da diáfise óssea; menos comum em amputações congênitas ou eletivas antes dos 12 anos; não ocorre em amputações através de articulações.\n• Local mais frequente — Amputações transtibiais (mais na fíbula que na tíbia) e transumerais.\n• Fisiopatologia — O periósteo continua a crescer sobre a extremidade do osso, contrai-se sobre o canal medular aberto e é tracionado para dentro dele, de onde continua a crescer, produzindo hipercrescimento distal ao coto ósseo original (demonstrado por Aitken com marcadores metálicos).\n• Apresentação..."},{"id":"tempo-ideal-amputacao-deficiencia-congenita","area":"Pediátrica","front":"TEMPO-AMPUT\n\nQuais são os critérios dessa classificação?\n(Tempo Ideal para Amputação Eletiva na Deficiência Congênita de Membro Inferior)","back":"• Regra geral — Amputação eletiva realizada poucos meses antes de a criança estar pronta para ficar em pé (quando começa a se apoiar para ficar de pé), permitindo protetização no momento certo do desenvolvimento motor.\n• Exceção — Em casos raros em que a extremidade deformada interfere no engatinhar, a amputação pode ser antecipada, mas a protetização deve aguardar até ter valor funcional.\n• PFFD — Pode ser realizada em idade um pouco mais tardia (e após protetização inicial), por razões técnicas.\n• Limite de idade — Não há limite superior de idade definido, mas a maioria das amputações deve ser realizada antes da idade escolar, se possível."},{"id":"achterman-kalamchi-deficiencia-fibular","area":"Pediátrica","front":"ACHTERMAN-KALAMCHI\n\nQuais são os critérios dessa classificação?\n(Classificação de Achterman e Kalamchi da Deficiência Fibular Longitudinal)","back":"• Tipo Ia — Fíbula proximal curta, porém presente; encurtamento parcial da fíbula.\n• Tipo Ib — Fíbula proximal ausente; frequentemente associada a deficiência femoral proximal focal (PFFD).\n• Tipo II — Fíbula completamente ausente; associada a arqueamento anterior da tíbia e ausência dos raios laterais do pé."},{"id":"birch-classificacao-funcional-deficiencia-fibular","area":"Pediátrica","front":"BIRCH-FUNCIONAL\n\nQuais são os critérios dessa classificação?\n(Classificação Funcional e Indicação Cirúrgica de Birch na Deficiência Fibular Longitudinal)","back":"• Pé não funcional — Amputação recomendada independentemente do comprimento do membro, exceto se houver deficiência de membro superior concomitante que torne o pé funcionalmente útil como \"mão\".\n• Pé funcional, discrepância < 5% — Observação, sem necessidade de cirurgia.\n• Pé funcional, discrepância 6%-10% — Epifisiodese ou alongamento único.\n• Pé funcional, discrepância 10%-30% — Zona de controvérsia: candidato tanto a amputação quanto a alongamento estagiado (múltiplos alongamentos), decisão compartilhada com a família.\n• Pé funcional, discrepância > 30% — Amputação recomendada (Birch); autores mais antigos (Westin) recomendavam amputação já a partir de discrepância prevista > 7,5 cm."},{"id":"paley-classificacao-tornozelo-retrope-deficiencia-fibular","area":"Pediátrica","front":"PALEY-TORNOZELO\n\nQuais são os critérios dessa classificação?\n(Classificação de Paley da Deformidade de Tornozelo/Retropé na Deficiência Fibular)","back":"• Valgo leve dinâmico — Deformidade discreta e não fixa; costuma responder a hemiepifisiodese medial distal da tíbia ou osteotomia supramaleolar.\n• Valgo mais grave fixo (tornozelo e/ou subtalar) — Requer osteotomia de realinhamento subtalar ou da tíbia distal; Paley sugere ressecção do ânlage fibular e recessão do gastrocnêmio nos casos mais graves.\n• Equinovaro (raro) — Ocasionalmente presente, por coalizão tarsal em varo do retropé; pode ser confundido com pé torto congênito no período neonatal."},{"id":"amputacao-syme-vs-boyd-deficiencia-fibular-tibial","area":"Pediátrica","front":"SYME-BOYD\n\nQuais são os critérios dessa classificação?\n(Amputação de Syme versus Boyd na Deficiência Fibular e Tibial)","back":"• Amputação de Syme — Preserva o coxim calcâneo com capacidade de apoio terminal; tecnicamente mais simples; não requer alteração óssea da tíbia distal na criança.\n• Amputação de Boyd — O tálus é excisado e o calcâneo remanescente (com coxim) é fundido à tíbia (ou à fíbula, na deficiência tibial); evita a migração posterior do coxim calcâneo vista em alguns casos de Syme.\n• Desvantagem do Boyd — Calcâneo e tíbia distal são predominantemente cartilaginosos na criança pequena, dificultando a artrodese; se não há fusão, o calcâneo pode migrar, exigindo revisão ou conversão para Syme.\n• Vantagem do Boyd — O coxim calcâneo tende a crescer com a criança (ao contrário do Syme, em que permanece pequeno); o contorno do calcâneo retido melhora a s..."},{"id":"jones-classificacao-deficiencia-tibial","area":"Pediátrica","front":"JONES-TIBIAL\n\nQuais são os critérios dessa classificação?\n(Classificação de Jones da Deficiência Tibial Longitudinal)","back":"• Tipo 1a — Ausência completa de ossificação da tíbia, com hipoplasia da epífise femoral distal (ausência completa de ânlage tibial cartilaginoso); mecanismo extensor do joelho geralmente ausente/muito deficiente.\n• Tipo 1b — Côndilos femorais mais desenvolvidos, implicando ânlage tibial cartilaginoso presente articulando com o fêmur distal (ossifica entre 2 e 4 anos); mecanismo extensor geralmente presente.\n• Tipo 2 — Tíbia proximal presente, com ausência de ossificação da tíbia distal (equivalente ao tipo II da classificação original de Kalamchi e Dawe).\n• Tipo 3 — Muito raro; ausência da tíbia proximal com presença da tíbia distal.\n• Tipo 4 — Diástase da articulação tibiofibular distal, com o tálus encunhado entre tíbia e fíbula dista..."},{"id":"conduta-por-tipo-jones-deficiencia-tibial","area":"Pediátrica","front":"COND-TIBIAL\n\nQuais são os critérios dessa classificação?\n(Conduta Cirúrgica Recomendada por Tipo de Jones na Deficiência Tibial)","back":"• Tipo 1a sem extensão ativa do joelho — Desarticulação do joelho e protetização; a centralização da fíbula sob os côndilos femorais (procedimento de Brown) tem resultados historicamente ruins e não é recomendada.\n• Tipo 1b ou 2 com extensão ativa do joelho — Aguardar ossificação do remanescente tibial e então realizar sinostose tibiofibular término-terminal, associada a amputação de Boyd modificada (fusão da fíbula distal ao calcâneo); ressecção da fíbula proximal se proeminente/instável.\n• Tipo 3 — Desarticulação de tornozelo e protetização (extrapolado de série pequena/Schoenecker).\n• Tipo 4, discrepância prevista ≤ 5 cm — Correção de partes moles do pé precocemente, com epifisiodese contralateral tardia para igualar comprimentos.\n• T..."},{"id":"aitken-classificacao-pffd","area":"Pediátrica","front":"AITKEN\n\nQuais são os critérios dessa classificação?\n(Classificação de Aitken da Deficiência Femoral Focal Proximal (PFFD))","back":"• Classe A — Fêmur curto, com porção ossificada mais proximal no nível ou pouco acima do acetábulo; ossificação subtrocantérica incompleta que tende a se completar com o tempo; acetábulo bem formado.\n• Classe B — Defeito mais extenso ou ausência da porção proximal do fêmur; acetábulo mais displásico que na classe A; o defeito subtrocantérico não ossifica com o tempo, formando pseudoartrose.\n• Classe C — Acetábulo severamente displásico (cabeça femoral ausente e não ossificará); fêmur mais curto que na classe B; todo o fêmur proximal não ossifica com o tempo.\n• Classe D — Diáfise femoral essencialmente ausente; côndilos femorais distais localizados no nível em que deveria estar o acetábulo; parede pélvica lateral achatada, sem desenvolvim..."},{"id":"gillespie-classificacao-pffd","area":"Pediátrica","front":"GILLESPIE\n\nQuais são os critérios dessa classificação?\n(Classificação de Gillespie da Deficiência Femoral Congênita (Baseada em Tratamento))","back":"• Grupo A — Fêmur curto congênito com quadril clinicamente estável, sem contratura em flexão significativa do joelho, e pé caindo no nível ou abaixo do ponto médio da tíbia contralateral; segmento femoral maior que 60% do lado contralateral; candidatos a alongamento do membro.\n• Grupo B — Quadril instável à carga e segmento femoral menor que 50% do lado contralateral.\n• Grupo C — Apenas um pequeno tufo do fêmur distal presente, sem desenvolvimento acetabular."},{"id":"sabharwal-paley-classificacao-deficiencia-femoral","area":"Pediátrica","front":"SABHARWAL-PALEY\n\nQuais são os critérios dessa classificação?\n(Classificação de Sabharwal e Paley da Deficiência Femoral Congênita (para Alongamento))","back":"• Tipo 1 — Semelhante ao grupo A de Gillespie, subdividido em três subgrupos conforme problemas de quadril e joelho que devem ser corrigidos antes ou durante o alongamento.\n• Tipo 2 — Pseudoartrose móvel, com ou sem cabeça femoral móvel; requer estabilização da pseudoartrose ou do fêmur proximal em relação à pelve antes do alongamento (frequentemente fixação do fixador externo à pelve associada a osteotomia proximal em valgo/extensão, quando a cabeça femoral é imóvel ou ausente).\n• Tipo 3 — Semelhante ao grupo C de Gillespie; se a mobilidade do joelho é menor que 45 graus, o ganho funcional com alongamento é duvidoso."},{"id":"estrategia-tratamento-deficiencia-femoral-congenita","area":"Pediátrica","front":"ESTRATEGIA-PFFD\n\nQuais são os critérios dessa classificação?\n(Estratégia de Tratamento Cirúrgico da Deficiência Femoral Congênita por Discrepância Prevista)","back":"• Discrepância prevista < 20 cm, quadril estável (ou passível de estabilização) e boa mobilidade/estabilidade de joelho-tornozelo-pé — Alongamento do membro (múltiplos estágios), associado a epifisiodese contralateral e eventual calço de sapato.\n• Discrepância prevista > 20 cm (ou outra razão contra alongamento) — Decisão entre artrodese de joelho com amputação de pé, rotacionoplastia, ou (mais raramente) protetização acomodativa sem cirurgia.\n• Casos bilaterais — Tratamento predominantemente não operatório; a maioria dessas crianças não usa prótese."},{"id":"rotacionoplastia-van-nes-indicacoes","area":"Pediátrica","front":"VAN-NES\n\nQuais são os critérios dessa classificação?\n(Rotacionoplastia de Van Nes na Deficiência Femoral Congênita — Indicações e Contraindicações)","back":"• Indicação central — Tornozelo/retropé com amplitude de flexo-extensão suficiente (a articulação do tornozelo passará a funcionar como o novo joelho); rotação de 180 graus predominantemente através da artrodese do joelho, com rotação adicional pela tíbia se necessário.\n• Pré-requisito de força — Fortalecimento pré-operatório de artelhos, tornozelo e retropé, estruturas motoras do novo \"joelho\".\n• Contraindicação — Deformidades graves em valgo e equino do tornozelo/pé, com pé deficiente.\n• Complicação principal — Rotação insuficiente na cirurgia ou desrotação progressiva com o crescimento, tratável com osteotomia rotacional da tíbia (pode ser repetida)."},{"id":"criterios-estabilizacao-quadril-superhip-deficiencia-femoral","area":"Pediátrica","front":"SUPERHIP-CRIT\n\nQuais são os critérios dessa classificação?\n(Critérios para Estabilização Cirúrgica do Quadril (Procedimento SUPERhip) na Deficiência Femoral Congênita)","back":"• Indicação — Pacientes Aitken classe A ou B, com cabeça femoral móvel dentro do acetábulo.\n• Critério angular — Correção cirúrgica do varo/retroversão indicada quando o ângulo cervicodiafisário é menor que 110 graus.\n• Componentes abordados — Deformidade óssea (varo/retroversão femoral, displasia acetabular) e contraturas de partes moles (flexores do quadril — reto femoral e iliopsoas — e abdutores — glúteo médio e mínimo).\n• Objetivo — Obter boa contenção da cabeça femoral antes do alongamento, já que o acetábulo na deficiência femoral congênita é tipicamente retrovertido (déficit de cobertura póstero-lateral), diferente da displasia do desenvolvimento do quadril."},{"id":"categorias-clinicas-deficiencia-terminal-membro-superior","area":"Pediátrica","front":"CATEG-MMSS\n\nQuais são os critérios dessa classificação?\n(Categorias Clínicas de Deficiência Terminal do Membro Superior e Implicações Protéticas)","back":"• Amelia — Ausência completa do membro; próteses funcionais pouco aceitas, especialmente na amelia unilateral; na amelia bilateral com membros inferiores íntegros, a criança tende a rejeitar a prótese e usar os pés para todas as AVDs.\n• Focomelia — Segmento distal do membro parece se inserir diretamente no tronco; geralmente há alguma mobilidade e sensibilidade no coto residual, com função variável conforme comprimento e capacidade de aproximar as mãos ao campo visual.\n• Deficiência umeral transversa completa (transumeral) — Uso protético geralmente restrito a tarefas específicas; nos com segmento umeral longo o suficiente, o \"pinçamento úmero-torácico\" auxilia a extremidade contralateral.\n• Deficiência transversa completa do antebraço (..."},{"id":"indicacoes-procedimento-krukenberg","area":"Pediátrica","front":"KRUKENBERG\n\nQuais são os critérios dessa classificação?\n(Indicações do Procedimento de Krukenberg na Deficiência Transversa Bilateral do Antebraço)","back":"• Princípio — Separação do rádio e da ulna para criar um antebraço capaz de pinça e preensão entre extremidades sensíveis.\n• Indicação preferencial — Criança com deficiência de membro superior bilateral, quando há amplitude completa de cotovelo e antebraço e este tem comprimento suficiente para inserção funcional do pronador redondo (pelo menos 25% do comprimento do antebraço normal).\n• Indicação atual restrita — No mundo ocidental, atualmente limitada a pacientes com deficiência bilateral de membro superior e cegueira associada, devido a preocupações estéticas.\n• Complicações — Subluxação/luxação da cabeça radial proximal; pinça insuficiente em uma minoria de pacientes."},{"id":"cronograma-protetizacao-membro-superior-pediatrico","area":"Pediátrica","front":"CRONO-PROTESE-MMSS\n\nQuais são os critérios dessa classificação?\n(Cronograma de Protetização do Membro Superior na Criança com Deficiência Congênita)","back":"• 4 a 6 meses — Ajuste de mão passiva, coincidindo com o início de levar as mãos à linha média e apoiar-se nos cotovelos; objetivo é favorecer o desenvolvimento bimanual.\n• 15 a 18 meses — Considerar dispositivo terminal mais funcional (corpo-motor ou mioelétrico voluntário abre-fecha automático — \"cookie cruncher\").\n• 3 a 3,5 anos — Sistema mioelétrico de dois sítios (um eletrodo para cada função — flexores fecham a mão, extensores abrem), quando a criança demonstra bom controle independente dos dois grupos musculares.\n• Após 4 anos — Sistemas de um sítio mais avançados (sensíveis à velocidade ou ao nível de contração), quando não há dois sítios musculares disponíveis, controlando duas funções com um músculo."},{"id":"classificacao-funcional-pes-proteticos-pediatricos","area":"Pediátrica","front":"PES-PROTETICOS\n\nQuais são os critérios dessa classificação?\n(Classificação Funcional dos Pés Protéticos Pediátricos)","back":"• SACH (solid ankle cushion heel) — Sem partes articuladas; movimento depende da compressão dos materiais entre contato do calcanhar e saída dos artelhos; indicado quando há necessidade de estabilidade em média/final da fase de apoio; usado em pediatria quando o tamanho do pé é menor que 12 cm.\n• Eixo único (single axis) — Contém amortecedores de borracha que permitem flexão dorsal e plantar passiva; não disponível em tamanho pediátrico; melhor indicado para o amputado transfemoral que necessita de contato total do pé com o solo.\n• Multieixo (multiaxis) — Permite flexão dorsal/plantar passiva, inversão/eversão e rotação transversa passiva; amplamente aceito em pediatria por absorver forças no tornozelo e reduzir sua transmissão ao soquet..."},{"id":"selecao-joelho-protetico-pediatrico","area":"Pediátrica","front":"JOELHO-PROTETICO\n\nQuais são os critérios dessa classificação?\n(Seleção de Joelho Protético na Criança com Amputação Transfemoral/Desarticulação de Joelho)","back":"• Joelho de eixo único sem unidade de controle — Primeiro joelho a ser usado na criança, pelo peso leve, braço de alavanca curto e simplicidade.\n• Joelho policêntrico (quatro barras) — Introduzido em 1998 para uso em lactentes/crianças pequenas; o centro de rotação varia com o ângulo de flexão do coto, proporcionando estabilidade na fase de apoio, flexão fluida e maior espaço livre ao solo na fase de balanço.\n• Idade de introdução — Tradicionalmente introduzido por volta de 3-4 anos; relatos mostram bons resultados com joelhos articulados a partir de 17 meses e até mesmo aos 11 meses de idade.\n• Sistemas hidráulicos/microprocessados — Reservados para crianças maiores e mais pesadas (ex.: joelho hidráulico policêntrico de adulto rotineira..."},{"id":"desenho-soquete-desarticulacao-quadril-transfemoral","area":"Pediátrica","front":"SOQUETE-QUADRIL-FEMUR\n\nQuais são os critérios dessa classificação?\n(Desenho de Soquete na Desarticulação de Quadril e na Amputação Transfemoral Pediátrica)","back":"• Desarticulação de quadril — Soquete envolve o remanescente pélvico amputado e o lado contralateral para suspensão; quadris protéticos de eixo único montados anterodistalmente no lado afetado; recomenda-se travar o joelho inicialmente até que o controle do quadril seja aprendido.\n• Soquete quadrilateral (transfemoral) — Modelo tradicional até 1987; útil na criança pequena, especialmente se possível apoio distal, mas não estabiliza bem o segmento femoral.\n• Soquete de contenção isquiática (narrow ML / CAT-CAM) — Adota o fêmur em adução com a tuberosidade isquiática travada dentro do soquete, proporcionando alinhamento mais anatômico durante a marcha; pode ser inviável em lactentes pela coxa/nádegas gordurosas e uso de fraldas."},{"id":"nivel-amputacao-parcial-pe-chopart-protetizacao","area":"Pediátrica","front":"CHOPART-PARCIAL\n\nQuais são os critérios dessa classificação?\n(Protetização por Nível de Amputação Parcial do Pé (incluindo Chopart))","back":"• Ausência total/parcial dos artelhos — Geralmente requer apenas um preenchimento de sapato (shoe filler).\n• Amputação parcial com perda da coluna medial — Maior demanda sobre o dispositivo protético para auxiliar a função de apoio terminal; frequentemente combinado a órtese tornozelo-pé (AFO) de reação ao solo (anterior shell) para transferir forças mais proximalmente.\n• Amputação de Chopart (mediotársica) — Uso reservado a instâncias especiais; a prótese deve envolver calcâneo e tálus, resultando em prótese frequentemente mais longa que o membro contralateral; seleção de pé protético é limitada pela falta de espaço distal."},{"id":"principios-amputacao-adquirida-crianca","area":"Tumor","front":"PRINC-AMPUT-ADQUIRIDA\n\nQuais são os critérios dessa classificação?\n(Princípios de Amputação Adquirida (Traumática/Tumoral) na Criança)","back":"• Preservação de comprimento — Preferir preservar o máximo de comprimento possível nos ossos longos, especialmente no fêmur (70% do crescimento ocorre pela fise distal).\n• Desarticulação vs amputação diafisária — Desarticulações são preferidas às amputações através do osso, pois evitam o hipercrescimento ósseo terminal; não é necessário remover a cartilagem da extremidade óssea.\n• Cobertura cutânea — Ao contrário do adulto, enxertos de pele são cobertura aceitável para coto de carga em criança, desde que não fiquem aderentes ao osso (comum em meningococcemia, queimaduras e alguns traumas).\n• Capeamento com material amputado — Se uma amputação diafisária primária é inevitável, usar partes disponíveis do segmento amputado para capear a ext..."},{"id":"sensacao-dor-fantasma-crianca-deficiencia-membro","area":"Pediátrica","front":"FANTASMA-PED\n\nQuais são os critérios dessa classificação?\n(Sensação e Dor Fantasma na Criança com Deficiência/Amputação de Membro)","back":"• Prevalência — Ao menos 20% das crianças com amputação congênita e 50% daquelas amputadas antes dos 6 anos relatam sensação de membro fantasma.\n• Dor fantasma — Descrita como dolorosa em 20% do grupo congênito versus 42% do grupo com deficiência adquirida.\n• Gatilhos comuns — Nervosismo ou euforia, não usar a prótese, sensação de frio e doença aguda.\n• Impacto funcional — Geralmente não interfere na atividade habitual da criança; a maioria apenas tenta ignorar as sensações.\n• Manejo — Analgesia preemptiva perioperatória, anestesia peridural/raquianestesia, cateteres intraneurais contínuos no pós-operatório; gabapentina útil em adolescentes com dor fantasma estabelecida."},{"id":"indicacoes-protese-nao-convencional-pffd","area":"Pediátrica","front":"PROTESE-EXTENSAO-PFFD\n\nQuais são os critérios dessa classificação?\n(Indicações da Prótese de Extensão (Não Convencional) na Deficiência Femoral Congênita)","back":"• Idade insuficiente para conversão cirúrgica — Criança ainda jovem demais para os procedimentos definitivos (artrodese de joelho, rotacionoplastia, etc.).\n• Recusa familiar — Paciente ou responsável recusa intervenção cirúrgica e uma prótese é necessária para permitir a deambulação.\n• Casos bilaterais — Quando altura extra ou melhor equilíbrio é o objetivo.\n• Deficiência associada de membro superior — Envolvimento de membro inferior combinado com ausência bilateral de membro superior, exigindo uso dos pés para atividades de vida diária."},{"id":"tibial-spine-meyers-mckeever","area":"Pediátrica","front":"M&M/Zaricznyj\n\nQuais são os critérios dessa classificação?\n(Classificação de Meyers-McKeever (modificada por Zaricznyj) para fraturas da eminência (espinha) tibial)","back":"• Tipo 1 — Deslocamento mínimo do fragmento da espinha tibial em relação à epífise tibial proximal.\n• Tipo 2 — Deslocamento do terço a metade anterior do fragmento avulsionado, que se eleva mas permanece em dobradiça (contato) com a epífise tibial em sua borda posterior.\n• Tipo 3 — Separação completa do fragmento em relação à epífise tibial proximal, geralmente com deslocamento superior e rotação; subdividido em 3A (envolve apenas a inserção do LCA) e 3B (envolve todo o entalhe intercondilar).\n• Tipo 4 (Zaricznyj) — Fratura cominutiva da espinha tibial, adicionada como modificação posterior à classificação original."},{"id":"discoid-meniscus-watanabe","area":"Pediátrica","front":"Watanabe\n\nQuais são os critérios dessa classificação?\n(Classificação de Watanabe para menisco discoide)","back":"• Tipo 1 (completo, estável) — Menisco em bloco, espesso (8-10 mm), cobrindo a totalidade do platô tibial lateral.\n• Tipo 2 (incompleto, estável) — Formato em bloco semelhante ao tipo 1, porém cobrindo menos de 80% do platô tibial.\n• Tipo 3 - variante de Wrisberg (instável) — Aparência variável, sem fixação periférica posterior exceto pelo ligamento de Wrisberg; predispõe a instabilidade e subluxação do corno posterior."},{"id":"meniscal-tear-zone-healing-pediatric","area":"Pediátrica","front":"—\n\nQuais são os critérios dessa classificação?\n(Localização da lesão meniscal e potencial de cicatrização em crianças)","back":"• Zona vermelho-vermelha (periférica) — Corresponde a 10-30% periférico do menisco (totalmente vascularizado); rasgos longitudinais pequenos (<10 mm) e deslocáveis <3 mm cicatrizam espontaneamente.\n• Zona central avascular — Nutrição por difusão sinovial; menor potencial de cicatrização espontânea, porém o reparo ainda é preferido à meniscectomia dado o risco de artrose.\n• Padrões degenerativos — Rasgos por cisalhamento horizontal, radiais e complexos são menos comuns, têm pior potencial de cicatrização e frequentemente exigem meniscectomia parcial criteriosa.\n• Lesão em alça de balde (bucket-handle) — Rasgo não incomum envolvendo grande extensão do menisco; reparo preferido, especialmente no contexto de reconstrução do LCA."},{"id":"patellar-dislocation-classification","area":"Pediátrica","front":"—\n\nQuais são os critérios dessa classificação?\n(Classificação da luxação patelar)","back":"• Aguda — Evento único em atleta adolescente de alto nível, geralmente por trauma indireto (pé fixo, joelho em valgo/rotação interna do fêmur); frequentemente há anormalidade anatômica subjacente predisponente.\n• Recorrente — Ocorre em indivíduos com variantes anatômicas conhecidas (frouxidão ligamentosa, patela alta, genu valgo, aumento do ângulo Q, torção tibial externa excessiva, displasia condilar femoral).\n• Habitual — Categoria adicional citada pelos autores, distinta das formas aguda e recorrente."},{"id":"osteochondral-fragment-fixation-criteria","area":"Pediátrica","front":"—\n\nQuais são os critérios dessa classificação?\n(Critérios de tamanho/integridade do fragmento osteocondral pós-luxação patelar para excisão versus fixação)","back":"• Fragmento < 1 cm e fissurado/fragmentado — Indicação de excisão artroscópica do fragmento.\n• Fragmento > 1 cm e íntegro — Indicação de redução e fixação (artrotomia com parafusos canulados rebaixados ao nível subcondral).\n• Ausência de fratura osteocondral — Reparo agudo das estruturas mediais (LPFM e retináculo patelar), geralmente com liberação retinacular lateral associada; imobilização por 10-14 dias seguida de reabilitação."},{"id":"patellar-instability-risk-anatomic","area":"Pediátrica","front":"—\n\nQuais são os critérios dessa classificação?\n(Fatores de risco anatômicos e critérios cirúrgicos na instabilidade patelar recorrente)","back":"• Ângulo Q normal — ≤ 10 graus; formado entre o eixo do mecanismo extensor (EIAS ao centro do joelho) e o eixo do tendão patelar.\n• Fatores anatômicos predisponentes — Aumento do ângulo Q, valgo femorotibial aumentado, torção tibial externa excessiva, displasia condilar femoral, patela alta e frouxidão ligamentar generalizada.\n• Teste de apreensão — Positivo quando a tentativa de deslocar a patela lateralmente com o joelho fletido a ~30 graus reproduz apreensão.\n• Indicação cirúrgica — Três a quatro recorrências de luxação patelar com impacto no estilo de vida do paciente; correção das variantes anatômicas é fundamental para o resultado a longo prazo."},{"id":"ankle-sprain-grade-lateral-ligament","area":"Pediátrica","front":"Grau I-III\n\nQuais são os critérios dessa classificação?\n(Classificação da entorse lateral de tornozelo por gravidade)","back":"• Grau I (leve) — Sem ruptura tecidual aparente, perda mínima de função; envolve apenas o ligamento talofibular anterior.\n• Grau II (moderado) — Ruptura parcial do tecido com perda parcial de função; envolve os ligamentos talofibular anterior e calcaneofibular.\n• Grau III (grave) — Ruptura significativa ou completa, com perda acentuada de função; envolve todos os ligamentos laterais e pode acometer o deltoide medialmente.\n• Lesão da sindesmose (interóssea) — Sempre associada a lesão do ligamento deltoide; suspeitar quando o mecanismo é pronossupinação-rotação externa; alargamento da sindesmose > 5 mm em radiografia confirma ruptura."},{"id":"ankle-instability-functional-mechanical","area":"Pediátrica","front":"—\n\nQuais são os critérios dessa classificação?\n(Instabilidade crônica de tornozelo: funcional versus mecânica)","back":"• Instabilidade funcional — Sensação subjetiva de falseio durante atividade física, ocorrendo em até 50% após entorse; atribuída a déficit de propriocepção e controle muscular. Tratada com treino proprioceptivo (prancha de equilíbrio), fortalecimento e órteses/bandagem.\n• Instabilidade mecânica — Incompetência dos ligamentos estabilizadores; demonstrada pelo teste da gaveta anterior do tálus e radiografias de estresse (talar tilt).\n• Critérios radiográficos de instabilidade mecânica — Diferença lado a lado ≥ 10 mm de translação talar anterior e talar tilt ≥ 9 graus são altamente sugestivos."},{"id":"ankle-sprain-rehab-phases","area":"Pediátrica","front":"Fase I-III\n\nQuais são os critérios dessa classificação?\n(Fases de reabilitação da entorse aguda de tornozelo)","back":"• Fase I — Repouso e proteção (órtese, gesso, tala, muletas, gelo), controle do edema (gelo, compressão, elevação) e carga precoce.\n• Fase II — Redução do edema residual, restauração da amplitude de movimento e força, seguida de condicionamento aeróbico de baixo impacto.\n• Fase III — Exercícios proprioceptivos e habilidades específicas do esporte (corrida, mudança de direção, saltos), com retorno gradual ao esporte, podendo usar órtese ou bandagem estabilizadora."},{"id":"pelvic-apophyseal-avulsion-sites","area":"Pediátrica","front":"—\n\nQuais são os critérios dessa classificação?\n(Avulsões apofisárias da pelve em crescimento por local de origem muscular)","back":"• Espinha ilíaca ântero-superior (EIAS) — Avulsão por contração violenta do sartório, típica de salto/corrida.\n• Espinha ilíaca ântero-inferior (EIAI) — Avulsão por tração excessiva da cabeça reta do reto femoral; comum em esportes de chute.\n• Tuberosidade isquiática — Avulsão por contração forçada dos isquiotibiais; comum em ginastas e corredores de barreira. O núcleo aparece aos 15 anos e pode não fundir até os 25 anos, permitindo avulsão até no início da vida adulta.\n• Crista ilíaca — Local de inserção dos músculos abdominais e do tronco.\n• Pequeno trocânter — Local de inserção do iliopsoas."},{"id":"pelvic-avulsion-rehab-metzmaker","area":"Pediátrica","front":"Metzmaker-Pappas\n\nQuais são os critérios dessa classificação?\n(Programa de reabilitação em 5 estágios para avulsões pélvicas (Metzmaker e Pappas))","back":"• Estágio 1 — Repouso para relaxar a musculatura envolvida, gelo e analgésicos.\n• Estágio 2 — Início de mobilização ativa e passiva suave.\n• Estágio 3 — Exercícios de resistência após recuperação de 75% da amplitude de movimento.\n• Estágio 4 — Alongamento e fortalecimento com ênfase em exercícios específicos do esporte.\n• Estágio 5 — Retorno ao esporte competitivo."},{"id":"glenohumeral-dislocation-traumatic-atraumatic","area":"Pediátrica","front":"—\n\nQuais são os critérios dessa classificação?\n(Classificação da luxação glenoumeral em crianças: traumática versus atraumática)","back":"• Traumática — Evento traumático específico (abdução-rotação externa forçada, queda sobre a mão espalmada); associada a lesão de Bankart e maior taxa de recidiva; tratamento cirúrgico considerado especialmente em esportes de contato/colisão.\n• Atraumática - voluntária — Paciente aprende a subluxar/luxar voluntariamente o ombro; pode associar-se a distúrbios psicológicos/psiquiátricos; cautela cirúrgica nesse grupo.\n• Atraumática - involuntária — Ocorre com evento específico não traumático (ex.: carregar peso); associada a frouxidão ligamentar generalizada e doenças do tecido conjuntivo (Ehlers-Danlos, Marfan)."},{"id":"glenohumeral-translation-grading","area":"Pediátrica","front":"Grau 1-4\n\nQuais são os critérios dessa classificação?\n(Graduação da translação glenoumeral ao exame de instabilidade)","back":"• Grau 1 — Sem aumento da translação em relação ao lado contralateral.\n• Grau 2 — Translação até a borda da glenoide.\n• Grau 3 — Translação sobre a borda da glenoide com redução espontânea (subluxação).\n• Grau 4 — Translação além da borda da glenoide (luxação franca)."},{"id":"ocd-guhl-arthroscopic-classification","area":"Pediátrica","front":"Guhl\n\nQuais são os critérios dessa classificação?\n(Classificação artroscópica de Guhl para osteocondrite dissecante do joelho)","back":"• Lesão íntegra (intacta) — Superfície articular preservada, sem separação; tratada com perfuração (drilling) transarticular ou retrógrada para estimular cicatrização vascular.\n• Lesão em separação inicial — Início de descolamento; indicação de fixação interna do fragmento.\n• Lesão parcialmente destacada — Fragmento parcialmente solto; indicação de fixação interna, com desbridamento do leito até osso sangrante e eventual enxerto ósseo antes da fixação.\n• Crateras e corpos livres salvatáveis — Fragmento passível de reimplante/fixação após preparo do leito.\n• Crateras e corpos livres não salvatáveis — Remoção do(s) corpo(s) livre(s) e regularização das bordas da cartilagem articular; excisão isolada tem maus resultados a longo prazo, favor..."},{"id":"ocd-mri-instability-criteria","area":"Pediátrica","front":"—\n\nQuais são os critérios dessa classificação?\n(Critérios de instabilidade da lesão de OCD do joelho na ressonância magnética)","back":"• Sinal de alta intensidade em T2 entre a lesão e o osso subcondral — Indica líquido sinovial interposto, sugerindo instabilidade da lesão (achado patognomônico de instabilidade na forma adulta de OCD).\n• Sinal semelhante em crianças — Pode representar tecido de granulação vascular em cicatrização (não necessariamente instabilidade verdadeira), exigindo cautela na interpretação isolada em pacientes pediátricos.\n• RM com gadolínio / artro-RM — Melhoram a acurácia na avaliação da estabilidade da lesão."},{"id":"osgood-schlatter-disease","area":"Pediátrica","front":"OSD\n\nQuais são os critérios dessa classificação?\n(Doença de Osgood-Schlatter (apofisite de tração da tuberosidade tibial))","back":"• Faixa etária — 10 a 15 anos, mais prevalente em meninos praticantes de esportes de salto, mas ocorre também em meninas.\n• Fase aguda — Dor e sensibilidade diretamente sobre a tuberosidade tibial, piorando com atividade física.\n• Fase crônica/tardia — Dor e sensibilidade diminuem; pode restar apenas uma proeminência (massa) anterior indolor.\n• Radiografia — Incidência lateral com rotação interna de 10-20 graus mostra fragmentação da tuberosidade ou ossículo separado da tuberosidade subjacente."},{"id":"sinding-larsen-johansson-syndrome","area":"Pediátrica","front":"SLJ\n\nQuais são os critérios dessa classificação?\n(Síndrome de Sinding-Larsen-Johansson)","back":"• Localização — Inserção proximal do tendão patelar no polo inferior da patela (diferente da OSD, que acomete a tuberosidade tibial).\n• Faixa etária — 10 a 12 anos, ligeiramente mais jovem que a faixa etária típica da OSD.\n• Clínica — Dor pontual no polo inferior da patela; radiografia pode mostrar calcificação nesse local.\n• Tratamento — Semelhante ao da OSD: repouso e AINEs; a maioria responde bem."},{"id":"synovial-plica-anatomic-classification","area":"Pediátrica","front":"—\n\nQuais são os critérios dessa classificação?\n(Classificação anatômica das plicas sinoviais do joelho)","back":"• Plica medial — A mais comumente sintomática; do polo súpero-medial da patela ao coxim adiposo patelar medial.\n• Plica suprapatelar — Localizada na região superior do joelho.\n• Plica lateral — Menos comum.\n• Plica infrapatelar (ligamento mucoso) — Recobre o ligamento cruzado anterior."},{"id":"sever-calcaneal-apophysitis","area":"Pediátrica","front":"Sever\n\nQuais são os critérios dessa classificação?\n(Doença de Sever (apofisite calcânea))","back":"• Faixa etária — 9 a 14 anos, envolvidos em esportes de corrida.\n• Apresentação — Bilateral na maioria dos casos; dor difusa e sensibilidade sobre a proeminência do calcanhar (não restrita à face plantar como na fasceíte plantar).\n• Radiografia — Normal; diagnóstico é clínico.\n• Tratamento — Repouso, modificação de atividade, gelo, AINEs orais, alongamento do tendão calcâneo e da fáscia plantar, palmilhas; imobilização gessada raramente necessária em casos incapacitantes."},{"id":"stress-fracture-fatigue-insufficiency","area":"Pediátrica","front":"—\n\nQuais são os critérios dessa classificação?\n(Classificação das fraturas por estresse: fadiga versus insuficiência)","back":"• Fratura por fadiga — Estresse anormal repetitivo aplicado a osso normal; forma mais comum em atletas jovens (corrida, saltos).\n• Fratura por insuficiência — Estresse normal aplicado a osso anormal; menos comum em atletas.\n• Locais mais acometidos — Tíbia proximal, colo femoral, diáfise femoral/metáfise distal do fêmur, maléolo medial e metatarsais."},{"id":"stress-fracture-risk-site-classification","area":"Pediátrica","front":"Alto/baixo risco\n\nQuais são os critérios dessa classificação?\n(Fraturas por estresse de alto risco versus baixo risco (localização))","back":"• Diáfise femoral (baixo risco) — Baixo risco de não união/deslocamento; tratada com modificação de atividade.\n• Colo femoral, lado de tensão superior (alto risco) — Alto risco de não união/deslocamento e necrose avascular; tratamento cirúrgico recomendado (parafusos de compressão canulados).\n• Tíbia, lado de compressão posteromedial (baixo risco) — Fratura mais comum e de baixo risco; cicatriza em 4-6 semanas com bota pneumática.\n• Tíbia, lado de tensão anterior (alto risco) — Região hipovascular, risco de retardo/não união; pode requerer cirurgia (banda de tensão) se não cicatrizar em 6 meses de tratamento conservador.\n• Maléolo medial, navicular társico e 5º metatarso (alto risco) — Maior taxa de falha do tratamento não operatório; fr..."},{"id":"shin-splints-mtss-vs-stress-fracture","area":"Pediátrica","front":"MTSS\n\nQuais são os critérios dessa classificação?\n(Diferenciação entre síndrome do estresse tibial medial (\"canelite\") e fratura por estresse)","back":"• Localização da dor na MTSS — Borda posteromedial da tíbia, na junção do terço proximal com o terço distal, sem dor na borda subcutânea da tíbia.\n• Cintilografia óssea na MTSS — Captação aumentada em padrão longitudinal ao longo da cortical posteromedial da tíbia.\n• Cintilografia óssea na fratura por estresse tibial — Captação aumentada em padrão transverso.\n• RM na fratura por estresse — Área bandeada de sinal muito baixo na região intramedular, contínua com o córtex, com diminuição de sinal em T1 na medular."},{"id":"stress-physeal-reaction-upper-extremity","area":"Pediátrica","front":"—\n\nQuais são os critérios dessa classificação?\n(Reação fisária de estresse do membro superior no atleta (punho do ginasta e ombro do arremessador jovem))","back":"• Fise radial distal (punho do ginasta) — Radiolucência e irregularidade no lado metafisário da fise por carga compressiva repetitiva (solo e salto); achados radiográficos em até 85% dos ginastas competitivos esqueleticamente imaturos.\n• Variância ulnar positiva — Associada a fechamento fisário prematuro por sobrecarga compressiva repetitiva; predispõe a lesão do complexo fibrocartilaginoso triangular e impacto ulnar.\n• Fise umeral proximal (ombro do arremessador jovem/\"Little League shoulder\") — Alargamento e irregularidade da fise proximal do úmero em jovens lançadores de beisebol.\n• Tratamento — Interrupção da força ofensora por 2-3 meses (arremesso ou carga no punho), seguida de fortalecimento específico (flexores do punho no ginasta..."},{"id":"little-league-elbow-spectrum","area":"Pediátrica","front":"\"Thrower elbow\"\n\nQuais são os critérios dessa classificação?\n(Espectro do cotovelo do arremessador jovem (\"Little League elbow\"/\"thrower elbow\"))","back":"• Apofisite do epicôndilo medial — Microfraturas de tração na cartilagem apofisária medial, análogas à OSD.\n• Osteocondrite dissecante do capítulo — Lesão compressiva lateral (radiocapitelar), diferenciada da doença de Panner.\n• Deformação da cabeça do rádio — Alteração compressiva lateral crônica.\n• Apofisite do olécrano — Estresse de tração posterior por extensão repetitiva forçada.\n• Contratura em flexão — Consequência crônica do espectro de sobrecarga em valgo/compressão."},{"id":"medial-epicondyle-apophysitis-avulsion","area":"Pediátrica","front":"—\n\nQuais são os critérios dessa classificação?\n(Apofisite e avulsão do epicôndilo medial: critério de deslocamento para tratamento)","back":"• Apofisite (sem avulsão franca) — Dor pontual sobre o epicôndilo medial, piora com estresse em valgo ou flexão/pronação resistida do punho; radiografia pode ser normal ou mostrar fragmentação/alargamento fisário. Tratamento: repouso, gelo, AINEs, retorno gradual em 6-12 semanas.\n• Avulsão deslocada ≤ 5 mm — Tratamento com imobilização gessada.\n• Avulsão deslocada > 5 mm (atleta arremessador ou ginasta) — Indicação de fixação cirúrgica com parafuso canulado (não precisa transfixar a cortical oposta), permitindo mobilização precoce."},{"id":"capitellar-ocd-panner-differentiation","area":"Pediátrica","front":"—\n\nQuais são os critérios dessa classificação?\n(Diferenciação entre doença de Panner e osteocondrite dissecante do capítulo)","back":"• Doença de Panner — Ocorre em crianças menores de 10 anos, atraumática, provavelmente variação da ossificação (não OCD verdadeira), autolimitada e com resolução espontânea.\n• OCD do capítulo — Idade de apresentação ≥ 10 anos, envolvimento incompleto do capítulo, formação de corpos livres e curso clínico prolongado.\n• Perfil demográfico — Maioria dos pacientes com OCD do capítulo são meninos praticantes de beisebol e meninas ginastas.\n• Achado radiográfico característico — \"Sinal do crescente\" (crescent sign) — zona semilunar rarefeita na face ântero-distal do capítulo."},{"id":"pitch-count-guidelines-little-league","area":"Pediátrica","front":"Little League Baseball\n\nQuais são os critérios dessa classificação?\n(Diretrizes de contagem de arremessos por idade no beisebol juvenil)","back":"• ≤ 10 anos — Máximo de 75 arremessos por dia (diretriz Little League Baseball, 2010).\n• 11-12 anos — Máximo de 85 arremessos por dia.\n• 13-16 anos — Máximo de 95 arremessos por dia.\n• 17-18 anos — Máximo de 105 arremessos por dia."},{"id":"acl-reconstruction-technique-skeletal-maturity","area":"Pediátrica","front":"Tanner/idade óssea\n\nQuais são os critérios dessa classificação?\n(Seleção da técnica de reconstrução do LCA conforme a maturidade esquelética (estágio de Tanner))","back":"• Tanner 1-2 (pré-púbere) — Idade óssea usualmente < 14 anos (meninos) ou < 13 anos (meninas), grande crescimento remanescente; reconstrução poupadora da fise (physeal-sparing), com técnica combinada intra e extra-articular (modificação de MacIntosh com banda iliotibial) ou túneis totalmente epifisários.\n• Tanner 3-4 (adolescente) — Crescimento significativo remanescente; reconstrução transfisária convencional com enxerto autólogo de isquiotibiais.\n• Tanner 5 (maturidade esquelética) — Tratado como adulto (reconstrução transfisária padrão).\n• Instabilidade rotatória lateral/hiperfrouxidão/slope tibial posterior aumentado — Considerar aumento extra-articular associado (reconstrução do ligamento anterolateral ou tenodese extra-articular la..."},{"id":"terrible-triad-miserable-malalignment","area":"Pediátrica","front":"—\n\nQuais são os critérios dessa classificação?\n(Desalinhamento rotacional do membro inferior predisponente a dor anterior do joelho e fraturas por estresse (\"tríade terrível\" / \"miserable malalignment\"))","back":"• \"Tríade terrível\" (fraturas por estresse) — Anteversão femoral, genu valgo e pé plano — fator predisponente a lesões por sobrecarga do compartimento patelofemoral e das pernas.\n• \"Miserable malalignment\" (dor anterior de joelho idiopática) — Torção femoral interna excessiva, torção tibial externa, genu valgo leve com desvio medial da patela e tendência a pé plano/pronação.\n• Achados de exame associados — Atrofia de quadríceps, crepitação patelar, patela hipermóvel com sinais de maltracking (sem luxação/subluxação franca); avaliação deve incluir ângulo Q, tilt lateral e rastreamento patelar."},{"id":"salter-harris-classificacao-fisaria","area":"Pediátrica","front":"SH\n\nQuais são os critérios dessa classificação?\n(Classificação de Salter-Harris das Fraturas Fisárias)","back":"• Tipo I — Separação transepifisária completa através de toda a fise, sem fragmento metafisário. Comum em lactentes/crianças pequenas; pode ser não ou minimamente deslocada, dificultando o diagnóstico.\n• Tipo II — Cerca de 75% das fraturas fisárias. A linha atravessa parte da fise e sai por um segmento da metáfise, formando o fragmento de Thurston-Holland (lado da compressão).\n• Tipo III — Fratura vertical intra-articular: atravessa parte da fise e sai pela epífise até a superfície articular.\n• Tipo IV — Linha vertical intra-articular que cruza todas as zonas: metáfise, fise e epífise/superfície articular. Maior risco de ponte óssea por lesão de condrócitos de repouso.\n• Tipo V — Lesão de esmagamento (crush) da fise por carga axial; rara..."},{"id":"peterson-tipo-i-fisaria","area":"Pediátrica","front":"Peterson I\n\nQuais são os critérios dessa classificação?\n(Fratura Fisária Tipo Peterson I (variante metafisária paralela à fise))","back":"• Definição — Fratura metafisária adjacente e paralela à fise, com extensão ramificada que toca a fise (Ham Peterson, revisão da classificação de fraturas fisárias).\n• Frequência — Provavelmente o tipo mais comum de fratura fisária, respondendo por pelo menos 15% de todas as fraturas que envolvem a fise.\n• Risco de distúrbio de crescimento — É o tipo com MENOR probabilidade de causar distúrbio do crescimento: apenas cerca de 5% evoluem com perturbação fisária.\n• Utilidade clínica — Referência útil para orientar a conversa de prognóstico com a família, por representar o extremo de baixo risco entre as lesões fisárias."},{"id":"estruturas-biomecanicas-fise","area":"Pediátrica","front":"Fise\n\nQuais são os critérios dessa classificação?\n(Determinantes Biomecânicos da Estabilidade da Fise (Cartilagem de Crescimento))","back":"• Zona de calcificação provisória — Zona mais fraca da fise sob estresse mecânico em estudos animais; local predominante das fraturas fisáticas experimentais, embora microfraturas também ocorram na zona germinativa. Em humanos, a maioria das fraturas fisárias ocorre pela zona de células hipertróficas.\n• Topografia não planar — Fises onduladas (ex.: fêmur distal) e processos mamilares aumentam a resistência ao cisalhamento.\n• Formações \"lappet\" — Contornos em taça nos quais a fise se sobrepõe à metáfise adjacente (ex.: tíbia proximal), reforçando a periferia fisária.\n• Sulco de Ranvier / Anel de Lacroix — Estruturas microscópicas periféricas (células de repouso e proliferação / cartilagem contígua ao periósteo metafisário) que contribuem ..."},{"id":"fraturas-incompletas-crianca","area":"Pediátrica","front":"Incompletas\n\nQuais são os critérios dessa classificação?\n(Classificação das Fraturas Incompletas Exclusivas/Predominantes da Criança)","back":"• Deformidade plástica — Falha microscópica interna do osso (disrupção das junções entre osteons) por força de flexão além do limite elástico, sem linha de fratura visível — apenas angulação na radiografia. Mínimo edema e hematoma.\n• Fratura em galho verde (greenstick) — Falha completa do lado de tensão da diáfise com deformidade plástica persistente do lado côncavo/compressivo; ocorre quando o limite da deformidade plástica é excedido.\n• Fratura em torus/buckle — Falha em compressão da fina cortical metafisária na transição metáfise-diáfise por carga axial; mais comum no rádio distal, mas também no fêmur distal, tíbia proximal e úmero proximal. Sem edema de partes moles significativo (hematoma contido).\n• Fratura por estresse — Fratura ..."},{"id":"padroes-fratura-diafisaria-mecanismo","area":"Pediátrica","front":"Padrão-Mecanismo\n\nQuais são os critérios dessa classificação?\n(Padrões de Fratura Diafisária Conforme o Mecanismo de Lesão)","back":"• Força torcional — Resulta em fratura espiral.\n• Força de momento perpendicular — Resulta em fratura transversa.\n• Força compressiva longitudinal (carga axial) — Resulta em fratura oblíqua.\n• Combinação compressão + momento — Resulta em padrão \"borboleta\" (butterfly), de maior energia.\n• Instabilidade ao encurtamento — Os padrões oblíquo e borboleta podem ser instáveis ao encurtamento (length unstable), tornando a manutenção do comprimento em gesso mais difícil, por vezes exigindo fixação."},{"id":"principios-reducao-fratura-por-padrao","area":"Pediátrica","front":"Redução\n\nQuais são os critérios dessa classificação?\n(Princípios de Redução Fechada Conforme o Padrão de Fratura)","back":"• Princípio geral — Recriar o mecanismo de lesão para desimpactar o periósteo interposto, seguido de reversão do mecanismo para realinhar a fratura, usando a dobradiça de periósteo intacto para estabilizar.\n• Fraturas espirais/em galho verde — Reduzidas revertendo a rotação; a faixa longitudinal de periósteo intacto geralmente confere estabilidade suficiente para imobilização gessada isolada.\n• Fraturas transversas — O periósteo intacto do lado de compressão pode se interpor no foco; redução seguida de moldagem em três pontos do gesso mantém melhor a redução.\n• Fraturas oblíquas/borboleta — Instabilidade ao encurtamento torna a manutenção do comprimento em gesso mais difícil; fixação cirúrgica é por vezes necessária."},{"id":"fatores-capacidade-remodelacao-ossea","area":"Pediátrica","front":"Remodelação\n\nQuais são os critérios dessa classificação?\n(Fatores que Determinam a Capacidade de Remodelação Óssea Pediátrica)","back":"• Proximidade da fise — A capacidade de remodelação é maior quanto mais próxima a fratura estiver de uma fise ativa.\n• Plano de movimento articular — A remodelação é mais confiável quando a angulação residual está no plano de movimento da articulação mais próxima.\n• Crescimento remanescente — A remodelação praticamente não ocorre em crianças com menos de 2 anos de crescimento esquelético restante.\n• Mecanismos — Ocorre por \"bone drift\" (reabsorção na convexidade/deposição na concavidade da deformidade) e, principalmente, por crescimento longitudinal assimétrico e reorientação da fise.\n• Janela temporal — A remodelação pode continuar por 5 a 6 anos após a consolidação; deformidades angulares graves e más-rotações remodelam de forma menos ..."},{"id":"estimulo-crescimento-simetrico-assimetrico","area":"Pediátrica","front":"Overgrowth\n\nQuais são os critérios dessa classificação?\n(Estímulo de Crescimento Simétrico (Overgrowth) e Assimétrico Pós-Fratura)","back":"• Overgrowth simétrico — Mais comum após fraturas diafisárias do fêmur em crianças de 2 a 10 anos, com média de 0,9 cm (variação de 0,4 a 2,4 cm) de sobrecrescimento.\n• Mecanismo proposto — Perda de tensão periosteal e aumento do fluxo sanguíneo (hiperemia) para a fise do osso fraturado; secção transversa do periósteo próximo à fise reproduz overgrowth experimentalmente.\n• Overgrowth assimétrico — Menos comum; exemplo clássico é a fratura incompleta da metáfise tibial proximal evoluindo com deformidade em valgo entre 1 e 2 anos após a lesão.\n• Etiologia do valgo pós-fratura tibial proximal — Hiperemia assimétrica (maior fluxo sanguíneo medial que lateral, demonstrado por Ogden) somada a tensão periosteal assimétrica contralateral ao foco..."},{"id":"tecnicas-analgesia-sedacao-reducao-fratura","area":"Pediátrica","front":"Analgesia\n\nQuais são os critérios dessa classificação?\n(Técnicas de Analgesia e Sedação para Redução de Fraturas na Emergência Pediátrica)","back":"• Bloqueio de hematoma — Infiltração do hematoma da fratura com lidocaína 1-2% (máx. 3-5 mg/kg), técnica de barbotagem; ineficaz em galho-verde, fraturas fisárias (fise como barreira) ou apresentações tardias (hematoma coagulado). Não injetar >10 mL no punho (risco de síndrome do túnel do carpo).\n• Anestesia regional intravenosa (IVRA/Bier) — Usada em ~20% dos centros pediátricos para fraturas de antebraço; analgesia satisfatória em ~90% dos casos. Manter o torniquete insuflado por pelo menos 20 minutos após a redução para evitar toxicidade sistêmica por lidocaína.\n• Bloqueio axilar (plexo braquial) — Analgesia equivalente à sedação, duração de até 4 horas, permitindo reduções repetidas; menos utilizado na emergência por exigir treinamen..."},{"id":"indice-gessado-cast-index","area":"Pediátrica","front":"Cast Index\n\nQuais são os critérios dessa classificação?\n(Índice de Gesso (Cast Index) para Fraturas do Rádio Distal)","back":"• Definição — Razão entre o diâmetro sagital e o diâmetro coronal do gesso, medidos no foco de fratura em radiografias AP e lateral do antebraço engessado (Chess et al.).\n• Valor ideal — Índice de gesso de 0,7 (gesso ovalado) mantém melhor a redução comparado a gessos mais circulares (índices mais altos).\n• Limiar de risco — Índice de gesso <0,8 correlaciona-se com manutenção confiável da redução de fraturas do rádio distal.\n• Técnica associada — Moldagem em três pontos ao redor do foco de fratura, gesso ovalado com borda lateral achatada ao longo da borda subcutânea da ulna."},{"id":"indicacoes-tala-vs-gesso","area":"Pediátrica","front":"Tala/Gesso\n\nQuais são os critérios dessa classificação?\n(Indicações de Tala (Splint) versus Gesso Circular na Imobilização Pediátrica)","back":"• Edema importante — Lesões com edema significativo dos membros favorecem tala em vez de gesso circular fechado.\n• Lesões cutâneas — Lacerações, abrasões ou erupções cutâneas favorecem imobilização com tala.\n• Comunicação prejudicada — Crianças com traumatismo craniano ou incapacidade de comunicar dor/desconforto — tala é mais segura.\n• Pele insensível — Ex.: espinha bífida — risco aumentado de lesão cutânea não percebida sob gesso fechado.\n• Vantagem da tala — Aplicação rápida, permite edema do membro com menor risco de constrição, ruptura de pele e síndrome compartimental."},{"id":"glasgow-pediatric-trauma-score-politrauma","area":"Pediátrica","front":"GCS/PTS\n\nQuais são os critérios dessa classificação?\n(Escala de Coma de Glasgow e Pediatric Trauma Score na Avaliação Inicial do Politraumatizado)","back":"• Escala de Coma de Glasgow (GCS) — Avalia clinicamente a função cortical; GCS <8 indica risco de desfecho ruim, incluindo lesão neurológica permanente e óbito.\n• Momento de maior valor preditivo — O escore obtido em 72 horas após a lesão é o mais preditivo de comprometimento permanente.\n• Pediatric Trauma Score (PTS) — Ferramenta de triagem eficaz e preditor confiável de gravidade da lesão.\n• Limitação do PTS — Atribui o mesmo peso a uma fratura de metacarpo exposta e a uma fratura de fêmur exposta, uma limitação reconhecida da ferramenta."},{"id":"damage-control-orthopaedics-dco","area":"Pediátrica","front":"DCO\n\nQuais são os critérios dessa classificação?\n(Indicações de Damage Control Orthopaedics (DCO) no Politraumatizado Pediátrico)","back":"• Conceito — Fixação/imobilização esquelética limitada de emergência para permitir a estabilização cardiopulmonar, com manejo ortopédico definitivo adiado (geralmente dias após), reduzindo o \"segundo hit\" fisiológico.\n• Indicação 1 — Lesão craniana grave com pressão intracraniana >30 mmHg não controlada por manejo clínico.\n• Indicação 2 — Hipotermia profunda, acidose metabólica ou coagulopatia que não tolerariam tempo anestésico prolongado, especialmente com perda sanguínea moderada esperada.\n• Indicação 3 — Cirurgia extensa de madrugada quando a equipe diurna é mais familiarizada com o procedimento, ou falta de expertise emergencial disponível.\n• Janela de segurança — Um atraso no tratamento definitivo de até 6 dias raramente tem efeito..."},{"id":"mangled-extremity-severity-score","area":"Pediátrica","front":"MESS\n\nQuais são os critérios dessa classificação?\n(Mangled Extremity Severity Score na Decisão de Salvamento de Membro)","back":"• Utilidade — Auxilia o cirurgião nas decisões imediatas de manejo relacionadas ao salvamento de membro em fraturas graves de ossos longos com comprometimento neurovascular.\n• Contexto de uso — Aplicado no momento da admissão do politraumatizado, junto ao tratamento emergencial limitado de fraturas em risco de comprometimento neurovascular.\n• Manejo provisório — Enquanto se aguarda a decisão definitiva, utiliza-se fixação externa provisória, tala ou tração cutânea das fraturas instáveis de ossos longos."},{"id":"gustilo-anderson-mendoza-fraturas-expostas-crianca","area":"Pediátrica","front":"GA-Mendoza\n\nQuais são os critérios dessa classificação?\n(Classificação de Gustilo-Anderson Modificada por Mendoza para Fraturas Expostas em Crianças)","back":"• Grau I — Ferida <1 cm, contaminação mínima, pouca lesão de partes moles/periósteo.\n• Grau II — Ferida entre 1 e 10 cm, com grau moderado de lesão de partes moles/estripamento periosteal.\n• Grau III (A/B/C) — Lesão extensa de partes moles e/ou periósteo, com (IIIA) cobertura óssea adequada apesar da lesão extensa, (IIIB) perda de partes moles exigindo retalho, ou (IIIC) lesão vascular associada exigindo reparo.\n• Critério de graduação — O grau é determinado pelo tamanho absoluto da ferida e pelo grau de descolamento periosteal e de partes moles — mesmo feridas pequenas podem ter alta contaminação por serem de alta energia.\n• Correlação com infecção — Risco de infecção de até 3% nos graus 1 e 2, e de até 10% no grau 3, quando antibiótico..."},{"id":"classificacao-fraturas-patologicas","area":"Pediátrica","front":"Patológicas\n\nQuais são os critérios dessa classificação?\n(Classificação das Fraturas Patológicas na Criança)","back":"• Tipo 1 — Lesão óssea local isolada — Deficiência ou fraqueza estrutural de uma lesão isolada, como cisto ósseo simples, fibroma não ossificante, osteomielite prévia, fratura por estresse preexistente ou ao redor/após remoção de implante.\n• Tipo 1 — Etiologia rara — Tumores malignos primários (osteossarcoma, sarcoma de Ewing) e metástases ósseas.\n• Tipo 2 — Condição sistêmica — Fratura secundária a doença que enfraquece todo o esqueleto, como osteogênese imperfeita ou osteodistrofia renal.\n• Sinal de alerta clínico — Alto índice de suspeita quando há dor prévia à fratura ou mecanismo de lesão incompatível com o padrão radiográfico observado.\n• Conduta geral — Lesões benignas geralmente tratadas após a consolidação da fratura; suspeita d..."},{"id":"cisto-osseo-simples-indicacao-enxerto","area":"Tumor","front":"UBC\n\nQuais são os critérios dessa classificação?\n(Cisto Ósseo Simples (Unicameral) — Indicações de Enxerto Ósseo Após Fratura)","back":"• Achado radiográfico — Cavidade central bem definida e irregular com pequenos septos e, ocasionalmente, fragmentos ósseos finos (\"fallen leaf sign\") — patognomônico de fratura através de cisto ósseo simples.\n• Evolução natural — A maioria das fraturas consolida com tratamento conservador, mas a resolução espontânea do cisto é incomum.\n• Indicação de enxerto — diâmetro — Diâmetro transverso do cisto ocupando mais de 85% do diâmetro ósseo.\n• Indicação de enxerto — cortical — Espessura cortical residual menor que 5 mm."},{"id":"fibroma-nao-ossificante-defeito-cortical-fibroso","area":"Tumor","front":"FNO/FCD\n\nQuais são os critérios dessa classificação?\n(Fibroma Não Ossificante e Defeito Cortical Fibroso — Risco de Fratura)","back":"• Achado típico — Lesões fibrosas benignas comuns, geralmente diagnosticadas incidentalmente; defeitos corticais fibrosos são histologicamente semelhantes mas menores e de localização mais excêntrica (cortical).\n• Risco de fratura — Fraturas ocorrem sobretudo quando o defeito ósseo é grande, especialmente ocupando 50% ou mais do diâmetro cortical transverso do osso, em fraturas de membro inferior.\n• Conduta habitual — Tratamento fechado da fratura é eficaz na maioria dos pacientes; poucos necessitam enxerto ósseo posterior.\n• Aconselhamento — Pacientes/famílias com lesões maiores podem ser orientados sobre o risco de fratura e a opção de curetagem e enxertia profilática."},{"id":"osteogenese-imperfeita-fraturas","area":"Pediátrica","front":"OI\n\nQuais são os critérios dessa classificação?\n(Osteogênese Imperfeita — Considerações no Manejo de Fraturas)","back":"• Incidência — Identificada em 1 a cada 20.000 crianças; frequentemente se apresenta como fratura única ou múltipla.\n• Diagnóstico diferencial — Em lactente com múltiplas fraturas, maus-tratos infantis deve sempre ser considerado no diagnóstico diferencial.\n• Educação familiar — Kit de imobilização domiciliar é útil; nem toda fratura requer avaliação de emergência ou gesso.\n• Risco do gesso prolongado — Imobilização e gesso podem aumentar o risco de futuras fraturas por osteopenia por desuso, agravando a doença metabólica de base."},{"id":"fraturas-doencas-neuromusculares","area":"Pediátrica","front":"Neuromuscular\n\nQuais são os critérios dessa classificação?\n(Fraturas em Crianças com Doenças Neuromusculares — Incidência e Fatores de Risco)","back":"• Paralisia cerebral (PC) — Incidência de fraturas de 10% a 15%; quase 50% dos pacientes não deambuladores desenvolvem fraturas espontâneas.\n• Mielodisplasia — nível torácico — 41% dos pacientes com nível motor torácico sofrem fraturas.\n• Mielodisplasia — nível lombar baixo/sacral — Apenas 13% dos pacientes com déficit lombar baixo ou sacral sofrem fraturas.\n• Lesão medular — Junto à mielodisplasia, chega a 30% de incidência de fraturas — quanto pior o nível de função motora, maior o risco.\n• Momento de maior risco — Três quartos das fraturas nesses pacientes ocorrem nas primeiras semanas após imobilização gessada (por outra cirurgia/fratura), refletindo a osteopenia por desuso."},{"id":"sinais-radiograficos-maus-tratos","area":"Pediátrica","front":"Red Flags\n\nQuais são os critérios dessa classificação?\n(Achados Radiográficos e Clínicos Sugestivos de Maus-Tratos Infantis (Child Abuse))","back":"• Fratura metafisária em \"alça de balde\"/\"canto\" — Considerada patognomônica de trauma abusivo.\n• Fraturas de costela — Especialmente as posteriores; múltiplas fraturas de costela em criança ≤3 anos tiveram valor preditivo positivo de 100% para maus-tratos quando excluídos acidente ou doença conhecidos.\n• Fratura de crânio complexa — Altamente sugestiva de lesão intencional, principalmente se o mecanismo relatado for trivial (ex.: queda do sofá).\n• Idade e mobilidade — Fratura espiral diafisária isolada de tíbia/fêmur é comum em acidentes de crianças que andam, mas é suspeita se a criança ainda não anda (\"cruising\")/deambula.\n• Discordância história-lesão — Lesão que não corresponde à história relatada, apresentação tardia (dias após o e..."},{"id":"datacao-radiografica-fraturas-maus-tratos","area":"Pediátrica","front":"Datação\n\nQuais são os critérios dessa classificação?\n(Datação Radiográfica da Consolidação Óssea (Estadiamento de Fraturas em Suspeita de Abuso))","back":"• 5 a 7 dias — Primeira formação de osso subperiosteal novo.\n• 10 a 14 dias — Indistinção ou reabsorção da linha de fratura.\n• 2 a 3 semanas — Início da formação de calo mole.\n• ≥6 semanas — Calcificação mais avançada e remodelação, com variabilidade individual.\n• Linhas de Harris-Park — Linhas de parada de crescimento cuja distância até a fise adjacente ajuda a datar lesões antigas, assim como comparação da quantidade de calo entre fraturas do mesmo paciente."},{"id":"equipe-multidisciplinar-maus-tratos","area":"Pediátrica","front":"Equipe-Abuso\n\nQuais são os critérios dessa classificação?\n(Avaliação Multidisciplinar da Suspeita de Maus-Tratos Infantis)","back":"• Pediatra especialista em abuso — Lidera a equipe multidisciplinar de avaliação.\n• Ortopedista + radiologista pediátrico — Revisão do levantamento esquelético e demais imagens.\n• Oftalmologista pediátrico — Exame de retina em busca de retinopatia hemorrágica e outros sinais de abuso.\n• Cirurgia pediátrica e neurocirurgia — Avaliação de trauma abdominal e revisão de TC/RM de crânio, quando suspeita de lesão craniana.\n• Geneticista pediátrico — Auxilia a descartar etiologias alternativas para as lesões observadas."},{"id":"risco-infeccao-fratura-exposta-grau","area":"Pediátrica","front":"Infecção-GA\n\nQuais são os critérios dessa classificação?\n(Risco de Infecção Pós-Fratura Exposta Conforme o Grau de Gustilo-Anderson)","back":"• Graus 1 e 2 — Infecção em até 3% dos casos.\n• Grau 3 — Infecção em até 10% dos casos.\n• Fator não determinante — O tempo de desbridamento cirúrgico (<6h vs ≥7h) não alterou a taxa de infecção quando antibióticos IV foram administrados imediatamente na emergência.\n• Local mais afetado — Fraturas expostas de tíbia são as que mais frequentemente desenvolvem infecção em crianças."},{"id":"nao-uniao-crianca","area":"Pediátrica","front":"Não-União\n\nQuais são os critérios dessa classificação?\n(Não União (Nonunion) de Fraturas em Crianças — Sítios e Fatores de Risco)","back":"• Raridade — Não união é rara em crianças, sobretudo após fraturas fechadas.\n• Ossos mais acometidos — Tíbia, fêmur, ulna, úmero, rádio e fíbula.\n• Fatores de risco — Fraturas expostas com grande lesão de partes moles, infecção, estabilização inadequada e manipulações repetidas.\n• Exemplo clássico — Não união do côndilo lateral do cotovelo é complicação bem reconhecida, mais comum quando fraturas instáveis são tratadas apenas com imobilização gessada; RAFI melhora, mas não garante, a consolidação.\n• Conduta — Tratamento individualizado; após excluir infecção, exige remoção do tecido fibroso interposto, enxertia óssea e fixação estável — a maioria das não uniões pediátricas é do tipo hipertrófica."},{"id":"sindrome-compartimental-criterios-diagnosticos","area":"Pediátrica","front":"SCA\n\nQuais são os critérios dessa classificação?\n(Síndrome Compartimental Aguda na Criança — Critérios Diagnósticos)","back":"• Os \"três As\" pediátricos — Dor crescente que exige doses crescentes de analgésico (Analgesia), associada a Ansiedade (Anxiety) e Agitação (Agitation) — sinal mais confiável em crianças, já que o exame sensitivomotor clássico do adulto é pouco confiável nesta faixa etária.\n• Achados tardios — Diminuição do enchimento capilar e ausência de pulso são manifestações tardias, não devendo ser aguardadas para o diagnóstico.\n• Pressão intracompartimental — Pressão >30 mmHg, ou dentro de 30 mmHg da pressão diastólica do paciente, é indicação de fasciotomia descompressiva emergencial.\n• Janela de isquemia — Lesão irreversível aos tecidos começa entre 4 e 6 horas do início da pressão anormal.\n• Sítios mais comuns — Perna (associada a fratura diafi..."},{"id":"fasciotomia-abordagens-antebraco-perna","area":"Pediátrica","front":"Fasciotomia\n\nQuais são os critérios dessa classificação?\n(Vias de Acesso para Fasciotomia Descompressiva no Antebraço e na Perna)","back":"• Abordagem volar de Henry — Incisão cruzando a prega do cotovelo até a palma pela eminência tenar; libera compartimento superficial e, com retração do FCR ulnarmente, o compartimento flexor profundo.\n• Abordagem volar-ulnar (McConnell modificada) — Incisão ao longo da borda ulnar do antebraço; mais direta para o compartimento flexor profundo, retraindo nervo e artéria ulnares.\n• Fasciotomia da perna — incisão única — Pode descomprimir os quatro compartimentos sem necessidade de excisão da fíbula.\n• Fasciotomia da perna — dupla incisão — Permite acesso mais direto ao compartimento posterior profundo; abordagem preferida para confirmação visual de todos os compartimentos.\n• Desbridamento — Tecido muscular desvitalizado é debridado quando ..."},{"id":"classificacao-barra-fisaria-peterson","area":"Pediátrica","front":"Barra Fisária\n\nQuais são os critérios dessa classificação?\n(Classificação das Pontes (Barras) Fisárias Pós-Traumáticas)","back":"• Tipo I — Barra periférica — Tipo mais comum; produz deformidade angular.\n• Tipo II — Barra central — Atua como tether central ao crescimento; pequenos defeitos centrais podem ter pouca repercussão clínica, mas grandes defeitos causam \"tenting\" da fise e distorção da superfície articular.\n• Tipo III — Barra linear/combinada — Envolve uma faixa estreita do centro e da periferia da fise, geralmente ao longo de uma linha de fratura antiga (ex.: SH IV mal consolidado); causa distorção articular e deformidade angular.\n• Comparação de gravidade — Barras periféricas tendem a produzir maiores deformidades que barras centrais de tamanho equivalente, pela localização.\n• Diagnóstico por imagem — RM com sequência gradiente-eco 3D suprimida em gordu..."},{"id":"tratamento-parada-fisaria-completa-discrepancia","area":"Pediátrica","front":"Parada Completa\n\nQuais são os critérios dessa classificação?\n(Conduta na Parada Fisária Completa Conforme a Discrepância de Comprimento Projetada)","back":"• <2 cm ao final do crescimento — Nenhum tratamento necessário.\n• 2 a 5 cm — Palmilhas/calços são opção não cirúrgica; epifisiodese contralateral é a melhor opção cirúrgica se restarem pelo menos 2 anos de crescimento.\n• Próximo à maturidade esquelética — Encurtamento do segmento ósseo longo contralateral pode ser considerado para discrepâncias de fêmur/tíbia.\n• >5 cm — Alongamento ósseo é a melhor estratégia de manejo.\n• Membro superior — Discrepância de comprimento raramente requer tratamento por ter poucas repercussões funcionais; no antebraço, epifisiodese ou encurtamento ulnar pode aliviar dor ulnar do punho por desequilíbrio rádio-ulnar."},{"id":"tratamento-parada-fisaria-parcial-ressecao-barra","area":"Pediátrica","front":"Parada Parcial\n\nQuais são os critérios dessa classificação?\n(Critérios para Ressecção de Barra Fisária na Parada de Crescimento Parcial)","back":"• Extensão da barra — Ressecção geralmente indicada quando menos de 50% da fise está em ponte.\n• Deformidade angular — Indicada quando a deformidade angular é menor que 20 graus.\n• Crescimento remanescente — A criança deve ter pelo menos 2 anos de crescimento esquelético restante.\n• Sem deformidade estabelecida — Se diagnosticada antes do desenvolvimento de deformidade angular, tratamento mais simples é completar a parada por epifisiodese (associada a osteotomia se já houver deformidade e/ou epifisiodese contralateral/alongamento se LLD significativa prevista).\n• Distração fisária — Técnica alternativa que supera a barra (associada a correção gradual de angulação), viável se a barra afeta menos de 40% da fise; pouco utilizada por dor, ri..."},{"id":"clavicula-diafise-conduta","area":"Pediátrica","front":"CLAV-D\n\nQuais são os critérios dessa classificação?\n(Fratura de Diáfise da Clavícula — Conduta)","back":"• Tratamento padrão — Suporte com tipoia ou bandagem em oito; redução não é tentada na maioria dos casos.\n• Retorno ao esporte — Evitar esportes por aproximadamente 8 semanas; consolidação rápida é a regra.\n• Indicações cirúrgicas — Fratura exposta, desvio extremo com extremidade óssea impactada através do trapézio, tenda cutânea irredutível.\n• Adolescentes próximos da maturidade — Conduta cirúrgica considerada se desvio >100% ou encurtamento >2 cm, especialmente em atletas arremessadores no lado dominante.\n• Prognóstico — Bossa residual (calo) remodela ao longo de meses a anos, independentemente do alinhamento."},{"id":"clavicula-medial-fise-luxacao","area":"Pediátrica","front":"EC-MED\n\nQuais são os critérios dessa classificação?\n(Fratura Fisária Medial da Clavícula / Luxação Esternoclavicular)","back":"• Fisiologia — Centro de ossificação medial aparece aos 17 anos; a fise só fecha entre 20-25 anos — desvios são geralmente separações fisárias, não luxação articular verdadeira.\n• Desvio anterior/superior — Tratamento não operatório na maioria dos casos.\n• Desvio posterior — Risco de compressão de estruturas mediastinais (disfagia, compromisso respiratório) — indicação de tratamento cirúrgico.\n• Diagnóstico — Exame físico e radiografia simples são pouco confiáveis; TC é o melhor método para avaliar o desvio.\n• Redução fechada — Deve ser tentada em até 48 horas do trauma para ser mais efetiva nos casos posteriores."},{"id":"clavicula-lateral-ac-classificacao","area":"Pediátrica","front":"AC-I-VI\n\nQuais são os critérios dessa classificação?\n(Lesão da Clavícula Lateral / Separação Acromioclavicular — Graus I a VI)","back":"• Graus I-III — Entorse a subluxação/luxação leve a moderada dos ligamentos acromioclavicular e coracoclavicular; tratamento conservador com tipoia por 3 semanas.\n• Grau III completo — Clavícula permanece proeminente, mas geralmente assintomática; conservador mesmo em atletas competitivos.\n• Grau IV — Clavícula desviada posteriormente através da fáscia do trapézio — redução aberta e estabilização recomendadas.\n• Grau V — Desvio superior de 100% a 300%, clavícula subcutânea — cirurgia recomendada.\n• Grau VI — Clavícula desviada inferiormente sob o acrômio ou coracoide — cirurgia recomendada."},{"id":"escapula-fratura-conduta","area":"Pediátrica","front":"ESCAP\n\nQuais são os critérios dessa classificação?\n(Fratura de Escápula — Conduta por Localização)","back":"• Corpo escapular — Imobilização com tipoia; desvio raro e bem tolerado pela espessa musculatura circundante.\n• Acrômio/coracoide — Cirurgia indicada apenas se gravemente desviada.\n• Glenoide — Fraturas mais propensas a necessitar redução e fixação interna, especialmente as intra-articulares com desvio substancial.\n• Abordagem cirúrgica — Anterior para fraturas glenoidais anteriores; posterior para fraturas do colo escapular e da fossa glenoide.\n• Alerta de associação — Suspeitar de disjunção escapulotorácica se associada a fratura de clavícula — avaliar cuidadosamente função vascular e neurológica do membro ipsilateral."},{"id":"ombro-luxacao-traumatica","area":"Pediátrica","front":"LUX-OMB\n\nQuais são os critérios dessa classificação?\n(Luxação Traumática do Ombro no Adolescente)","back":"• Epidemiologia — Menos de 2% das luxações glenoumerais ocorrem antes dos 10 anos; ~20% de todas as luxações de ombro ocorrem entre 10-20 anos.\n• Padrão de lesão — Maioria anterior, com lesão de Bankart (descolamento da cápsula anteroinferior do colo da glenoide).\n• Tratamento agudo — Redução fechada gentil com analgesia e relaxamento muscular adequados; tipoia/imobilizador por 2-3 semanas.\n• Recorrência — Incidência entre 60% e 85%, geralmente dentro de 2 anos após a luxação primária.\n• Atletas ≥14 anos — Meta-análise mostra que o tratamento operatório melhora o retorno ao esporte e reduz a recorrência."},{"id":"umero-proximal-fise-neer","area":"Pediátrica","front":"NEER\n\nQuais são os critérios dessa classificação?\n(Fratura Fisária/Metafisária do Úmero Proximal — Grau de Desvio)","back":"• Padrão etário — Separação epifisária Salter-Harris tipo II é mais comum em adolescentes; fratura metafisária é mais comum antes dos 10 anos.\n• Indicação de tentativa de redução — Desvio maior que dois terços da largura (Neer grau III ou IV) e angulação >45° em adolescentes mais velhos (>12 anos) — tentar redução fechada sob anestesia geral.\n• Aceitável sem redução — Até 3 cm de cavalgamento e 60° de angulação em pacientes a mais de 2 anos da maturidade esquelética; até 45° até o fechamento fisário.\n• Tratamento padrão — Tipoia com enfaixamento (sling and swathe) por 3-4 semanas na maioria dos casos, sem tentativa de redução.\n• Obstáculo à redução — O tendão da cabeça longa do bíceps (ou o periósteo) pode se interpor entre os fragmentos..."},{"id":"umero-proximal-fixacao-percutanea","area":"Pediátrica","front":"CRPP-UP\n\nQuais são os critérios dessa classificação?\n(Fixação Percutânea do Úmero Proximal — Técnica e Zona de Segurança)","back":"• Indicação — Fratura instável ou irredutível após tentativa de redução fechada sob anestesia geral.\n• Zona do nervo axilar — O nervo corre de posterior para anterior 5-7 cm distal à ponta do acrômio — os fios devem iniciar distal a essa zona.\n• Configuração dos fios — Dois fios grandes (≥0,062 pol.) inseridos a partir da metáfise lateral proximal, direcionados à epífise, com alguma divergência para estabilidade.\n• Fragmento de Thurston Holland — Um fio pode permanecer abaixo da fise para capturar esse fragmento metafisário posteromedial, quando presente.\n• Pós-operatório — Enfaixamento por 3-4 semanas; remoção de parafusos transfisários indicada se houver potencial de crescimento remanescente."},{"id":"umero-diafise-conduta","area":"Pediátrica","front":"UD-CONDUTA\n\nQuais são os critérios dessa classificação?\n(Fratura da Diáfise do Úmero — Conduta e Angulação Aceitável)","back":"• Lactentes/crianças pequenas — Tratamento fechado (enfaixamento/imobilização); remodelação notável, com até 65° de angulação documentada em lactentes.\n• Angulação aceitável — terço proximal — 25° a 30° em crianças mais velhas/adolescentes.\n• Angulação aceitável — terço médio — Até 20°.\n• Angulação aceitável — terço distal — Até 15° (deformidade mais visível perto do cotovelo, menor tolerância).\n• Indicações cirúrgicas — Fratura exposta, politrauma, fratura ipsilateral do antebraço (\"cotovelo flutuante\")."},{"id":"cotovelo-linhas-radiograficas","area":"Pediátrica","front":"BAUM-AHL\n\nQuais são os critérios dessa classificação?\n(Linhas Radiográficas do Cotovelo — Ângulo de Baumann e Linha Umeral Anterior)","back":"• Ângulo de Baumann — Formado entre a linha fisária do capítulo e uma linha perpendicular ao eixo longitudinal do úmero; avalia o varo/valgo distal.\n• Valor de referência — Deve estar dentro de 5° a 8° do mesmo ângulo no cotovelo contralateral não lesado.\n• Linha umeral anterior (LUA) — Linha ao longo da cortical anterior do úmero deve passar pelo capítulo.\n• Interpretação — Capítulo posterior à LUA sugere fratura supracondiliana, condilar lateral ou transfisária desviada.\n• Limitação técnica — Rotação de 10° do braço produz variação de 6° no ângulo de Baumann — comparação com o lado contralateral é essencial."},{"id":"cotovelo-fraturas-diferenciacao","area":"Pediátrica","front":"DIFF-COT\n\nQuais são os critérios dessa classificação?\n(Diferenciação Radiográfica das Fraturas do Cotovelo Infantil)","back":"• Luxação do cotovelo — Disrupção do alinhamento radiocapitelar; maioria dos casos é posterolateral.\n• Fratura de côndilo lateral desviada — Também apresenta disrupção do alinhamento radiocapitelar.\n• Fratura supracondiliana — Rádio e capítulo permanecem alinhados, apesar do desvio do fragmento distal do úmero.\n• Separação fisária distal do úmero (transfisária) — Relação radiocapitelar preservada; o segmento distal é tipicamente desviado posteromedial.\n• Uso da artrografia — Auxilia a diferenciação entre fratura transfisária e fratura de côndilo lateral em crianças pequenas com cotovelo edemaciado."},{"id":"gartland-classificacao","area":"Pediátrica","front":"GARTLAND\n\nQuais são os critérios dessa classificação?\n(Classificação de Gartland — Fratura Supracondiliana do Úmero)","back":"• Tipo I — Não desviada ou minimamente desviada.\n• Tipo II — Angulada com disrupção moderada, mas com uma porção do córtex mantendo contato de extremidade a extremidade (córtex posterior íntegro).\n• Tipo III — Completamente desviada, sem continuidade cortical.\n• Tipo IV — Instabilidade multidirecional por dobradiça perióssea incompetente; o fragmento distal pode cair em flexão ou extensão, frequentemente determinado apenas sob anestesia no intraoperatório.\n• Variante em flexão — Representa cerca de 2% das fraturas supracondilianas, por queda direta sobre o cotovelo; o capítulo fica anterior à LUA na radiografia lateral."},{"id":"supracondiliana-tratamento-tipo1-2","area":"Pediátrica","front":"SUPRA-I-II\n\nQuais são os critérios dessa classificação?\n(Fratura Supracondiliana — Tratamento dos Tipos I e II)","back":"• Tipo I — Gesso acima do cotovelo por 3 semanas; atenção especial à impactação medial sutil na radiografia.\n• Ângulo de Baumann >80° — Sugere varo — indicação de redução fechada e fixação percutânea (CRPP).\n• Tipo II — Geralmente extensão com córtex posterior íntegro; quando a LUA não tangencia o capítulo, há extensão inaceitável.\n• Risco do tratamento apenas com gesso — Mais de 20% dos tratados sem fixação podem perder a redução e necessitar cirurgia tardia.\n• Indicação de CRPP — Necessidade de flexão ≥90° para manter a redução (aumenta a pressão compartimental e reduz o fluxo da artéria braquial)."},{"id":"supracondiliana-tratamento-tipo3-4","area":"Pediátrica","front":"SUPRA-III-IV\n\nQuais são os critérios dessa classificação?\n(Fratura Supracondiliana — Tratamento dos Tipos III e IV)","back":"• Conduta primária — CRPP é o tratamento preferido para as lesões tipo III.\n• Risco do gesso isolado — Maior incidência de deformidade residual e maior risco de contratura isquêmica de Volkmann comparado à fixação com fios.\n• Configuração de fios — 2 fios laterais divergentes geralmente suficientes para tipo II; 3 fios (laterais ou 2 laterais + 1 medial) para tipo III.\n• Tipo IV — Fios são inseridos primeiro no fragmento distal; a fluoroscopia é rotacionada (e não o braço) para obter imagens AP e lateral sem perder a redução.\n• Fio medial — Risco de subluxação do nervo ulnar com flexão ≥120° em mais de 50% das crianças — inserir os fios laterais primeiro para reduzir o risco."},{"id":"supracondiliana-vascular-conduta","area":"Pediátrica","front":"SUPRA-VASC\n\nQuais são os critérios dessa classificação?\n(Fratura Supracondiliana com Comprometimento Vascular — Conduta)","back":"• Mão bem perfundida, sem pulso — Redução da fratura geralmente é suficiente; não requer exploração arterial de rotina — o pulso costuma retornar em até 48 horas.\n• Conduta de observação — Mão quente, com boa coloração e enchimento capilar rápido — observação hospitalar com imobilização não circunferencial e flexão <60° por 48 horas.\n• Mão mal perfundida e sem pulso — Cerca de 50% de chance de necessitar cirurgia vascular e quase 25% de chance de desenvolver síndrome compartimental.\n• Insuficiência vascular persistente — Redução aberta por via anterior é recomendada; o feixe neurovascular frequentemente é encontrado angulado (\"kinked\") no sítio da fratura.\n• Reconstrução vascular — Realizada se a mão permanece avascular apesar de medidas..."},{"id":"supracondiliana-nervo-conduta","area":"Pediátrica","front":"SUPRA-NERVO\n\nQuais são os critérios dessa classificação?\n(Lesão Nervosa na Fratura Supracondiliana — Padrão e Conduta)","back":"• Incidência geral — Aproximadamente 15%; a maioria é neuropraxia com resolução espontânea em até 4 meses.\n• Desvio posterolateral — Associado a lesão do nervo mediano (incluindo o interósseo anterior).\n• Desvio posteromedial — Associado a lesão do nervo radial.\n• Fraturas em flexão — Associadas a lesão do nervo ulnar.\n• Ausência de recuperação em 4-6 meses — Indicação de eletroneuromiografia (EMG) e exploração cirúrgica."},{"id":"cubito-varo-pos-supracondiliana","area":"Pediátrica","front":"CUBITO-VARO\n\nQuais são os critérios dessa classificação?\n(Cúbito Varo Pós-Fratura Supracondiliana)","back":"• Etiologia — Representa malunião da fratura; raramente resulta de parada parcial de crescimento da fise condilar medial.\n• Prevenção — Redução anatômica e fixação segura no tratamento inicial.\n• Riscos associados — Fratura de côndilo lateral, paralisia ulnar tardia, instabilidade rotatória posterolateral do cotovelo, instabilidade posterior do ombro.\n• Osteotomia — Uniplanar em cunha de fechamento apresenta as menores taxas de complicação, mas pode gerar proeminência condilar lateral.\n• Planejamento — A diferença do ângulo de carregamento comparado ao cotovelo contralateral guia o ângulo da cunha a ser removida no plano coronal."},{"id":"cotovelo-flutuante","area":"Pediátrica","front":"FLOAT-ELBOW\n\nQuais são os critérios dessa classificação?\n(Cotovelo Flutuante (Floating Elbow))","back":"• Definição — Fraturas supracondiliana e de antebraço ipsilaterais simultâneas.\n• Mecanismo — Trauma de alta energia.\n• Risco — Lesão neurológica e síndrome compartimental quase 2 vezes mais comuns que na fratura supracondiliana isolada.\n• Conduta — Geralmente consideradas para fixação cirúrgica urgente de ambas as fraturas.\n• Técnica — Fixação percutânea de ambas (supracondiliana e antebraço) permite imobilização menos constritiva e reduz o risco de redesvio."},{"id":"fratura-t-condilar","area":"Pediátrica","front":"T-COND\n\nQuais são os critérios dessa classificação?\n(Fratura T-Condilar do Úmero Distal)","back":"• Anatomia da lesão — Capítulo e tróclea separados entre si e do úmero proximal (fratura intra-articular).\n• Mecanismo — Impactação axial; predomina em adolescentes próximos ao fechamento fisário, mas pode ocorrer em crianças menores.\n• Tratamento fechado — Fixação percutânea transcondilar seguida de pinagem ou haste flexível do componente supracondiliano.\n• Abordagem aberta — Posterior — tríceps-split ou osteotomia do olécrano (raramente necessária pela baixa cominuição articular em crianças).\n• Imobilização — 3 semanas ou menos para prevenir rigidez; fixação rígida com mobilização precoce é preferida perto da maturidade esquelética."},{"id":"fratura-transfisaria-distal-umero","area":"Pediátrica","front":"TRANSFISE-UD\n\nQuais são os critérios dessa classificação?\n(Fratura-Separação da Fise Umeral Distal (Transfisária))","back":"• População — Principalmente lactentes e crianças pequenas; maus-tratos devem ser suspeitados.\n• Padrão — Salter-Harris tipo I ou II por forças de cisalhamento rotatório.\n• Diagnóstico diferencial — Frequentemente confundida com luxação do cotovelo (rara em crianças pequenas) e com fratura de côndilo lateral.\n• Conduta — Fixação com dois fios laterais de pequeno diâmetro após redução.\n• Apresentação tardia (7-10 dias) — Não manipular — risco de parada de crescimento; aguardar remodelação ou realizar osteotomia supracondiliana tardia se necessário."},{"id":"condilo-lateral-weiss","area":"Pediátrica","front":"WEISS\n\nQuais são os critérios dessa classificação?\n(Classificação de Weiss — Fratura do Côndilo Lateral do Úmero)","back":"• Tipo I — Desvio menor que 2 mm.\n• Tipo II — Desvio ≥2 mm com cartilagem articular íntegra (congruência confirmada por artrografia ou RM).\n• Tipo III — Desvio ≥2 mm e falta de congruência articular (dobradiça cartilaginosa rota).\n• Classificação de Milch — Histórica; considerada não confiável e de utilidade clínica limitada pelos autores do capítulo.\n• Risco de progressão — Fraturas com desvio inicial ≥3 mm tendem a desviar mais e têm maior incidência de pseudoartrose."},{"id":"condilo-lateral-tratamento","area":"Pediátrica","front":"COND-LAT-TX\n\nQuais são os critérios dessa classificação?\n(Fratura de Côndilo Lateral — Tratamento por Tipo (Weiss))","back":"• Tipo I (<2 mm) — Imobilização gessada; até 30% podem desviar mais nos primeiros 15 dias — seguimento radiográfico semanal por 2 semanas.\n• Tipo II (≥2 mm, congruente) — Pinagem fechada após artrografia confirmando superfície articular intacta (preferir portal posterior/olecraniano para a artrografia).\n• Tipo III (≥2 mm, incongruente) — Redução aberta com fixação com fios ou parafusos.\n• Fixação com parafuso — Menor risco de pseudoartrose e retorno mais rápido ao movimento, mas pode requerer remoção posterior.\n• Cuidado cirúrgico — Evitar dissecção posterior do fragmento para reduzir o risco de necrose avascular do capítulo/tróclea."},{"id":"epicondilo-medial-fratura","area":"Pediátrica","front":"EPI-MED\n\nQuais são os critérios dessa classificação?\n(Fratura do Epicôndilo Medial do Úmero — Indicações de Tratamento)","back":"• Epidemiologia — Ocorre por carga em valgo no cotovelo estendido; associada a luxação posterolateral do cotovelo em quase 50% dos casos.\n• Indicação absoluta de cirurgia — Fragmento encarcerado na articulação (pode aprisionar também o nervo ulnar).\n• Tratamento fechado — Aceito mesmo com desvio significativo ou luxação associada — pseudoartrose é frequente, porém geralmente assintomática.\n• Indicação relativa de ORIF — Desvio >5-10 mm; atletas de arremesso/ginástica; fratura com luxação concomitante do cotovelo.\n• Fixação — Parafuso canulado em adolescentes (permite mobilização precoce); fios de Kirschner + gesso por 3 semanas em pré-adolescentes."},{"id":"condilo-medial-fratura","area":"Pediátrica","front":"COND-MED\n\nQuais são os critérios dessa classificação?\n(Fratura do Côndilo Medial do Úmero)","back":"• Diagnóstico diferencial — Pode ser confundida com avulsão do epicôndilo medial em crianças de 5 a 7 anos (tróclea ainda não ossificada).\n• Sinal radiográfico — Procurar lasca/flake metafisária quando a tróclea ainda não está ossificada.\n• Gravidade — Mais grave que a fratura de epicôndilo medial, pois envolve a superfície articular.\n• Indicação cirúrgica — Redução aberta e fixação interna se o desvio for maior que 2 mm."},{"id":"colo-radio-fratura-epidemiologia","area":"Pediátrica","front":"COLO-RADIO\n\nQuais são os critérios dessa classificação?\n(Fratura do Colo do Rádio — Epidemiologia e Fatores Prognósticos)","back":"• Faixa etária — 7-12 anos é a mais comumente acometida.\n• Padrão — Predominantemente Salter-Harris tipo I ou II; muitas são metafisárias.\n• Lesão associada — Cerca de 50% têm fratura associada, mais comumente da ulna proximal.\n• Fatores de mau prognóstico — Idade >10 anos, angulação >30°, desvio >3 mm, tratamento tardio, lesões associadas, necessidade de redução aberta.\n• Limitação funcional — Cerca de metade das crianças terá limitação permanente da rotação do antebraço."},{"id":"colo-radio-tratamento-angulacao","area":"Pediátrica","front":"COLO-RADIO-TX\n\nQuais são os critérios dessa classificação?\n(Fratura do Colo do Rádio — Limiares de Angulação/Desvio para Tratamento)","back":"• Indicação de redução — Angulação >30° ou translação >3-5 mm.\n• Teste funcional pós-redução — Se pronossupinação <60°, prosseguir para redução percutânea.\n• Falha da redução percutânea — Se pronossupinação <45° apesar da tentativa percutânea, prosseguir para redução aberta.\n• Aceitável em <10 anos — Até 45° de angulação e 33% de translação.\n• Aceitável em >10 anos — Até 30° de angulação e 3-5 mm de translação."},{"id":"trash-lesao-cabeca-radio","area":"Pediátrica","front":"TRASH\n\nQuais são os critérios dessa classificação?\n(Lesão TRASH da Cabeça do Rádio (The Radiographic Appearance Seemed Harmless))","back":"• Definição — Fratura predominantemente cartilaginosa da cabeça do rádio, cuja radiografia simples aparenta ser inócua.\n• Diagnóstico — RM pode ser necessária para avaliar o tamanho real do fragmento em crianças pequenas.\n• Classificação subjacente — Frequentemente Salter-Harris tipo III ou IV.\n• Tratamento — Redução aberta com fixação interna (parafusos transepifisários de compressão sem cabeça)."},{"id":"cabeca-radio-luxacao-diferenciacao","area":"Pediátrica","front":"LUX-RADIO\n\nQuais são os critérios dessa classificação?\n(Luxação da Cabeça do Rádio — Traumática vs. Congênita)","back":"• Traumática — Cabeça do rádio desloca-se anteriormente; frequentemente representa lesão de Monteggia oculta, com deformação plástica da ulna.\n• Congênita — Direção posterior; superfície articular da cabeça do rádio é convexa ou plana (em vez da concavidade normal).\n• Achado clínico — Falta de rotação do antebraço frequentemente não reconhecida previamente pela família nos casos congênitos.\n• Tratamento traumático — Redução fechada e imobilização com cotovelo em flexão e supinação.\n• Tratamento congênito sintomático — Excisão da cabeça do rádio nos casos de dor persistente."},{"id":"pronacao-dolorosa-cotovelo","area":"Pediátrica","front":"NURSEMAID\n\nQuais são os critérios dessa classificação?\n(Pronação Dolorosa (Nursemaid Elbow / Cotovelo Puxado))","back":"• Faixa etária — 1-4 anos, tipicamente após tração longitudinal do braço.\n• Fisiopatologia — Subluxação do ligamento anular (não é luxação articular verdadeira); o ligamento desliza sobre a cabeça radial.\n• Radiografia — Não indicada inicialmente; é normal quando obtida.\n• Manobra de redução — Flexão do cotovelo além de 90° com supinação completa do antebraço e pressão sobre a cabeça radial; um clique é frequentemente sentido.\n• Falha de redução — Se a criança não mover o braço em poucos minutos, obter radiografia para excluir fratura oculta; recorrência é comum e tratada da mesma forma."},{"id":"olecrano-fratura-tipos","area":"Pediátrica","front":"OLECRANO\n\nQuais são os critérios dessa classificação?\n(Fratura de Olécrano — Padrões de Lesão)","back":"• Avulsão/flexão — Mecanismo mais comum; disrupção do periósteo posterior e fratura do córtex — requer redução em extensão.\n• Extensão — Periósteo posterior íntegro; frequentemente fraturas anguladas com lesões associadas por forças em varo/valgo.\n• Cominuída (trauma direto) — Cominuição com desvio mínimo, pois o periósteo permanece íntegro.\n• Indicação de redução — Desvio >4 mm em osso metafisário ou degrau articular >2 mm na fossa coronoide.\n• Osteogênese imperfeita — Fratura \"em manga\" (sleeve) do olécrano pode ser seguida de fratura contralateral em até 6 meses."},{"id":"luxacao-cotovelo-pediatrica","area":"Pediátrica","front":"LUX-COT\n\nQuais são os critérios dessa classificação?\n(Luxação do Cotovelo na Criança — Epidemiologia e Conduta)","back":"• Incidência — Incomum em crianças pequenas (fise mais fraca que os ligamentos); pico de incidência na segunda década de vida.\n• Padrão — Predomínio masculino (70%), membro não dominante (60%), maioria das luxações posteriores/posterolaterais.\n• Lesões associadas — Mais comum: fratura do epicôndilo medial; também coronoide e colo do rádio.\n• Redução — Empurrar o olécrano anteriormente com o cotovelo fletido (similar à fratura supracondiliana) ou tração longitudinal, sob analgesia/relaxamento.\n• Mobilização — Iniciar movimento precoce em órtese articulada de cotovelo (5-10 dias) para minimizar o risco de contratura."},{"id":"monteggia-bado-ped","area":"Pediátrica","front":"BADO\n\nQuais são os critérios dessa classificação?\n(Classificação de Bado — Lesão de Monteggia (contexto pediátrico))","back":"• Tipo I — Fratura da ulna com ápice anterior e luxação anterior da cabeça do rádio; corresponde à maioria das lesões de Monteggia na infância.\n• Tipo II — Luxação posterior ou posterolateral da cabeça do rádio; o tipo menos comum.\n• Tipo III — Luxação lateral da cabeça do rádio com fratura de ápice lateral da ulna (geralmente metafisária proximal); corresponde a 25-30% das lesões pediátricas.\n• Tipo IV — Luxação anterior da cabeça do rádio combinada com fratura de rádio e ulna.\n• Equivalentes de Monteggia — Fratura ulnar combinada com fratura do colo do rádio, fraturas segmentares ou deformação plástica isolada da ulna."},{"id":"monteggia-tratamento","area":"Pediátrica","front":"MONTEGGIA-TX\n\nQuais são os critérios dessa classificação?\n(Lesão de Monteggia — Tratamento por Padrão de Fratura)","back":"• Fratura ulnar incompleta (galho-verde/deformação plástica) — Redução fechada e gesso acima do cotovelo na maioria dos casos.\n• Posicionamento — tipo I — Cotovelo fletido >90° com antebraço em supinação.\n• Posicionamento — tipo II — Cotovelo em extensão com antebraço em supinação (maior estabilidade da cabeça radial).\n• Posicionamento — tipo III — Redução em varo; frequentemente difícil de manter apenas com gesso.\n• Fratura ulnar completa — Cirurgia geralmente indicada — haste intramedular (traço transverso/oblíquo curto) ou placa (oblíquo longo/cominuído); seguimento radiográfico semanal por 2-3 semanas se tratada de forma fechada."},{"id":"galeazzi-lesao","area":"Pediátrica","front":"GALEAZZI\n\nQuais são os critérios dessa classificação?\n(Lesão de Galeazzi e Equivalente de Galeazzi)","back":"• Galeazzi clássica — Fratura do terço distal do rádio sem fratura da ulna, associada a luxação da articulação radioulnar distal.\n• Galeazzi-equivalente (mais comum em crianças) — Fratura do rádio com fratura fisária da ulna distal.\n• Achado radiográfico — Ulna distal desviada dorsalmente na incidência lateral; complexo fibrocartilaginoso triangular rompido.\n• Tratamento — Redução fechada do rádio e da fise ulnar, com gesso acima do cotovelo em supinação plena ou posição neutra.\n• Complicação tardia — Parada fisária prematura da ulna, com encurtamento e perda de supinação."},{"id":"deformacao-plastica-antebraco","area":"Pediátrica","front":"DEF-PLASTICA\n\nQuais são os critérios dessa classificação?\n(Deformação Plástica (Arqueamento Traumático) do Antebraço)","back":"• Fisiopatologia — Microfraturas múltiplas não visíveis em radiografia simples, possíveis pela elasticidade óssea infantil.\n• Indicação de redução — Deformidade cosmeticamente inaceitável ou perda de rotação do antebraço >45°.\n• Remodelação (<6 anos) — Até 15° a 20° de angulação pode ser aceito.\n• Remodelação (>6 anos) — Mais de 10° de angulação pode não remodelar — capacidade de remodelação limitada após os 6 anos de idade.\n• Deformidade crônica — Osteotomias corretivas em múltiplos níveis descritas para restrição residual da rotação do antebraço."},{"id":"fratura-galho-verde-antebraco","area":"Pediátrica","front":"GALHO-VERDE\n\nQuais são os critérios dessa classificação?\n(Fratura em Galho Verde do Antebraço)","back":"• Padrão — Fratura completa de uma cortical e deformação plástica da cortical oposta; geralmente com componente rotacional além da angulação.\n• Ápice volar — Mecanismo de supinação excessiva; palma voltada para o ápice da deformidade — reduzida por pronação do fragmento distal.\n• Ápice dorsal — Mecanismo de pronação excessiva; reduzida por supinação do fragmento distal.\n• Indicação de redução — Deformidade rotacional >45° em crianças 30° em crianças mais velhas.\n• Refratura — Ocorre em 1,4% a 6,7% dos casos, possivelmente mais comum após fraturas em galho verde; fratura no terço médio é o principal fator de risco."},{"id":"antebraco-fratura-completa-diretrizes","area":"Pediátrica","front":"ANTEBR-COMPLETA\n\nQuais são os critérios dessa classificação?\n(Fratura Completa (Bicortical) da Diáfise do Antebraço — Diretrizes de Redução Fechada)","back":"• Prognóstico — Crianças mais jovens com fraturas mais distais têm melhor prognóstico; obesidade é fator de risco para perda de redução.\n• Aposição em baioneta — No terço médio/distal não compromete a rotação do antebraço.\n• Alinhamento rotacional — O do rádio é mais crítico que o da ulna; até 45° de má-rotação do rádio é aceitável em crianças mais jovens.\n• Angulação diafisária aceitável — ≤15° em crianças <8 anos; ≤10° em crianças ≥8 anos.\n• Posição de imobilização — Neutra ou supinação moderada quando há dúvida — perda de supinação (pronação fixa) é pior tolerada que perda de pronação."},{"id":"antebraco-fixacao-im-vs-placa","area":"Pediátrica","front":"IM-PLACA\n\nQuais são os critérios dessa classificação?\n(Fratura Completa do Antebraço — Fixação Intramedular vs. Placa)","back":"• Indicação cirúrgica — Fraturas instáveis ou falha do tratamento fechado.\n• Placa — Preferida em cominuição ou em adolescentes próximos à maturidade esquelética; permite alinhamento mais anatômico e restauração do arco radial, mas requer maior dissecção.\n• Fixação intramedular (IM) — Preferida em crianças e adolescentes mais jovens; menor dissecção, boa remodelação, hastes flexíveis de 1,5-2,5 mm de diâmetro.\n• Ordem de redução — A ulna geralmente é reduzida/fixada primeiro (subcutânea, fácil palpação); o rádio pode não precisar de haste se alinhar após a fixação ulnar.\n• Limitação da técnica IM — Não indicada para fraturas do rádio distais à porção estreita da diáfise (canal medular largo permite desvio dos fragmentos)."},{"id":"radio-ulna-metafisaria-distal","area":"Pediátrica","front":"TORUS-BUCKLE\n\nQuais são os critérios dessa classificação?\n(Fratura Metafisária Distal do Rádio/Ulna — Torus vs. Bicortical)","back":"• Torus/buckle (unicortical) — Fratura estável por compressão; tratada com tala por 3 semanas, sem necessidade de seguimento radiográfico adicional.\n• Fratura bicortical desviada/angulada — Redução fechada com gesso bem moldado ou tala sugar-tong.\n• Seguimento — Radiografias em 1 e 2 semanas após redução fechada de fraturas bicorticais, para avaliar perda de alinhamento.\n• Fatores de risco para perda de redução — Angulação inicial, translação da fratura >50%, acurácia da redução, índice de gesso (cast index) >0,7.\n• Fixação percutânea — Considerada quando o alinhamento aceitável não pode ser mantido apenas com gesso."},{"id":"radio-distal-angulacao-remodelacao","area":"Pediátrica","front":"RADIO-DIST-REMOD\n\nQuais são os critérios dessa classificação?\n(Fratura Metafisária Distal do Rádio — Angulação Aceitável por Idade)","back":"• <5 anos — Até 35° de báscula dorsal (angulação ápice volar) pode ser aceita.\n• 5-12 anos — 20° a 25° de báscula dorsal aceitável.\n• >12 anos — Báscula dorsal deve ser controlada a menos de 10-15°.\n• Desvio no plano coronal (radioulnar) — Remodela menos que a angulação no plano flexão-extensão; manter <15° (<12 anos) ou <10° (≥12 anos).\n• Cinética da remodelação — 50% da remodelação ocorre nos primeiros 6 meses e os 50% restantes nos 18 meses seguintes, enquanto a fise distal do rádio permanece aberta."},{"id":"radio-distal-fise-fratura","area":"Pediátrica","front":"SH-RADIO-DIST\n\nQuais são os critérios dessa classificação?\n(Fratura Fisária Distal do Rádio (Salter-Harris))","back":"• Frequência — Segunda fise mais comumente fraturada (após a falangeana); cerca de 15% de todas as fraturas de antebraço.\n• Padrão — Mais de 95% são Salter-Harris tipo I ou II.\n• Aceitável sem redução (<10 anos, tipo II) — Até 20° de angulação e 40% de desvio.\n• Risco de manipulações repetidas — Duas ou mais tentativas de redução associadas a mais de 25% de parada fisária.\n• Janela de manipulação — Manipulação tardia (mais de 7-10 dias) pode lesar ainda mais a fise, que já está em processo de consolidação."},{"id":"denis-three-column-toracolombar","area":"Pediátrica","front":"Denis\n\nQuais são os critérios dessa classificação?\n(Teoria das Três Colunas de Denis para Trauma Toracolombar)","back":"• Coluna anterior — Ligamento longitudinal anterior e metade anterior do corpo vertebral/anel fibroso.\n• Coluna média — Metade posterior do corpo vertebral/anel fibroso e ligamento longitudinal posterior.\n• Coluna posterior — Complexo ligamentar posterior, arcos neurais e articulações facetárias.\n• Quatro tipos de lesão — A partir do conceito de coluna, Denis descreveu quatro tipos principais: compressão, explosão (burst), flexão-distração e fratura-luxação.\n• Instabilidade — A lesão é considerada instável quando duas das três colunas estão envolvidas, embora esse critério isolado tenha correlação fraca com a decisão cirúrgica versus conservadora."},{"id":"tlics-pediatrica","area":"Pediátrica","front":"TLICS\n\nQuais são os critérios dessa classificação?\n(Thoracolumbar Injury Classification and Severity Score aplicado à criança)","back":"• Componente 1 — Morfologia da lesão (padrão de fratura observado na imagem).\n• Componente 2 — Integridade do complexo ligamentar posterior (PLC).\n• Componente 3 — Estado neurológico do paciente.\n• Escore > 4 — Cirurgia é recomendada.\n• Escore < 4 — Tratamento conservador deve ser considerado."},{"id":"fratura-compressao-coluna-pediatrica","area":"Pediátrica","front":"Compressão\n\nQuais são os critérios dessa classificação?\n(Fratura em Compressão (Lesão Isolada da Coluna Anterior))","back":"• Mecanismo — Carga axial ou hiperflexão, limitada ao colapso da coluna anterior.\n• Critério radiográfico — Diferença maior que 3 mm entre a altura cortical anterior e posterior do corpo vertebral sugere fortemente compressão; pode acometer múltiplos níveis contíguos.\n• Diagnóstico diferencial — Deve ser diferenciada da fratura em explosão, que também compromete a coluna média.\n• Estabilidade — Considerada estável; tratada de forma conservadora com analgesia, modificação de atividade e órtese/colete.\n• Papel do colete — Colete pode não alterar o resultado radiológico final quando a angulação segmentar é menor que 10 graus, mas pode prevenir progressão da deformidade se a angulação for maior que 10 graus."},{"id":"fratura-explosao-coluna-pediatrica","area":"Pediátrica","front":"Burst\n\nQuais são os critérios dessa classificação?\n(Fratura em Explosão (Burst) — Lesão de Colunas Anterior e Média)","back":"• Mecanismo — Carga axial, associada ou não a momento de hiperflexão, com retropulsão frequente da coluna média para o canal vertebral.\n• Comprometimento do canal — O grau de comprometimento do canal não se correlaciona de forma direta e comprovada com lesão neurológica, tanto em adultos quanto em séries pediátricas.\n• Gatilhos cirúrgicos históricos questionados — Revisão crítica de evidências (Shimer et al.) contesta os limiares clássicos de indicação cirúrgica (50% de comprometimento do canal, 50% de perda de altura do corpo vertebral, 30 graus de cifose) como preditores isolados de desfecho.\n• Fator determinante real — Déficit neurológico progressivo e integridade do complexo ligamentar posterior (PLC) devem ser os principais direcion..."},{"id":"fratura-flexao-distracao-chance-pediatrica","area":"Pediátrica","front":"Chance\n\nQuais são os critérios dessa classificação?\n(Fratura em Flexão-Distração (Chance) — Lesão de Três Colunas)","back":"• Localização típica — Coluna lombar alta, com a coluna posterior falhando em distração e a coluna anterior/média falhando em compressão, conforme o ponto do fulcro de flexão.\n• Mecanismo clássico — Cinto de segurança tipo \"lap belt\" em crianças pequenas; associação com lesão visceral (abdominal) em 40% a 70% dos casos.\n• Subtipos — Podem ser puramente ósseos (fratura de Chance verdadeira), puramente ligamentosos, ou combinação de osso e ligamento.\n• Achado radiográfico — Alargamento do espaço interespinhoso na radiografia em perfil sugere distração dos elementos posteriores.\n• Limiar de tratamento — Lesões puramente ósseas podem ser tratadas com colete/gesso em extensão se o alinhamento sagital em ortostase for menor que 20 graus; acima..."},{"id":"fratura-luxacao-coluna-pediatrica","area":"Pediátrica","front":"Fx-luxação\n\nQuais são os critérios dessa classificação?\n(Fratura-Luxação (Lesão de Três Colunas com Translação))","back":"• Definição — Translação de um segmento da coluna vertebral fraturada em relação ao outro; por definição, lesão altamente instável.\n• Associação neurológica — Frequentemente associada a algum grau de lesão neurológica.\n• Conduta — Estabilização cirúrgica rígida é indicada para prevenir lesão secundária da medula e realinhar a coluna; descompressão do canal frequentemente necessária (via posterior ou combinada anterior/posterior).\n• Timing da descompressão — Estudo STASCIS (adultos) sugere que descompressão precoce (dentro de 24 horas) melhora o desfecho neurológico em pelo menos 2 graus na escala ASIA aos 6 meses.\n• Prognóstico pediátrico — Crianças que sobrevivem à lesão medular inicial têm bom prognóstico de melhora neurológica (75-85%..."},{"id":"fratura-apofise-anel-pediatrica","area":"Pediátrica","front":"Apófise em anel\n\nQuais são os critérios dessa classificação?\n(Fratura da Apófise em Anel (Ring Apophysis / Fratura do Limbus))","back":"• Natureza — Lesão típica da coluna em crescimento, decorrente de fise aberta; separação da apófise da camada esponjosa do corpo vertebral, com a fratura cruzando a zona hipertrófica da fise.\n• Localização preferencial — A fise caudal é mais frequentemente envolvida.\n• Apresentação clínica — Pode simular hérnia discal aguda do adulto, com dor lombar baixa e radiculopatia, podendo se apresentar com síndrome da cauda equina.\n• Diagnóstico — Pode se reduzir espontaneamente e não ser aparente em radiografia simples; TC ou RM frequentemente necessárias.\n• Conduta — Pacientes com dor isolada sem déficit neurológico podem ser tratados conservadoramente; dor persistente ou déficit neurológico significativo são indicação de descompressão cirúrgic..."},{"id":"sequelas-deformidade-pos-trauma-raquimedular-pediatrica","area":"Pediátrica","front":"Deformidade pós-TRM\n\nQuais são os critérios dessa classificação?\n(Padrão de Deformidade Espinhal Tardia após Trauma Toracolombar Pediátrico)","back":"• Fraturas estáveis (compressão/burst) — Não alteram significativamente o crescimento vertebral; deformidade angular no local da fratura não costuma exceder 10 graus no seguimento final.\n• Fraturas instáveis tratadas conservadoramente — Maior escoliose e cifose segmentares no seguimento final (médias de 20 e 18 graus, respectivamente), estendendo-se além do nível fraturado.\n• Lesão medular pré-estirão de crescimento — Mais de 90% desenvolvem deformidade espinhal (escoliótica, cifótica ou lordótica) quando a lesão ocorre antes do estirão puberal.\n• Distribuição dos tipos de deformidade — Em uma série, escoliose em 92%, cifose em 64% e lordose em 20% dos pacientes; 68% necessitaram de cirurgia adicional.\n• Fatores de risco para escoliose p..."},{"id":"watts-fratura-pelvica-pediatrica","area":"Pediátrica","front":"Watts\n\nQuais são os critérios dessa classificação?\n(Classificação de Watts para Fraturas Pélvicas Pediátricas)","back":"• Categoria 1 — Fraturas avulsivas (geralmente lesões esportivas, apófises isquiática, ilíaca anteroinferior e crista ilíaca anterior).\n• Categoria 2 — Fraturas do anel pélvico (estáveis e instáveis).\n• Categoria 3 — Fraturas do acetábulo.\n• Uso clínico — Classificação preferida pelos autores por refletir diretamente a tomada de decisão terapêutica na criança, diferentemente de sistemas puramente descritivos."},{"id":"ao-asif-anel-pelvico-pediatrico","area":"Pediátrica","front":"AO/ASIF\n\nQuais são os critérios dessa classificação?\n(Classificação AO/ASIF de Estabilidade do Anel Pélvico Aplicada à Criança)","back":"• Tipo A (estável) — Fraturas do ramo púbico (isolada, ou envolvendo ramos superior e inferior) ou da asa ilíaca; pode haver diástase da sínfise púbica sem instabilidade sacroilíaca posterior devido à elasticidade da pelve infantil.\n• Tipo B (rotacionalmente instável) — Disrupção do anel pélvico estável no plano vertical mas instável no plano transverso; compressão lateral (fraturas dos ramos púbico/isquiático com fratura sacral contralateral) ou compressão anterior (\"open-book\" com diástase púbica).\n• Tipo C (rotacional e verticalmente instável) — Fraturas bilaterais dos ramos púbicos (lesão em \"straddle\", raramente desloca em crianças), fraturas verticais por cisalhamento através dos anéis anterior e posterior ipsilaterais, e fraturas ..."},{"id":"estabilidade-anel-pelvico-criterio-deslocamento","area":"Pediátrica","front":"Estabilidade pélvica\n\nQuais são os critérios dessa classificação?\n(Critério de Estabilidade do Anel Pélvico por Deslocamento (Conduta))","back":"• Fratura estável — Lesão em anel único ou múltiplas fraturas com deslocamento menor que 1 cm.\n• Fratura instável — Fratura do anel anterior e posterior com deslocamento maior que 1 cm.\n• Conduta na fratura estável — Tratamento sintomático e restrição de carga, com radiografia de controle após mobilização.\n• Conduta na instável com deslocamento < 1 cm — Restrição de carga e acompanhamento radiográfico rigoroso, sem cirurgia, se não houver envolvimento do acetábulo.\n• Conduta na instável com deslocamento > 1 cm — Recomenda-se redução da fratura; estabilização anterior (fixador externo ou placa de sínfise) e, se necessário, fixação interna posterior (placas/parafusos ou parafuso sacroilíaco)."},{"id":"watts-fratura-acetabular-pediatrica","area":"Pediátrica","front":"Watts (acetábulo)\n\nQuais são os critérios dessa classificação?\n(Classificação de Watts para Fraturas do Acetábulo Pediátrico)","back":"• Tipo I — Fratura-luxação posterior com redução concêntrica estável e fragmentos pequenos; tratamento fechado, sem necessidade de restauração anatômica precisa.\n• Tipo II — Fratura acetabular não desviada; manejo fechado (conservador).\n• Tipo III — Múltiplos fragmentos com instabilidade; melhor manejo com redução aberta e fixação interna estável.\n• Tipo IV (implícito) — Fraturas com luxação central do quadril têm prognóstico ruim independentemente do tratamento cirúrgico ou conservador; tração pode ser utilizada, ou cirurgia se a cominuição for mínima.\n• Comentário geral — A cominuição costuma ser menos grave em crianças do que em adultos, com resultados cirúrgicos geralmente satisfatórios, embora resultados ruins possam ocorrer em qual..."},{"id":"lesao-cartilagem-trirradiada-fechamento-precoce","area":"Pediátrica","front":"Cartilagem trirradiada\n\nQuais são os critérios dessa classificação?\n(Lesão da Cartilagem Trirradiada e Risco de Fechamento Fisário Precoce)","back":"• Anatomia — A cartilagem trirradiada é formada pela junção dos três centros de ossificação (ísquio, púbis e ílio) no acetábulo, responsável pelo crescimento em altura e largura do acetábulo.\n• Grupo de risco — Crianças menores de 10 anos apresentam o maior risco de fechamento fisário prematuro após fratura envolvendo a cartilagem trirradiada.\n• Padrão da fratura de risco — Fraturas que resultam em fechamento fisário precoce costumam ser fraturas não desviadas.\n• Consequência — Desenvolvimento de acetábulo raso, com displasia e subluxação do quadril, podendo exigir osteotomia pélvica redirecional.\n• Conduta preventiva — Em crianças menores de 10 anos com formação de barra fisária da cartilagem trirradiada, recomenda-se ressecção da barra..."},{"id":"delbet-fratura-colo-femoral-pediatrica","area":"Pediátrica","front":"Delbet\n\nQuais são os critérios dessa classificação?\n(Classificação de Delbet para Fraturas Proximais do Fêmur Pediátrico)","back":"• Tipo I — Transfisária — Separação transepifisária; risco de necrose avascular (AVN) próximo de 100% se a epífise estiver luxada do acetábulo; prognóstico variável se o fêmur permanecer na articulação. Boa evolução em menores de 2 anos.\n• Tipo II — Transcervical — Fratura entre a fise e a base do colo; cerca de 50% de todas as fraturas proximais do fêmur; AVN em 50-60%; pseudartrose (não-união) em 15%.\n• Tipo III — Cervicotrocantérica (basicervical) — Segundo tipo mais comum; AVN em 30% das fraturas desviadas; malunião em 20% e pseudartrose em 10%.\n• Tipo IV — Intertrocantérica — Menor risco de dano vascular à cabeça femoral; AVN entre 0% e 10%; deformidade em varo é a complicação mais provável, podendo corrigir-se com o crescimento em ..."},{"id":"luxacao-traumatica-quadril-pediatrica","area":"Pediátrica","front":"Luxação de quadril\n\nQuais são os critérios dessa classificação?\n(Luxação Traumática do Quadril na Criança)","back":"• Direção mais comum — A maioria das luxações é posterior; luxações anteriores e obturadoras também podem ocorrer.\n• Mecanismo por idade — Em menores de 8 anos, ocorre com trauma leve (frouxidão articular, acetábulo cartilaginoso); em maiores de 8 anos, geralmente trauma moderado a grave.\n• Janela de redução — Redução fechada dentro de 6 horas do trauma é recomendada para reduzir o risco de necrose óssea, embora a evidência para esse prazo seja fraca.\n• Imobilização pós-redução — Crianças menores de 8 anos devem ser imobilizadas em gesso pelvipodálico por 4 a 6 semanas para reduzir risco de luxação recorrente.\n• Indicação de redução aberta — Redução instável, não concêntrica, fragmentos ósseos/partes moles intra-articulares, ou grande fr..."},{"id":"conduta-fratura-diafisaria-femur-por-idade","area":"Pediátrica","front":"Fêmur por idade\n\nQuais são os critérios dessa classificação?\n(Conduta na Fratura Diafisária do Fêmur Pediátrico por Faixa Etária)","back":"• Até 6 meses — Arnês de Pavlik, tala ou gesso pelvipodálico convencional; imobilização de 2-3 semanas (<4 meses) a 4 semanas (6-12 meses); suspeitar de maus-tratos ou osteogênese imperfeita.\n• 6 meses a 5 anos — Gesso pelvipodálico (espica) precoce, geralmente em \"walking spica\"; aceitável até 3 cm de encurtamento e 20-30 graus de angulação em qualquer plano (até 20 graus no terço distal).\n• 5 a 11 anos — Haste intramedular flexível (elástica) é o método mais usado para fraturas diafisárias estáveis; tração/gesso ainda aceitável; alinhamento aceito até 15 graus varo/valgo, 15 graus antero-posterior e 20 mm de encurtamento.\n• 11 anos até a maturidade — Estabilização cirúrgica (interna ou externa) geralmente indicada; alinhamento aceito a..."},{"id":"fratura-subtrocanterica-femur-pediatrica","area":"Pediátrica","front":"Subtrocantérica\n\nQuais são os critérios dessa classificação?\n(Fratura Subtrocantérica do Fêmur Pediátrico)","back":"• Mecanismo — Geralmente resulta de trauma de alta energia; o fragmento proximal tende a fletir, abduzir e rodar externamente, dificultando o tratamento fechado.\n• Fator de risco para malunião — Fraturas mais próximas ao grande trocânter e em crianças maiores de 8 anos resultam mais frequentemente em malunião.\n• Conduta em crianças pequenas — Gesso pelvipodálico precoce em posição \"sentada\" pode ser suficiente; tração 90-90 pode ser necessária até formação de calo visível.\n• Conduta em crianças maiores — Estabilização cirúrgica recomendada em maiores de 5 anos ou em fraturas instáveis mesmo em crianças menores; escolha do implante (haste intramedular ou placa proximal femoral) depende da localização e do padrão da fratura."},{"id":"modalidades-fixacao-fratura-femur-pediatrica","area":"Pediátrica","front":"Fixação femoral\n\nQuais são os critérios dessa classificação?\n(Modalidades de Fixação da Fratura Diafisária do Fêmur Pediátrico)","back":"• Tração esquelética — Método seguro e confiável para praticamente qualquer fratura, hoje raramente de primeira escolha; pino inserido na metáfise distal do fêmur em direção medial-lateral; cerca de 17-21 dias até estabilidade relativa, seguido de gesso.\n• Fixador externo — Indicado em fraturas com padrão instável (cominuição significativa), fraturas muito proximais/distais ou dano de partes moles (aberta, queimadura); complicações incluem infecção de trajeto de pino, retardo de consolidação e refratura após retirada.\n• Haste intramedular flexível (elástica) — Indicação ideal: criança de 5-11 anos, fise aberta, fratura diafisária transversa não cominuída inadequada para gesso precoce; menos confiável em crianças >50 kg, >11 anos ou fratu..."},{"id":"fratura-fisaria-distal-femur-salter-harris","area":"Pediátrica","front":"SH — fêmur distal\n\nQuais são os critérios dessa classificação?\n(Fratura Fisária Distal do Fêmur (Aplicação de Salter-Harris))","back":"• Predomínio — A maioria das lesões fisárias distais do fêmur são Salter-Harris tipo I e II.\n• Risco de deformidade em crescimento — Taxa de fechamento fisário prematuro documentada em até 50% dos casos, mais relacionada à gravidade do desvio inicial; cominuição metafisária no tipo II é fator prognóstico adicional.\n• Salter-Harris tipo III do côndilo medial — Resulta de força em valgo; pode ter redução espontânea, dificultando o diagnóstico radiográfico; pode associar-se a lesão de ligamento cruzado e fragmentos osteocondrais intra-articulares.\n• Faixa etária de maior risco — Fraturas entre 2 e 11 anos costumam ter trauma mais grave e maior chance de lesão fisária; em lactentes/toddlers, o potencial de remodelação é excelente e raramente..."},{"id":"meyers-mckeever-fratura-espinha-tibial","area":"Pediátrica","front":"Meyers-McKeever\n\nQuais são os critérios dessa classificação?\n(Classificação de Meyers e McKeever para Fratura da Espinha Tibial (Eminência Tibial))","back":"• Tipo I — Minimamente desviada, com discreta elevação da margem anterior.\n• Tipo II — Dobrada posteriormente, produzindo aparência de \"bico\" (beak-like) na radiografia em perfil.\n• Tipo III — Completamente desviada e elevada do seu leito.\n• Conduta — Tipo I: imobilização em gesso cilíndrico ou órtese em extensão por 4-6 semanas; tipo II: tentativa de redução fechada em extensão, com aspiração articular auxiliar; tipo III: redução aberta ou artroscópica com fixação interna.\n• Complicação típica — Perda de extensão completa do joelho é mais problemática que a frouxidão residual do ligamento cruzado anterior; 60% dos pacientes perdem mais de 10 graus de extensão, mais comum em fraturas tipo III."},{"id":"ogden-watson-jones-fratura-tuberosidade-tibial","area":"Pediátrica","front":"Ogden/Watson-Jones\n\nQuais são os critérios dessa classificação?\n(Classificação de Watson-Jones Modificada por Ogden para Fratura da Tuberosidade Tibial)","back":"• Tipo I — Fratura através do centro de ossificação distal da tuberosidade.\n• Tipo II — Fratura na junção entre a tuberosidade e o centro de ossificação da epífise tibial.\n• Tipo III — Envolve a superfície articular da tíbia.\n• Tipo IV (proposto) — Avulsão de toda a epífise tibial proximal.\n• Conduta — Tipo I minimamente desviado: tratamento não cirúrgico; demais tipos: redução anatômica aberta e fixação interna com parafusos esponjosos, reparo do grande dano retinacular associado."},{"id":"fratura-sleeve-patelar-pediatrica","area":"Pediátrica","front":"Sleeve patelar\n\nQuais são os critérios dessa classificação?\n(Fratura em \"Sleeve\" da Patela (Entidade Específica da Criança))","back":"• Faixa etária — 8 a 12 anos, período em que a patela é predominantemente cartilaginosa.\n• Mecanismo — Avulsão da porção cartilaginosa distal da patela a partir do centro de ossificação.\n• Achado radiográfico — Patela alta e pequeno fragmento ósseo aderido à cartilagem distal não ossificada na radiografia em perfil; RM auxilia quando há dúvida diagnóstica.\n• Conduta — Fraturas não desviadas com mecanismo extensor íntegro: imobilização em extensão por 4-6 semanas; fraturas desviadas: redução aberta com fixação interna (técnica de banda de tensão AO)."},{"id":"fratura-fisaria-proximal-tibia-salter-harris","area":"Pediátrica","front":"SH — tíbia proximal\n\nQuais são os critérios dessa classificação?\n(Fratura Fisária Proximal da Tíbia e Risco Vascular Poplíteo)","back":"• Predomínio — A maioria das lesões epifisárias proximais é Salter-Harris tipo II com desvio posterolateral ou posteromedial; separações tipo I são a segunda mais comuns.\n• Risco vascular — Fraturas em hiperextensão ameaçam a artéria poplítea, que é tracionada por seus ramos junto à face posterior da tíbia.\n• Tipos III e IV — Lesões intra-articulares que exigem redução precisa e fixação interna para preservar a função articular e reduzir risco de fechamento fisário prematuro.\n• Taxa de fechamento fisário — Ocorre em 25% a 33% dos pacientes, independentemente do tipo de separação fisária.\n• Conduta em caso de comprometimento vascular — Pulsos anormais ou pé frio/descorado exigem consulta vascular e redução/fixação imediatas em centro cirú..."},{"id":"fratura-cozen-tibia-proximal","area":"Pediátrica","front":"Cozen\n\nQuais são os critérios dessa classificação?\n(Fratura Metafisária Proximal da Tíbia (Fratura de Cozen))","back":"• Faixa etária — Mais comum entre 2 e 8 anos de idade.\n• Mecanismo — Força em valgo aplicada ao joelho em extensão, produzindo fratura incompleta da tíbia (córtex lateral pode estar entortado, impactado ou com deformação plástica), com ou sem fratura da fíbula.\n• Conduta — Redução fechada e imobilização gessada em extensão do joelho, permitindo moldagem de três pontos em varo; manutenção do gesso por cerca de 4 semanas.\n• Complicação característica — Deformidade progressiva em valgo, mesmo em fraturas anatomicamente reduzidas, atribuída provavelmente a hipercrescimento da fise medial da tíbia; progride por semanas e cessa por volta de 12 meses.\n• Conduta na deformidade — Observação em menores de 5 anos, pois costuma resolver espontaneame..."},{"id":"toddlers-fracture-tibia-pediatrica","area":"Pediátrica","front":"Toddler's fx\n\nQuais são os critérios dessa classificação?\n(Fratura do \"Toddler\" (Fratura Não Desviada da Diáfise Tibial na Criança Pequena))","back":"• Faixa etária — 1 a 4 anos.\n• Apresentação — Trauma leve, muitas vezes não observado; criança apresenta claudicação aguda ou recusa de apoio de peso.\n• Mecanismo — Força torcional de baixa energia, como girar a perna ao descer de um escorregador.\n• Diagnóstico — Radiografia inicial pode ser normal; confirmação costuma ocorrer 10-14 dias depois, quando surge neoformação óssea perióstea; cerca de 20% das crianças com claudicação aguda inexplicada têm fratura oculta, metade delas na tíbia.\n• Conduta — Gesso curto de perna com apoio de peso permitido para as fraturas típicas estáveis e não desviadas; consolidação em cerca de 3 semanas em toddlers e 4-6 semanas em crianças maiores."},{"id":"classificacao-padrao-fratura-diafisaria-tibia","area":"Pediátrica","front":"Padrão diafisário tíbia\n\nQuais são os critérios dessa classificação?\n(Classificação por Padrão da Fratura Diafisária da Tíbia e Limites de Angulação Aceitável)","back":"• Categoria (a) não desviada — Mais comum em crianças pequenas, cujo córtex tibial mais fraco tende a dobrar/comprimir em vez de fraturar completamente; periósteo espesso limita o desvio.\n• Categoria (b) oblíqua ou espiral — Isolada da tíbia com fíbula íntegra é o padrão mais comum na infância; força rotacional/torcional na junção do terço médio com o distal.\n• Categoria (c) transversa e cominuída/desviada — Mais comum em adolescentes, geralmente por trauma de alta energia; maior comprometimento de partes moles e maior risco de síndrome compartimental.\n• Angulação aceitável (≥6 anos) — Até 10 graus de angulação em qualquer direção.\n• Angulação aceitável (<6 anos) — Até 15 graus de angulação em qualquer direção; deformidade rotacional tem..."},{"id":"vahvanen-aalto-fratura-tornozelo-pediatrica","area":"Pediátrica","front":"Vahvanen-Aalto\n\nQuais são os critérios dessa classificação?\n(Classificação de Vahvanen e Aalto para Fraturas do Tornozelo na Criança)","back":"• Grupo I — baixo risco — Fraturas avulsivas e separações epifisárias Salter-Harris tipos I e II.\n• Grupo II — alto risco — Fraturas através da epífise (Salter-Harris III e IV) e fraturas transicionais desviadas.\n• Racional — Proposta como alternativa simplificada às classificações combinadas de mecanismo de trauma + tipo de lesão fisária, consideradas confusas e de difícil aplicação em crianças (mecanismo do trauma frequentemente não identificável).\n• Conduta no grupo I — Fraturas não desviadas: gesso curto de perna com apoio de peso por 4 semanas (fíbula) ou gesso sem apoio de peso por 2-3 semanas seguido de apoio total (tíbia); consolidação em 4-6 semanas.\n• Conduta no grupo II — Redução deve ser \"perfeita\" para restaurar a superfície..."},{"id":"salter-harris-tornozelo-pediatrico","area":"Pediátrica","front":"SH tornozelo\n\nQuais são os critérios dessa classificação?\n(Fraturas Fisárias do Tornozelo (Aplicação de Salter-Harris))","back":"• Tipo I/II (baixo risco) — Separações epifisárias e avulsões maleolares mais comuns em crianças menores; bom prognóstico, extra-articulares na maioria dos casos.\n• Gap residual > 3 mm — Após redução, sugere interposição de tecido mole (retalho de periósteo, tendão ou estrutura neurovascular); dado inicial sugeria maior risco de fechamento fisário, mas estudo posterior do mesmo grupo não confirmou diferença com tratamento cirúrgico.\n• Tipo III/IV (alto risco) — Fraturas intra-articulares com frequente instabilidade articular; redução deve ser \"perfeita\" para minimizar risco de fechamento fisário.\n• \"Hairline\" (linha de fratura 1-2 mm) — Podem ser tratadas com gesso longo e acompanhamento rigoroso, sem necessidade de redução.\n• Cresciment..."},{"id":"fratura-tillaux-pediatrica","area":"Pediátrica","front":"Tillaux\n\nQuais são os critérios dessa classificação?\n(Fratura de Tillaux (Fratura Transicional Biplanar))","back":"• Mecanismo — Força de rotação externa, resultando em avulsão da porção anterolateral da epífise tibial distal pelo ligamento tibiofibular anterior.\n• Classificação — Considerada uma fratura Salter-Harris tipo III biplanar; algumas são difíceis de identificar em radiografia simples.\n• Conduta inicial — Redução fechada por rotação interna do pé e imobilização em gesso acima ou abaixo do joelho, com documentação precisa da qualidade da redução; TC auxilia quando a radiografia é inconclusiva.\n• Indicação cirúrgica — Redução aberta com fixação interna quando o degrau articular após redução fechada for maior que 2 mm; abordagem anterolateral com parafusos esponjosos parcialmente rosqueados cruzando a fise.\n• Fisiopatologia da idade — Ocorre n..."},{"id":"fratura-triplanar-pediatrica","area":"Pediátrica","front":"Triplanar\n\nQuais são os critérios dessa classificação?\n(Fratura Triplanar do Tornozelo (Fratura Transicional Tridimensional))","back":"• Aparência radiográfica — Na incidência AP, aparenta ser Salter-Harris tipo III; na incidência em perfil, aparenta ser Salter-Harris tipo II — daí o nome \"triplanar\".\n• Fratura de 2 partes — TC mostra uma única linha de fratura na secção horizontal através da epífise.\n• Fratura de 3 partes — TC mostra três linhas de fratura irradiando na secção transversa através da epífise, formando o chamado \"sinal de Mercedes\".\n• Variante extra-articular — A linha de fratura pode sair através do maléolo medial além da superfície articular, sem comprometer a articulação.\n• Indicação cirúrgica — Redução aberta com fixação interna quando incongruência articular exceder 2 mm, quando o paciente apresentar tardiamente, ou após falha de redução fechada; abo..."},{"id":"letts-gibeault-fratura-talus-pediatrica","area":"Pediátrica","front":"Letts-Gibeault\n\nQuais são os critérios dessa classificação?\n(Classificação de Letts e Gibeault para Fratura do Colo do Tálus na Criança)","back":"• Tipo I — Fratura minimamente desviada do colo distal do tálus; baixa incidência de osteonecrose.\n• Tipo II — Fratura minimamente desviada do colo proximal ou do corpo; risco de osteonecrose também baixo.\n• Tipo III — Fratura desviada do colo ou corpo do tálus; osteonecrose mais provável.\n• Tipo IV — Fratura do colo do tálus com luxação do fragmento do corpo; osteonecrose é esperada nesse tipo.\n• Conduta — Fraturas minimamente anguladas (<5 graus) e desviadas (<2 mm) podem ser tratadas de forma fechada em flexão plantar discreta; fraturas desviadas requerem redução aberta com fixação interna (parafusos de compressão preferíveis a fios lisos)."},{"id":"schmidt-weiner-fratura-calcaneo-pediatrica","area":"Pediátrica","front":"Schmidt-Weiner\n\nQuais são os critérios dessa classificação?\n(Classificação de Schmidt e Weiner para Fratura do Calcâneo na Criança)","back":"• Extra-articular — Mais frequente em crianças menores (cerca de 75% dos casos); poupa a articulação subtalar; bom prognóstico com tratamento conservador.\n• Intra-articular — Predomina em adolescentes e adultos; costuma exigir avaliação por TC para planejamento cirúrgico.\n• Com perda da inserção do Aquiles — Associada a lesão grave de partes moles (ex.: acidente com cortador de grama); requer atenção especial ao mecanismo extensor.\n• Conduta extra-articular — Gesso por 4-6 semanas com deambulação progressiva conforme tolerado.\n• Conduta intra-articular desviada — Redução aberta e fixação interna recomendada na maioria dos casos, por acesso lateral em \"L\", elevando fragmentos deprimidos e estabilizando a faceta posterior com parafusos e p..."}];
